public static class RagEndpoints
{
    internal const double NavigationRouteMinimumConfidence = 0.699;
    internal const double FuzzyTitleSimilarityMinimum = 0.68;
    internal const double FuzzyTitleLeadSimilarityMinimum = 0.66;

    public static void Map(WebApplication app)
    {
        app.MapGet("/rag/categories", CategoriesAsync);
        app.MapPost("/rag/search", SearchAsync);
        app.MapPost("/rag/query", QueryAsync);
        app.MapGet("/rag/debug/scroll", ScrollAsync).RequireAdminKey();
    }

    private static async Task<IResult> CategoriesAsync(HttpContext ctx, NpgsqlDataSource ds)
    {
        var tenantId = ctx.GetTenantId();
        await using var conn = await ds.OpenConnectionAsync(ctx.RequestAborted);

        const string sql = """
WITH snapshot AS (
  SELECT
    path AS category,
    display_order,
    name
  FROM documents_catalog_categories
  WHERE tenant_id=@tenant_id
    AND path <> ''
    AND position('/' in path) = 0
),
dynamic AS (
  SELECT DISTINCT
    split_part(replace(doc_path, chr(92), '/'), '/', 1) AS category
  FROM documents
  WHERE tenant_id=@tenant_id
    AND status='indexed'
    AND position('/' in replace(doc_path, chr(92), '/')) > 0
)
SELECT category
FROM (
  SELECT category, display_order, name FROM snapshot
  UNION ALL
  SELECT category, 2147483647 AS display_order, category AS name
  FROM dynamic d
  WHERE NOT EXISTS (
    SELECT 1
    FROM snapshot s
    WHERE LOWER(s.category) = LOWER(d.category)
  )
) categories
WHERE category <> ''
ORDER BY display_order, name;
""";

        var cats = (await conn.QueryAsync<string>(
            new CommandDefinition(sql, new { tenant_id = tenantId }, cancellationToken: ctx.RequestAborted)
        )).ToArray();

        return Results.Ok(cats);
    }

    private static async Task<IResult> QueryAsync(
        HttpContext ctx,
        NpgsqlDataSource ds,
        IOptions<RagOptions> ragOpt,
        IHttpClientFactory httpFactory,
        RagSearchBulkhead searchBulkhead,
        RagSearchRequestDto req)
    {
        using var admission = await searchBulkhead.AcquireAsync(ctx.RequestAborted);
        if (admission is null)
            return BuildRagSearchBusyResult(ctx, ragOpt.Value, searchBulkhead);

        AddRagSearchAdmissionHeaders(ctx, admission, searchBulkhead.GetSnapshot());
        using var interactiveRetrieval = RuntimeCapabilityBRagIdleCoordinator.BeginInteractiveRetrieval(
            ctx.RequestServices.GetService<IOptions<RuntimeGovernanceOptions>>()?.Value);
        var responseDto = await BuildSearchResponseDtoAsync(ctx, ds, ragOpt.Value, httpFactory, req);
        return Results.Ok(new
        {
            query = responseDto.Query,
            queryNormalized = responseDto.QueryNormalized,
            category = responseDto.Category,
            topK = responseDto.TopK,
            matches = responseDto.Items,
            metrics = responseDto.Metrics,
            guidance = responseDto.Guidance
        });
    }

    private static async Task<IResult> SearchAsync(
        HttpContext ctx,
        NpgsqlDataSource ds,
        IOptions<RagOptions> ragOpt,
        IHttpClientFactory httpFactory,
        RagSearchBulkhead searchBulkhead,
        RagSearchRequestDto req)
    {
        using var admission = await searchBulkhead.AcquireAsync(ctx.RequestAborted);
        if (admission is null)
            return BuildRagSearchBusyResult(ctx, ragOpt.Value, searchBulkhead);

        AddRagSearchAdmissionHeaders(ctx, admission, searchBulkhead.GetSnapshot());
        using var interactiveRetrieval = RuntimeCapabilityBRagIdleCoordinator.BeginInteractiveRetrieval(
            ctx.RequestServices.GetService<IOptions<RuntimeGovernanceOptions>>()?.Value);
        var responseDto = await BuildSearchResponseDtoAsync(ctx, ds, ragOpt.Value, httpFactory, req);
        return Results.Ok(responseDto);
    }

    private static IResult BuildRagSearchBusyResult(HttpContext ctx, RagOptions rag, RagSearchBulkhead searchBulkhead)
    {
        var snapshot = searchBulkhead.GetSnapshot();
        var retryAfterSeconds = ComputeRagSearchRetryAfterSeconds(rag, snapshot);
        ctx.Response.Headers.RetryAfter = retryAfterSeconds.ToString(CultureInfo.InvariantCulture);
        AddRagSearchCapacityHeaders(ctx, snapshot);

        return Results.Json(new
        {
            error = "rag_search_busy",
            requestId = ctx.GetRequestId(),
            retryAfterSeconds,
            active = snapshot.Active,
            queued = snapshot.Queued,
            maxConcurrency = snapshot.MaxConcurrency,
            queueLimit = snapshot.QueueLimit,
            availableSlots = snapshot.AvailableSlots,
            queueWaitTimeoutSeconds = snapshot.QueueWaitTimeoutSeconds,
            detail = "The RAG search service is busy. Retry shortly."
        }, statusCode: StatusCodes.Status429TooManyRequests);
    }

    internal static int ComputeRagSearchRetryAfterSeconds(RagOptions rag, RagSearchBulkheadSnapshot snapshot)
    {
        var configured = Math.Clamp(rag.SearchRetryAfterSeconds, 1, 300);
        var maxConcurrency = Math.Max(1, snapshot.MaxConcurrency);
        var queueRounds = Math.Max(1, (int)Math.Ceiling((snapshot.Queued + 1) / (double)maxConcurrency));
        var estimated = configured * queueRounds;
        var upperBound = Math.Clamp(snapshot.QueueWaitTimeoutSeconds, configured, 300);
        return Math.Clamp(estimated, configured, upperBound);
    }

    private static void AddRagSearchCapacityHeaders(HttpContext ctx, RagSearchBulkheadSnapshot snapshot)
    {
        ctx.Response.Headers["X-SAAIA-RAG-Active"] = snapshot.Active.ToString(CultureInfo.InvariantCulture);
        ctx.Response.Headers["X-SAAIA-RAG-Queued"] = snapshot.Queued.ToString(CultureInfo.InvariantCulture);
        ctx.Response.Headers["X-SAAIA-RAG-Max-Concurrency"] = snapshot.MaxConcurrency.ToString(CultureInfo.InvariantCulture);
        ctx.Response.Headers["X-SAAIA-RAG-Queue-Limit"] = snapshot.QueueLimit.ToString(CultureInfo.InvariantCulture);
        ctx.Response.Headers["X-SAAIA-RAG-Available-Slots"] = snapshot.AvailableSlots.ToString(CultureInfo.InvariantCulture);
        ctx.Response.Headers["X-SAAIA-RAG-Queue-Wait-Timeout-Seconds"] = snapshot.QueueWaitTimeoutSeconds.ToString(CultureInfo.InvariantCulture);
    }

    private static void AddRagSearchAdmissionHeaders(
        HttpContext ctx,
        RagSearchBulkhead.RagSearchBulkheadLease admission,
        RagSearchBulkheadSnapshot snapshot)
    {
        ctx.Response.Headers["X-SAAIA-RAG-Queue-Wait-Ms"] = admission.WaitMs.ToString(CultureInfo.InvariantCulture);
        ctx.Response.Headers["X-SAAIA-RAG-Waited-Queued"] = admission.WaitedQueued ? "true" : "false";
        AddRagSearchCapacityHeaders(ctx, snapshot);
    }

    private static IReadOnlyList<Match> SafeRegexMatches(Regex regex, string input)
    {
        if (string.IsNullOrEmpty(input))
            return Array.Empty<Match>();

        try
        {
            var matches = regex.Matches(input);
            var copy = new List<Match>(matches.Count);
            foreach (Match match in matches)
                copy.Add(match);
            return copy;
        }
        catch (RegexMatchTimeoutException)
        {
            return Array.Empty<Match>();
        }
    }

    internal static IReadOnlyList<Match> SafeRegexMatches(
        string input,
        string pattern,
        RegexOptions options,
        TimeSpan timeout)
    {
        if (string.IsNullOrEmpty(input))
            return Array.Empty<Match>();

        try
        {
            var matches = Regex.Matches(input, pattern, options, timeout);
            var copy = new List<Match>(matches.Count);
            foreach (Match match in matches)
                copy.Add(match);
            return copy;
        }
        catch (RegexMatchTimeoutException)
        {
            return Array.Empty<Match>();
        }
    }

    private static Match SafeRegexMatch(Regex regex, string input)
    {
        if (string.IsNullOrEmpty(input))
            return Match.Empty;

        try
        {
            return regex.Match(input);
        }
        catch (RegexMatchTimeoutException)
        {
            return Match.Empty;
        }
    }

    private static bool SafeRegexIsMatch(
        string input,
        string pattern,
        RegexOptions options,
        TimeSpan timeout)
    {
        if (string.IsNullOrEmpty(input))
            return false;

        try
        {
            return Regex.IsMatch(input, pattern, options, timeout);
        }
        catch (RegexMatchTimeoutException)
        {
            return false;
        }
    }

    private static string SafeRegexReplace(
        string input,
        string pattern,
        string replacement,
        RegexOptions options,
        TimeSpan timeout)
    {
        if (string.IsNullOrEmpty(input))
            return input;

        try
        {
            return Regex.Replace(input, pattern, replacement, options, timeout);
        }
        catch (RegexMatchTimeoutException)
        {
            return input;
        }
    }

    private static async Task<RagSearchResponseDto> BuildSearchResponseDtoAsync(
        HttpContext ctx,
        NpgsqlDataSource ds,
        RagOptions rag,
        IHttpClientFactory httpFactory,
        RagSearchRequestDto req)
    {
        var resp = await SearchCoreAsync(ctx, ds, rag, httpFactory, req);
        var tenantId = ctx.GetTenantId();
        var ct = ctx.RequestAborted;
        var categoryRefsTask = LoadTopCategoryRefsAsync(ds, tenantId, resp.Matches, ct);
        var hypQuestionsTask = LoadHypQuestionsMatchedByDocPathAsync(
            ds,
            tenantId,
            resp.Query,
            resp.Matches,
            ct);
        var extractionQualityTask = LoadRagExtractionQualityAsync(ds, tenantId, resp.Matches, ct);
        var documentLanguagesTask = LoadRagDocumentLanguagesAsync(ds, tenantId, resp.Matches, ct);
        var documentSourceHashesTask = LoadRagDocumentSourceHashesAsync(ds, tenantId, resp.Matches, ct);

        await Task.WhenAll(categoryRefsTask, hypQuestionsTask, extractionQualityTask, documentLanguagesTask, documentSourceHashesTask);
        var categoryRefsByTopLevelPath = await categoryRefsTask;
        var hypQuestionsMatchedByDocPath = await hypQuestionsTask;
        var extractionQualityByMatch = await extractionQualityTask;
        var documentLanguagesByDocId = await documentLanguagesTask;
        var documentSourceHashesByDocId = await documentSourceHashesTask;
        var qualityAdjustedMatches = BuildQualityAdjustedMatchesPreservingRank(resp.Matches, extractionQualityByMatch);

        return new RagSearchResponseDto(
            RequestId: resp.RequestId,
            Query: resp.Query,
            QueryNormalized: resp.QueryNormalized,
            Category: resp.Category,
            TopK: resp.TopK,
            MinScore: resp.MinScore,
            Candidates: resp.Candidates,
            MaxPerDoc: resp.MaxPerDoc,
            MaxPerPage: resp.MaxPerPage,
            Metrics: new RagMetricsDto(
                TookMs: resp.Timings.TotalMs,
                Returned: resp.Matches.Count,
                ExactMatchReturned: resp.Matches.Count(m => string.Equals(m.EmbeddingBasis, "exact_match_v1", StringComparison.Ordinal)),
                DenseReturned: resp.Matches.Count(m => string.Equals(ResolveRetriever(m), "dense_qdrant", StringComparison.Ordinal)),
                SparseReturned: resp.Matches.Count(m => string.Equals(ResolveRetriever(m), "sparse_bm25", StringComparison.Ordinal)),
                LinkedReturned: resp.Matches.Count(m => string.Equals(m.EmbeddingBasis, "linked_context_v1", StringComparison.Ordinal)),
                RetrieversUsed: resp.Matches
                    .Select(ResolveRetriever)
                    .Distinct(StringComparer.Ordinal)
                    .ToArray(),
                DataHash: ComputeDataHash(resp.Matches),
                TtlSeconds: 600,
                TeiMs: resp.Timings.TeiMs,
                RerankMs: resp.Timings.RerankMs,
                SparseMs: resp.Timings.SparseMs,
                QdrantMs: resp.Timings.QdrantMs,
                CandidatesEvaluated: resp.Candidates,
                DegradedRetrievers: resp.DegradedRetrievers,
                DegradedRetrieverErrors: resp.DegradedRetrieverErrors,
                ExactMs: resp.Timings.ExactMs,
                QuotedTitleMs: resp.Timings.QuotedTitleMs,
                LocalTitleTokenMs: resp.Timings.LocalTitleTokenMs,
                TitleAnchorRouteMs: resp.Timings.TitleAnchorRouteMs,
                SparsePhaseMs: resp.Timings.SparsePhaseMs,
                DenseMs: resp.Timings.DenseMs,
                ProfileMs: resp.Timings.ProfileMs,
                LinkedMs: resp.Timings.LinkedMs,
                FusionMs: resp.Timings.FusionMs,
                RerankPhaseMs: resp.Timings.RerankPhaseMs,
                SelectionMs: resp.Timings.SelectionMs
            ),
            Items: qualityAdjustedMatches
                .Select(item =>
                {
                    var m = item.Match;
                    var categoryPath = BuildDocumentCategoryPath(m.DocPath);
                    var category = ResolveMatchCategory(m, resp.Category);
                    var languageInfo = ResolveDocumentLanguageInfo(m, documentLanguagesByDocId);
                    var sourceHash = ResolveDocumentSourceHash(m, documentSourceHashesByDocId);
                    return new RagItemDto(
                        Score: item.AdjustedScore,
                        DocId: m.DocId,
                        DocName: m.DocName ?? "Unknown",
                        DocPath: m.DocPath,
                        Category: category,
                        CategoryRef: ResolveCategoryRef(categoryPath, categoryRefsByTopLevelPath),
                        DocLanguage: languageInfo.DocLanguage,
                        ProfileLanguage: languageInfo.ProfileLanguage,
                        PageStart: m.PageStart,
                        PageEnd: m.PageEnd,
                        ChunkId: m.ChunkId,
                        ChunkIndex: m.ChunkIndex,
                        Text: m.Text ?? string.Empty,
                        Retriever: ResolveRetriever(m),
                        Provenance: ResolveProvenance(m),
                        ExactMatchHit: string.Equals(m.EmbeddingBasis, "exact_match_v1", StringComparison.Ordinal),
                        SourceHash: sourceHash,
                        EmbeddingBasis: m.EmbeddingBasis,
                        ChunkType: m.ChunkType,
                        SectionTitle: m.SectionTitle,
                        HeadingPath: m.HeadingPath,
                        PrevChunkId: m.PrevChunkId,
                        NextChunkId: m.NextChunkId,
                        SameSectionChunkId: m.SameSectionChunkId,
                        ProvenanceInfo: BuildProvenanceInfo(m, sourceHash, allowLegacyHashFallback: false),
                        Context: BuildContextInfo(m),
                        CategoryPath: categoryPath,
                        Snippet: BuildSnippet(m.Text, query: resp.Query),
                        RerankScore: m.RerankScore,
                        HasTable: DetectHasTable(m.Text),
                        HasWarning: DetectHasWarning(m.Text, m.ChunkType),
                        ContextualSnippet: req.IncludeContextualSnippet == true ? m.EmbedText : null,
                        HypQuestionsMatched: ResolveHypQuestionsMatched(m.DocPath, hypQuestionsMatchedByDocPath),
                        ExtractionQuality: item.ExtractionQuality,
                        MatchedContentCards: BuildMatchedContentCardDtos(m),
                        SelectionHints: BuildSelectionHints(m, item.ExtractionQuality),
                        ProfileSignals: BuildProfileSignalsDto(m.ProfileSignals)
                    );
                })
                .ToList(),
            Guidance: BuildAnswerGuidance(
                resp.Query,
                qualityAdjustedMatches.Select(static item => item.Match).ToList(),
                extractionQualityByMatch)
        );
    }

    internal static async Task<IReadOnlyDictionary<string, RagItemExtractionQualityDto>> LoadRagExtractionQualityAsync(
        NpgsqlDataSource ds,
        Guid tenantId,
        IReadOnlyList<RagMatch> matches,
        CancellationToken ct)
    {
        var docIds = matches
            .Select(static match => Guid.TryParse(match.DocId, out var docId) ? docId : (Guid?)null)
            .Where(static docId => docId.HasValue)
            .Select(static docId => docId!.Value)
            .Distinct()
            .ToArray();
        var docPaths = matches
            .Select(static match => NormalizeRagDocPath(match.DocPath))
            .Where(static path => !string.IsNullOrWhiteSpace(path))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();

        if (docIds.Length == 0 && docPaths.Length == 0)
            return new Dictionary<string, RagItemExtractionQualityDto>(StringComparer.OrdinalIgnoreCase);

        await using var conn = await ds.OpenConnectionAsync(ct);
        const string docSql = """
WITH scoped_docs AS (
  SELECT
    d.doc_id,
    d.tenant_id,
    d.doc_path,
    d.indexed_version,
    rev.revision_id
  FROM documents d
  LEFT JOIN LATERAL (
    SELECT r.revision_id
    FROM document_revisions r
    WHERE r.tenant_id = d.tenant_id
      AND r.doc_id = d.doc_id
      AND r.indexed_version = d.indexed_version
    ORDER BY r.published_at DESC NULLS LAST
    LIMIT 1
  ) rev ON true
  WHERE d.tenant_id=@tenant
    AND (
      d.doc_id = ANY(@docIds)
      OR d.doc_path = ANY(@docPaths)
    )
),
latest_runs AS (
  SELECT
    sd.doc_id,
    r.payload
  FROM scoped_docs sd
  LEFT JOIN LATERAL (
    SELECT payload
    FROM document_processing_runs pr
    WHERE pr.tenant_id=sd.tenant_id
      AND pr.doc_id=sd.doc_id
      AND pr.action='upsert'
      AND pr.status='done'
      AND (
        (sd.revision_id IS NOT NULL AND pr.revision_id = sd.revision_id)
        OR (sd.revision_id IS NULL AND pr.indexed_version_after = sd.indexed_version)
      )
    ORDER BY pr.finished_at DESC NULLS LAST, pr.started_at DESC NULLS LAST
    LIMIT 1
  ) r ON true
),
page_rows AS (
  SELECT
    sd.doc_id,
    sd.tenant_id,
    rev.revision_id,
    pi.page_number,
    COALESCE(pi.char_count, 0)::int AS char_count,
    CASE
      WHEN COALESCE(pi.metadata ->> 'wordCount', '') ~ '^[0-9]+$' THEN (pi.metadata ->> 'wordCount')::int
      ELSE 0
    END AS word_count,
    CASE
      WHEN COALESCE(pi.metadata ->> 'imageCount', '') ~ '^[0-9]+$' THEN (pi.metadata ->> 'imageCount')::int
      ELSE 0
    END AS image_count
  FROM scoped_docs sd
  LEFT JOIN document_revisions rev
    ON rev.tenant_id=sd.tenant_id
   AND rev.doc_id=sd.doc_id
   AND rev.indexed_version=sd.indexed_version
  LEFT JOIN document_page_index pi
    ON pi.tenant_id=sd.tenant_id
   AND pi.revision_id=rev.revision_id
),
page_projection AS (
  SELECT
    pr.*,
    COALESCE(uc.unit_count, 0) AS unit_count,
    COALESCE(cc.chunk_count, 0) AS chunk_count
  FROM page_rows pr
  LEFT JOIN LATERAL (
    SELECT COUNT(*)::int AS unit_count
    FROM document_units u
    WHERE u.tenant_id=pr.tenant_id
      AND u.revision_id=pr.revision_id
      AND pr.page_number IS NOT NULL
      AND u.page_start <= pr.page_number
      AND pr.page_number <= u.page_end
  ) uc ON true
  LEFT JOIN LATERAL (
    SELECT COUNT(*)::int AS chunk_count
    FROM retrieval_chunks rc
    WHERE rc.tenant_id=pr.tenant_id
      AND rc.revision_id=pr.revision_id
      AND pr.page_number IS NOT NULL
      AND rc.page_start <= pr.page_number
      AND pr.page_number <= rc.page_end
  ) cc ON true
),
page_quality AS (
  SELECT
    doc_id,
    COUNT(page_number)::int AS page_count,
    COUNT(*) FILTER (WHERE word_count > 0 AND char_count > 0)::int AS text_page_count,
    COUNT(*) FILTER (WHERE page_number IS NOT NULL AND (word_count <= 0 OR char_count <= 0))::int AS empty_page_count,
    COUNT(*) FILTER (
      WHERE page_number IS NOT NULL
        AND word_count > 0
        AND char_count > 0
        AND (word_count < 12 OR char_count < 80)
    )::int AS sparse_page_count,
    COUNT(*) FILTER (WHERE image_count > 0)::int AS image_page_count,
    COUNT(*) FILTER (
      WHERE page_number IS NOT NULL
        AND (
          ((word_count <= 0 OR char_count <= 0) AND chunk_count <= 0)
          OR (word_count > 0 AND char_count > 0 AND (word_count < 12 OR char_count < 80) AND chunk_count <= 0)
          OR (unit_count <= 0 AND chunk_count <= 0 AND (word_count >= 30 OR char_count >= 200))
        )
    )::int AS page_warning_count,
    COUNT(*) FILTER (
      WHERE page_number IS NOT NULL
        AND (
          (image_count > 0 AND (word_count <= 0 OR char_count <= 0))
          OR (image_count > 0 AND unit_count <= 0 AND chunk_count <= 0 AND word_count > 0 AND char_count > 0 AND (word_count < 12 OR char_count < 80))
          OR (unit_count <= 0 AND chunk_count <= 0 AND (word_count >= 30 OR char_count >= 200))
        )
    )::int AS page_review_recommended_count,
    COALESCE(SUM(word_count), 0)::int AS total_word_count,
    COALESCE(SUM(char_count), 0)::int AS total_char_count
  FROM page_projection
  GROUP BY doc_id
),
doc_quality_base AS (
  SELECT
    sd.doc_id AS "DocId",
    sd.doc_path AS "DocPath",
    lr.payload ->> 'extractionSource' AS "ExtractionSource",
    CASE
      WHEN LOWER(COALESCE(lr.payload ->> 'ocrAttempted', '')) IN ('true', 'false')
        THEN (lr.payload ->> 'ocrAttempted')::boolean
      ELSE false
    END AS "OcrAttempted",
    CASE
      WHEN LOWER(COALESCE(lr.payload ->> 'ocrApplied', '')) IN ('true', 'false')
        THEN (lr.payload ->> 'ocrApplied')::boolean
      ELSE false
    END AS "OcrApplied",
    NULLIF(lr.payload ->> 'ocrLanguages', '') AS "OcrLanguages",
    CASE
      WHEN COALESCE(lr.payload ->> 'ocrDurationMs', '') ~ '^[0-9]+$'
        THEN (lr.payload ->> 'ocrDurationMs')::bigint
      ELSE NULL
    END AS "OcrDurationMs",
    lr.payload #>> '{nativeExtractionQuality,textStatus}' AS "NativeTextStatus",
    CASE
      WHEN LOWER(COALESCE(lr.payload #>> '{nativeExtractionQuality,ocrRecommended}', '')) IN ('true', 'false')
        THEN (lr.payload #>> '{nativeExtractionQuality,ocrRecommended}')::boolean
      ELSE NULL
    END AS "NativeOcrRecommended",
    (lr.payload -> 'ocrDiagnostics')::text AS "OcrDiagnosticsJson",
    lr.payload #>> '{extractionQuality,textStatus}' AS "RunTextStatus",
    CASE
      WHEN LOWER(COALESCE(lr.payload #>> '{extractionQuality,ocrRecommended}', '')) IN ('true', 'false')
        THEN (lr.payload #>> '{extractionQuality,ocrRecommended}')::boolean
      ELSE NULL
    END AS "RunOcrRecommended",
    COALESCE(
      CASE WHEN COALESCE(lr.payload #>> '{extractionQuality,pageCount}', '') ~ '^[0-9]+$' THEN (lr.payload #>> '{extractionQuality,pageCount}')::int ELSE NULL END,
      pq.page_count,
      0) AS "PageCount",
    COALESCE(
      CASE WHEN COALESCE(lr.payload #>> '{extractionQuality,textPageCount}', '') ~ '^[0-9]+$' THEN (lr.payload #>> '{extractionQuality,textPageCount}')::int ELSE NULL END,
      pq.text_page_count,
      0) AS "TextPageCount",
    COALESCE(
      CASE WHEN COALESCE(lr.payload #>> '{extractionQuality,emptyPageCount}', '') ~ '^[0-9]+$' THEN (lr.payload #>> '{extractionQuality,emptyPageCount}')::int ELSE NULL END,
      pq.empty_page_count,
      0) AS "EmptyPageCount",
    COALESCE(
      CASE WHEN COALESCE(lr.payload #>> '{extractionQuality,sparsePageCount}', '') ~ '^[0-9]+$' THEN (lr.payload #>> '{extractionQuality,sparsePageCount}')::int ELSE NULL END,
      pq.sparse_page_count,
      0) AS "SparsePageCount",
    COALESCE(pq.image_page_count, 0) AS "ImagePageCount",
    COALESCE(pq.page_warning_count, 0) AS "PageWarningCount",
    COALESCE(pq.page_review_recommended_count, 0) AS "PageReviewRecommendedCount",
    COALESCE(
      CASE WHEN COALESCE(lr.payload #>> '{extractionQuality,totalWordCount}', '') ~ '^[0-9]+$' THEN (lr.payload #>> '{extractionQuality,totalWordCount}')::int ELSE NULL END,
      pq.total_word_count,
      0) AS "TotalWordCount",
    COALESCE(
      CASE WHEN COALESCE(lr.payload #>> '{extractionQuality,totalCharCount}', '') ~ '^[0-9]+$' THEN (lr.payload #>> '{extractionQuality,totalCharCount}')::int ELSE NULL END,
      pq.total_char_count,
      0) AS "TotalCharCount",
    CASE
      WHEN COALESCE(pq.page_count, 0) <= 0 THEN 'unknown'
      WHEN COALESCE(pq.total_word_count, 0) <= 0 THEN 'empty_text'
      WHEN (COALESCE(pq.empty_page_count, 0)::double precision / GREATEST(COALESCE(pq.page_count, 0), 1)) >= 0.6 THEN 'low_text'
      WHEN (COALESCE(pq.sparse_page_count, 0)::double precision / GREATEST(COALESCE(pq.page_count, 0), 1)) >= 0.6
           AND (COALESCE(pq.total_word_count, 0)::double precision / GREATEST(COALESCE(pq.page_count, 0), 1)) < 30 THEN 'low_text'
      WHEN (COALESCE(pq.total_word_count, 0)::double precision / GREATEST(COALESCE(pq.page_count, 0), 1)) < 10 THEN 'low_text'
      ELSE 'ok'
    END AS "ComputedTextStatus",
    lr.payload #>> '{extractionQuality,signals}' AS "RunSignalsJson"
  FROM scoped_docs sd
  LEFT JOIN latest_runs lr ON lr.doc_id=sd.doc_id
  LEFT JOIN page_quality pq ON pq.doc_id=sd.doc_id
),
doc_quality AS (
  SELECT
    *,
    COALESCE("RunTextStatus", "ComputedTextStatus") AS "TextStatus",
    COALESCE("RunOcrRecommended", "ComputedTextStatus" IN ('empty_text', 'low_text')) AS "OcrRecommended",
    COALESCE(
      "RunSignalsJson",
      CASE "ComputedTextStatus"
        WHEN 'empty_text' THEN '["no_text_extracted","ocr_recommended"]'
        WHEN 'low_text' THEN '["low_text_extraction","ocr_recommended"]'
        WHEN 'ok' THEN '["text_extraction_ok"]'
        ELSE '[]'
      END
    ) AS "SignalsJson"
  FROM doc_quality_base
),
doc_quality_scored AS (
  SELECT
    *,
    CASE
      WHEN "OcrApplied" AND "TextStatus"='ok' AND COALESCE("ExtractionSource", '')='pdf_text_plus_image_ocr' THEN 'image_ocr_applied_ok'
      WHEN "OcrApplied" AND "TextStatus"='ok' AND ("PageWarningCount" > 0 OR "PageReviewRecommendedCount" > 0) THEN 'ocr_applied_ok_with_page_warnings'
      WHEN "OcrApplied" AND "TextStatus"='ok' THEN 'ocr_applied_ok'
      WHEN "OcrApplied" AND "TextStatus" <> 'ok' THEN 'ocr_applied_low_confidence'
      WHEN "OcrAttempted" AND NOT "OcrApplied" AND "OcrRecommended" THEN 'ocr_failed_or_insufficient'
      WHEN "TextStatus"='empty_text' THEN 'manual_review_empty_text'
      WHEN "TextStatus"='low_text' THEN 'manual_review_low_text'
      WHEN "TextStatus"='unknown' THEN 'unknown'
      WHEN "TextStatus"='ok' AND "PageReviewRecommendedCount" > 0 THEN 'extraction_ok_with_page_review'
      WHEN "TextStatus"='ok' AND "PageWarningCount" > 0 THEN 'extraction_ok_with_page_warnings'
      WHEN "ImagePageCount" > 0 AND NOT "OcrApplied" THEN 'text_extraction_ok_with_images'
      ELSE 'extraction_ok'
    END AS "QualityStatus",
    CASE
      WHEN "OcrApplied" AND "TextStatus"='ok' AND COALESCE("ExtractionSource", '')='pdf_text_plus_image_ocr' THEN 0.92::double precision
      WHEN "OcrApplied" AND "TextStatus"='ok' AND ("PageWarningCount" > 0 OR "PageReviewRecommendedCount" > 0) THEN 0.86::double precision
      WHEN "OcrApplied" AND "TextStatus"='ok' THEN 0.90::double precision
      WHEN "TextStatus"='ok' AND "PageReviewRecommendedCount" > 0 THEN 0.82::double precision
      WHEN "TextStatus"='ok' AND "PageWarningCount" > 0 THEN 0.88::double precision
      WHEN "TextStatus"='ok' AND "ImagePageCount" > 0 AND NOT "OcrApplied" THEN 0.85::double precision
      WHEN "TextStatus"='ok' THEN 1.00::double precision
      WHEN "OcrApplied" AND "TextStatus" <> 'ok' THEN 0.45::double precision
      WHEN "OcrAttempted" AND NOT "OcrApplied" AND "OcrRecommended" THEN 0.30::double precision
      WHEN "TextStatus"='low_text' THEN 0.35::double precision
      WHEN "TextStatus"='empty_text' THEN 0.15::double precision
      ELSE 0.50::double precision
    END AS "ExtractionConfidence",
    (
      "TextStatus" IN ('empty_text','low_text','unknown')
      OR ("OcrAttempted" AND NOT "OcrApplied" AND "OcrRecommended")
      OR ("OcrApplied" AND "TextStatus" <> 'ok')
      OR "PageReviewRecommendedCount" > 0
    ) AS "ManualReviewRecommended"
  FROM doc_quality
)
SELECT
  "DocId",
  "DocPath",
  "ExtractionSource",
  "OcrAttempted",
  "OcrApplied",
  "QualityStatus",
  "ExtractionConfidence",
  "ManualReviewRecommended",
  "OcrLanguages",
  "OcrDurationMs",
  "NativeTextStatus",
  "NativeOcrRecommended",
  "OcrDiagnosticsJson",
  "PageCount",
  "TextPageCount",
  "EmptyPageCount",
  "SparsePageCount",
  "ImagePageCount",
  "PageWarningCount",
  "PageReviewRecommendedCount",
  "TextStatus",
  "OcrRecommended",
  "SignalsJson"
FROM doc_quality_scored;
""";

        const string pageSql = """
WITH scoped_docs AS (
  SELECT
    d.doc_id,
    d.tenant_id,
    d.doc_path,
    d.indexed_version,
    rev.revision_id
  FROM documents d
  LEFT JOIN document_revisions rev
    ON rev.tenant_id=d.tenant_id
   AND rev.doc_id=d.doc_id
   AND rev.indexed_version=d.indexed_version
  WHERE d.tenant_id=@tenant
    AND (
      d.doc_id = ANY(@docIds)
      OR d.doc_path = ANY(@docPaths)
    )
)
SELECT
  sd.doc_id AS "DocId",
  sd.doc_path AS "DocPath",
  pi.page_number AS "PageNumber",
  COALESCE(pi.char_count, 0)::int AS "CharCount",
  CASE
    WHEN COALESCE(pi.metadata ->> 'wordCount', '') ~ '^[0-9]+$' THEN (pi.metadata ->> 'wordCount')::int
    ELSE 0
  END AS "WordCount",
  CASE
    WHEN COALESCE(pi.metadata ->> 'imageCount', '') ~ '^[0-9]+$' THEN (pi.metadata ->> 'imageCount')::int
    ELSE 0
  END AS "ImageCount",
  COALESCE(uc.unit_count, 0) AS "UnitCount",
  COALESCE(uc.unit_texts_json, '[]') AS "UnitTextsJson",
  COALESCE(cc.chunk_count, 0) AS "ChunkCount",
  pi.metadata #>> '{extractionQuality,signals}' AS "SignalsJson"
FROM scoped_docs sd
JOIN document_page_index pi
  ON pi.tenant_id=sd.tenant_id
 AND pi.revision_id=sd.revision_id
LEFT JOIN LATERAL (
  SELECT
    COUNT(*)::int AS unit_count,
    COALESCE(to_jsonb(array_agg(LEFT(u.text_content, 1000) ORDER BY u.ordinal))::text, '[]') AS unit_texts_json
  FROM document_units u
  WHERE u.tenant_id=sd.tenant_id
    AND u.revision_id=sd.revision_id
    AND u.page_start <= pi.page_number
    AND pi.page_number <= u.page_end
) uc ON true
LEFT JOIN LATERAL (
  SELECT COUNT(*)::int AS chunk_count
  FROM retrieval_chunks rc
  WHERE rc.tenant_id=sd.tenant_id
    AND rc.revision_id=sd.revision_id
    AND rc.page_start <= pi.page_number
    AND pi.page_number <= rc.page_end
) cc ON true
ORDER BY sd.doc_path, pi.page_number;
""";

        var parameters = new { tenant = tenantId, docIds, docPaths };
        var docRows = (await conn.QueryAsync<RagExtractionDocumentQualityRow>(
            new CommandDefinition(docSql, parameters, cancellationToken: ct))).ToArray();
        var pageRows = (await conn.QueryAsync<RagExtractionPageQualityRow>(
            new CommandDefinition(pageSql, parameters, cancellationToken: ct))).ToArray();

        var docById = docRows.ToDictionary(static row => row.DocId, static row => row);
        var docByPath = docRows
            .Where(static row => !string.IsNullOrWhiteSpace(row.DocPath))
            .GroupBy(static row => NormalizeRagDocPath(row.DocPath) ?? "", StringComparer.OrdinalIgnoreCase)
            .Where(static group => !string.IsNullOrWhiteSpace(group.Key))
            .ToDictionary(static group => group.Key, static group => group.First(), StringComparer.OrdinalIgnoreCase);
        var pagesById = pageRows
            .GroupBy(static row => row.DocId)
            .ToDictionary(static group => group.Key, static group => group.OrderBy(static row => row.PageNumber).ToArray());
        var pagesByPath = pageRows
            .Where(static row => !string.IsNullOrWhiteSpace(row.DocPath))
            .GroupBy(static row => NormalizeRagDocPath(row.DocPath) ?? "", StringComparer.OrdinalIgnoreCase)
            .Where(static group => !string.IsNullOrWhiteSpace(group.Key))
            .ToDictionary(static group => group.Key, static group => group.OrderBy(static row => row.PageNumber).ToArray(), StringComparer.OrdinalIgnoreCase);

        var byMatch = new Dictionary<string, RagItemExtractionQualityDto>(StringComparer.OrdinalIgnoreCase);
        foreach (var match in matches)
        {
            var doc = ResolveExtractionDocumentQuality(match, docById, docByPath);
            if (doc is null)
                continue;

            var pages = ResolveExtractionPageRows(match, pagesById, pagesByPath);
            var pageQuality = BuildPageExtractionQuality(match, pages);
            var documentSignals = doc.PageReviewRecommendedCount > 0
                ? ParseJsonStringArray(doc.SignalsJson).Append("page_review_recommended").ToArray()
                : ParseJsonStringArray(doc.SignalsJson);
            var signals = MergeExtractionSignals(documentSignals, pageQuality?.Signals);
            var diagnosticSummary = BuildRagExtractionDiagnosticSummary(doc);
            var item = new RagItemExtractionQualityDto(
                ExtractionSource: doc.ExtractionSource,
                OcrAttempted: doc.OcrAttempted,
                OcrApplied: doc.OcrApplied,
                DocumentQualityStatus: doc.QualityStatus,
                DocumentExtractionConfidence: doc.ExtractionConfidence,
                DocumentManualReviewRecommended: doc.ManualReviewRecommended,
                PageQualityStatus: pageQuality?.QualityStatus,
                PageExtractionConfidence: pageQuality?.ExtractionConfidence,
                PageManualReviewRecommended: pageQuality?.ManualReviewRecommended,
                TextStatus: pageQuality?.TextStatus ?? doc.TextStatus,
                OcrRecommended: doc.OcrRecommended,
                Signals: signals.Length == 0 ? null : signals,
                DiagnosticSummary: diagnosticSummary);

            byMatch[BuildExtractionQualityMatchKey(match)] = item;
        }

        return byMatch;
    }

    private static RagItemExtractionQualityDto? ResolveExtractionQuality(
        RagMatch match,
        IReadOnlyDictionary<string, RagItemExtractionQualityDto> extractionQualityByMatch)
        => extractionQualityByMatch.TryGetValue(BuildExtractionQualityMatchKey(match), out var quality)
            ? quality
            : null;

    internal static List<RagQualityAdjustedMatch> BuildQualityAdjustedMatchesPreservingRank(
        IReadOnlyList<RagMatch> matches,
        IReadOnlyDictionary<string, RagItemExtractionQualityDto> extractionQualityByMatch)
    {
        var adjusted = new List<RagQualityAdjustedMatch>(matches.Count);
        foreach (var match in matches)
        {
            var extractionQuality = ResolveExtractionQuality(match, extractionQualityByMatch);
            adjusted.Add(new RagQualityAdjustedMatch(
                match,
                extractionQuality,
                ApplyExtractionQualityScorePenalty(match.Score, extractionQuality)));
        }

        return adjusted;
    }

    internal static async Task<IReadOnlyDictionary<string, RagDocumentLanguageInfo>> LoadRagDocumentLanguagesAsync(
        NpgsqlDataSource ds,
        Guid tenantId,
        IReadOnlyList<RagMatch> matches,
        CancellationToken ct)
    {
        var docIds = matches
            .Select(static match => Guid.TryParse(match.DocId, out var docId) ? docId : (Guid?)null)
            .Where(static docId => docId.HasValue)
            .Select(static docId => docId!.Value)
            .Distinct()
            .ToArray();

        if (docIds.Length == 0)
            return new Dictionary<string, RagDocumentLanguageInfo>(StringComparer.OrdinalIgnoreCase);

        await using var conn = await ds.OpenConnectionAsync(ct);
        const string sql = """
SELECT
  d.doc_id::text AS "DocId",
  profile.language AS "ProfileLanguage",
  summary.doc_language AS "SummaryLanguage",
  run.payload ->> 'documentLanguage' AS "RunDocumentLanguage"
FROM documents d
LEFT JOIN LATERAL (
  SELECT NULLIF(BTRIM(p.language), '') AS language
  FROM document_profiles p
  JOIN document_revisions r
    ON r.revision_id = p.revision_id
   AND r.tenant_id = p.tenant_id
   AND r.doc_id = p.doc_id
  WHERE p.tenant_id = d.tenant_id
    AND p.doc_id = d.doc_id
    AND r.indexed_version = COALESCE(d.indexed_version, 0)
  ORDER BY
    (NULLIF(BTRIM(p.language), 'und') IS NULL) ASC,
    CASE p.profile_version
      WHEN 'llm_backoffice_v1' THEN 0
      WHEN 'foundation_v1' THEN 1
      ELSE 2
    END,
    r.published_at DESC NULLS LAST,
    p.profile_version ASC
  LIMIT 1
) profile ON true
LEFT JOIN LATERAL (
  SELECT NULLIF(BTRIM(s.doc_language), '') AS doc_language
  FROM document_summaries s
  WHERE s.tenant_id = d.tenant_id
    AND s.doc_id = d.doc_id
    AND s.level = 'medium'
    AND s.source_hash = saaia_document_summary_source_hash(d.content_hash, d.doc_path, d.file_size, d.file_mtime, d.indexed_version)
  ORDER BY s.updated_at DESC NULLS LAST, s.created_at DESC NULLS LAST
  LIMIT 1
) summary ON true
LEFT JOIN LATERAL (
  SELECT pr.payload
  FROM document_processing_runs pr
  WHERE pr.tenant_id=d.tenant_id
    AND pr.doc_id=d.doc_id
    AND pr.action='upsert'
    AND pr.status='done'
    AND (
      pr.revision_id IN (
        SELECT r.revision_id
        FROM document_revisions r
        WHERE r.tenant_id=d.tenant_id
          AND r.doc_id=d.doc_id
          AND r.indexed_version = COALESCE(d.indexed_version, 0)
      )
      OR pr.indexed_version_after = COALESCE(d.indexed_version, 0)
    )
  ORDER BY
    (pr.indexed_version_after = COALESCE(d.indexed_version, 0)) DESC,
    pr.finished_at DESC NULLS LAST,
    pr.started_at DESC NULLS LAST
  LIMIT 1
) run ON true
WHERE d.tenant_id=@tenant
  AND d.doc_id = ANY(@docIds);
""";

        var rows = await conn.QueryAsync<RagDocumentLanguageRow>(new CommandDefinition(
            sql,
            new { tenant = tenantId, docIds },
            cancellationToken: ct));

        return rows.ToDictionary(
            static row => row.DocId,
            static row =>
            {
                var profileLanguage = NormalizeRagLanguageTag(row.ProfileLanguage);
                var summaryLanguage = NormalizeRagLanguageTag(row.SummaryLanguage);
                var runLanguage = NormalizeRagLanguageTag(row.RunDocumentLanguage);
                var docLanguage = !string.Equals(profileLanguage, "und", StringComparison.Ordinal)
                    ? profileLanguage
                    : !string.Equals(summaryLanguage, "und", StringComparison.Ordinal)
                        ? summaryLanguage
                        : runLanguage;
                return new RagDocumentLanguageInfo(
                    DocLanguage: docLanguage,
                    ProfileLanguage: string.Equals(profileLanguage, "und", StringComparison.Ordinal) ? null : profileLanguage);
            },
            StringComparer.OrdinalIgnoreCase);
    }

    private static RagDocumentLanguageInfo ResolveDocumentLanguageInfo(
        RagMatch match,
        IReadOnlyDictionary<string, RagDocumentLanguageInfo> languagesByDocId)
    {
        if (Guid.TryParse(match.DocId, out var docId)
            && languagesByDocId.TryGetValue(docId.ToString(), out var byDashedId))
            return byDashedId;
        if (Guid.TryParse(match.DocId, out docId)
            && languagesByDocId.TryGetValue(docId.ToString("N"), out var byCompactId))
            return byCompactId;
        return new RagDocumentLanguageInfo("und", null);
    }

    internal static async Task<IReadOnlyDictionary<string, string>> LoadRagDocumentSourceHashesAsync(
        NpgsqlDataSource ds,
        Guid tenantId,
        IReadOnlyList<RagMatch> matches,
        CancellationToken ct)
    {
        var docIds = matches
            .Select(static match => Guid.TryParse(match.DocId, out var docId) ? docId : (Guid?)null)
            .Where(static docId => docId.HasValue)
            .Select(static docId => docId!.Value)
            .Distinct()
            .ToArray();
        var docPaths = matches
            .Select(static match => NormalizeDocumentSourceHashPathKey(match.DocPath))
            .Where(static path => !string.IsNullOrWhiteSpace(path))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();

        if (docIds.Length == 0 && docPaths.Length == 0)
            return new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);

        await using var conn = await ds.OpenConnectionAsync(ct);
        const string sql = """
SELECT
  d.doc_id::text AS "DocId",
  d.doc_path     AS "DocPath",
  saaia_document_summary_source_hash(d.content_hash, d.doc_path, d.file_size, d.file_mtime, d.indexed_version) AS "SourceHash"
FROM documents d
WHERE d.tenant_id=@tenant
  AND (d.doc_id = ANY(@docIds) OR d.doc_path = ANY(@docPaths));
""";

        var rows = await conn.QueryAsync<RagDocumentSourceHashRow>(new CommandDefinition(
            sql,
            new { tenant = tenantId, docIds, docPaths },
            cancellationToken: ct));

        var result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var row in rows.Where(static row => !string.IsNullOrWhiteSpace(row.SourceHash)))
        {
            void Add(string? key)
            {
                if (!string.IsNullOrWhiteSpace(key) && !result.ContainsKey(key))
                    result[key] = row.SourceHash!;
            }

            Add(row.DocId);
            if (Guid.TryParse(row.DocId, out var docId))
                Add(docId.ToString("N"));
            Add(NormalizeDocumentSourceHashPathKey(row.DocPath));
        }

        return result;
    }

    internal static string? ResolveDocumentSourceHash(
        RagMatch match,
        IReadOnlyDictionary<string, string> sourceHashesByDocId)
    {
        if (Guid.TryParse(match.DocId, out var docId)
            && sourceHashesByDocId.TryGetValue(docId.ToString(), out var byDashedId))
            return byDashedId;
        if (Guid.TryParse(match.DocId, out docId)
            && sourceHashesByDocId.TryGetValue(docId.ToString("N"), out var byCompactId))
            return byCompactId;
        var pathKey = NormalizeDocumentSourceHashPathKey(match.DocPath);
        if (!string.IsNullOrWhiteSpace(pathKey)
            && sourceHashesByDocId.TryGetValue(pathKey, out var byPath))
            return byPath;
        return null;
    }

    private static string NormalizeDocumentSourceHashPathKey(string? docPath)
        => string.IsNullOrWhiteSpace(docPath)
            ? string.Empty
            : docPath.Trim().Replace('\\', '/').TrimStart('/');

    private static string NormalizeRagLanguageTag(string? language)
    {
        if (string.IsNullOrWhiteSpace(language))
            return "und";

        var normalized = language.Trim().Replace('_', '-').ToLowerInvariant();
        if (normalized.Contains(',', StringComparison.Ordinal))
            normalized = normalized.Split(',', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).FirstOrDefault() ?? string.Empty;
        if (normalized.Contains('+', StringComparison.Ordinal))
            normalized = normalized.Split('+', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).FirstOrDefault() ?? string.Empty;

        if (string.Equals(normalized, "und", StringComparison.Ordinal))
            return "und";

        var parts = normalized.Split('-', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        if (parts.Length == 0 || parts.Length > 5)
            return "und";
        if (parts[0].Length is < 2 or > 8 || !parts[0].All(char.IsLetter))
            return "und";

        return parts.Skip(1).All(static part =>
            part.Length is >= 2 and <= 8 && part.All(static ch => char.IsLetterOrDigit(ch)))
            ? normalized
            : "und";
    }

    internal static double ApplyExtractionQualityScorePenalty(double score, RagItemExtractionQualityDto? quality)
    {
        if (quality is null)
            return score;

        var multiplier = 1.0;
        if (quality.DocumentManualReviewRecommended == true)
            multiplier *= 0.90;
        if (quality.PageManualReviewRecommended == true)
            multiplier *= 0.82;

        var confidence = quality.PageExtractionConfidence ?? quality.DocumentExtractionConfidence;
        if (confidence is <= 0.35)
            multiplier *= 0.78;
        else if (confidence is <= 0.50)
            multiplier *= 0.85;
        else if (confidence is <= 0.70)
            multiplier *= 0.93;

        var status = string.Join(' ', quality.PageQualityStatus, quality.DocumentQualityStatus, quality.TextStatus)
            .ToLowerInvariant();
        if (status.Contains("ocr_failed", StringComparison.Ordinal)
            || status.Contains("low_confidence", StringComparison.Ordinal)
            || status.Contains("manual_review", StringComparison.Ordinal))
        {
            multiplier *= 0.90;
        }

        return Math.Round(Math.Clamp(score * multiplier, 0.0, 1.02), 6);
    }

    private static RagExtractionDocumentQualityRow? ResolveExtractionDocumentQuality(
        RagMatch match,
        IReadOnlyDictionary<Guid, RagExtractionDocumentQualityRow> docById,
        IReadOnlyDictionary<string, RagExtractionDocumentQualityRow> docByPath)
    {
        if (Guid.TryParse(match.DocId, out var docId) && docById.TryGetValue(docId, out var byId))
            return byId;

        var docPath = NormalizeRagDocPath(match.DocPath);
        return !string.IsNullOrWhiteSpace(docPath) && docByPath.TryGetValue(docPath, out var byPath)
            ? byPath
            : null;
    }

    private static IReadOnlyList<RagExtractionPageQualityRow> ResolveExtractionPageRows(
        RagMatch match,
        IReadOnlyDictionary<Guid, RagExtractionPageQualityRow[]> pagesById,
        IReadOnlyDictionary<string, RagExtractionPageQualityRow[]> pagesByPath)
    {
        if (Guid.TryParse(match.DocId, out var docId) && pagesById.TryGetValue(docId, out var byId))
            return byId;

        var docPath = NormalizeRagDocPath(match.DocPath);
        return !string.IsNullOrWhiteSpace(docPath) && pagesByPath.TryGetValue(docPath, out var byPath)
            ? byPath
            : [];
    }

    private static RagExtractionPageQuality? BuildPageExtractionQuality(
        RagMatch match,
        IReadOnlyList<RagExtractionPageQualityRow> pages)
    {
        if (!match.PageStart.HasValue || pages.Count == 0)
            return null;

        var start = Math.Max(1, match.PageStart.Value);
        var end = Math.Max(start, match.PageEnd ?? start);
        var reviews = pages
            .Where(page => page.PageNumber >= start && page.PageNumber <= end)
            .Select(page => ExtractionQualityDiagnostics.AssessPage(
                page.WordCount,
                page.CharCount,
                page.ImageCount,
                page.UnitCount,
                CountSuspiciousExtractionUnits(page.UnitTextsJson),
                page.ChunkCount,
                ParseJsonStringArray(page.SignalsJson)))
            .ToArray();
        if (reviews.Length == 0)
            return null;

        var selected = reviews
            .OrderBy(static review => review.ExtractionConfidence)
            .ThenByDescending(static review => review.ManualReviewRecommended)
            .First();
        var signals = reviews
            .SelectMany(static review => review.Signals)
            .Where(static signal => !string.IsNullOrWhiteSpace(signal))
            .Select(static signal => signal.Trim())
            .Distinct(StringComparer.Ordinal)
            .Take(8)
            .ToArray();

        return new RagExtractionPageQuality(
            selected.Status,
            selected.ExtractionConfidence,
            selected.ManualReviewRecommended,
            selected.TextStatus,
            signals);
    }

    private static int CountSuspiciousExtractionUnits(string? unitTextsJson)
        => ParseJsonStringArray(unitTextsJson).Count(OcrNoiseFilter.LooksLikeProbableNoiseText);

    private static string[] MergeExtractionSignals(params IReadOnlyList<string>?[] signalGroups)
        => signalGroups
            .Where(static group => group is not null)
            .SelectMany(static group => group!)
            .Where(static signal => !string.IsNullOrWhiteSpace(signal))
            .Select(static signal => signal.Trim())
            .Distinct(StringComparer.Ordinal)
            .Take(8)
            .ToArray();

    private static RagItemExtractionDiagnosticSummaryDto? BuildRagExtractionDiagnosticSummary(RagExtractionDocumentQualityRow row)
    {
        var ocrDiagnostics = ParseRagOcrDiagnostics(row.OcrDiagnosticsJson);
        var summary = new RagItemExtractionDiagnosticSummaryDto(
            NativeTextStatus: NullIfWhiteSpace(row.NativeTextStatus),
            NativeOcrRecommended: row.NativeOcrRecommended,
            OcrMode: ocrDiagnostics.Mode,
            OcrLanguages: NullIfWhiteSpace(row.OcrLanguages),
            OcrDurationMs: row.OcrDurationMs,
            OcrFailureReason: ocrDiagnostics.FailureReason,
            OcrAppliedReason: ocrDiagnostics.AppliedReason,
            OcrTimedOut: ocrDiagnostics.TimedOut == true ? true : null,
            OcrAttemptedPageCount: PositiveOrNull(ocrDiagnostics.AttemptedPageCount.GetValueOrDefault()),
            OcrSkippedPageCount: PositiveOrNull(ocrDiagnostics.SkippedPageCount.GetValueOrDefault()),
            OcrPagesWithNovelTextCount: PositiveOrNull(ocrDiagnostics.PagesWithNovelTextCount.GetValueOrDefault()),
            PageCount: PositiveOrNull(row.PageCount),
            TextPageCount: row.PageCount > 0 ? row.TextPageCount : null,
            EmptyPageCount: row.PageCount > 0 ? row.EmptyPageCount : null,
            SparsePageCount: row.PageCount > 0 ? row.SparsePageCount : null,
            ImagePageCount: PositiveOrNull(row.ImagePageCount),
            PageWarningCount: PositiveOrNull(row.PageWarningCount),
            PageReviewRecommendedCount: PositiveOrNull(row.PageReviewRecommendedCount));

        return HasRagExtractionDiagnosticValue(summary) ? summary : null;
    }

    private static bool HasRagExtractionDiagnosticValue(RagItemExtractionDiagnosticSummaryDto summary)
        => !string.IsNullOrWhiteSpace(summary.NativeTextStatus)
           || summary.NativeOcrRecommended is not null
           || !string.IsNullOrWhiteSpace(summary.OcrMode)
           || !string.IsNullOrWhiteSpace(summary.OcrLanguages)
           || summary.OcrDurationMs is not null
           || !string.IsNullOrWhiteSpace(summary.OcrFailureReason)
           || !string.IsNullOrWhiteSpace(summary.OcrAppliedReason)
           || summary.OcrTimedOut is not null
           || summary.OcrAttemptedPageCount is not null
           || summary.OcrSkippedPageCount is not null
           || summary.OcrPagesWithNovelTextCount is not null
           || summary.PageCount is not null
           || summary.ImagePageCount is not null
           || summary.PageWarningCount is not null
           || summary.PageReviewRecommendedCount is not null;

    private static RagOcrDiagnosticsSummary ParseRagOcrDiagnostics(string? json)
    {
        if (string.IsNullOrWhiteSpace(json) || string.Equals(json, "null", StringComparison.OrdinalIgnoreCase))
            return new RagOcrDiagnosticsSummary();

        try
        {
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;
            if (root.ValueKind != JsonValueKind.Object)
                return new RagOcrDiagnosticsSummary();

            var failureReason = GetRagJsonString(root, "failureReason");
            var timedOut = GetRagJsonBool(root, "timedOut");
            var imageFailureReason = default(string);
            var imageTimedOut = false;
            if (root.TryGetProperty("imagePageDiagnostics", out var imageDiagnostics)
                && imageDiagnostics.ValueKind == JsonValueKind.Array)
            {
                foreach (var item in imageDiagnostics.EnumerateArray())
                {
                    if (item.ValueKind != JsonValueKind.Object)
                        continue;

                    imageTimedOut |= GetRagJsonBool(item, "timedOut") == true;
                    var status = GetRagJsonString(item, "status");
                    var reason = GetRagJsonString(item, "reason");
                    if (imageFailureReason is null
                        && (ContainsRagOcrFailure(status) || ContainsRagOcrFailure(reason) || GetRagJsonBool(item, "timedOut") == true))
                    {
                        imageFailureReason = NullIfWhiteSpace(reason) ?? NullIfWhiteSpace(status) ?? "ocr_failed";
                    }
                }
            }

            return new RagOcrDiagnosticsSummary(
                Mode: NullIfWhiteSpace(GetRagJsonString(root, "mode")),
                FailureReason: NullIfWhiteSpace(failureReason) ?? imageFailureReason,
                AppliedReason: NullIfWhiteSpace(GetRagJsonString(root, "appliedReason")),
                TimedOut: timedOut == true || imageTimedOut,
                AttemptedPageCount: GetRagJsonInt(root, "attemptedPageCount"),
                SkippedPageCount: GetRagJsonInt(root, "skippedPageCount"),
                PagesWithNovelTextCount: CountRagJsonArray(root, "pagesWithNovelText"));
        }
        catch (JsonException)
        {
            return new RagOcrDiagnosticsSummary();
        }
    }

    private static bool ContainsRagOcrFailure(string? value)
        => !string.IsNullOrWhiteSpace(value)
           && (value.Contains("fail", StringComparison.OrdinalIgnoreCase)
               || value.Contains("timeout", StringComparison.OrdinalIgnoreCase)
               || value.Contains("timed_out", StringComparison.OrdinalIgnoreCase));

    private static string? GetRagJsonString(JsonElement source, string propertyName)
        => source.TryGetProperty(propertyName, out var property) && property.ValueKind == JsonValueKind.String
            ? property.GetString()
            : null;

    private static int? GetRagJsonInt(JsonElement source, string propertyName)
    {
        if (!source.TryGetProperty(propertyName, out var property))
            return null;
        if (property.ValueKind == JsonValueKind.Number && property.TryGetInt32(out var value))
            return value;
        return property.ValueKind == JsonValueKind.String && int.TryParse(property.GetString(), out value)
            ? value
            : null;
    }

    private static bool? GetRagJsonBool(JsonElement source, string propertyName)
    {
        if (!source.TryGetProperty(propertyName, out var property))
            return null;
        if (property.ValueKind == JsonValueKind.True)
            return true;
        if (property.ValueKind == JsonValueKind.False)
            return false;
        return property.ValueKind == JsonValueKind.String && bool.TryParse(property.GetString(), out var value)
            ? value
            : null;
    }

    private static int? CountRagJsonArray(JsonElement source, string propertyName)
        => source.TryGetProperty(propertyName, out var property) && property.ValueKind == JsonValueKind.Array
            ? property.GetArrayLength()
            : null;

    private static int? PositiveOrNull(int value)
        => value > 0 ? value : null;

    private static string? NullIfWhiteSpace(string? value)
        => string.IsNullOrWhiteSpace(value) ? null : value.Trim();

    internal static string BuildExtractionQualityMatchKey(RagMatch match)
    {
        var identity = Guid.TryParse(match.DocId, out var docId)
            ? docId.ToString("N")
            : NormalizeRagDocPath(match.DocPath) ?? string.Empty;
        return $"{identity}|{match.PageStart?.ToString(CultureInfo.InvariantCulture) ?? ""}|{match.PageEnd?.ToString(CultureInfo.InvariantCulture) ?? ""}";
    }

    private static string? NormalizeRagDocPath(string? docPath)
    {
        if (string.IsNullOrWhiteSpace(docPath))
            return null;

        var normalized = docPath.Trim().Replace('\\', '/').TrimStart('/');
        return string.IsNullOrWhiteSpace(normalized) ? null : normalized;
    }

    internal static async Task<IReadOnlyDictionary<string, bool?>> LoadHypQuestionsMatchedByDocPathAsync(
        NpgsqlDataSource ds,
        Guid tenantId,
        string query,
        IReadOnlyList<RagMatch> matches,
        CancellationToken ct)
    {
        var docPaths = matches
            .Select(static match => NormalizeRagDocPath(match.DocPath))
            .Where(static path => !string.IsNullOrWhiteSpace(path))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();

        if (docPaths.Length == 0)
            return new Dictionary<string, bool?>(StringComparer.OrdinalIgnoreCase);

        await using var conn = await ds.OpenConnectionAsync(ct);
        var docs = (await conn.QueryAsync<CapabilityAHypQuestionDocRow>(new CommandDefinition(
            """
SELECT d.doc_id AS "DocId",
       d.doc_path AS "DocPath",
       d.doc_name AS "DocName",
       d.indexed_version AS "IndexedVersion",
       COALESCE(to_jsonb(profile.hypothetical_questions)::text, '[]') AS "HypotheticalQuestionsJson"
FROM documents d
LEFT JOIN document_revisions r
  ON r.tenant_id = d.tenant_id
 AND r.doc_id = d.doc_id
 AND r.indexed_version = d.indexed_version
LEFT JOIN LATERAL (
    SELECT COALESCE(
        ARRAY_AGG(DISTINCT NULLIF(BTRIM(question.text), ''))
            FILTER (WHERE NULLIF(BTRIM(question.text), '') IS NOT NULL),
        ARRAY[]::text[]) AS hypothetical_questions
    FROM document_profiles p
    CROSS JOIN LATERAL unnest(COALESCE(p.hypothetical_questions, ARRAY[]::text[])) AS question(text)
    WHERE p.tenant_id = r.tenant_id
      AND p.revision_id = r.revision_id
) profile ON TRUE
WHERE d.tenant_id=@tenant
  AND ltrim(replace(d.doc_path, chr(92), '/'), '/') = ANY(@docPaths)
  AND d.indexed_version > 0
ORDER BY d.doc_path;
""",
            new
            {
                tenant = tenantId,
                docPaths
            },
            cancellationToken: ct)))
            .Select(static row => new CapabilityAHypQuestionDoc(
                row.DocId,
                row.DocPath,
                row.DocName,
                row.IndexedVersion,
                ParseJsonStringArray(row.HypotheticalQuestionsJson)))
            .ToArray();

        var docsMissingStoredQuestions = docs
            .Where(static doc => doc.HypotheticalQuestions.Length == 0)
            .ToArray();
        var missingDocVersions = docsMissingStoredQuestions
            .Select(static doc => (doc.DocId, doc.IndexedVersion))
            .ToArray();
        IReadOnlyDictionary<Guid, string[]> sectionTitlesByDocId = new Dictionary<Guid, string[]>();
        IReadOnlyDictionary<Guid, string[]> excerptsByDocId = new Dictionary<Guid, string[]>();

        if (missingDocVersions.Length > 0)
        {
            sectionTitlesByDocId = await RuntimeGovernanceService.LoadCapabilityBSectionTitlesBatchAsync(
                conn,
                tenantId,
                missingDocVersions,
                limit: 3,
                ct);
            excerptsByDocId = await RuntimeGovernanceService.LoadCapabilityBUnitExcerptsBatchAsync(
                conn,
                tenantId,
                missingDocVersions,
                limit: 2,
                ct);
        }

        var result = new Dictionary<string, bool?>(StringComparer.OrdinalIgnoreCase);
        foreach (var doc in docs)
        {
            IReadOnlyList<string> hypotheticalQuestions = doc.HypotheticalQuestions;
            if (hypotheticalQuestions.Count == 0)
            {
                sectionTitlesByDocId.TryGetValue(doc.DocId, out var sectionTitles);
                excerptsByDocId.TryGetValue(doc.DocId, out var excerpts);
                hypotheticalQuestions = RuntimeGovernanceService.BuildCapabilityAHypotheticalQuestions(
                    doc.DocName,
                    sectionTitles ?? Array.Empty<string>(),
                    excerpts ?? Array.Empty<string>());
            }

            var matched = hypotheticalQuestions.Count == 0
                ? (bool?)null
                : ComputeHypQuestionsMatched(query, hypotheticalQuestions);
            var normalizedDocPath = NormalizeRagDocPath(doc.DocPath);
            if (!string.IsNullOrWhiteSpace(normalizedDocPath))
                result[normalizedDocPath] = matched;
            if (!string.IsNullOrWhiteSpace(doc.DocPath))
                result[doc.DocPath] = matched;
        }

        return result;
    }

    internal static async Task<RagSearchResponse> SearchCoreAsync(
        HttpContext ctx,
        NpgsqlDataSource ds,
        RagOptions rag,
        IHttpClientFactory httpFactory,
        RagSearchRequestDto req)
    {
        var tenantId = ctx.GetTenantId();
        var ct = ctx.RequestAborted;

        if (string.IsNullOrWhiteSpace(req.Query))
            throw new BadHttpRequestException("query is required");

        const string catalogOverviewFallbackQuery = "Which documents are available in this category?";

        var repairedQuery = RepairLikelyMojibakeText(req.Query);
        if (!string.Equals(repairedQuery, req.Query, StringComparison.Ordinal))
            req = req with { Query = repairedQuery };

        var topK = req.TopK ?? rag.DefaultTopK;
        topK = Math.Clamp(topK, 1, rag.MaxTopK);
        var requestedTopK = topK;

        var requestedCategory = string.IsNullOrWhiteSpace(req.Category)
            ? null
            : req.Category.Trim().ToLowerInvariant();
        var categoryPath = await ResolveRagCategoryPathAsync(ds, tenantId, req.CategoryPath, req.CategoryRef, ct);
        var category = string.IsNullOrWhiteSpace(categoryPath)
            ? requestedCategory
            : null;
        var categoryQueryHint = requestedCategory
                                ?? NormalizeRagCategory(ExtractTopLevelCategoryPath(categoryPath));

        var hasDocScope = !string.IsNullOrWhiteSpace(req.DocId) || !string.IsNullOrWhiteSpace(req.DocPath);
        var hasExplicitFileDocumentHint = HasExplicitFileLookupIntent(req.Query);
        var useBareVsComparativeOperandRoute = ShouldUseBareVsComparativeOperandRoute(req.Query);
        var useChoiceBetweenLexicalRoute = ShouldUseChoiceBetweenLexicalRoute(req.Query)
            && !hasDocScope
            && !hasExplicitFileDocumentHint;
        var retrievalQuery = useChoiceBetweenLexicalRoute
            ? BuildChoiceBetweenRetrievalQuery(req.Query)
            : ResolvePrimaryRetrievalQuery(req.Query, categoryQueryHint);
        retrievalQuery = ExpandGenericTechnicalRetrievalQuery(req.Query, retrievalQuery);
        var lexicalRetrievalSurface = ResolveLexicalRetrievalSurface(req.Query, retrievalQuery);
        var usesDelimitedLexicalSurface = !string.Equals(lexicalRetrievalSurface, req.Query, StringComparison.Ordinal);
        var queryNorm = NormalizeQuery(req.Query);
        var retrievalQueryNorm = NormalizeQuery(retrievalQuery);

        var mode = ResolveEffectiveSearchMode(req.Mode, req.Query);
        topK = ResolveInternalSelectionTopK(
            req.Query,
            requestedTopK,
            rag.MaxTopK,
            hasDocScope,
            hasExplicitFileDocumentHint,
            mode);
        if (usesDelimitedLexicalSurface)
            topK = Math.Min(Math.Max(topK, 16), rag.MaxTopK);
        var preferDocumentDiversity = ShouldPreferDocumentDiversity(req.Query) && mode != "focused";
        double defMinScore = mode switch
        {
            "focused" => 0.35,
            "broad" => 0.15,
            _ => 0.25
        };
        int defCandidates = ResolveDefaultCandidateCount(mode, preferDocumentDiversity, topK);
        // CDC v3.1 §11.3: max 3 chunks per document default
        int defMaxPerDoc = ResolveDefaultMaxPerDoc(mode, preferDocumentDiversity, topK);

        var minScore = Math.Clamp(req.MinScore ?? defMinScore, 0.0, 1.0);
        var selectionMinScore = !req.MinScore.HasValue && ShouldRelaxDefaultScoreFloorForFocusedStructuredLookup(req.Query)
            ? 0.0
            : minScore;
        var candidates = Math.Clamp(req.Candidates ?? defCandidates, topK, Math.Max(topK, rag.MaxTopK * 20));
        var maxPerDoc = Math.Clamp(req.MaxPerDoc ?? defMaxPerDoc, 1, topK);
        var maxPerPage = Math.Clamp(req.MaxPerPage ?? 1, 1, topK);
        var hasExplicitMaxPerDoc = req.MaxPerDoc.HasValue;
        var hasExplicitMaxPerPage = req.MaxPerPage.HasValue;

        if (req.Diversity != null)
        {
            if (req.Diversity.MaxChunksPerDoc.HasValue)
            {
                maxPerDoc = Math.Clamp(req.Diversity.MaxChunksPerDoc.Value, 1, topK);
                hasExplicitMaxPerDoc = true;
            }
            if (req.Diversity.PreferDistinctPages == true)
            {
                maxPerPage = 1;
                hasExplicitMaxPerPage = true;
            }
        }

        if (!hasExplicitMaxPerDoc && ShouldConstrainPreciseTitleLookup(req.Query))
            maxPerDoc = Math.Min(topK, Math.Max(maxPerDoc, 2));
        if (!hasExplicitMaxPerDoc && ShouldAllowMultipleChunksForComparativeSubject(req.Query))
            maxPerDoc = Math.Min(topK, Math.Max(maxPerDoc, 2));
        if (!hasExplicitMaxPerPage && ShouldConstrainPreciseTitleLookup(req.Query))
            maxPerPage = Math.Min(topK, Math.Max(maxPerPage, 2));

        var swTotal = Stopwatch.StartNew();
        var hasCategoryFilter = !string.IsNullOrWhiteSpace(category) || !string.IsNullOrWhiteSpace(categoryPath);
        var skipPreciseTitleLookupForDocumentOverview = ShouldSkipPreciseTitleLookupForDocumentOverview(
            req.Query,
            hasDocScope,
            mode);
        var skipChunkRetrieversForDocumentOverview = ShouldSkipChunkRetrieversForDocumentOverview(req.Query, hasDocScope, mode);
        var forceDocumentRoleProfileFallback = !hasDocScope
            && hasCategoryFilter
            && (ContainsDocumentRoleClassificationSurface(req.Query)
                || ContainsDelimitedDocumentRoleClassificationSurface(req.Query));
        var preferUnquotedTitleAnchorRoute = !hasDocScope
            && !forceDocumentRoleProfileFallback
            && ShouldProbeUnquotedTitleAnchorRoute(
                req.Query,
                skipChunkRetrieversForDocumentOverview,
                useScopedProfileFallback: false);
        var hasQuotedLookupPhrases = ExtractQuotedLookupPhrases(req.Query).Count > 0;
        var skipUnquotedPreciseTitleScans = preferUnquotedTitleAnchorRoute
            && !hasQuotedLookupPhrases;
        var skipUnquotedCategoryTitleScans = hasCategoryFilter
            && skipUnquotedPreciseTitleScans;
        var useScopedProfileFallback = !hasDocScope
            && (forceDocumentRoleProfileFallback
                || (!preferUnquotedTitleAnchorRoute
                    && ShouldUseScopedProfileFallback(req.Query, hasCategoryFilter, mode)));
        var useScopedCatalogDocumentOverviewFallback = !hasDocScope
            && hasCategoryFilter
            && ShouldUseScopedCatalogDocumentOverviewFallback(req.Query, mode);
        if (useScopedCatalogDocumentOverviewFallback)
        {
            retrievalQuery = catalogOverviewFallbackQuery;
            retrievalQueryNorm = NormalizeQuery(retrievalQuery);
        }
        var selectionQuery = useScopedCatalogDocumentOverviewFallback
            ? catalogOverviewFallbackQuery
            : usesDelimitedLexicalSurface
                ? lexicalRetrievalSurface
            : req.Query;
        var allowSparseAssistForScopedProfileFallback =
            useScopedProfileFallback && ShouldAllowSparseAssistForScopedProfileFallback(req.Query);
        var allowSparseAssistForBroadDiversity =
            !hasDocScope && ShouldAllowSparseAssistForBroadDiversity(req.Query);
        var skipUnanchoredTitleAnchorRouteForBroadDiversity =
            useChoiceBetweenLexicalRoute
            || ShouldSkipUnanchoredTitleAnchorRouteForBroadDiversity(req.Query);
        var skipSparseRetrieverForBroadDiversity = !hasDocScope
            && !allowSparseAssistForBroadDiversity
            && (ShouldSkipSparseRetrieverForBroadDiversity(req.Query, mode)
                || ShouldSkipSparseRetrieverForQuantityLookup(req.Query, mode));
        var skipSparseProfileCardAssist = !hasDocScope
            && ShouldSkipSparseProfileCardAssist(req.Query, mode);
        var requireDocumentOverviewProfileMatch = skipChunkRetrieversForDocumentOverview
            && ShouldRequireDocumentOverviewProfileMatch(req.Query);
        using var searchActivity = RetrievalTelemetry.StartSearchActivity(mode, hasCategoryFilter, hasDocScope, topK, candidates, req.Query);
        var skipLocalTitleTokenRoute = forceDocumentRoleProfileFallback
            || skipUnquotedCategoryTitleScans
            || skipUnquotedPreciseTitleScans
            || ShouldSkipLocalTitleTokenRouteForIndexedTitleAnchors(
            req.Query,
            hasCategoryScope: hasCategoryFilter,
            hasDocScope: hasDocScope,
            skipChunkRetrieversForDocumentOverview: skipChunkRetrieversForDocumentOverview,
            useScopedProfileFallback: useScopedProfileFallback);
        var skipQuotedTitleFullScan = ShouldSkipQuotedTitleFullScan(req.Query, hasDocScope);

        async Task<(T Result, long DurationMs)> MeasurePhaseAsync<T>(
            string phaseName,
            string? retriever,
            Func<Task<T>> action,
            Func<T, int>? getReturnedCount = null)
        {
            using var phaseActivity = RetrievalTelemetry.StartPhaseActivity(phaseName);
            var swPhase = Stopwatch.StartNew();

            try
            {
                var result = await action();
                swPhase.Stop();
                RetrievalTelemetry.CompletePhase(phaseActivity, getReturnedCount?.Invoke(result) ?? 0, swPhase.ElapsedMilliseconds, retriever);
                return (result, swPhase.ElapsedMilliseconds);
            }
            catch (Exception ex)
            {
                swPhase.Stop();
                RetrievalTelemetry.MarkPhaseError(phaseActivity, ex);
                throw;
            }
        }

        var degradedRetrievers = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var degradedRetrieverErrors = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        object degradedRetrieversLock = new();

        void MarkRetrieverDegraded(string retriever, string? reason = null)
        {
            if (string.IsNullOrWhiteSpace(retriever))
                return;

            var normalized = retriever.Trim().ToLowerInvariant();
            lock (degradedRetrieversLock)
            {
                degradedRetrievers.Add(normalized);
                if (!string.IsNullOrWhiteSpace(reason))
                    degradedRetrieverErrors[normalized] = reason.Trim();
            }
        }

        var (exactMatches, exactMs) = await MeasurePhaseAsync(
            phaseName: "retrieval_exact_match",
            retriever: "exact_match",
            action: () => SearchExactMatchesAsync(ds, tenantId, req.Query, category, req.DocId, req.DocPath, ResolveExactMatchCandidateLimit(topK), ct, categoryPath),
            getReturnedCount: static matches => matches.Count);
        long titleAnchorRoutePhaseMs = 0;
        var (quotedTitleMatches, quotedTitleMs) = await MeasurePhaseAsync(
            phaseName: "retrieval_quoted_title",
            retriever: "quoted_title",
            action: () => skipPreciseTitleLookupForDocumentOverview || skipUnquotedPreciseTitleScans
                || skipQuotedTitleFullScan
                ? Task.FromResult(new List<RagMatch>())
                : SearchQuotedTitleMatchesAsync(ds, tenantId, req.Query, category, req.DocId, req.DocPath, topK, ct, categoryPath),
            getReturnedCount: static matches => matches.Count);
        var (quotedTitleAnchorMatches, quotedTitleAnchorMs) = await MeasurePhaseAsync(
            phaseName: "retrieval_quoted_title_anchor_route",
            retriever: "title_anchor_route",
            action: async () =>
            {
                if (skipPreciseTitleLookupForDocumentOverview
                    || !hasQuotedLookupPhrases
                    || !hasCategoryFilter
                    || hasDocScope)
                {
                    return new List<RagMatch>();
                }

                var anchorMatches = new List<RagMatch>();
                foreach (var phrase in ExtractTitleLookupPhrases(req.Query).Take(3))
                {
                    var titleAnchorQuery = phrase.Contains('"', StringComparison.Ordinal)
                        ? phrase
                        : $"\"{phrase}\"";
                    anchorMatches.AddRange(await SearchTitleAnchorRouteMatchesAsync(
                        ds,
                        tenantId,
                        titleAnchorQuery,
                        category,
                        req.DocId,
                        req.DocPath,
                        Math.Min(candidates, Math.Max(topK, 16)),
                        ct,
                        categoryPath,
                        degradedRetrieverRef: MarkRetrieverDegraded,
                        allowDirectChunkRoute: false));
                }

                return DeduplicatePreciseTitleBackfillMatches(anchorMatches)
                    .Take(Math.Min(candidates, Math.Max(topK, 16)))
                    .ToList();
            },
            getReturnedCount: static matches => matches.Count);
        titleAnchorRoutePhaseMs += quotedTitleAnchorMs;
        var (explicitDocumentTitleMatches, explicitDocumentTitleMs) = await MeasurePhaseAsync(
            phaseName: "retrieval_explicit_document_title",
            retriever: "explicit_document_title_route",
            action: () => hasExplicitFileDocumentHint
                ? SearchExplicitDocumentTitleMatchesAsync(
                    ds,
                    tenantId,
                    req.Query,
                    category,
                    req.DocId,
                    req.DocPath,
                    Math.Min(candidates, Math.Max(topK, 16)),
                    ct,
                    categoryPath,
                    degradedRetrieverRef: MarkRetrieverDegraded)
                : Task.FromResult(new List<RagMatch>()),
            getReturnedCount: static matches => matches.Count);
        titleAnchorRoutePhaseMs += explicitDocumentTitleMs;
        var (localTitleTokenMatches, localTitleTokenMs) = await MeasurePhaseAsync(
            phaseName: "retrieval_local_title_token",
            retriever: "local_title_token_route",
            action: () => skipPreciseTitleLookupForDocumentOverview
                || skipLocalTitleTokenRoute
                ? Task.FromResult(new List<RagMatch>())
                : SearchLocalTitleTokenRouteMatchesAsync(
                ds,
                tenantId,
                req.Query,
                category,
                req.DocId,
                req.DocPath,
                ResolveLocalTitleTokenCandidateLimit(topK, hasDocScope),
                ct,
                categoryPath,
                degradedRetrieverRef: MarkRetrieverDegraded),
            getReturnedCount: static matches => matches.Count);
        var titleLookupMatches = explicitDocumentTitleMatches
            .Concat(quotedTitleMatches)
            .Concat(quotedTitleAnchorMatches)
            .Concat(localTitleTokenMatches)
            .GroupBy(BuildMatchDedupKey, StringComparer.OrdinalIgnoreCase)
            .Select(static group => group
                .OrderByDescending(match => match.Score)
                .ThenBy(match => match.DocPath, StringComparer.OrdinalIgnoreCase)
                .ThenBy(match => match.ChunkIndex)
                .First())
            .OrderByDescending(static match => match.Score)
            .ThenBy(static match => match.DocPath, StringComparer.OrdinalIgnoreCase)
            .ThenBy(static match => match.ChunkIndex)
            .ToList();
        var explicitDocumentScopedBackfillQuery = hasExplicitFileDocumentHint
            ? BuildDocumentHintScopedBackfillQuery(req.Query, retrievalQuery)
            : string.Empty;
        var explicitDocumentTitleRouteReturnedContent = hasExplicitFileDocumentHint
            && explicitDocumentTitleMatches.Count > 0;
        var useExplicitDocumentScopedBackfill = ShouldUseExplicitDocumentScopedBackfillRoute(
            req.Query,
            explicitDocumentScopedBackfillQuery)
            && !explicitDocumentTitleRouteReturnedContent;
        var skipBroadRetrieversForExplicitFileHint = hasExplicitFileDocumentHint;
        var shortCircuitAfterExact = ShouldShortCircuitAfterExact(req.Query, exactMatches);
        var shortCircuitAfterQuotedTitle = false;
        var selected = new List<RagMatch>(capacity: topK);
        var selectedKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        List<RagMatch>? broadDiversityCandidateBackfillPool = null;

        long teiMs = 0;
        long rerankMs = 0;
        long sparseMs = 0;
        long qdrantMs = 0;
        long sparsePhaseMs = 0;
        long densePhaseMs = 0;
        long linkedPhaseMs = 0;
        long profilePhaseMs = 0;
        long fusionMs = 0;
        long rerankPhaseMs = 0;
        long selectionMs = 0;
        int qdrantStatus = 0;
        var sparseCommandTimeoutSeconds = RagOptions.ResolveSearchSparseCommandTimeoutSeconds(rag.SearchSparseCommandTimeoutSeconds);
        var sqlHeavyCandidateLimit = ResolveSqlHeavyRetrieverCandidateLimit(candidates, topK);

        Task<List<RagMatch>> SearchPreciseTitleRouteBackfillAsync(string titleBackfillQuery, int limit)
        {
            if (ShouldSkipLocalTitleTokenRouteForIndexedTitleAnchors(
                    titleBackfillQuery,
                    hasCategoryScope: hasCategoryFilter,
                    hasDocScope: hasDocScope,
                    skipChunkRetrieversForDocumentOverview: skipChunkRetrieversForDocumentOverview,
                    useScopedProfileFallback: useScopedProfileFallback))
            {
                return SearchTitleAnchorRouteMatchesAsync(
                    ds,
                    tenantId,
                    titleBackfillQuery,
                    category,
                    req.DocId,
                    req.DocPath,
                    limit,
                    ct,
                    categoryPath,
                    degradedRetrieverRef: MarkRetrieverDegraded,
                    allowDirectChunkRoute: false);
            }

            return SearchLocalTitleTokenRouteMatchesAsync(
                ds,
                tenantId,
                titleBackfillQuery,
                category,
                req.DocId,
                req.DocPath,
                limit,
                ct,
                categoryPath,
                degradedRetrieverRef: MarkRetrieverDegraded);
        }

        List<RagMatch>? earlyTitleAnchorRouteMatches = null;
        List<RagMatch> preciseTitleRouteReuseMatches = [];
        long earlyTitleAnchorRouteMs = 0;
        var shortCircuitAfterTitleAnchorRoute = false;
        if (!shortCircuitAfterExact
            && !shortCircuitAfterQuotedTitle
            && ShouldProbeUnquotedTitleAnchorRoute(req.Query, skipChunkRetrieversForDocumentOverview, useScopedProfileFallback))
        {
            var (probedTitleAnchorRouteMatches, measuredTitleAnchorRouteMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_title_anchor_route",
                retriever: "title_anchor_route",
                action: () => SearchTitleAnchorRouteMatchesAsync(
                    ds,
                    tenantId,
                    req.Query,
                    category,
                    req.DocId,
                    req.DocPath,
                    Math.Min(candidates, Math.Max(topK, 16)),
                    ct,
                    categoryPath,
                    degradedRetrieverRef: MarkRetrieverDegraded),
                getReturnedCount: static matches => matches.Count);
            earlyTitleAnchorRouteMatches = probedTitleAnchorRouteMatches;
            earlyTitleAnchorRouteMs = measuredTitleAnchorRouteMs;
            shortCircuitAfterTitleAnchorRoute = ShouldShortCircuitAfterTitleAnchorRoute(req.Query, probedTitleAnchorRouteMatches);
        }

        if (shortCircuitAfterExact)
        {
            AddRankedMatches(selected, selectedKeys, exactMatches, topK, minScore: 0.0, maxPerDoc, maxPerPage);
        }
        else if (shortCircuitAfterQuotedTitle)
        {
            AddRankedMatches(
                selected,
                selectedKeys,
                exactMatches.Concat(titleLookupMatches),
                topK,
                minScore: 0.0,
                maxPerDoc,
                maxPerPage,
                query: req.Query);
        }
        else if (shortCircuitAfterTitleAnchorRoute && earlyTitleAnchorRouteMatches is not null)
        {
            titleAnchorRoutePhaseMs = earlyTitleAnchorRouteMs;
            preciseTitleRouteReuseMatches = BuildReusablePreciseTitleRouteMatches(earlyTitleAnchorRouteMatches);
            AddRankedMatches(
                selected,
                selectedKeys,
                exactMatches
                    .Concat(titleLookupMatches)
                    .Concat(RankTitleAnchorRouteShortCircuitMatches(earlyTitleAnchorRouteMatches)),
                topK,
                minScore: 0.0,
                maxPerDoc,
                maxPerPage,
                query: req.Query);
        }
        else
        {
            Task<(List<RagMatch> Result, long DurationMs)> titleAnchorRouteMatchesTask = earlyTitleAnchorRouteMatches is not null
                ? Task.FromResult((earlyTitleAnchorRouteMatches, earlyTitleAnchorRouteMs))
                : skipChunkRetrieversForDocumentOverview
                  || useScopedProfileFallback
                  || skipBroadRetrieversForExplicitFileHint
                  || skipUnanchoredTitleAnchorRouteForBroadDiversity
                ? Task.FromResult((new List<RagMatch>(), 0L))
                : MeasurePhaseAsync(
                    phaseName: "retrieval_title_anchor_route",
                    retriever: "title_anchor_route",
                    action: () => SearchTitleAnchorRouteMatchesAsync(
                        ds,
                        tenantId,
                        req.Query,
                        category,
                        req.DocId,
                        req.DocPath,
                        Math.Min(candidates, Math.Max(topK, 16)),
                        ct,
                        categoryPath,
                        degradedRetrieverRef: MarkRetrieverDegraded),
                    getReturnedCount: static matches => matches.Count);
            Task<(List<RagMatch> Result, long DurationMs)> sparseMatchesTask = skipChunkRetrieversForDocumentOverview
                || (useScopedProfileFallback && !allowSparseAssistForScopedProfileFallback)
                || (skipSparseRetrieverForBroadDiversity && !allowSparseAssistForScopedProfileFallback)
                || skipBroadRetrieversForExplicitFileHint
                || useChoiceBetweenLexicalRoute
                || useBareVsComparativeOperandRoute
                ? Task.FromResult((new List<RagMatch>(), 0L))
                : MeasurePhaseAsync(
                    phaseName: "retrieval_sparse",
                    retriever: "sparse_bm25",
                    action: () => SearchSparseMatchesAsync(
                        ds,
                        tenantId,
                        lexicalRetrievalSurface,
                        category,
                        req.DocId,
                        req.DocPath,
                        sqlHeavyCandidateLimit,
                        ct,
                        sparseMsRef: value => sparseMs = value,
                        lexicalExpansionQuery: retrievalQuery,
                        categoryPath: categoryPath,
                        includeProfileCardMatches: !skipSparseProfileCardAssist && !usesDelimitedLexicalSurface,
                        degradedRetrieverRef: MarkRetrieverDegraded,
                        commandTimeoutSeconds: sparseCommandTimeoutSeconds),
                    getReturnedCount: static matches => matches.Count);
            Task<(List<RagMatch> Result, long DurationMs)> denseMatchesTask = skipChunkRetrieversForDocumentOverview
                || useScopedProfileFallback
                || skipBroadRetrieversForExplicitFileHint
                ? Task.FromResult((new List<RagMatch>(), 0L))
                : MeasurePhaseAsync(
                    phaseName: "retrieval_dense",
                    retriever: "dense_qdrant",
                    action: () => SearchDenseMatchesAsync(
                        ds,
                        httpFactory,
                        rag,
                        tenantId,
                        retrievalQueryNorm,
                        category,
                        req.DocId,
                        req.DocPath,
                        candidates,
                        ct,
                        teiMsRef: value => teiMs = value,
                        qdrantMsRef: value => qdrantMs = value,
                        qdrantStatusRef: value => qdrantStatus = value,
                        categoryPath: categoryPath,
                        degradedRetrieverRef: MarkRetrieverDegraded),
                    getReturnedCount: static matches => matches.Count);
            var skipDocumentProfileSearchForPreciseLookup =
                !skipChunkRetrieversForDocumentOverview
                && !useScopedProfileFallback
                && !useChoiceBetweenLexicalRoute
                && (useBareVsComparativeOperandRoute
                    || ShouldSkipDocumentProfileSearchForPreciseLookup(req.Query)
                    || ShouldSkipDocumentProfileSearchForComparativeLookup(req.Query));
            var allowComparativeDocumentProfileAssist = ShouldAllowDocumentProfileAssistForComparativeLookup(req.Query);
            var documentProfileCandidateCount = ResolveDocumentProfileCandidateCount(
                candidates,
                topK,
                skipChunkRetrieversForDocumentOverview || useScopedProfileFallback,
                allowComparativeDocumentProfileAssist);
            var canSearchDocumentProfiles = !skipDocumentProfileSearchForPreciseLookup
                && (allowComparativeDocumentProfileAssist || !ShouldSkipDocumentProfileSearchForQuantityLookup(req.Query))
                && (skipChunkRetrieversForDocumentOverview
                    || useScopedProfileFallback
                    || useChoiceBetweenLexicalRoute
                    || !ShouldSkipDocumentProfileSearchForLowCostBroadQuery(req.Query, mode));
            var deferDocumentProfileSearch = !allowComparativeDocumentProfileAssist && ShouldDeferDocumentProfileSearch(
                canSearchDocumentProfiles,
                skipChunkRetrieversForDocumentOverview,
                useScopedProfileFallback,
                allowSparseAssistForScopedProfileFallback);
            Task<(List<RagMatch> Result, long DurationMs)> profileMatchesTask = !canSearchDocumentProfiles || deferDocumentProfileSearch
                || skipBroadRetrieversForExplicitFileHint
                ? Task.FromResult((new List<RagMatch>(), 0L))
                : SearchDocumentProfilesMeasuredAsync();
            Task<(List<RagMatch> Result, long DurationMs)> explicitDocumentScopedMatchesTask = !useExplicitDocumentScopedBackfill
                ? Task.FromResult((new List<RagMatch>(), 0L))
                : MeasurePhaseAsync(
                    phaseName: "retrieval_explicit_document_scoped_backfill",
                    retriever: "document_hint_scoped_backfill",
                    action: () => SearchDocumentHintScopedBackfillMatchesAsync(
                        ds,
                        tenantId,
                        req.Query,
                        explicitDocumentScopedBackfillQuery,
                        category,
                        categoryPath,
                        Math.Max(topK, 8),
                        ct,
                        degradedRetrieverRef: MarkRetrieverDegraded,
                        includeProfileCardMatches: false,
                        commandTimeoutSeconds: sparseCommandTimeoutSeconds),
                    getReturnedCount: static matches => matches.Count);

            Task<(List<RagMatch> Result, long DurationMs)> SearchDocumentProfilesMeasuredAsync()
                => MeasurePhaseAsync(
                    phaseName: "retrieval_document_profile",
                    retriever: "document_profile",
                    action: () => skipChunkRetrieversForDocumentOverview || useScopedProfileFallback
                        ? SearchDocumentOverviewProfileMatchesAsync(
                            ds,
                            tenantId,
                            retrievalQuery,
                            category,
                            req.DocId,
                            req.DocPath,
                            documentProfileCandidateCount,
                            ct,
                            categoryPath,
                            requireDocumentOverviewProfileMatch,
                            degradedRetrieverRef: MarkRetrieverDegraded,
                            commandTimeoutSeconds: sparseCommandTimeoutSeconds)
                        : SearchDocumentProfileMatchesAsync(
                            ds,
                            tenantId,
                            retrievalQuery,
                            category,
                            req.DocId,
                            req.DocPath,
                            documentProfileCandidateCount,
                            ct,
                            categoryPath,
                            degradedRetrieverRef: MarkRetrieverDegraded,
                            commandTimeoutSeconds: sparseCommandTimeoutSeconds),
                    getReturnedCount: static matches => matches.Count);

            await Task.WhenAll(
                titleAnchorRouteMatchesTask,
                sparseMatchesTask,
                denseMatchesTask,
                profileMatchesTask,
                explicitDocumentScopedMatchesTask);

            var (titleAnchorRouteMatches, measuredTitleAnchorRoutePhaseMs) = await titleAnchorRouteMatchesTask;
            var (sparseMatches, measuredSparsePhaseMs) = await sparseMatchesTask;
            var (denseMatches, measuredDensePhaseMs) = await denseMatchesTask;
            var (profileMatches, measuredProfilePhaseMs) = await profileMatchesTask;
            var (explicitDocumentScopedMatches, measuredExplicitDocumentScopedMs) = await explicitDocumentScopedMatchesTask;
            var effectiveSparseMatches = explicitDocumentScopedMatches.Count == 0
                ? sparseMatches
                : sparseMatches.Concat(explicitDocumentScopedMatches).ToList();
            var combinedTitleAnchorRouteMatches = quotedTitleAnchorMatches.Count == 0
                ? titleAnchorRouteMatches
                : DeduplicatePreciseTitleBackfillMatches(quotedTitleAnchorMatches.Concat(titleAnchorRouteMatches)).ToList();
            preciseTitleRouteReuseMatches = BuildReusablePreciseTitleRouteMatches(combinedTitleAnchorRouteMatches);
            titleAnchorRoutePhaseMs += measuredTitleAnchorRoutePhaseMs;
            sparsePhaseMs = measuredSparsePhaseMs + measuredExplicitDocumentScopedMs;
            densePhaseMs = measuredDensePhaseMs;
            profilePhaseMs = measuredProfilePhaseMs;

            var fusionSw = Stopwatch.StartNew();
            var exactAndQuotedMatches = titleLookupMatches.Count == 0
                ? exactMatches
                : exactMatches.Concat(titleLookupMatches).ToList();
            var fusedMatches = FuseWithRrf(exactAndQuotedMatches, effectiveSparseMatches, denseMatches, profileMatches, combinedTitleAnchorRouteMatches);
            fusedMatches = CalibrateFusedMatches(retrievalQuery, fusedMatches, req.Query);
            fusedMatches = SuppressNavigationalNoise(req.Query, fusedMatches);
            var suppressUnanchoredSpecificResults = !useScopedProfileFallback
                && !useChoiceBetweenLexicalRoute
                && ShouldSuppressUnanchoredSpecificResults(retrievalQuery, fusedMatches);
            fusionSw.Stop();
            fusionMs += fusionSw.ElapsedMilliseconds;

            if (suppressUnanchoredSpecificResults)
            {
                fusedMatches = [];
            }
            else
            {
                var (rerankAttempt, measuredRerankPhaseMs) = await MeasurePhaseAsync(
                    phaseName: "retrieval_rerank",
                    retriever: "tei_rerank",
                    action: () => TryRerankWithTeiAsync(
                        httpFactory,
                        rag,
                        retrievalQuery,
                        fusedMatches,
                        ct,
                        rerankMsRef: value => rerankMs = value),
                    getReturnedCount: static attempt => attempt.Matches.Count);
                rerankPhaseMs += measuredRerankPhaseMs;
                if (rerankAttempt.Applied)
                {
                    fusionSw.Restart();
                    fusedMatches = rerankAttempt.Matches;
                    fusedMatches = CalibrateFusedMatches(retrievalQuery, fusedMatches, selectionQuery);
                    fusedMatches = SuppressNavigationalNoise(selectionQuery, fusedMatches);
                    fusionSw.Stop();
                    fusionMs += fusionSw.ElapsedMilliseconds;
                }
                else
                {
                    fusedMatches = rerankAttempt.Matches;
                }
            }

            var selectionSw = Stopwatch.StartNew();
            var prioritizeDocumentProfilesForSelection = ShouldPrioritizeDocumentProfilesForSelection(
                preferDocumentDiversity,
                allowSparseAssistForScopedProfileFallback || allowSparseAssistForBroadDiversity,
                allowComparativeDocumentProfileAssist);
            if (ShouldRunBroadDiversityCandidateBackfill(req.Query, selected.Count, topK))
                broadDiversityCandidateBackfillPool = fusedMatches.ToList();
            AddRankedMatches(
                selected,
                selectedKeys,
                fusedMatches,
                topK,
                useScopedProfileFallback ? 0.0 : selectionMinScore,
                maxPerDoc,
                maxPerPage,
                prioritizeDocumentProfiles: prioritizeDocumentProfilesForSelection,
                query: selectionQuery);
            selectionSw.Stop();
            selectionMs += selectionSw.ElapsedMilliseconds;

            if (!skipChunkRetrieversForDocumentOverview
                && !hasExplicitFileDocumentHint
                && ShouldAllowMultipleChunksForComparativeSubject(req.Query))
            {
                var comparativeSubjectBackfillQueries = BuildComparativeSubjectBackfillQueries(req.Query);
                if (comparativeSubjectBackfillQueries.Count > 0)
                {
                    var (comparativeSubjectBackfillMatches, comparativeSubjectBackfillMs) = await MeasurePhaseAsync(
                        phaseName: "retrieval_comparative_subject_backfill",
                        retriever: "title_anchor_route",
                        action: async () =>
                        {
                            var backfill = new List<RagMatch>();
                            foreach (var focusedQuery in comparativeSubjectBackfillQueries)
                            {
                                if (!skipUnanchoredTitleAnchorRouteForBroadDiversity)
                                {
                                    backfill.AddRange(await SearchTitleAnchorRouteMatchesAsync(
                                        ds,
                                        tenantId,
                                        focusedQuery,
                                        category,
                                        req.DocId,
                                        req.DocPath,
                                        Math.Min(Math.Max(topK, 12), 32),
                                        ct,
                                        categoryPath,
                                        degradedRetrieverRef: MarkRetrieverDegraded));
                                }
                                if (!useBareVsComparativeOperandRoute)
                                {
                                    backfill.AddRange(await SearchLexicalContentFallbackMatchesAsync(
                                        ds,
                                        tenantId,
                                        focusedQuery,
                                        category,
                                        req.DocId,
                                        req.DocPath,
                                        Math.Min(Math.Max(topK, 12), 32),
                                        ct,
                                        categoryPath: categoryPath,
                                        degradedRetrieverRef: MarkRetrieverDegraded,
                                        commandTimeoutSeconds: sparseCommandTimeoutSeconds));
                                    if (!skipUnanchoredTitleAnchorRouteForBroadDiversity)
                                    {
                                        backfill.AddRange(await SearchSparseMatchesAsync(
                                            ds,
                                            tenantId,
                                            focusedQuery,
                                            category,
                                            req.DocId,
                                            req.DocPath,
                                            Math.Min(Math.Max(topK, 12), 32),
                                            ct,
                                            sparseMsRef: value => sparseMs += value,
                                            lexicalExpansionQuery: focusedQuery,
                                            categoryPath: categoryPath,
                                            includeProfileCardMatches: false,
                                            degradedRetrieverRef: MarkRetrieverDegraded,
                                            commandTimeoutSeconds: sparseCommandTimeoutSeconds));
                                    }
                                }
                            }

                            return backfill
                                .GroupBy(BuildMatchDedupKey, StringComparer.OrdinalIgnoreCase)
                                .Select(static group => group
                                    .OrderByDescending(match => match.Score)
                                    .ThenBy(match => match.ChunkIndex)
                                    .First())
                                .ToList();
                        },
                        getReturnedCount: static matches => matches.Count);
                    titleAnchorRoutePhaseMs += comparativeSubjectBackfillMs;

                    if (comparativeSubjectBackfillMatches.Count > 0)
                    {
                        selectionSw.Restart();
                        MergeComparativeSubjectBackfillMatches(
                            selected,
                            selectedKeys,
                            comparativeSubjectBackfillMatches,
                            topK,
                            minScore: 0.0,
                            maxPerDoc: Math.Max(maxPerDoc, 2),
                            maxPerPage: Math.Max(maxPerPage, 2),
                            prioritizeDocumentProfiles: prioritizeDocumentProfilesForSelection,
                            query: req.Query);
                        PromoteActionableSameDocumentEvidence(selected);
                        RebuildSelectedKeys(selected, selectedKeys);
                        selectionSw.Stop();
                        selectionMs += selectionSw.ElapsedMilliseconds;
                    }
                }
            }

            if (!skipChunkRetrieversForDocumentOverview
                && !hasExplicitFileDocumentHint
                && ShouldRunComparativeTitleBackfill(req.Query, selected))
            {
                var comparativeTitleBackfillQueries = BuildComparativeTitleBackfillQueries(
                    req.Query,
                    allowProfileAssistBackfill: allowComparativeDocumentProfileAssist);
                if (comparativeTitleBackfillQueries.Count > 0)
                {
                    var (comparativeTitleBackfillMatches, comparativeTitleBackfillMs) = await MeasurePhaseAsync(
                        phaseName: "retrieval_comparative_title_backfill",
                        retriever: "title_anchor_route",
                        action: async () =>
                        {
                            var backfill = new List<RagMatch>();
                            foreach (var focusedQuery in comparativeTitleBackfillQueries)
                            {
                                var focusedTopK = useBareVsComparativeOperandRoute
                                    ? Math.Min(Math.Max(topK, 8), 12)
                                    : Math.Min(Math.Max(topK, 12), 32);
                                if (!skipUnanchoredTitleAnchorRouteForBroadDiversity)
                                {
                                    backfill.AddRange(await SearchTitleAnchorRouteMatchesAsync(
                                        ds,
                                        tenantId,
                                        focusedQuery,
                                        category,
                                        req.DocId,
                                        req.DocPath,
                                        focusedTopK,
                                        ct,
                                        categoryPath,
                                        degradedRetrieverRef: MarkRetrieverDegraded));
                                }
                                backfill.AddRange(await SearchLexicalContentFallbackMatchesAsync(
                                    ds,
                                    tenantId,
                                    focusedQuery,
                                    category,
                                    req.DocId,
                                    req.DocPath,
                                    focusedTopK,
                                    ct,
                                    categoryPath: categoryPath,
                                    degradedRetrieverRef: MarkRetrieverDegraded,
                                    commandTimeoutSeconds: sparseCommandTimeoutSeconds));
                                if (!skipUnanchoredTitleAnchorRouteForBroadDiversity
                                    && !useBareVsComparativeOperandRoute)
                                {
                                    backfill.AddRange(await SearchSparseMatchesAsync(
                                        ds,
                                        tenantId,
                                        focusedQuery,
                                        category,
                                        req.DocId,
                                        req.DocPath,
                                        focusedTopK,
                                        ct,
                                        sparseMsRef: value => sparseMs += value,
                                        lexicalExpansionQuery: focusedQuery,
                                        categoryPath: categoryPath,
                                        includeProfileCardMatches: false,
                                        degradedRetrieverRef: MarkRetrieverDegraded,
                                        commandTimeoutSeconds: sparseCommandTimeoutSeconds));
                                }
                            }

                            return backfill
                                .GroupBy(BuildMatchDedupKey, StringComparer.OrdinalIgnoreCase)
                                .Select(static group => group
                                    .OrderByDescending(match => match.Score)
                                    .ThenBy(match => match.ChunkIndex)
                                    .First())
                                .ToList();
                        },
                        getReturnedCount: static matches => matches.Count);
                    titleAnchorRoutePhaseMs += comparativeTitleBackfillMs;

                    if (comparativeTitleBackfillMatches.Count > 0)
                    {
                        selectionSw.Restart();
                        MergeComparativeSubjectBackfillMatches(
                            selected,
                            selectedKeys,
                            comparativeTitleBackfillMatches,
                            topK,
                            minScore: 0.0,
                            maxPerDoc: Math.Max(maxPerDoc, 2),
                            maxPerPage: Math.Max(maxPerPage, 2),
                            prioritizeDocumentProfiles: prioritizeDocumentProfilesForSelection,
                            query: req.Query);
                        PromoteActionableSameDocumentEvidence(selected);
                        RebuildSelectedKeys(selected, selectedKeys);
                        selectionSw.Stop();
                        selectionMs += selectionSw.ElapsedMilliseconds;
                    }
                }
            }

            if (!skipChunkRetrieversForDocumentOverview
                && !hasExplicitFileDocumentHint
                && ShouldRunComparativeOperandProfileBackfill(req.Query, selected))
            {
                var comparativeOperandProfileQueries = BuildComparativeOperandProfileBackfillQueries(req.Query);
                if (comparativeOperandProfileQueries.Count > 0)
                {
                    var (comparativeOperandProfileMatches, comparativeOperandProfileMs) = await MeasurePhaseAsync(
                        phaseName: "retrieval_comparative_operand_profile_backfill",
                        retriever: "document_profile",
                        action: async () =>
                        {
                            var backfill = new List<RagMatch>();
                            foreach (var focusedQuery in comparativeOperandProfileQueries)
                            {
                                backfill.AddRange(await SearchDocumentProfileMatchesAsync(
                                    ds,
                                    tenantId,
                                    focusedQuery,
                                    category,
                                    req.DocId,
                                    req.DocPath,
                                    Math.Min(Math.Max(topK, 12), 32),
                                    ct,
                                    categoryPath,
                                    degradedRetrieverRef: MarkRetrieverDegraded,
                                    commandTimeoutSeconds: sparseCommandTimeoutSeconds));
                            }

                            return backfill
                                .GroupBy(BuildMatchDedupKey, StringComparer.OrdinalIgnoreCase)
                                .Select(static group => group
                                    .OrderByDescending(match => match.Score)
                                    .ThenBy(match => match.ChunkIndex)
                                    .First())
                                .ToList();
                        },
                        getReturnedCount: static matches => matches.Count);
                    profilePhaseMs += comparativeOperandProfileMs;

                    if (comparativeOperandProfileMatches.Count > 0)
                    {
                        selectionSw.Restart();
                        MergeComparativeSubjectBackfillMatches(
                            selected,
                            selectedKeys,
                            comparativeOperandProfileMatches,
                            topK,
                            minScore: 0.0,
                            maxPerDoc: Math.Max(maxPerDoc, 2),
                            maxPerPage: Math.Max(maxPerPage, 2),
                            prioritizeDocumentProfiles: true,
                            query: req.Query);
                        PromoteActionableSameDocumentEvidence(selected);
                        RebuildSelectedKeys(selected, selectedKeys);
                        selectionSw.Stop();
                        selectionMs += selectionSw.ElapsedMilliseconds;
                    }
                }
            }

            IReadOnlyList<string> preciseBackfillPhrases = skipPreciseTitleLookupForDocumentOverview
                ? Array.Empty<string>()
                : ExtractTitleLookupPhrases(req.Query);
            var hasResolvedQuotedTitleSelection = preciseBackfillPhrases.Count > 0
                && selected.Any(match =>
                    HasResolvedPreciseTitleSelection(preciseBackfillPhrases, match));
            var hasSufficientPreciseContentSelection = preciseBackfillPhrases.Count > 0
                && HasSufficientPreciseContentSelection(req.Query, preciseBackfillPhrases, selected);
            var forcePreciseTitleBackfill = !useScopedProfileFallback
                && preciseBackfillPhrases.Count > 0
                && selected.Count > 0
                && !hasSufficientPreciseContentSelection;
            if (forcePreciseTitleBackfill)
            {
                async Task<List<RagMatch>> SearchPreciseTitleBackfillMatchesAsync()
                {
                    var backfill = BuildReusablePreciseTitleBackfillMatches(
                        req.Query,
                        preciseBackfillPhrases,
                        preciseTitleRouteReuseMatches);
                    var reusableBackfillIsSufficient = HasReusablePreciseTitleBackfillSelection(
                            req.Query,
                            preciseBackfillPhrases,
                            selected,
                            backfill);
                    if (reusableBackfillIsSufficient
                        && !ShouldContinuePreciseTitleBackfillAfterReusableSelection(
                            req.Query,
                            preciseBackfillPhrases,
                            backfill))
                    {
                        return DeduplicatePreciseTitleBackfillMatches(backfill);
                    }

                    var scopedDocCandidates = selected
                        .Take(8)
                        .Where(match =>
                            IsPreciseTitleBackfillScopeCandidate(preciseBackfillPhrases, match)
                            || (!hasResolvedQuotedTitleSelection
                                && !IsDocumentProfileMatch(match)
                                && match.Score >= 0.65
                                && IsContentSelectionCandidate(match)))
                        .Where(static match => !string.IsNullOrWhiteSpace(match.DocPath))
                        .GroupBy(static match => NormalizeRagDocPath(match.DocPath), StringComparer.OrdinalIgnoreCase)
                        .Select(static group => group.First())
                        .Take(3)
                        .ToList();
                    foreach (var phrase in ExtractTitleLookupPhrases(req.Query).Take(3))
                    {
                        var titleBackfillQuery = phrase.Contains('"', StringComparison.Ordinal)
                            ? phrase
                            : $"\"{phrase}\"";
                        var preferIndexedTitleBackfill = ShouldSkipLocalTitleTokenRouteForIndexedTitleAnchors(
                            titleBackfillQuery,
                            hasCategoryScope: hasCategoryFilter,
                            hasDocScope: false,
                            skipChunkRetrieversForDocumentOverview: skipChunkRetrieversForDocumentOverview,
                            useScopedProfileFallback);

                        var scopedSearchTasks = scopedDocCandidates
                            .Select(scopedDoc => preferIndexedTitleBackfill
                                ? SearchTitleAnchorRouteMatchesAsync(
                                    ds,
                                    tenantId,
                                    titleBackfillQuery,
                                    category,
                                    docId: null,
                                    scopedDoc.DocPath,
                                    Math.Min(topK, 8),
                                    ct,
                                    categoryPath,
                                    degradedRetrieverRef: MarkRetrieverDegraded)
                                : SearchLocalTitleTokenRouteMatchesAsync(
                                    ds,
                                    tenantId,
                                    titleBackfillQuery,
                                    category,
                                    docId: null,
                                    scopedDoc.DocPath,
                                    Math.Min(topK, 8),
                                    ct,
                                    categoryPath,
                                    degradedRetrieverRef: MarkRetrieverDegraded))
                            .ToArray();
                        foreach (var scopedMatches in await Task.WhenAll(scopedSearchTasks))
                        {
                            backfill.AddRange(scopedMatches);
                        }

                        reusableBackfillIsSufficient = HasReusablePreciseTitleBackfillSelection(
                                req.Query,
                                preciseBackfillPhrases,
                                selected,
                                backfill);
                        if (reusableBackfillIsSufficient
                            && !ShouldContinuePreciseTitleBackfillAfterReusableSelection(
                                req.Query,
                                preciseBackfillPhrases,
                                backfill))
                        {
                            continue;
                        }

                        var matches = await SearchPreciseTitleRouteBackfillAsync(
                            titleBackfillQuery,
                            Math.Min(topK, 8));
                        backfill.AddRange(matches);
                    }

                    return DeduplicatePreciseTitleBackfillMatches(backfill);
                }

                var (preciseTitleBackfillMatches, preciseTitleBackfillMs) = await MeasurePhaseAsync(
                    phaseName: "retrieval_precise_title_backfill",
                    retriever: "local_title_token_route",
                    action: SearchPreciseTitleBackfillMatchesAsync,
                    getReturnedCount: static matches => matches.Count);
                localTitleTokenMs += preciseTitleBackfillMs;

                if (preciseTitleBackfillMatches.Count > 0)
                {
                    var mergedTitleSelections = CalibrateFusedMatches(
                        retrievalQuery,
                        selected.Concat(preciseTitleBackfillMatches).ToList(),
                        req.Query);
                    mergedTitleSelections = PrioritizePreciseTitleBackfillSelections(
                        req.Query,
                        mergedTitleSelections,
                        preciseTitleBackfillMatches);
                    mergedTitleSelections = SuppressNavigationalNoise(req.Query, mergedTitleSelections);
                    selected.Clear();
                    selectedKeys.Clear();
                    AddRankedMatches(
                        selected,
                        selectedKeys,
                        mergedTitleSelections,
                        topK,
                        minScore: 0.0,
                        Math.Max(maxPerDoc, 2),
                        Math.Max(maxPerPage, 2),
                        query: req.Query);
                }
            }

            if (deferDocumentProfileSearch
                && ShouldRunDeferredDocumentProfileSearch(
                    selected,
                    topK,
                    preferDocumentDiversity,
                    useScopedProfileFallback,
                    allowSparseAssistForScopedProfileFallback))
            {
                var (deferredProfileMatches, deferredProfileMs) = await SearchDocumentProfilesMeasuredAsync();
                profilePhaseMs += deferredProfileMs;

                var selectionSwDeferred = Stopwatch.StartNew();
                AddRankedMatches(
                    selected,
                    selectedKeys,
                    RankDeferredDocumentProfileMatches(deferredProfileMatches),
                    topK,
                    minScore: 0.0,
                    maxPerDoc,
                        maxPerPage,
                        prioritizeDocumentProfiles: ShouldPrioritizeDocumentProfilesForSelection(
                            preferDocumentDiversity,
                            allowSparseAssistForScopedProfileFallback || allowSparseAssistForBroadDiversity,
                            allowComparativeDocumentProfileAssist));
                selectionSwDeferred.Stop();
                selectionMs += selectionSwDeferred.ElapsedMilliseconds;
            }

            var forcePreciseTitleLinkedBackfill = !useScopedProfileFallback
                && ShouldRunPreciseTitleLinkedBackfill(req.Query, selected);
            if (!useScopedProfileFallback && (selected.Count < topK || forcePreciseTitleLinkedBackfill))
            {
                var linkedLimit = selected.Count < topK
                    ? topK - selected.Count
                    : Math.Min(topK, 6);
                var (linkedMatches, linkedDurationMs) = await MeasurePhaseAsync(
                    phaseName: "retrieval_linked_context",
                    retriever: "linked_context",
                    action: () => SearchLinkedMatchesAsync(
                        ds,
                        tenantId,
                        selected,
                        category,
                        req.DocId,
                        req.DocPath,
                        linkedLimit,
                        ct,
                        categoryPath),
                    getReturnedCount: static matches => matches.Count);
                linkedPhaseMs += linkedDurationMs;

                if (forcePreciseTitleLinkedBackfill && selected.Count >= topK && linkedMatches.Count > 0)
                {
                    var mergedLinkedSelections = CalibrateFusedMatches(
                        retrievalQuery,
                        selected.Concat(linkedMatches).ToList(),
                        req.Query);
                    mergedLinkedSelections = SuppressNavigationalNoise(req.Query, mergedLinkedSelections);
                    selected.Clear();
                    selectedKeys.Clear();
                    AddRankedMatches(
                        selected,
                        selectedKeys,
                        mergedLinkedSelections,
                        topK,
                        minScore: 0.0,
                        Math.Max(maxPerDoc, 2),
                        Math.Max(maxPerPage, 2),
                        query: req.Query);
                }
                else
                {
                    AddRankedMatches(selected, selectedKeys, linkedMatches, topK, minScore: 0.0, Math.Max(maxPerDoc, 2), Math.Max(maxPerPage, 2));
                }
            }

            if (!useScopedProfileFallback && selected.Count < topK)
            {
                var (secondWaveLinkedMatches, secondWaveLinkedMs) = await MeasurePhaseAsync(
                    phaseName: "retrieval_linked_context",
                    retriever: "linked_context",
                    action: () => SearchLinkedMatchesAsync(
                        ds,
                        tenantId,
                        selected,
                        category,
                        req.DocId,
                        req.DocPath,
                        topK - selected.Count,
                        ct,
                        categoryPath),
                    getReturnedCount: static matches => matches.Count);
                linkedPhaseMs += secondWaveLinkedMs;

                AddRankedMatches(selected, selectedKeys, secondWaveLinkedMatches, topK, minScore: 0.0, Math.Max(maxPerDoc, 2), Math.Max(maxPerPage, 2));
            }
        }

        // CDC v3.1 §11.3: autocut - remove trailing results after largest relative score drop
        var selectionRankingQuery = string.Equals(retrievalQuery.Trim(), req.Query.Trim(), StringComparison.OrdinalIgnoreCase)
            ? req.Query
            : retrievalQuery;

        if (!hasDocScope
            && !hasExplicitFileDocumentHint
            && !useScopedProfileFallback
            && !skipChunkRetrieversForDocumentOverview
            && ShouldRunDocumentHintScopedBackfill(req.Query, selected))
        {
            var documentHintBackfillQuery = BuildDocumentHintScopedBackfillQuery(req.Query, retrievalQuery);
            if (!string.IsNullOrWhiteSpace(documentHintBackfillQuery))
            {
                var (documentHintBackfillMatches, documentHintBackfillMs) = await MeasurePhaseAsync(
                    phaseName: "retrieval_document_hint_scoped_backfill",
                    retriever: "document_hint_scoped_backfill",
                    action: () => SearchDocumentHintScopedBackfillMatchesAsync(
                        ds,
                        tenantId,
                        req.Query,
                        documentHintBackfillQuery,
                        category,
                        categoryPath,
                        Math.Max(topK, 8),
                        ct,
                        degradedRetrieverRef: MarkRetrieverDegraded,
                        commandTimeoutSeconds: sparseCommandTimeoutSeconds),
                    getReturnedCount: static matches => matches.Count);
                sparsePhaseMs += documentHintBackfillMs;

                if (documentHintBackfillMatches.Count > 0)
                {
                    var mergedDocumentHintSelections = CalibrateFusedMatches(
                        documentHintBackfillQuery,
                        selected.Concat(documentHintBackfillMatches).ToList(),
                        req.Query);
                    mergedDocumentHintSelections = SuppressNavigationalNoise(req.Query, mergedDocumentHintSelections);
                    selected.Clear();
                    selectedKeys.Clear();
                    AddRankedMatches(
                        selected,
                        selectedKeys,
                        mergedDocumentHintSelections,
                        topK,
                        minScore: 0.0,
                        Math.Max(maxPerDoc, 2),
                        Math.Max(maxPerPage, 2),
                        query: req.Query);

                    var documentHintTokens = ExtractDocumentHintTokens(req.Query);
                    var documentHintLinkedAnchors = documentHintBackfillMatches
                        .Where(match => DocumentMatchesHint(documentHintTokens, match))
                        .Take(3)
                        .ToList();
                    if (documentHintLinkedAnchors.Count > 0)
                    {
                        var (documentHintLinkedMatches, documentHintLinkedMs) = await MeasurePhaseAsync(
                            phaseName: "retrieval_document_hint_linked_context",
                            retriever: "linked_context",
                            action: () => SearchLinkedMatchesAsync(
                                ds,
                                tenantId,
                                documentHintLinkedAnchors,
                                category,
                                docId: null,
                                docPath: null,
                                Math.Min(topK, 6),
                                ct,
                                categoryPath),
                            getReturnedCount: static matches => matches.Count);
                        linkedPhaseMs += documentHintLinkedMs;

                        if (documentHintLinkedMatches.Count > 0)
                        {
                            var mergedLinkedDocumentHintSelections = CalibrateFusedMatches(
                                documentHintBackfillQuery,
                                selected.Concat(documentHintLinkedMatches).ToList(),
                                req.Query);
                            mergedLinkedDocumentHintSelections = SuppressNavigationalNoise(req.Query, mergedLinkedDocumentHintSelections);
                            selected.Clear();
                            selectedKeys.Clear();
                            AddRankedMatches(
                                selected,
                                selectedKeys,
                                mergedLinkedDocumentHintSelections,
                                topK,
                                minScore: 0.0,
                                Math.Max(maxPerDoc, 2),
                                Math.Max(maxPerPage, 2),
                                query: req.Query);
                        }
                    }
                }
            }
        }

        PrioritizeExactTitleSelections(selectionRankingQuery, selected);
        PrioritizeQuotedTitleSelections(req.Query, selected);
        PrioritizeDocumentHintSelections(req.Query, selected);
        PrioritizeOperationalSettingSelections(req.Query, selected);
        if (!useScopedProfileFallback)
        {
            var selectionSw = Stopwatch.StartNew();
            PruneWeakTitleExpansionSelections(selectionRankingQuery, selected);
            PruneWeakAdjacentSiblingSelections(selectionRankingQuery, selected);
            PrunePreciseTitleTailSelections(selectionRankingQuery, selected);
            PruneUnmatchedPreciseTitleSelections(selectionRankingQuery, selected);
            PruneUnpagedProfileSelectionsForPreciseLookup(selectionRankingQuery, selected);
            selectionSw.Stop();
            selectionMs += selectionSw.ElapsedMilliseconds;
        }
        var finalSelectionSw = Stopwatch.StartNew();
        PruneNavigationalSelections(req.Query, selected);
        PromoteActionableSameDocumentEvidence(selected);
        if (!skipChunkRetrieversForDocumentOverview)
            ApplyAutocut(selected, selectionMinScore, req.Query);
        RebuildSelectedKeys(selected, selectedKeys);
        finalSelectionSw.Stop();
        selectionMs += finalSelectionSw.ElapsedMilliseconds;

        if (!skipChunkRetrieversForDocumentOverview
            && !hasExplicitFileDocumentHint
            && ShouldRunShortTechnicalDirectPhraseBackfill(selectionRankingQuery, selected))
        {
            var (shortTechnicalPhraseMatches, shortTechnicalPhraseMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_short_technical_direct_phrase",
                retriever: "sparse_bm25",
                action: () => SearchShortTechnicalDirectPhraseMatchesAsync(
                    ds,
                    tenantId,
                    selectionRankingQuery,
                    category,
                    req.DocId,
                    req.DocPath,
                    Math.Max(topK * 2, 12),
                    ct,
                    categoryPath,
                    degradedRetrieverRef: MarkRetrieverDegraded),
                getReturnedCount: static matches => matches.Count);
            sparsePhaseMs += shortTechnicalPhraseMs;

            if (shortTechnicalPhraseMatches.Count > 0)
            {
                var calibratedShortTechnicalSelections = CalibrateFusedMatches(
                    selectionRankingQuery,
                    selected.Concat(shortTechnicalPhraseMatches).DistinctBy(BuildRagMatchIdentityKey).ToList(),
                    req.Query);
                calibratedShortTechnicalSelections = SuppressNavigationalNoise(req.Query, calibratedShortTechnicalSelections);

                var selectionSw = Stopwatch.StartNew();
                selected.Clear();
                selectedKeys.Clear();
                AddRankedMatches(
                    selected,
                    selectedKeys,
                    calibratedShortTechnicalSelections,
                    topK,
                    minScore: 0.0,
                    Math.Max(maxPerDoc, 2),
                    Math.Max(maxPerPage, 2),
                    query: req.Query);
                PruneNavigationalSelections(req.Query, selected);
                PromoteActionableSameDocumentEvidence(selected);
                if (!skipChunkRetrieversForDocumentOverview)
                    ApplyAutocut(selected, selectionMinScore, req.Query);
                RebuildSelectedKeys(selected, selectedKeys);
                selectionSw.Stop();
                selectionMs += selectionSw.ElapsedMilliseconds;
            }
        }

        if (!skipChunkRetrieversForDocumentOverview
            && !hasExplicitFileDocumentHint
            && ShouldRunShortTechnicalDirectEvidenceLinkedBackfill(selectionRankingQuery, selected))
        {
            var (shortTechnicalLinkedMatches, shortTechnicalLinkedMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_short_technical_linked_context",
                retriever: "linked_context",
                action: () => SearchLinkedMatchesAsync(
                    ds,
                    tenantId,
                    selected,
                    category,
                    req.DocId,
                    req.DocPath,
                    Math.Max(topK, 8),
                    ct,
                    categoryPath,
                    includeSamePageForLinkedAnchors: true,
                    maxAnchorCandidates: 12),
                getReturnedCount: static matches => matches.Count);
            linkedPhaseMs += shortTechnicalLinkedMs;

            var directEvidenceLinkedMatches = shortTechnicalLinkedMatches
                .Where(match => ComputeShortTechnicalDirectEvidencePriority(selectionRankingQuery, match, string.Empty, string.Empty) > 0)
                .ToList();
            if (directEvidenceLinkedMatches.Count == 0 && shortTechnicalLinkedMatches.Count > 0)
            {
                var (deepShortTechnicalLinkedMatches, deepShortTechnicalLinkedMs) = await MeasurePhaseAsync(
                    phaseName: "retrieval_short_technical_deep_linked_context",
                    retriever: "linked_context",
                    action: () => SearchLinkedMatchesAsync(
                        ds,
                        tenantId,
                        shortTechnicalLinkedMatches,
                        category,
                        req.DocId,
                        req.DocPath,
                        Math.Max(topK * 2, 12),
                        ct,
                        categoryPath,
                        includeSamePageForLinkedAnchors: true,
                        maxAnchorCandidates: 16),
                    getReturnedCount: static matches => matches.Count);
                linkedPhaseMs += deepShortTechnicalLinkedMs;

                shortTechnicalLinkedMatches = shortTechnicalLinkedMatches
                    .Concat(deepShortTechnicalLinkedMatches)
                    .DistinctBy(BuildRagMatchIdentityKey)
                    .ToList();
                directEvidenceLinkedMatches = shortTechnicalLinkedMatches
                    .Where(match => ComputeShortTechnicalDirectEvidencePriority(selectionRankingQuery, match, string.Empty, string.Empty) > 0)
                    .ToList();
            }
            if (directEvidenceLinkedMatches.Count == 0 && shortTechnicalLinkedMatches.Count > 0)
            {
                var (thirdWaveShortTechnicalLinkedMatches, thirdWaveShortTechnicalLinkedMs) = await MeasurePhaseAsync(
                    phaseName: "retrieval_short_technical_third_linked_context",
                    retriever: "linked_context",
                    action: () => SearchLinkedMatchesAsync(
                        ds,
                        tenantId,
                        shortTechnicalLinkedMatches,
                        category,
                        req.DocId,
                        req.DocPath,
                        Math.Max(topK * 3, 16),
                        ct,
                        categoryPath,
                        includeSamePageForLinkedAnchors: true,
                        maxAnchorCandidates: 24),
                    getReturnedCount: static matches => matches.Count);
                linkedPhaseMs += thirdWaveShortTechnicalLinkedMs;

                shortTechnicalLinkedMatches = shortTechnicalLinkedMatches
                    .Concat(thirdWaveShortTechnicalLinkedMatches)
                    .DistinctBy(BuildRagMatchIdentityKey)
                    .ToList();
                directEvidenceLinkedMatches = shortTechnicalLinkedMatches
                    .Where(match => ComputeShortTechnicalDirectEvidencePriority(selectionRankingQuery, match, string.Empty, string.Empty) > 0)
                    .ToList();
            }

            if (directEvidenceLinkedMatches.Count > 0)
            {
                var calibratedShortTechnicalSelections = CalibrateFusedMatches(
                    selectionRankingQuery,
                    selected.Concat(directEvidenceLinkedMatches).ToList(),
                    req.Query);
                calibratedShortTechnicalSelections = SuppressNavigationalNoise(req.Query, calibratedShortTechnicalSelections);

                var selectionSw = Stopwatch.StartNew();
                selected.Clear();
                selectedKeys.Clear();
                AddRankedMatches(
                    selected,
                    selectedKeys,
                    calibratedShortTechnicalSelections,
                    topK,
                    minScore: 0.0,
                    Math.Max(maxPerDoc, 2),
                    Math.Max(maxPerPage, 2),
                    query: req.Query);
                PruneNavigationalSelections(req.Query, selected);
                PromoteActionableSameDocumentEvidence(selected);
                if (!skipChunkRetrieversForDocumentOverview)
                    ApplyAutocut(selected, selectionMinScore, req.Query);
                RebuildSelectedKeys(selected, selectedKeys);
                selectionSw.Stop();
                selectionMs += selectionSw.ElapsedMilliseconds;
            }
        }

        if (!skipChunkRetrieversForDocumentOverview
            && !hasExplicitFileDocumentHint
            && ShouldBackfillFuzzyTitleLead(req.Query, selected))
        {
            var focusedFuzzyQuery = BuildFocusedLexicalBackfillQuery(req.Query);
            if (!string.IsNullOrWhiteSpace(focusedFuzzyQuery))
            {
                var (fuzzyTitleLeadMatches, fuzzyTitleLeadMs) = await MeasurePhaseAsync(
                    phaseName: "retrieval_fuzzy_title_lead",
                    retriever: "fuzzy_title_lead",
                    action: () => SearchFuzzyTitleLeadMatchesAsync(
                        ds,
                        tenantId,
                        focusedFuzzyQuery,
                        category,
                        req.DocId,
                        req.DocPath,
                        Math.Max(topK, 8),
                        ct,
                        categoryPath,
                        degradedRetrieverRef: MarkRetrieverDegraded),
                    getReturnedCount: static matches => matches.Count);
                sparsePhaseMs += fuzzyTitleLeadMs;

                var calibratedFuzzyMatches = CalibrateFusedMatches(focusedFuzzyQuery, fuzzyTitleLeadMatches, req.Query);
                calibratedFuzzyMatches = SuppressNavigationalNoise(req.Query, calibratedFuzzyMatches);
                var selectionSw = Stopwatch.StartNew();
                AddRankedMatches(
                    selected,
                    selectedKeys,
                    calibratedFuzzyMatches,
                    topK,
                    minScore: 0.0,
                    maxPerDoc,
                    Math.Max(maxPerPage, 2));
                PruneNavigationalSelections(req.Query, selected);
                PromoteActionableSameDocumentEvidence(selected);
                if (!skipChunkRetrieversForDocumentOverview)
                    ApplyAutocut(selected, selectionMinScore, req.Query);
                RebuildSelectedKeys(selected, selectedKeys);
                selectionSw.Stop();
                selectionMs += selectionSw.ElapsedMilliseconds;
            }
        }

        if (!skipChunkRetrieversForDocumentOverview
            && !hasExplicitFileDocumentHint
            && ShouldBackfillEnumerativeSearch(req.Query, selected.Count, topK))
        {
            var focusedLexicalQuery = BuildFocusedLexicalBackfillQuery(req.Query);
            if (!string.IsNullOrWhiteSpace(focusedLexicalQuery)
                && !string.Equals(focusedLexicalQuery.Trim(), req.Query.Trim(), StringComparison.OrdinalIgnoreCase))
            {
                var (backfillMatches, backfillDurationMs) = await MeasurePhaseAsync(
                    phaseName: "retrieval_lexical_backfill",
                    retriever: "lexical_backfill",
                    action: () => SearchSparseMatchesAsync(
                        ds,
                        tenantId,
                        focusedLexicalQuery,
                        category,
                        req.DocId,
                        req.DocPath,
                        sqlHeavyCandidateLimit,
                        ct,
                        sparseMsRef: value => sparseMs += value,
                        lexicalExpansionQuery: focusedLexicalQuery,
                        categoryPath: categoryPath,
                        includeProfileCardMatches: false,
                        degradedRetrieverRef: MarkRetrieverDegraded,
                        commandTimeoutSeconds: sparseCommandTimeoutSeconds),
                    getReturnedCount: static matches => matches.Count);
                sparsePhaseMs += backfillDurationMs;

                var calibratedBackfill = CalibrateFusedMatches(focusedLexicalQuery, backfillMatches, req.Query);
                calibratedBackfill = SuppressNavigationalNoise(req.Query, calibratedBackfill);
                var selectionSw = Stopwatch.StartNew();
                AddRankedMatches(
                    selected,
                    selectedKeys,
                    calibratedBackfill,
                    topK,
                    minScore: 0.0,
                    maxPerDoc,
                    Math.Max(maxPerPage, 2));
                PruneNavigationalSelections(req.Query, selected);
                PromoteActionableSameDocumentEvidence(selected);
                RebuildSelectedKeys(selected, selectedKeys);
                selectionSw.Stop();
                selectionMs += selectionSw.ElapsedMilliseconds;
            }
        }

        if (!skipChunkRetrieversForDocumentOverview
            && selected.Count == 0
            && ShouldUseScopedProfileFallback(req.Query, hasCategoryFilter, mode))
        {
            var (fallbackProfiles, fallbackProfilesMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_scoped_profile_fallback",
                retriever: "document_profile_fallback",
                action: () => SearchDocumentOverviewProfileMatchesAsync(
                    ds,
                    tenantId,
                    req.Query,
                    category,
                    req.DocId,
                    req.DocPath,
                    Math.Min(Math.Max(topK * 2, 12), 24),
                    ct,
                    categoryPath,
                    requireLexicalMatch: false,
                    degradedRetrieverRef: MarkRetrieverDegraded,
                    commandTimeoutSeconds: sparseCommandTimeoutSeconds),
                getReturnedCount: static matches => matches.Count);
            profilePhaseMs += fallbackProfilesMs;

            var selectionSw = Stopwatch.StartNew();
            AddRankedMatches(
                selected,
                selectedKeys,
                fallbackProfiles,
                topK,
                minScore: 0.0,
                maxPerDoc: 1,
                maxPerPage: Math.Max(maxPerPage, 1),
                query: req.Query);
            selectionSw.Stop();
            selectionMs += selectionSw.ElapsedMilliseconds;
        }

        var useScopedCatalogEmptySelectionRecovery = ShouldRunScopedCatalogEmptySelectionRecovery(req.Query, hasCategoryFilter, mode);
        if (selected.Count == 0
            && ((skipChunkRetrieversForDocumentOverview && ShouldUseCatalogDocumentOverviewFallback(req.Query))
                || useScopedCatalogDocumentOverviewFallback
                || useScopedCatalogEmptySelectionRecovery))
        {
            var (catalogProfiles, catalogProfilesMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_catalog_document_overview_fallback",
                retriever: "document_profile_catalog",
                action: () => SearchDocumentOverviewProfileMatchesAsync(
                    ds,
                    tenantId,
                    catalogOverviewFallbackQuery,
                    category,
                    req.DocId,
                    req.DocPath,
                    Math.Min(Math.Max(topK * 2, 12), 24),
                    ct,
                    categoryPath,
                    requireLexicalMatch: false,
                    degradedRetrieverRef: MarkRetrieverDegraded,
                    commandTimeoutSeconds: sparseCommandTimeoutSeconds),
                getReturnedCount: static matches => matches.Count);
            profilePhaseMs += catalogProfilesMs;

            var calibratedCatalogProfiles = CalibrateFusedMatches(
                catalogOverviewFallbackQuery,
                catalogProfiles,
                req.Query);
            var catalogProfileSelections = useScopedCatalogEmptySelectionRecovery
                ? catalogProfiles
                : calibratedCatalogProfiles;
            var selectionSw = Stopwatch.StartNew();
            AddRankedMatches(
                selected,
                selectedKeys,
                catalogProfileSelections,
                topK,
                minScore: 0.0,
                maxPerDoc: 1,
                maxPerPage: Math.Max(maxPerPage, 1),
                prioritizeDocumentProfiles: true,
                query: selectionQuery);
            selectionSw.Stop();
            selectionMs += selectionSw.ElapsedMilliseconds;
        }

        if (selected.Count == 0)
        {
            var standardReferenceBackfillPhrases = ExtractStandardReferenceTitleLookupPhrases(req.Query);
            if (standardReferenceBackfillPhrases.Count > 0)
            {
                async Task<List<RagMatch>> SearchStandardReferenceTitleBackfillMatchesAsync()
                {
                    var backfill = new List<RagMatch>();
                    foreach (var phrase in standardReferenceBackfillPhrases.Take(4))
                    {
                        var titleAnchorQuery = phrase.Contains('"', StringComparison.Ordinal)
                            ? phrase
                            : $"\"{phrase}\"";
                        backfill.AddRange(await SearchTitleAnchorRouteMatchesAsync(
                            ds,
                            tenantId,
                            titleAnchorQuery,
                            category,
                            req.DocId,
                            req.DocPath,
                            Math.Min(candidates, Math.Max(topK, 16)),
                            ct,
                            categoryPath,
                            degradedRetrieverRef: MarkRetrieverDegraded));
                    }

                    backfill.AddRange(await SearchStandardReferenceDocumentNameContentMatchesAsync(
                        ds,
                        tenantId,
                        req.Query,
                        standardReferenceBackfillPhrases,
                        category,
                        req.DocId,
                        req.DocPath,
                        Math.Min(candidates, Math.Max(topK, 16)),
                        ct,
                        categoryPath,
                        degradedRetrieverRef: MarkRetrieverDegraded));
                    backfill.AddRange(await SearchStandardReferenceDocumentNameProfileMatchesAsync(
                        ds,
                        tenantId,
                        req.Query,
                        standardReferenceBackfillPhrases,
                        category,
                        req.DocId,
                        req.DocPath,
                        Math.Min(candidates, Math.Max(topK, 16)),
                        ct,
                        categoryPath,
                        degradedRetrieverRef: MarkRetrieverDegraded,
                        commandTimeoutSeconds: sparseCommandTimeoutSeconds));

                    return DeduplicatePreciseTitleBackfillMatches(backfill);
                }

                var (standardReferenceTitleBackfillMatches, standardReferenceTitleBackfillMs) = await MeasurePhaseAsync(
                    phaseName: "retrieval_standard_reference_title_backfill",
                    retriever: "title_anchor_route",
                    action: SearchStandardReferenceTitleBackfillMatchesAsync,
                    getReturnedCount: static matches => matches.Count);
                titleAnchorRoutePhaseMs += standardReferenceTitleBackfillMs;

                if (standardReferenceTitleBackfillMatches.Count > 0)
                {
                    var calibratedStandardReferenceBackfill = SuppressNavigationalNoise(
                        req.Query,
                        CalibrateFusedMatches(req.Query, standardReferenceTitleBackfillMatches, req.Query));
                    var selectionSw = Stopwatch.StartNew();
                    AddRankedMatches(
                        selected,
                        selectedKeys,
                        calibratedStandardReferenceBackfill,
                        topK,
                        minScore: 0.0,
                        Math.Max(maxPerDoc, 2),
                        Math.Max(maxPerPage, 2),
                        query: selectionQuery);
                    selectionSw.Stop();
                    selectionMs += selectionSw.ElapsedMilliseconds;
                }
            }
        }

        var dateDocumentBackfillPhrases = ExtractDateAnchoredTitleLookupPhrases(req.Query);
        if (dateDocumentBackfillPhrases.Count > 0 && !SelectionsCoverDateAnchoredDocument(req.Query, selected))
        {
            var (dateDocumentBackfillMatches, dateDocumentBackfillMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_date_document_name_backfill",
                retriever: "date_document_name",
                action: () => SearchDateAnchoredDocumentNameContentMatchesAsync(
                    ds,
                    tenantId,
                    req.Query,
                    dateDocumentBackfillPhrases,
                    category,
                    req.DocId,
                    req.DocPath,
                    Math.Min(candidates, Math.Max(topK, 16)),
                    ct,
                    categoryPath,
                    degradedRetrieverRef: MarkRetrieverDegraded),
                getReturnedCount: static matches => matches.Count);
            titleAnchorRoutePhaseMs += dateDocumentBackfillMs;

            if (dateDocumentBackfillMatches.Count > 0)
            {
                var dateSelectionSw = Stopwatch.StartNew();
                var calibratedDateDocumentBackfill = SuppressNavigationalNoise(
                    req.Query,
                    CalibrateFusedMatches(req.Query, dateDocumentBackfillMatches, req.Query));
                RebuildSelectedKeys(selected, selectedKeys);
                AddRankedMatches(
                    selected,
                    selectedKeys,
                    calibratedDateDocumentBackfill,
                    topK,
                    minScore: 0.0,
                    maxPerDoc: Math.Max(maxPerDoc, 3),
                    maxPerPage: Math.Max(maxPerPage, 2),
                    query: req.Query);
                CleanupLateSelectionBackfills(req.Query, selected);
                RebuildSelectedKeys(selected, selectedKeys);
                dateSelectionSw.Stop();
                selectionMs += dateSelectionSw.ElapsedMilliseconds;
            }
        }

        if (selected.Count > 0 && ShouldUseReferenceVersionOperandRoute(req.Query))
        {
            var referenceVersionGroupKeys = InferReferenceVersionOperandGroupKeys(req.Query, selected);
            if (referenceVersionGroupKeys.Count > 0)
            {
                var (referenceVersionOperandBackfillMatches, referenceVersionOperandBackfillMs) = await MeasurePhaseAsync(
                    phaseName: "retrieval_reference_version_operand_backfill",
                    retriever: "reference_version_operand_document_name",
                    action: () => SearchReferenceVersionOperandDocumentNameContentMatchesAsync(
                        ds,
                        tenantId,
                        req.Query,
                        referenceVersionGroupKeys,
                        category,
                        req.DocId,
                        req.DocPath,
                        Math.Min(candidates, Math.Max(topK, 16)),
                        ct,
                        categoryPath,
                        degradedRetrieverRef: MarkRetrieverDegraded),
                    getReturnedCount: static matches => matches.Count);
                titleAnchorRoutePhaseMs += referenceVersionOperandBackfillMs;

                if (referenceVersionOperandBackfillMatches.Count > 0)
                {
                    var referenceVersionSelectionSw = Stopwatch.StartNew();
                    var calibratedReferenceVersionBackfill = SuppressNavigationalNoise(
                        req.Query,
                        CalibrateFusedMatches(req.Query, referenceVersionOperandBackfillMatches, req.Query));
                    RebuildSelectedKeys(selected, selectedKeys);
                    if (selected.Count < topK)
                    {
                        AddRankedMatches(
                            selected,
                            selectedKeys,
                            calibratedReferenceVersionBackfill,
                            topK,
                            minScore: 0.0,
                            maxPerDoc: Math.Max(maxPerDoc, 2),
                            maxPerPage: Math.Max(maxPerPage, 2),
                            query: req.Query);
                    }

                    EnsureComparativeBackfillDocumentDiversity(
                        selected,
                        selectedKeys,
                        calibratedReferenceVersionBackfill,
                        topK,
                        minScore: 0.0,
                        maxPerPage: Math.Max(maxPerPage, 2),
                        query: req.Query);
                    CleanupLateSelectionBackfills(req.Query, selected);
                    RebuildSelectedKeys(selected, selectedKeys);
                    referenceVersionSelectionSw.Stop();
                    selectionMs += referenceVersionSelectionSw.ElapsedMilliseconds;
                }
            }
        }

        IReadOnlyList<string> finalPreciseBackfillPhrases = skipPreciseTitleLookupForDocumentOverview
            ? Array.Empty<string>()
            : ExtractTitleLookupPhrases(req.Query);
        var finalHasSufficientPreciseContentSelection = finalPreciseBackfillPhrases.Count > 0
            && HasSufficientPreciseContentSelection(req.Query, finalPreciseBackfillPhrases, selected);
        if (!useScopedProfileFallback
            && finalPreciseBackfillPhrases.Count > 0
            && selected.Count > 0
            && !finalHasSufficientPreciseContentSelection)
        {
            async Task<List<RagMatch>> SearchFinalPreciseTitleBackfillMatchesAsync()
            {
                var backfill = BuildReusablePreciseTitleBackfillMatches(
                    req.Query,
                    finalPreciseBackfillPhrases,
                    preciseTitleRouteReuseMatches);
                var reusableBackfillIsSufficient = HasReusablePreciseTitleBackfillSelection(
                        req.Query,
                        finalPreciseBackfillPhrases,
                        selected,
                        backfill);
                if (reusableBackfillIsSufficient
                    && !ShouldContinuePreciseTitleBackfillAfterReusableSelection(
                        req.Query,
                        finalPreciseBackfillPhrases,
                        backfill))
                {
                    return DeduplicatePreciseTitleBackfillMatches(backfill);
                }

                var scopedDocCandidates = selected
                    .Take(8)
                    .Where(static match => !IsDocumentProfileMatch(match))
                    .Where(static match => IsContentSelectionCandidate(match))
                    .Where(static match => !string.IsNullOrWhiteSpace(match.DocPath))
                    .GroupBy(static match => NormalizeRagDocPath(match.DocPath), StringComparer.OrdinalIgnoreCase)
                    .Select(static group => group.First())
                    .Take(3)
                    .ToList();

                foreach (var phrase in finalPreciseBackfillPhrases.Take(3))
                {
                    var titleBackfillQuery = phrase.Contains('"', StringComparison.Ordinal)
                        ? phrase
                        : $"\"{phrase}\"";
                    var preferIndexedTitleBackfill = ShouldSkipLocalTitleTokenRouteForIndexedTitleAnchors(
                        titleBackfillQuery,
                        hasCategoryScope: hasCategoryFilter,
                        hasDocScope: false,
                        skipChunkRetrieversForDocumentOverview: skipChunkRetrieversForDocumentOverview,
                        useScopedProfileFallback);

                    var scopedSearchTasks = scopedDocCandidates
                        .Select(scopedDoc => preferIndexedTitleBackfill
                            ? SearchTitleAnchorRouteMatchesAsync(
                                ds,
                                tenantId,
                                titleBackfillQuery,
                                category,
                                docId: null,
                                scopedDoc.DocPath,
                                Math.Min(topK, 8),
                                ct,
                                categoryPath,
                                degradedRetrieverRef: MarkRetrieverDegraded)
                            : SearchLocalTitleTokenRouteMatchesAsync(
                                ds,
                                tenantId,
                                titleBackfillQuery,
                                category,
                                docId: null,
                                scopedDoc.DocPath,
                                Math.Min(topK, 8),
                                ct,
                                categoryPath,
                                degradedRetrieverRef: MarkRetrieverDegraded))
                        .ToArray();
                    foreach (var scopedMatches in await Task.WhenAll(scopedSearchTasks))
                    {
                        backfill.AddRange(scopedMatches);
                    }

                    reusableBackfillIsSufficient = HasReusablePreciseTitleBackfillSelection(
                            req.Query,
                            finalPreciseBackfillPhrases,
                            selected,
                            backfill);
                    if (reusableBackfillIsSufficient
                        && !ShouldContinuePreciseTitleBackfillAfterReusableSelection(
                            req.Query,
                            finalPreciseBackfillPhrases,
                            backfill))
                    {
                        continue;
                    }

                    var globalMatches = await SearchPreciseTitleRouteBackfillAsync(
                        titleBackfillQuery,
                        Math.Min(Math.Max(topK, 12), 24));
                    backfill.AddRange(globalMatches);
                }

                return DeduplicatePreciseTitleBackfillMatches(backfill);
            }

            var (finalPreciseTitleBackfillMatches, finalPreciseTitleBackfillMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_final_precise_title_backfill",
                retriever: "local_title_token_route",
                action: SearchFinalPreciseTitleBackfillMatchesAsync,
                getReturnedCount: static matches => matches.Count);
            localTitleTokenMs += finalPreciseTitleBackfillMs;

            if (finalPreciseTitleBackfillMatches.Count > 0)
            {
                var mergedFinalSelections = CalibrateFusedMatches(
                    retrievalQuery,
                    selected.Concat(finalPreciseTitleBackfillMatches).ToList(),
                    req.Query);
                mergedFinalSelections = PrioritizePreciseTitleBackfillSelections(
                    req.Query,
                    mergedFinalSelections,
                    finalPreciseTitleBackfillMatches);
                mergedFinalSelections = SuppressNavigationalNoise(req.Query, mergedFinalSelections);
                selected.Clear();
                selectedKeys.Clear();
                AddRankedMatches(
                    selected,
                    selectedKeys,
                    mergedFinalSelections,
                    topK,
                    minScore: 0.0,
                    Math.Max(maxPerDoc, 2),
                    Math.Max(maxPerPage, 2),
                    query: req.Query);
            }
        }

        var finalDocumentHintTokens = ExtractDocumentHintTokens(req.Query);
        if (!hasDocScope
            && !useScopedProfileFallback
            && !skipChunkRetrieversForDocumentOverview
            && finalDocumentHintTokens.Count > 0)
        {
            var finalDocumentHintLinkedAnchors = selected
                .Where(match =>
                    !IsDocumentProfileMatch(match)
                    && IsContentSelectionCandidate(match)
                    && DocumentMatchesHint(finalDocumentHintTokens, match))
                .Take(3)
                .ToList();
            if (finalDocumentHintLinkedAnchors.Count > 0)
            {
                var (finalDocumentHintLinkedMatches, finalDocumentHintLinkedMs) = await MeasurePhaseAsync(
                    phaseName: "retrieval_final_document_hint_linked_context",
                    retriever: "linked_context",
                    action: () => SearchLinkedMatchesAsync(
                        ds,
                        tenantId,
                        finalDocumentHintLinkedAnchors,
                        category,
                        docId: null,
                        docPath: null,
                        Math.Min(topK, 6),
                        ct,
                        categoryPath),
                    getReturnedCount: static matches => matches.Count);
                linkedPhaseMs += finalDocumentHintLinkedMs;

                if (finalDocumentHintLinkedMatches.Count > 0)
                {
                    var mergedFinalLinkedSelections = CalibrateFusedMatches(
                        retrievalQuery,
                        selected.Concat(finalDocumentHintLinkedMatches).ToList(),
                        req.Query);
                    mergedFinalLinkedSelections = SuppressNavigationalNoise(req.Query, mergedFinalLinkedSelections);
                    selected.Clear();
                    selectedKeys.Clear();
                    AddRankedMatches(
                        selected,
                        selectedKeys,
                        mergedFinalLinkedSelections,
                        topK,
                        minScore: 0.0,
                        Math.Max(maxPerDoc, 2),
                        Math.Max(maxPerPage, 2),
                        query: req.Query);
                }
            }
        }

        var finalOrderingSw = Stopwatch.StartNew();
        PruneUnanchoredFocusedLookupSelections(selectionQuery, selected);
        finalOrderingSw.Stop();
        selectionMs += finalOrderingSw.ElapsedMilliseconds;

        if (!skipChunkRetrieversForDocumentOverview
            && !hasExplicitFileDocumentHint
            && !skipUnanchoredTitleAnchorRouteForBroadDiversity
            && ShouldRunFinalComparativeSparseDiversityBackfill(req.Query, selected))
        {
            var comparativeSubjectBackfillQueries = BuildComparativeSubjectBackfillQueries(req.Query);
            var (comparativeSparseBackfillMatches, comparativeSparseBackfillMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_final_comparative_sparse_backfill",
                retriever: "sparse_bm25",
                action: async () =>
                {
                    var backfill = new List<RagMatch>();
                    foreach (var focusedQuery in comparativeSubjectBackfillQueries)
                    {
                        backfill.AddRange(await SearchSparseMatchesAsync(
                            ds,
                            tenantId,
                            focusedQuery,
                            category,
                            req.DocId,
                            req.DocPath,
                            Math.Min(Math.Max(topK, 12), 32),
                            ct,
                            sparseMsRef: value => sparseMs += value,
                            lexicalExpansionQuery: focusedQuery,
                            categoryPath: categoryPath,
                            includeProfileCardMatches: false,
                            degradedRetrieverRef: MarkRetrieverDegraded,
                            commandTimeoutSeconds: sparseCommandTimeoutSeconds));
                    }

                    return backfill
                        .GroupBy(BuildMatchDedupKey, StringComparer.OrdinalIgnoreCase)
                        .Select(static group => group
                            .OrderByDescending(match => match.Score)
                            .ThenBy(match => match.DocPath, StringComparer.OrdinalIgnoreCase)
                            .ThenBy(match => match.ChunkIndex)
                            .First())
                        .ToList();
                },
                getReturnedCount: static matches => matches.Count);
            sparsePhaseMs += comparativeSparseBackfillMs;

            if (comparativeSparseBackfillMatches.Count > 0)
            {
                finalOrderingSw.Restart();
                RebuildSelectedKeys(selected, selectedKeys);
                EnsureComparativeBackfillDocumentDiversity(
                    selected,
                    selectedKeys,
                    comparativeSparseBackfillMatches,
                    topK,
                    minScore: 0.0,
                    maxPerPage: Math.Max(maxPerPage, 2),
                    query: req.Query);
                PruneNavigationalSelections(req.Query, selected);
                PromoteActionableSameDocumentEvidence(selected);
                RebuildSelectedKeys(selected, selectedKeys);
                finalOrderingSw.Stop();
                selectionMs += finalOrderingSw.ElapsedMilliseconds;
            }
        }

        if (broadDiversityCandidateBackfillPool is { Count: > 0 }
            && ShouldRunBroadDiversityCandidateBackfill(req.Query, selected.Count, topK))
        {
            finalOrderingSw.Restart();
            RebuildSelectedKeys(selected, selectedKeys);
            AddRankedMatches(
                selected,
                selectedKeys,
                broadDiversityCandidateBackfillPool,
                topK,
                minScore: 0.0,
                maxPerDoc,
                maxPerPage,
                prioritizeDocumentProfiles: true,
                query: req.Query);
            PruneNavigationalSelections(req.Query, selected);
            PromoteActionableSameDocumentEvidence(selected);
            RebuildSelectedKeys(selected, selectedKeys);
            finalOrderingSw.Stop();
            selectionMs += finalOrderingSw.ElapsedMilliseconds;
        }

        if (broadDiversityCandidateBackfillPool is { Count: > 0 }
            && ShouldRunBroadDiversityCandidateCoverage(req.Query, topK))
        {
            finalOrderingSw.Restart();
            RebuildSelectedKeys(selected, selectedKeys);
            EnsureBroadDiversityCandidateCoverage(
                selected,
                selectedKeys,
                broadDiversityCandidateBackfillPool,
                topK,
                minScore: 0.0,
                maxPerPage: Math.Max(maxPerPage, 2),
                query: req.Query);
            PruneNavigationalSelections(req.Query, selected);
            PromoteActionableSameDocumentEvidence(selected);
            RebuildSelectedKeys(selected, selectedKeys);
            finalOrderingSw.Stop();
            selectionMs += finalOrderingSw.ElapsedMilliseconds;
        }

        if (!useScopedProfileFallback && ShouldRunStructuredContinuationBackfill(req.Query, selected))
        {
            var structuredContinuationAnchors = SelectStructuredContinuationAnchors(
                req.Query,
                selected,
                Math.Min(topK, 4));
            if (structuredContinuationAnchors.Count > 0)
            {
                var structuredContinuationLimit = Math.Min(topK, Math.Max(4, structuredContinuationAnchors.Count * 2));
                var (structuredContinuationMatches, structuredContinuationMs) = await MeasurePhaseAsync(
                    phaseName: "retrieval_structured_continuation",
                    retriever: "linked_context",
                    action: () => SearchLinkedMatchesAsync(
                        ds,
                        tenantId,
                        structuredContinuationAnchors,
                        category,
                        req.DocId,
                        req.DocPath,
                        structuredContinuationLimit,
                        ct,
                        categoryPath,
                        includeSamePageForLinkedAnchors: true),
                    getReturnedCount: static matches => matches.Count);
                linkedPhaseMs += structuredContinuationMs;

                var structuredContinuations = FilterStructuredContinuationMatches(
                    req.Query,
                    structuredContinuationAnchors,
                    structuredContinuationMatches,
                    structuredContinuationLimit);
                if (structuredContinuations.Count > 0)
                {
                    var structuredContinuationSelectionSw = Stopwatch.StartNew();
                    MergeStructuredContinuationSelections(req.Query, selected, structuredContinuations, topK);
                    structuredContinuationSelectionSw.Stop();
                    selectionMs += structuredContinuationSelectionSw.ElapsedMilliseconds;
                }
            }
        }

        if (!skipChunkRetrieversForDocumentOverview
            && !hasExplicitFileDocumentHint
            && selected.Count == 0
            && ShouldRunFocusedLookupEmptySelectionRecovery(req.Query))
        {
            var focusedRecoveryQuery = BuildFocusedLexicalBackfillQuery(req.Query);
            var focusedRecoveryLimit = Math.Min(candidates, Math.Max(topK * 4, 24));
            var (focusedRecoveryMatches, focusedRecoveryMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_focused_empty_recovery",
                retriever: "focused_lookup_recovery",
                action: async () =>
                {
                    var recovery = new List<RagMatch>();
                    recovery.AddRange(await SearchTitleAnchorRouteMatchesAsync(
                        ds,
                        tenantId,
                        focusedRecoveryQuery,
                        category,
                        req.DocId,
                        req.DocPath,
                        focusedRecoveryLimit,
                        ct,
                        categoryPath,
                        degradedRetrieverRef: MarkRetrieverDegraded));
                    recovery.AddRange(await SearchSparseMatchesAsync(
                        ds,
                        tenantId,
                        focusedRecoveryQuery,
                        category,
                        req.DocId,
                        req.DocPath,
                        focusedRecoveryLimit,
                        ct,
                        sparseMsRef: value => sparseMs += value,
                        lexicalExpansionQuery: focusedRecoveryQuery,
                        categoryPath: categoryPath,
                        includeProfileCardMatches: true,
                        degradedRetrieverRef: MarkRetrieverDegraded,
                        commandTimeoutSeconds: sparseCommandTimeoutSeconds));
                    recovery.AddRange(await SearchDenseMatchesAsync(
                        ds,
                        httpFactory,
                        rag,
                        tenantId,
                        NormalizeQuery(focusedRecoveryQuery),
                        category,
                        req.DocId,
                        req.DocPath,
                        focusedRecoveryLimit,
                        ct,
                        teiMsRef: value => teiMs += value,
                        qdrantMsRef: value => qdrantMs += value,
                        qdrantStatusRef: value => qdrantStatus = value,
                        categoryPath: categoryPath,
                        degradedRetrieverRef: MarkRetrieverDegraded));

                    return recovery
                        .GroupBy(BuildMatchDedupKey, StringComparer.OrdinalIgnoreCase)
                        .Select(static group => group
                            .OrderByDescending(match => match.Score)
                            .ThenBy(match => match.DocPath, StringComparer.OrdinalIgnoreCase)
                            .ThenBy(match => match.ChunkIndex)
                            .First())
                        .ToList();
                },
                getReturnedCount: static matches => matches.Count);
            selectionMs += focusedRecoveryMs;

            if (focusedRecoveryMatches.Count > 0)
            {
                var focusedRecoverySelectionSw = Stopwatch.StartNew();
                var calibratedRecovery = CalibrateFusedMatches(focusedRecoveryQuery, focusedRecoveryMatches, req.Query);
                calibratedRecovery = SuppressNavigationalNoise(req.Query, calibratedRecovery);
                AddRankedMatches(
                    selected,
                    selectedKeys,
                    calibratedRecovery,
                    topK,
                    minScore: 0.0,
                    Math.Max(maxPerDoc, 2),
                    Math.Max(maxPerPage, 2),
                    query: req.Query);
                if (selected.Count > 0 && selected.Count < topK)
                {
                    var (focusedRecoveryLinkedMatches, focusedRecoveryLinkedMs) = await MeasurePhaseAsync(
                        phaseName: "retrieval_focused_empty_recovery_linked_context",
                        retriever: "linked_context",
                        action: () => SearchLinkedMatchesAsync(
                            ds,
                            tenantId,
                            selected,
                            category,
                            req.DocId,
                            req.DocPath,
                            topK - selected.Count,
                            ct,
                            categoryPath,
                            includeSamePageForLinkedAnchors: true),
                        getReturnedCount: static matches => matches.Count);
                    linkedPhaseMs += focusedRecoveryLinkedMs;
                    AddRankedMatches(
                        selected,
                        selectedKeys,
                        focusedRecoveryLinkedMatches,
                        topK,
                        minScore: 0.0,
                        Math.Max(maxPerDoc, 2),
                        Math.Max(maxPerPage, 2),
                        query: req.Query);
                }

                PruneNavigationalSelections(req.Query, selected);
                PromoteActionableSameDocumentEvidence(selected);
                PruneUnanchoredFocusedLookupSelections(req.Query, selected);
                RebuildSelectedKeys(selected, selectedKeys);
                focusedRecoverySelectionSw.Stop();
                selectionMs += focusedRecoverySelectionSw.ElapsedMilliseconds;
            }
        }

        var compactDocumentCodeLookupPhrases = ExtractCompactDocumentCodeLookupPhrases(req.Query);
        if (!skipChunkRetrieversForDocumentOverview
            && ShouldAllowCompactDocumentCodeEmptyRecovery(req.Query, hasExplicitFileDocumentHint)
            && selected.Count == 0
            && compactDocumentCodeLookupPhrases.Count > 0)
        {
            var compactCodeRecoveryLimit = Math.Min(candidates, Math.Max(topK * 4, 24));
            var (compactCodeRecoveryMatches, compactCodeRecoveryMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_compact_document_code_empty_recovery",
                retriever: "compact_document_code_recovery",
                action: async () =>
                {
                    var recovery = new List<RagMatch>();
                    foreach (var compactCode in compactDocumentCodeLookupPhrases.Take(3))
                    {
                        recovery.AddRange(await SearchTitleAnchorRouteMatchesAsync(
                            ds,
                            tenantId,
                            compactCode,
                            category,
                            req.DocId,
                            req.DocPath,
                            compactCodeRecoveryLimit,
                            ct,
                            categoryPath,
                            degradedRetrieverRef: MarkRetrieverDegraded));
                        recovery.AddRange(await SearchDenseMatchesAsync(
                            ds,
                            httpFactory,
                            rag,
                            tenantId,
                            NormalizeQuery(compactCode),
                            category,
                            req.DocId,
                            req.DocPath,
                            compactCodeRecoveryLimit,
                            ct,
                            teiMsRef: value => teiMs += value,
                            qdrantMsRef: value => qdrantMs += value,
                            qdrantStatusRef: value => qdrantStatus = value,
                            categoryPath: categoryPath,
                            degradedRetrieverRef: MarkRetrieverDegraded));
                    }

                    return recovery
                        .GroupBy(BuildMatchDedupKey, StringComparer.OrdinalIgnoreCase)
                        .Select(static group => group
                            .OrderByDescending(match => match.Score)
                            .ThenBy(match => match.DocPath, StringComparer.OrdinalIgnoreCase)
                            .ThenBy(match => match.ChunkIndex)
                            .First())
                        .ToList();
                },
                getReturnedCount: static matches => matches.Count);
            titleAnchorRoutePhaseMs += compactCodeRecoveryMs;

            if (compactCodeRecoveryMatches.Count > 0)
            {
                var compactCodeRecoverySelectionSw = Stopwatch.StartNew();
                var calibratedRecovery = CalibrateFusedMatches(
                    string.Join(' ', compactDocumentCodeLookupPhrases),
                    compactCodeRecoveryMatches,
                    req.Query);
                AddRankedMatches(
                    selected,
                    selectedKeys,
                    SuppressNavigationalNoise(req.Query, calibratedRecovery),
                    topK,
                    minScore: 0.0,
                    Math.Max(maxPerDoc, 2),
                    Math.Max(maxPerPage, 2),
                    query: string.Join(' ', compactDocumentCodeLookupPhrases));
                PruneNavigationalSelections(req.Query, selected);
                RebuildSelectedKeys(selected, selectedKeys);
                compactCodeRecoverySelectionSw.Stop();
                selectionMs += compactCodeRecoverySelectionSw.ElapsedMilliseconds;
            }
        }

        var explicitFileLookupTokens = ExtractExplicitFileLookupPhrases(req.Query);
        if (!ContainsDocumentOverviewIntent(req.Query)
            && explicitFileLookupTokens.Count > 0
            && !SelectionsCoverExplicitFileLookupGroups(req.Query, selected))
        {
            var (explicitDocumentRecoveryMatches, explicitDocumentRecoveryMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_explicit_document_title_recovery",
                retriever: "explicit_document_title_route",
                action: () => SearchExplicitDocumentTitleMatchesAsync(
                    ds,
                    tenantId,
                    req.Query,
                    category,
                    req.DocId,
                    req.DocPath,
                    Math.Min(candidates, Math.Max(topK, 16)),
                    ct,
                    categoryPath,
                    degradedRetrieverRef: MarkRetrieverDegraded),
                getReturnedCount: static matches => matches.Count);
            titleAnchorRoutePhaseMs += explicitDocumentRecoveryMs;
            if (explicitDocumentRecoveryMatches.Count > 0)
            {
                var mergedExplicitSelections = CalibrateFusedMatches(
                    req.Query,
                    explicitDocumentRecoveryMatches.Concat(selected).ToList(),
                    req.Query);
                selected.Clear();
                selectedKeys.Clear();
                AddRankedMatches(
                    selected,
                    selectedKeys,
                    mergedExplicitSelections,
                    topK,
                    minScore: 0.0,
                    Math.Min(topK, Math.Max(maxPerDoc, 3)),
                    Math.Min(topK, Math.Max(maxPerPage, 2)),
                    query: req.Query);
            }
            else
            {
                selected.Clear();
                selectedKeys.Clear();
            }
        }

        if (ContainsDocumentCompanionRelationIntent(req.Query)
            && ExtractStandardReferenceTitleLookupPhrases(req.Query).Count > 0)
        {
            var companionBackfill = new List<RagMatch>();
            foreach (var phrase in ExtractStandardReferenceTitleLookupPhrases(req.Query).Take(2))
            {
                var titleAnchorQuery = phrase.Contains('"', StringComparison.Ordinal)
                    ? phrase
                    : $"\"{phrase}\"";
                var (referenceCompanionMatches, referenceCompanionMs) = await MeasurePhaseAsync(
                    phaseName: "retrieval_reference_companion_title_anchor",
                    retriever: "title_anchor_route",
                    action: () => SearchTitleAnchorRouteMatchesAsync(
                        ds,
                        tenantId,
                        titleAnchorQuery,
                        category,
                        req.DocId,
                        req.DocPath,
                        Math.Min(candidates, Math.Max(topK, 16)),
                        ct,
                        categoryPath,
                        degradedRetrieverRef: MarkRetrieverDegraded,
                        allowDirectChunkRoute: false),
                    getReturnedCount: static matches => matches.Count);
                titleAnchorRoutePhaseMs += referenceCompanionMs;
                companionBackfill.AddRange(referenceCompanionMatches);
            }

            if (companionBackfill.Count > 0)
            {
                AddRankedMatches(
                    selected,
                    selectedKeys,
                    CalibrateFusedMatches(req.Query, companionBackfill, req.Query),
                    topK,
                    minScore: 0.0,
                    Math.Max(maxPerDoc, 3),
                    Math.Max(maxPerPage, 2),
                    query: req.Query);
            }
        }

        List<RagMatch>? documentStatusOperandSelectionPool = null;
        var documentStatusOperandTerms = ExtractDocumentStatusOperandLookupTerms(req.Query);
        if (documentStatusOperandTerms.Count > 0 && !hasExplicitFileDocumentHint)
        {
            var (documentStatusOperandMatches, documentStatusOperandMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_document_status_operand",
                retriever: "document_status_operand",
                action: () => SearchDocumentStatusOperandContentMatchesAsync(
                    ds,
                    tenantId,
                    req.Query,
                    documentStatusOperandTerms,
                    category,
                    req.DocId,
                    req.DocPath,
                    Math.Min(candidates, Math.Max(topK, 16)),
                    ct,
                    categoryPath,
                    degradedRetrieverRef: MarkRetrieverDegraded),
                getReturnedCount: static matches => matches.Count);
            titleAnchorRoutePhaseMs += documentStatusOperandMs;

            if (documentStatusOperandMatches.Count > 0)
            {
                var hasStatusCompanionBackfillMatches = false;
                var statusCompanionBackfillQueries = BuildDocumentStatusOperandCompanionBackfillQueries(
                    req.Query,
                    documentStatusOperandTerms,
                    documentStatusOperandMatches);
                if (statusCompanionBackfillQueries.Count > 0)
                {
                    var (statusCompanionBackfillMatches, statusCompanionBackfillMs) = await MeasurePhaseAsync(
                        phaseName: "retrieval_document_status_companion_backfill",
                        retriever: "document_status_companion_backfill",
                        action: async () =>
                        {
                            var backfill = new List<RagMatch>();
                            foreach (var focusedQuery in statusCompanionBackfillQueries)
                            {
                                backfill.AddRange(await SearchTitleAnchorRouteMatchesAsync(
                                    ds,
                                    tenantId,
                                    focusedQuery,
                                    category,
                                    req.DocId,
                                    req.DocPath,
                                    Math.Min(candidates, Math.Max(topK, 16)),
                                    ct,
                                    categoryPath,
                                    degradedRetrieverRef: MarkRetrieverDegraded));
                                backfill.AddRange(await SearchDenseMatchesAsync(
                                    ds,
                                    httpFactory,
                                    rag,
                                    tenantId,
                                    NormalizeQuery(focusedQuery),
                                    category,
                                    req.DocId,
                                    req.DocPath,
                                    Math.Min(candidates, Math.Max(topK, 16)),
                                    ct,
                                    teiMsRef: value => teiMs += value,
                                    qdrantMsRef: value => qdrantMs += value,
                                    qdrantStatusRef: value => qdrantStatus = value,
                                    categoryPath: categoryPath,
                                    degradedRetrieverRef: MarkRetrieverDegraded));
                            }

                            return backfill
                                .GroupBy(BuildMatchDedupKey, StringComparer.OrdinalIgnoreCase)
                                .Select(static group => group
                                    .OrderByDescending(match => match.Score)
                                    .ThenBy(match => match.DocPath, StringComparer.OrdinalIgnoreCase)
                                    .ThenBy(match => match.ChunkIndex)
                                    .First())
                                .ToList();
                        },
                        getReturnedCount: static matches => matches.Count);
                    titleAnchorRoutePhaseMs += statusCompanionBackfillMs;
                    if (statusCompanionBackfillMatches.Count > 0)
                    {
                        hasStatusCompanionBackfillMatches = true;
                        documentStatusOperandMatches.AddRange(statusCompanionBackfillMatches);
                        documentStatusOperandMatches = DeduplicatePreciseTitleBackfillMatches(documentStatusOperandMatches);
                    }
                }

                var shouldMergeDocumentStatusOperandSelections = ShouldMergeDocumentStatusOperandSelectionsForComparativeVersionRoute(
                    req.Query,
                    documentStatusOperandTerms);
                if (shouldMergeDocumentStatusOperandSelections)
                {
                    var counterpartBackfillQueries = BuildComparativeVersionCounterpartBackfillQueries(req.Query);
                    if (counterpartBackfillQueries.Count > 0)
                    {
                        var (counterpartBackfillMatches, counterpartBackfillMs) = await MeasurePhaseAsync(
                            phaseName: "retrieval_comparative_version_counterpart_sparse",
                            retriever: "sparse_bm25",
                            action: async () =>
                            {
                                var backfill = new List<RagMatch>();
                                foreach (var focusedQuery in counterpartBackfillQueries)
                                {
                                    backfill.AddRange(await SearchSparseMatchesAsync(
                                        ds,
                                        tenantId,
                                        focusedQuery,
                                        category,
                                        req.DocId,
                                        req.DocPath,
                                        Math.Min(Math.Max(topK, 12), 32),
                                        ct,
                                        sparseMsRef: value => sparseMs += value,
                                        lexicalExpansionQuery: focusedQuery,
                                        categoryPath: categoryPath,
                                        includeProfileCardMatches: false,
                                        degradedRetrieverRef: MarkRetrieverDegraded,
                                        commandTimeoutSeconds: sparseCommandTimeoutSeconds));
                                }

                                return backfill
                                    .GroupBy(BuildMatchDedupKey, StringComparer.OrdinalIgnoreCase)
                                    .Select(static group => group
                                        .OrderByDescending(match => match.Score)
                                        .ThenBy(match => match.DocPath, StringComparer.OrdinalIgnoreCase)
                                        .ThenBy(match => match.ChunkIndex)
                                        .First())
                                    .ToList();
                            },
                            getReturnedCount: static matches => matches.Count);
                        sparsePhaseMs += counterpartBackfillMs;
                        documentStatusOperandMatches.AddRange(counterpartBackfillMatches);
                    }
                }

                var mergedStatusSelections = CalibrateFusedMatches(
                    req.Query,
                    documentStatusOperandMatches.Concat(selected).ToList(),
                    req.Query);
                mergedStatusSelections = PrioritizeDocumentStatusOperandSelections(
                    req.Query,
                    documentStatusOperandTerms,
                    mergedStatusSelections);
                documentStatusOperandSelectionPool = mergedStatusSelections;
                if (!shouldMergeDocumentStatusOperandSelections && !hasStatusCompanionBackfillMatches)
                {
                    mergedStatusSelections = mergedStatusSelections
                        .Where(static match => string.Equals(
                            ResolveRetriever(match),
                            "document_status_operand",
                            StringComparison.Ordinal))
                        .ToList();
                }

                if (shouldMergeDocumentStatusOperandSelections)
                {
                    RebuildSelectedKeys(selected, selectedKeys);
                    AddRankedMatches(
                        selected,
                        selectedKeys,
                        mergedStatusSelections,
                        topK,
                        minScore: 0.0,
                        Math.Max(maxPerDoc, 3),
                        Math.Max(maxPerPage, 2),
                        query: req.Query);
                    EnsureComparativeBackfillDocumentDiversity(
                        selected,
                        selectedKeys,
                        mergedStatusSelections,
                        topK,
                        minScore: 0.0,
                        maxPerPage: Math.Max(maxPerPage, 2),
                        query: req.Query);
                }
                else
                {
                    selected.Clear();
                    selectedKeys.Clear();
                    AddRankedMatches(
                        selected,
                        selectedKeys,
                        mergedStatusSelections,
                        topK,
                        minScore: 0.0,
                        Math.Max(maxPerDoc, 3),
                        Math.Max(maxPerPage, 2),
                        query: req.Query);
                }
            }
        }

        var lateStandardReferencePhrases = ExtractStandardReferenceTitleLookupPhrases(req.Query);
        if (lateStandardReferencePhrases.Count > 1
            && !SelectionsCoverStandardReferencePhrases(lateStandardReferencePhrases, selected))
        {
            var (lateStandardReferenceMatches, lateStandardReferenceMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_standard_reference_late_recovery",
                retriever: "standard_reference_document_name",
                action: () => SearchStandardReferenceDocumentNameContentMatchesAsync(
                    ds,
                    tenantId,
                    req.Query,
                    lateStandardReferencePhrases,
                    category,
                    req.DocId,
                    req.DocPath,
                    Math.Min(candidates, Math.Max(topK, 16)),
                    ct,
                    categoryPath,
                    degradedRetrieverRef: MarkRetrieverDegraded),
                getReturnedCount: static matches => matches.Count);
            if (!SelectionsCoverStandardReferencePhrases(lateStandardReferencePhrases, lateStandardReferenceMatches))
            {
                lateStandardReferenceMatches.AddRange(await SearchStandardReferenceDocumentNameProfileMatchesAsync(
                    ds,
                    tenantId,
                    req.Query,
                    lateStandardReferencePhrases,
                    category,
                    req.DocId,
                    req.DocPath,
                    Math.Min(candidates, Math.Max(topK, 16)),
                    ct,
                    categoryPath,
                    degradedRetrieverRef: MarkRetrieverDegraded,
                    commandTimeoutSeconds: sparseCommandTimeoutSeconds));
                lateStandardReferenceMatches = DeduplicatePreciseTitleBackfillMatches(lateStandardReferenceMatches);
            }
            titleAnchorRoutePhaseMs += lateStandardReferenceMs;

            if (lateStandardReferenceMatches.Count > 0)
            {
                var lateStandardReferenceSelectionPool = SelectionsCoverStandardReferencePhrases(
                    lateStandardReferencePhrases,
                    lateStandardReferenceMatches)
                    ? lateStandardReferenceMatches
                    : lateStandardReferenceMatches.Concat(selected).ToList();
                var mergedStandardReferenceSelections = CalibrateFusedMatches(
                    req.Query,
                    lateStandardReferenceSelectionPool,
                    req.Query);
                selected.Clear();
                selectedKeys.Clear();
                AddRankedMatches(
                    selected,
                    selectedKeys,
                    mergedStandardReferenceSelections,
                    topK,
                    minScore: 0.0,
                    Math.Max(maxPerDoc, 3),
                    Math.Max(maxPerPage, 2),
                    query: req.Query);
            }
        }

        finalOrderingSw = Stopwatch.StartNew();
        CleanupLateSelectionBackfills(req.Query, selected);
        PruneUnrelatedReferenceVersionGroupSelections(req.Query, selected);
        PruneCurrentReferenceVersionSelectionsWhenHistoricalVersionRequested(req.Query, selected);
        PruneUnrequestedReferenceVersionYearSelections(req.Query, selected);
        PruneSupersededReferenceVersionSelections(req.Query, selected);
        PrioritizeFinalSelections(req.Query, selected);
        PrioritizeResponseDiversityCoverage(req.Query, selected, requestedTopK);
        ReattachStructuredContinuationCompanions(req.Query, selected, topK);
        PruneQualifiedQuotedTitleCompetitorDocuments(req.Query, selected);
        PrunePreciseTitleLocalNeighborhoodSelections(req.Query, selected);
        RebuildSelectedKeys(selected, selectedKeys);
        ReattachDocumentStatusOperandCompanions(
            req.Query,
            documentStatusOperandTerms,
            documentStatusOperandSelectionPool,
            selected,
            selectedKeys,
            topK);
        RebuildSelectedKeys(selected, selectedKeys);
        finalOrderingSw.Stop();
        selectionMs += finalOrderingSw.ElapsedMilliseconds;

        if (dateDocumentBackfillPhrases.Count > 0 && !SelectionsCoverDateAnchoredDocument(req.Query, selected))
        {
            var (lateDateDocumentBackfillMatches, lateDateDocumentBackfillMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_date_document_name_late_recovery",
                retriever: "date_document_name",
                action: () => SearchDateAnchoredDocumentNameContentMatchesAsync(
                    ds,
                    tenantId,
                    req.Query,
                    dateDocumentBackfillPhrases,
                    category,
                    req.DocId,
                    req.DocPath,
                    Math.Min(candidates, Math.Max(topK, 16)),
                    ct,
                    categoryPath,
                    degradedRetrieverRef: MarkRetrieverDegraded),
                getReturnedCount: static matches => matches.Count);
            titleAnchorRoutePhaseMs += lateDateDocumentBackfillMs;

            if (lateDateDocumentBackfillMatches.Count > 0)
            {
                finalOrderingSw.Restart();
                selected.Clear();
                selectedKeys.Clear();
                var calibratedLateDateDocumentBackfill = SuppressNavigationalNoise(
                    req.Query,
                    CalibrateFusedMatches(req.Query, lateDateDocumentBackfillMatches, req.Query));
                AddRankedMatches(
                    selected,
                    selectedKeys,
                    calibratedLateDateDocumentBackfill,
                    topK,
                    minScore: 0.0,
                    maxPerDoc: Math.Max(maxPerDoc, 3),
                    maxPerPage: Math.Max(maxPerPage, 2),
                    query: req.Query);
                PrioritizeFinalSelections(req.Query, selected);
                RebuildSelectedKeys(selected, selectedKeys);
                finalOrderingSw.Stop();
                selectionMs += finalOrderingSw.ElapsedMilliseconds;
            }
        }

        if (ShouldUseReferenceVersionOperandRoute(req.Query)
            && !SelectionsCoverReferenceVersionOperandContent(req.Query, selected))
        {
            var lateReferenceVersionGroupKeys = ExtractReferenceVersionGroupKeysFromQuery(req.Query).ToList();
            if (lateReferenceVersionGroupKeys.Count == 0)
                lateReferenceVersionGroupKeys.AddRange(InferReferenceVersionOperandGroupKeys(req.Query, selected));
            lateReferenceVersionGroupKeys = lateReferenceVersionGroupKeys
                .Where(static key => !string.IsNullOrWhiteSpace(key))
                .Distinct(StringComparer.Ordinal)
                .Take(6)
                .ToList();

            if (lateReferenceVersionGroupKeys.Count > 0)
            {
                var (lateReferenceVersionOperandMatches, lateReferenceVersionOperandMs) = await MeasurePhaseAsync(
                    phaseName: "retrieval_reference_version_operand_late_recovery",
                    retriever: "reference_version_operand_document_name",
                    action: () => SearchReferenceVersionOperandDocumentNameContentMatchesAsync(
                        ds,
                        tenantId,
                        req.Query,
                        lateReferenceVersionGroupKeys,
                        category,
                        req.DocId,
                        req.DocPath,
                        Math.Min(candidates, Math.Max(topK, 16)),
                        ct,
                        categoryPath,
                        degradedRetrieverRef: MarkRetrieverDegraded),
                    getReturnedCount: static matches => matches.Count);
                titleAnchorRoutePhaseMs += lateReferenceVersionOperandMs;

                if (lateReferenceVersionOperandMatches.Count > 0)
                {
                    finalOrderingSw.Restart();
                    RebuildSelectedKeys(selected, selectedKeys);
                    var calibratedLateReferenceVersionOperand = SuppressNavigationalNoise(
                        req.Query,
                        CalibrateFusedMatches(req.Query, lateReferenceVersionOperandMatches, req.Query));
                    AddRankedMatches(
                        selected,
                        selectedKeys,
                        calibratedLateReferenceVersionOperand,
                        topK,
                        minScore: 0.0,
                        maxPerDoc: Math.Max(maxPerDoc, 2),
                        maxPerPage: Math.Max(maxPerPage, 2),
                        query: req.Query);
                    EnsureComparativeBackfillDocumentDiversity(
                        selected,
                        selectedKeys,
                        calibratedLateReferenceVersionOperand,
                        topK,
                        minScore: 0.0,
                        maxPerPage: Math.Max(maxPerPage, 2),
                        query: req.Query);
                    PruneUnrelatedReferenceVersionGroupSelections(req.Query, selected);
                    PruneCurrentReferenceVersionSelectionsWhenHistoricalVersionRequested(req.Query, selected);
                    PrioritizeFinalSelections(req.Query, selected);
                    RebuildSelectedKeys(selected, selectedKeys);
                    finalOrderingSw.Stop();
                    selectionMs += finalOrderingSw.ElapsedMilliseconds;
                }
            }
        }

        if (selected.Count == 0 && !hasExplicitFileDocumentHint)
        {
            var lateDocumentStatusOperandTerms = ExtractDocumentStatusOperandLookupTerms(req.Query);
            if (lateDocumentStatusOperandTerms.Count > 0)
            {
                var (lateDocumentStatusRecoveryMatches, lateDocumentStatusRecoveryMs) = await MeasurePhaseAsync(
                    phaseName: "retrieval_document_status_operand_empty_recovery",
                    retriever: "document_status_operand",
                    action: () => SearchDocumentStatusOperandContentMatchesAsync(
                        ds,
                        tenantId,
                        req.Query,
                        lateDocumentStatusOperandTerms,
                        category,
                        req.DocId,
                        req.DocPath,
                        Math.Min(candidates, Math.Max(topK, 16)),
                        ct,
                        categoryPath,
                        degradedRetrieverRef: MarkRetrieverDegraded),
                    getReturnedCount: static matches => matches.Count);
                titleAnchorRoutePhaseMs += lateDocumentStatusRecoveryMs;

                if (lateDocumentStatusRecoveryMatches.Count > 0)
                {
                    finalOrderingSw.Restart();
                    var calibratedLateDocumentStatusRecovery = SuppressNavigationalNoise(
                        req.Query,
                        CalibrateFusedMatches(req.Query, lateDocumentStatusRecoveryMatches, req.Query));
                    AddRankedMatches(
                        selected,
                        selectedKeys,
                        calibratedLateDocumentStatusRecovery,
                        topK,
                        minScore: 0.0,
                        maxPerDoc: Math.Max(maxPerDoc, 2),
                        maxPerPage: Math.Max(maxPerPage, 2),
                        query: req.Query);
                    PrioritizeFinalSelections(req.Query, selected);
                    RebuildSelectedKeys(selected, selectedKeys);
                    finalOrderingSw.Stop();
                    selectionMs += finalOrderingSw.ElapsedMilliseconds;
                }
            }
        }

        if (selected.Count == 0
            && hasCategoryFilter
            && ShouldUseGenericVersionConflictOverviewRecovery(req.Query))
        {
            var (genericVersionOverviewMatches, genericVersionOverviewMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_generic_version_conflict_overview_recovery",
                retriever: "document_profile",
                action: () => SearchDocumentOverviewProfileMatchesAsync(
                    ds,
                    tenantId,
                    catalogOverviewFallbackQuery,
                    category,
                    req.DocId,
                    req.DocPath,
                    Math.Min(Math.Max(topK * 2, 12), 24),
                    ct,
                    categoryPath,
                    requireLexicalMatch: false,
                    degradedRetrieverRef: MarkRetrieverDegraded,
                    commandTimeoutSeconds: sparseCommandTimeoutSeconds),
                getReturnedCount: static matches => matches.Count);
            profilePhaseMs += genericVersionOverviewMs;

            if (genericVersionOverviewMatches.Count > 0)
            {
                finalOrderingSw.Restart();
                AddRankedMatches(
                    selected,
                    selectedKeys,
                    CalibrateFusedMatches(catalogOverviewFallbackQuery, genericVersionOverviewMatches, req.Query),
                    topK,
                    minScore: 0.0,
                    maxPerDoc: 1,
                    maxPerPage: Math.Max(maxPerPage, 1),
                    query: req.Query);
                RebuildSelectedKeys(selected, selectedKeys);
                finalOrderingSw.Stop();
                selectionMs += finalOrderingSw.ElapsedMilliseconds;
            }
        }

        if (hasExplicitFileDocumentHint
            && !SelectionsCoverExplicitFileLookupGroups(req.Query, selected))
        {
            var (lateExplicitFileProfileMatches, lateExplicitFileProfileMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_explicit_file_profile_late_recovery",
                retriever: "document_hint_profile_recovery",
                action: () => SearchExplicitFileHintProfileRecoveryMatchesAsync(
                    ds,
                    tenantId,
                    req.Query,
                    category,
                    categoryPath,
                    Math.Min(Math.Max(topK, 8), 16),
                    ct,
                    degradedRetrieverRef: MarkRetrieverDegraded,
                    commandTimeoutSeconds: sparseCommandTimeoutSeconds),
                getReturnedCount: static matches => matches.Count);
            profilePhaseMs += lateExplicitFileProfileMs;

            if (lateExplicitFileProfileMatches.Count > 0)
            {
                finalOrderingSw.Restart();
                selected.Clear();
                selectedKeys.Clear();
                AddRankedMatches(
                    selected,
                    selectedKeys,
                    CalibrateFusedMatches(req.Query, lateExplicitFileProfileMatches, req.Query),
                    topK,
                    minScore: 0.0,
                    maxPerDoc: Math.Max(maxPerDoc, 2),
                    maxPerPage: Math.Max(maxPerPage, 1),
                    query: req.Query);
                RebuildSelectedKeys(selected, selectedKeys);
                finalOrderingSw.Stop();
                selectionMs += finalOrderingSw.ElapsedMilliseconds;
            }
        }

        var finalStandardReferencePhrases = ExtractStandardReferenceTitleLookupPhrases(req.Query);
        if (finalStandardReferencePhrases.Count > 1
            && !SelectionsCoverStandardReferencePhrases(finalStandardReferencePhrases, selected))
        {
            var (finalStandardReferenceProfileMatches, finalStandardReferenceProfileMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_standard_reference_profile_final_recovery",
                retriever: "standard_reference_document_name_profile",
                action: () => SearchStandardReferenceDocumentNameProfileMatchesAsync(
                    ds,
                    tenantId,
                    req.Query,
                    finalStandardReferencePhrases,
                    category,
                    req.DocId,
                    req.DocPath,
                    Math.Min(candidates, Math.Max(topK, 16)),
                    ct,
                    categoryPath,
                    degradedRetrieverRef: MarkRetrieverDegraded,
                    commandTimeoutSeconds: sparseCommandTimeoutSeconds),
                getReturnedCount: static matches => matches.Count);
            profilePhaseMs += finalStandardReferenceProfileMs;

            if (SelectionsCoverStandardReferencePhrases(finalStandardReferencePhrases, finalStandardReferenceProfileMatches))
            {
                finalOrderingSw.Restart();
                selected.Clear();
                selectedKeys.Clear();
                AddRankedMatches(
                    selected,
                    selectedKeys,
                    CalibrateFusedMatches(req.Query, finalStandardReferenceProfileMatches, req.Query),
                    topK,
                    minScore: 0.0,
                    maxPerDoc: Math.Max(maxPerDoc, 2),
                    maxPerPage: Math.Max(maxPerPage, 1),
                    query: req.Query);
                PrioritizeFinalSelections(req.Query, selected);
                RebuildSelectedKeys(selected, selectedKeys);
                finalOrderingSw.Stop();
                selectionMs += finalOrderingSw.ElapsedMilliseconds;
            }
        }

        PruneUnrequestedStandardReferenceSelections(req.Query, selected);
        RebuildSelectedKeys(selected, selectedKeys);

        PrioritizeShortTechnicalDirectEvidenceSelections(req.Query, selected);
        RebuildSelectedKeys(selected, selectedKeys);

        if (ShouldSuppressUnscopedAmbiguousDocumentReferenceSources(req.Query, req.DocId, req.DocPath))
        {
            selected.Clear();
            selectedKeys.Clear();
        }

        if (selected.Count == 0
            && !skipChunkRetrieversForDocumentOverview
            && ShouldAllowCompactDocumentCodeEmptyRecovery(req.Query, hasExplicitFileDocumentHint)
            && compactDocumentCodeLookupPhrases.Count > 0)
        {
            var finalCompactCodeRecoveryLimit = Math.Min(candidates, Math.Max(topK * 4, 24));
            var (finalCompactCodeRecoveryMatches, finalCompactCodeRecoveryMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_compact_document_code_final_empty_recovery",
                retriever: "compact_document_code_recovery",
                action: async () =>
                {
                    var recovery = new List<RagMatch>();
                    foreach (var compactCode in compactDocumentCodeLookupPhrases.Take(3))
                    {
                        recovery.AddRange(await SearchTitleAnchorRouteMatchesAsync(
                            ds,
                            tenantId,
                            compactCode,
                            category,
                            req.DocId,
                            req.DocPath,
                            finalCompactCodeRecoveryLimit,
                            ct,
                            categoryPath,
                            degradedRetrieverRef: MarkRetrieverDegraded));
                        recovery.AddRange(await SearchDenseMatchesAsync(
                            ds,
                            httpFactory,
                            rag,
                            tenantId,
                            NormalizeQuery(compactCode),
                            category,
                            req.DocId,
                            req.DocPath,
                            finalCompactCodeRecoveryLimit,
                            ct,
                            teiMsRef: value => teiMs += value,
                            qdrantMsRef: value => qdrantMs += value,
                            qdrantStatusRef: value => qdrantStatus = value,
                            categoryPath: categoryPath,
                            degradedRetrieverRef: MarkRetrieverDegraded));
                    }

                    return recovery
                        .GroupBy(BuildMatchDedupKey, StringComparer.OrdinalIgnoreCase)
                        .Select(static group => group
                            .OrderByDescending(match => match.Score)
                            .ThenBy(match => match.DocPath, StringComparer.OrdinalIgnoreCase)
                            .ThenBy(match => match.ChunkIndex)
                            .First())
                        .ToList();
                },
                getReturnedCount: static matches => matches.Count);
            titleAnchorRoutePhaseMs += finalCompactCodeRecoveryMs;

            if (finalCompactCodeRecoveryMatches.Count > 0)
            {
                finalOrderingSw.Restart();
                var compactRecoveryQuery = string.Join(' ', compactDocumentCodeLookupPhrases);
                var calibratedRecovery = CalibrateFusedMatches(
                    compactRecoveryQuery,
                    finalCompactCodeRecoveryMatches,
                    req.Query);
                AddRankedMatches(
                    selected,
                    selectedKeys,
                    SuppressNavigationalNoise(req.Query, calibratedRecovery),
                    topK,
                    minScore: 0.0,
                    Math.Max(maxPerDoc, 2),
                    Math.Max(maxPerPage, 2),
                    query: compactRecoveryQuery);
                PruneNavigationalSelections(req.Query, selected);
                RebuildSelectedKeys(selected, selectedKeys);
                finalOrderingSw.Stop();
                selectionMs += finalOrderingSw.ElapsedMilliseconds;
            }
        }

        var finalCompactDocumentCodeProfilePhrases = ExtractCompactDocumentCodeProfileRecoveryPhrases(req.Query)
            .Where(phrase => !SelectionsCoverCompactDocumentCodePhrase(phrase, selected))
            .ToArray();
        if (finalCompactDocumentCodeProfilePhrases.Length > 0
            && !skipChunkRetrieversForDocumentOverview
            && ShouldAllowCompactDocumentCodeEmptyRecovery(req.Query, hasExplicitFileDocumentHint)
            && (selected.Count == 0 || ShouldPreferComparativeDocumentDiversity(req.Query)))
        {
            var (finalCompactProfileMatches, finalCompactProfileMs) = await MeasurePhaseAsync(
                phaseName: "retrieval_compact_document_code_profile_final_recovery",
                retriever: "compact_document_code_profile",
                action: async () =>
                {
                    var backfill = new List<RagMatch>();
                    foreach (var phrase in finalCompactDocumentCodeProfilePhrases.Take(4))
                    {
                        backfill.AddRange(await SearchDocumentOverviewProfileMatchesAsync(
                            ds,
                            tenantId,
                            phrase,
                            category,
                            req.DocId,
                            req.DocPath,
                            Math.Min(Math.Max(topK, 8), 16),
                            ct,
                            categoryPath,
                            requireLexicalMatch: true,
                            degradedRetrieverRef: MarkRetrieverDegraded,
                            commandTimeoutSeconds: sparseCommandTimeoutSeconds));
                    }

                    return DeduplicatePreciseTitleBackfillMatches(backfill);
                },
                getReturnedCount: static matches => matches.Count);
            profilePhaseMs += finalCompactProfileMs;

            if (finalCompactProfileMatches.Count > 0)
            {
                finalOrderingSw.Restart();
                var compactProfileQuery = string.Join(' ', finalCompactDocumentCodeProfilePhrases);
                AddRankedMatches(
                    selected,
                    selectedKeys,
                    CalibrateFusedMatches(compactProfileQuery, finalCompactProfileMatches, req.Query),
                    topK,
                    minScore: 0.0,
                    Math.Max(maxPerDoc, 2),
                    Math.Max(maxPerPage, 1),
                    query: compactProfileQuery);
                PrioritizeFinalSelections(req.Query, selected);
                RebuildSelectedKeys(selected, selectedKeys);
                finalOrderingSw.Stop();
                selectionMs += finalOrderingSw.ElapsedMilliseconds;
            }
        }

        if (selected.Count == 0
            && ShouldAllowLexicalProfileEmptyRecovery(req.Query, hasExplicitFileDocumentHint))
        {
            var lexicalProfileRecoveryQuery = BuildLexicalProfileEmptyRecoveryQuery(req.Query, categoryQueryHint);
            if (!string.IsNullOrWhiteSpace(lexicalProfileRecoveryQuery))
            {
                var (lexicalProfileRecoveryMatches, lexicalProfileRecoveryMs) = await MeasurePhaseAsync(
                    phaseName: "retrieval_lexical_profile_empty_recovery",
                    retriever: "lexical_profile_recovery",
                    action: () => SearchDocumentOverviewProfileMatchesAsync(
                        ds,
                        tenantId,
                        lexicalProfileRecoveryQuery,
                        category,
                        req.DocId,
                        req.DocPath,
                        Math.Min(Math.Max(topK, 8), 16),
                        ct,
                        categoryPath,
                        requireLexicalMatch: true,
                        degradedRetrieverRef: MarkRetrieverDegraded,
                        commandTimeoutSeconds: sparseCommandTimeoutSeconds),
                    getReturnedCount: static matches => matches.Count);
                profilePhaseMs += lexicalProfileRecoveryMs;

                if (lexicalProfileRecoveryMatches.Count > 0)
                {
                    finalOrderingSw.Restart();
                    AddRankedMatches(
                        selected,
                        selectedKeys,
                        CalibrateFusedMatches(lexicalProfileRecoveryQuery, lexicalProfileRecoveryMatches, req.Query),
                        topK,
                        minScore: 0.0,
                        Math.Max(maxPerDoc, 2),
                        Math.Max(maxPerPage, 1),
                        query: lexicalProfileRecoveryQuery);
                    PrioritizeFinalSelections(req.Query, selected);
                    RebuildSelectedKeys(selected, selectedKeys);
                    finalOrderingSw.Stop();
                    selectionMs += finalOrderingSw.ElapsedMilliseconds;
                }
            }
        }

        swTotal.Stop();

        var response = new RagSearchResponse(
            RequestId: ctx.GetRequestId(),
            Query: req.Query,
            QueryNormalized: queryNorm,
            Category: requestedCategory ?? categoryQueryHint,
            TopK: requestedTopK,
            MinScore: selectionMinScore,
            Candidates: candidates,
            MaxPerDoc: maxPerDoc,
            MaxPerPage: maxPerPage,
            QdrantStatus: qdrantStatus,
            Timings: new RagSearchTimings(
                TotalMs: swTotal.ElapsedMilliseconds,
                TeiMs: teiMs,
                RerankMs: rerankMs,
                SparseMs: sparseMs,
                QdrantMs: qdrantMs,
                ExactMs: exactMs,
                QuotedTitleMs: quotedTitleMs,
                LocalTitleTokenMs: localTitleTokenMs,
                TitleAnchorRouteMs: titleAnchorRoutePhaseMs,
                SparsePhaseMs: sparsePhaseMs,
                DenseMs: densePhaseMs,
                ProfileMs: profilePhaseMs,
                LinkedMs: linkedPhaseMs,
                FusionMs: fusionMs,
                RerankPhaseMs: rerankPhaseMs,
                SelectionMs: selectionMs),
            Matches: selected.Take(requestedTopK).ToList(),
            DegradedRetrievers: degradedRetrievers.Count == 0
                ? null
                : degradedRetrievers.OrderBy(static retriever => retriever, StringComparer.Ordinal).ToArray(),
            DegradedRetrieverErrors: degradedRetrieverErrors.Count == 0
                ? null
                : degradedRetrieverErrors
                    .OrderBy(static pair => pair.Key, StringComparer.Ordinal)
                    .ToDictionary(static pair => pair.Key, static pair => pair.Value, StringComparer.Ordinal));

        RetrievalTelemetry.CompleteSearch(searchActivity, response, mode, hasCategoryFilter, hasDocScope);
        RetrievalTelemetry.RecordSearch(response, mode, hasCategoryFilter, hasDocScope, exactMs, sparsePhaseMs + titleAnchorRoutePhaseMs + profilePhaseMs, densePhaseMs, linkedPhaseMs);

        return response;
    }

    private static async Task<string?> ResolveRagCategoryPathAsync(
        NpgsqlDataSource ds,
        Guid tenantId,
        string? categoryPath,
        string? categoryRef,
        CancellationToken ct)
    {
        var normalizedPath = DocumentsCategoryScopeResolver.NormalizeCategoryPathOrNull(categoryPath);
        var normalizedRef = DocumentsCategoryScopeResolver.NormalizeCategoryRefOrNull(categoryRef);
        if (string.IsNullOrWhiteSpace(normalizedPath) && string.IsNullOrWhiteSpace(normalizedRef))
            return null;

        await using var conn = await ds.OpenConnectionAsync(ct);
        var resolved = await DocumentsCategoryScopeResolver.ResolveCategoryScopeAsync(
            conn,
            tenantId,
            normalizedPath,
            normalizedRef,
            ct);

        return DocumentsCategoryScopeResolver.NormalizeCategoryPathOrNull(resolved ?? normalizedPath);
    }

    private static string? NormalizeRagCategoryPathForSql(string? categoryPath)
        => DocumentsCategoryScopeResolver.NormalizeCategoryPathOrNull(categoryPath);

    private static bool RagDocPathMatchesCategoryPath(string? docPath, string? categoryPath)
    {
        if (string.IsNullOrWhiteSpace(categoryPath))
            return true;
        if (string.IsNullOrWhiteSpace(docPath))
            return false;

        var normalizedDocPath = docPath.Trim().Replace('\\', '/').Trim('/');
        return string.Equals(normalizedDocPath, categoryPath, StringComparison.OrdinalIgnoreCase)
            || normalizedDocPath.StartsWith(categoryPath + "/", StringComparison.OrdinalIgnoreCase);
    }

    internal static string ResolveEffectiveSearchMode(string? requestedMode, string query)
    {
        var mode = (requestedMode ?? string.Empty).Trim().ToLowerInvariant();
        if (string.Equals(mode, "focused", StringComparison.Ordinal)
            && ShouldPromoteFocusedSearchForBroadIntent(query))
        {
            return ShouldPreferDocumentDiversity(query) ? "broad" : "balanced";
        }

        if (mode is "focused" or "balanced" or "broad")
            return mode;

        return ShouldPreferDocumentDiversity(query)
            ? "broad"
            : "balanced";
    }

    internal static int ResolveInternalSelectionTopK(
        string query,
        int requestedTopK,
        int maxTopK,
        bool hasDocScope,
        bool hasExplicitFileDocumentHint,
        string mode)
    {
        if (requestedTopK <= 0)
            return requestedTopK;
        if (hasDocScope || hasExplicitFileDocumentHint)
            return requestedTopK;
        if (string.Equals(mode, "focused", StringComparison.Ordinal))
            return requestedTopK;

        var needsTitleOrDiversityHeadroom =
            ExtractTitleLookupPhrases(query).Count > 0
            || ShouldPreferComparativeDocumentDiversity(query);
        if (!needsTitleOrDiversityHeadroom)
            return requestedTopK;

        return Math.Min(
            Math.Max(requestedTopK, 16),
            Math.Max(requestedTopK, maxTopK));
    }

    internal static bool ShouldPreferDocumentDiversity(string query)
        => ShouldPreferComparativeDocumentDiversity(query)
           || ContainsDocumentOverviewIntent(query);

    internal static bool ShouldSkipChunkRetrieversForDocumentOverview(string query, bool hasDocScope, string mode)
    {
        if (ShouldTreatQuotedLookupAsTopic(query))
            return false;

        if (ExtractQuotedLookupPhrases(query).Count > 0
            && !ShouldSkipPreciseTitleLookupForDocumentOverview(query, hasDocScope, mode))
        {
            return false;
        }

        return !hasDocScope
           && !string.Equals(mode, "focused", StringComparison.Ordinal)
           && ContainsDocumentOverviewIntent(query)
           && !ShouldRequireDocumentOverviewProfileMatch(query);
    }

    internal static bool ShouldSkipPreciseTitleLookupForDocumentOverview(string query, bool hasDocScope, string mode)
    {
        if (hasDocScope || string.Equals(mode, "focused", StringComparison.Ordinal))
            return false;

        var quotedPhrases = ExtractQuotedLookupPhrases(query);
        if (quotedPhrases.Count == 0)
            return false;
        if (quotedPhrases.Any(static phrase => LooksLikeExplicitFileLookupPhrase(phrase)))
            return false;
        var normalized = $" {FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query)).ToLowerInvariant()} ";
        var hasQuotedDocumentOverviewIntent = ContainsDocumentOverviewIntent(query)
            || (ContainsAny(normalized, " documents ", " document ", " sources ", " source ", " pdf ")
                && ContainsAny(
                    normalized,
                    " qui parle ",
                    " qui parlent ",
                    " parle de ",
                    " parlent de ",
                    " mentionne ",
                    " mentionnent ",
                    " contient ",
                    " contiennent ",
                    " about ",
                    " mention ",
                    " mentions ",
                    " contain ",
                    " contains "));
        if (!hasQuotedDocumentOverviewIntent)
            return false;

        return true;
    }

    private static bool LooksLikeExplicitFileLookupPhrase(string phrase)
    {
        if (string.IsNullOrWhiteSpace(phrase))
            return false;

        var normalized = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(phrase)).ToLowerInvariant();
        var tokens = normalized
            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        if (tokens.Length == 0 || !tokens.Any(IsFileExtensionToken))
            return false;

        return tokens.Any(IsDocumentHintSignalToken);
    }

    internal static bool ShouldTreatQuotedLookupAsTopic(string query)
    {
        if (ExtractQuotedLookupPhrases(query).Count == 0)
            return false;

        var normalized = $" {FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query)).ToLowerInvariant()} ";
        var hasTopicRelation = ContainsAny(
            normalized,
            " sur ",
            " about ",
            " on ",
            " concernant ",
            " en lien avec ",
            " associe a ",
            " associes a ",
            " associated with ",
            " related to ",
            " parle de ",
            " parle d ",
            " parlent de ",
            " parlent d ",
            " impose ",
            " imposent ",
            " documente ",
            " documentent ",
            " documented ",
            " documents ",
            " require ",
            " requires ",
            " requires that ",
            " obligation ",
            " obligations ",
            " recommandation ",
            " recommendation ",
            " recommendations ",
            " demontre ",
            " demonstrated ",
            " verifie si ",
            " verify whether ");
        if (!hasTopicRelation)
            return false;

        return ContainsAny(
            normalized,
            " oui non ",
            " yes no ",
            " documents ",
            " pdf ",
            " corpus ",
            " passages ",
            " question client ",
            " refuse la simplification ",
            " no clear yes no ",
            " if the pdf ",
            " if the documents ",
            " cannot confirm ");
    }

    internal static bool ShouldSkipSparseRetrieverForBroadDiversity(string query, string mode)
        => !string.Equals(mode, "focused", StringComparison.Ordinal)
           && ExtractQuotedLookupPhrases(query).Count == 0
           && ShouldTreatAsBroadDiversityQuery(query)
           && !ShouldAllowSparseAssistForBroadDiversity(query);

    internal static bool ShouldSkipUnanchoredTitleAnchorRouteForBroadDiversity(string query)
    {
        if (string.IsNullOrWhiteSpace(query)
            || ExtractQuotedLookupPhrases(query).Count > 0
            || HasExplicitDocumentNameHint(query))
        {
            return false;
        }

        var normalized = " " + FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query)).ToLowerInvariant() + " ";
        var shouldSkipBroadComparativeSynthesis =
            ShouldSkipUnanchoredTitleAnchorRouteForBroadComparativeSynthesis(query, normalized);
        if (HasReferenceLikeQueryToken(query) && !shouldSkipBroadComparativeSynthesis)
            return false;

        if (ContainsAny(normalized, " vs ", " versus ") && !shouldSkipBroadComparativeSynthesis)
            return false;

        if (shouldSkipBroadComparativeSynthesis)
            return true;

        if (ShouldPreferComparativeDocumentDiversity(query)
            && ContainsAny(normalized, " choisir entre ", " choisis entre ", " choisissez entre ", " choix entre ", " choose between ", " select between "))
        {
            return true;
        }

        if (!ShouldTreatAsBroadDiversityQuery(query))
            return false;

        return true;
    }

    private static bool ShouldSkipUnanchoredTitleAnchorRouteForBroadComparativeSynthesis(string query, string normalized)
    {
        if (!ShouldPreferComparativeDocumentDiversity(query))
            return false;

        var hasComparativeShape = ContainsAny(
            normalized,
            " vs ",
            " versus ",
            " compare ",
            " comparer ",
            " comparaison ",
            " comparative ",
            " comparatif ",
            " difference entre ",
            " differences entre ",
            " difference between ",
            " differences between ",
            " avant apres ",
            " before after ");
        if (!hasComparativeShape)
            return false;

        var hasSynthesisSurface = ContainsAny(
            normalized,
            " tableau ",
            " table ",
            " colonne ",
            " colonnes ",
            " ancienne source ",
            " nouvelle source ",
            " source ancienne ",
            " source nouvelle ",
            " old source ",
            " new source ",
            " older source ",
            " newer source ",
            " changement ",
            " changements ",
            " change ",
            " changes ",
            " evolue ",
            " evolution ",
            " evolutions ",
            " impact ",
            " impacts ",
            " mise a jour ",
            " mises a jour ",
            " updated ",
            " update ",
            " perimetre ",
            " scope ",
            " recouvrement ",
            " overlap ");
        if (!hasSynthesisSurface)
            return false;

        return ContainsAny(
                normalized,
                " document ",
                " documents ",
                " pdf ",
                " pdfs ",
                " corpus ",
                " source ",
                " sources ",
                " version ",
                " versions ")
            || ContainsAny(normalized, " vs ", " versus ");
    }

    internal static bool ShouldUseChoiceBetweenLexicalRoute(string query)
    {
        if (string.IsNullOrWhiteSpace(query)
            || ExtractQuotedLookupPhrases(query).Count > 0
            || HasExplicitDocumentNameHint(query)
            || HasReferenceLikeQueryToken(query))
        {
            return false;
        }

        var normalized = " " + FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query)).ToLowerInvariant() + " ";
        return ContainsAny(normalized, " choisir entre ", " choisis entre ", " choisissez entre ", " choix entre ", " choose between ", " select between ")
            && !ContainsAny(normalized, " vs ", " versus ");
    }

    internal static string BuildChoiceBetweenRetrievalQuery(string query)
    {
        if (!ShouldUseChoiceBetweenLexicalRoute(query))
            return ResolvePrimaryRetrievalQuery(query, category: null);

        var normalized = ExactMatchEntryExtractor.NormalizeForLookup(query);
        var folded = FoldDiacritics(normalized);
        var betweenMatch = Regex.Match(
            folded,
            @"\b(?:entre|between)\s+(?<target>[\p{L}\p{Nd}\s\-:;,]{8,180}?)(?=\s+(?:comment|how|pourquoi|why|explique|explain)\b|[\?\r\n]|$)",
            RegexOptions.CultureInvariant);
        if (!betweenMatch.Success)
            return ResolvePrimaryRetrievalQuery(query, category: null);

        var subject = betweenMatch.Groups["target"].Value.Trim();
        return string.IsNullOrWhiteSpace(subject)
            ? ResolvePrimaryRetrievalQuery(query, category: null)
            : subject;
    }

    internal static bool ShouldAllowSparseAssistForBroadDiversity(string query)
    {
        var hasReferenceLikeQuery = HasReferenceLikeQueryToken(query);
        if (!ShouldTreatAsBroadDiversityQuery(query)
            || ExtractQuotedLookupPhrases(query).Count > 0
            || (hasReferenceLikeQuery && !ShouldAllowReferenceLikeComparativeDiversity(query, $" {FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query)).ToLowerInvariant()} ")))
        {
            return false;
        }

        var concreteTokens = ExtractLexicalQueryTokens(query)
            .Where(static token => !BroadDiversityGenericSubjectTokens.Contains(token))
            .Where(static token => !BroadDiversityAbstractAssistTokens.Contains(token))
            .Where(static token => !DocumentOverviewTopicStopwords.Contains(token))
            .Where(static token => !PrimaryAnchorStopwords.Contains(token))
            .Where(static token => !ComparativeSubjectStopwords.Contains(token))
            .Distinct(StringComparer.Ordinal)
            .ToArray();

        return concreteTokens.Length >= 3;
    }

    internal static bool ShouldSkipSparseRetrieverForQuantityLookup(string query, string mode)
        => false;

    internal static bool ShouldSkipSparseProfileCardAssist(string query, string mode)
    {
        if (string.IsNullOrWhiteSpace(query)
            || ExtractQuotedLookupPhrases(query).Count > 0
            || HasReferenceLikeQueryToken(query))
        {
            return false;
        }

        var normalized = " " + FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query)).ToLowerInvariant() + " ";
        return ContainsDocumentOverviewIntent(query)
            || ContainsExplicitBroadScopedSynthesisIntent(normalized)
            || ContainsBroadScopedSynthesisIntent(normalized)
            || ContainsUnsupportedClaimVerificationIntent(normalized)
            || ContainsSituationalBroadSelectionIntent(normalized)
            || ContainsQuantityComputationIntent(normalized)
            || (string.Equals(mode, "broad", StringComparison.Ordinal) && ShouldPreferDocumentDiversity(query));
    }

    internal static bool ShouldSkipDocumentProfileSearchForLowCostBroadQuery(string query, string mode)
    {
        if (string.IsNullOrWhiteSpace(query)
            || ExtractQuotedLookupPhrases(query).Count > 0
            || HasReferenceLikeQueryToken(query)
            || ContainsDocumentOverviewIntent(query))
        {
            return false;
        }

        var normalized = " " + FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query)).ToLowerInvariant() + " ";
        if (ShouldAllowDocumentProfileAssistForComparativeLookup(query))
            return false;

        return ContainsExplicitBroadScopedSynthesisIntent(normalized)
            || ContainsBroadScopedSynthesisIntent(normalized)
            || ContainsSituationalBroadSelectionIntent(normalized)
            || ContainsQuantityComputationIntent(normalized)
            || (string.Equals(mode, "broad", StringComparison.Ordinal) && ShouldPreferDocumentDiversity(query));
    }

    internal static bool ShouldTreatAsBroadDiversityQuery(string query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return false;

        var normalized = " " + FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query)).ToLowerInvariant() + " ";
        return ShouldTreatAsBroadDiversityQuery(query, normalized);
    }

    private static bool ShouldTreatAsBroadDiversityQuery(string query, string normalized)
    {
        var hasReferenceLikeQuery = HasReferenceLikeQueryToken(query);
        if (!ShouldPreferComparativeDocumentDiversity(query)
            || ExtractQuotedLookupPhrases(query).Count > 0
            || (hasReferenceLikeQuery
                && ExtractComparativeVersionOperandLookupTerms(query).Count == 0
                && !ShouldAllowReferenceLikeComparativeDiversity(query, normalized)))
        {
            return false;
        }

        var hasComparisonMarker = ContainsAny(normalized,
            " compare ",
            " comparer ",
            " compares ",
            " comparing ",
            " comparative ",
            " comparaison ",
            " comparatif ",
            " compara ",
            " comparar ",
            " comparacion ",
            " comparacao ",
            " confronto ",
            " difference entre ",
            " differences entre ",
            " different between ",
            " difference between ",
            " differences between ",
            " distinction ",
            " distinguer ",
            " distinguish between ",
            " distinguish ",
            " vs ",
            " versus ",
            " contre ",
            " choisir entre ",
            " choisis entre ",
            " choose between ",
            " vergleiche ",
            " vergleichen ");
        if (ContainsGuidanceOrAdviceSelectionIntent(normalized)
            && !hasComparisonMarker)
        {
            return false;
        }

        var hasExplicitDiversityMarker = ContainsAny(normalized,
                " deux ",
                " trois ",
                " plusieurs ",
                " multiple ",
                " several ",
                " versions ",
                " variantes ",
                " styles ",
                " famille ",
                " familles ",
                " family ",
                " series ",
                " serie ",
                " parties ",
                " partie ",
                " parts ",
                " part ",
                " entre ",
                " between ",
                " corpus ",
                " documents ",
                " docs ",
                " pdf ",
                " pdfs ");
        return hasExplicitDiversityMarker
            || (hasComparisonMarker && HasSpecificComparativeSubject(query))
            || ShouldUseBareVsComparativeOperandRoute(query)
            || (ContainsAny(normalized, " le plus ", " la plus ", " les plus ", " most ", " mas ", " mais ", " am meisten ")
                && ContainsAny(
                    normalized,
                    " quel ",
                    " quelle ",
                    " quels ",
                    " quelles ",
                    " lequel ",
                    " laquelle ",
                    " lesquels ",
                    " lesquelles ",
                    " which ",
                    " what ",
                    " cual ",
                    " qual ",
                    " quale ",
                    " welches ",
                    " welche "));
    }

    private static bool ShouldAllowReferenceLikeComparativeDiversity(string query, string normalized)
    {
        if (string.IsNullOrWhiteSpace(query)
            || ExtractStandardReferenceTitleLookupPhrases(query).Count == 0)
        {
            return false;
        }

        var hasFamilyScope = ContainsAny(
            normalized,
            " famille ",
            " family ",
            " serie ",
            " series ",
            " gamme ",
            " collection ",
            " partie ",
            " parties ",
            " part ",
            " parts ",
            " volume ",
            " volumes ",
            " documents lies ",
            " related documents ",
            " documents connexes ",
            " normes liees ",
            " related standards ");
        if (!hasFamilyScope)
            return false;

        return ContainsAny(
            normalized,
            " compare ",
            " comparer ",
            " comparaison ",
            " comparative ",
            " comparatif ",
            " vs ",
            " versus ",
            " difference entre ",
            " differences entre ",
            " difference between ",
            " differences between ",
            " distinction ",
            " distinguer ",
            " distinguish ",
            " distinguish between ");
    }

    private static bool HasSpecificComparativeSubject(string query)
        => ExtractComparativeLookupPhrases(query)
            .SelectMany(ExtractLexicalQueryTokens)
            .Any(static token => token.Length >= 5 && !BroadDiversityGenericSubjectTokens.Contains(token));

