        if (!hasScopedCorpus)
            return false;

        var asksVerification = ContainsAny(normalized,
                " verifie si ",
                " verifier si ",
                " verifie que ",
                " verifier que ",
                " confirme si ",
                " confirmer si ",
                " est ce prouve ",
