        {
            return true;
        }

        if (ContainsAny(normalized, " deux documents ", " deux pdf ", " deux fichiers ", " two documents ", " two pdfs ", " two files ")
            && ContainsAny(normalized,
                " meme chose ",
                " memes choses ",
