                " differs "))
        {
            return true;
        }

        if (ContainsAny(normalized, " le plus ", " la plus ", " les plus ", " most ", " mas ", " mais ", " am meisten "))
            return ContainsAny(normalized,
                " quel ",
                " quelle ",
                " quels ",
                " quelles ",
