            " not a copy paste ",
            " not copy paste ",
            " key points ",
            " important points ");
        if (!hasRawVagueCategoryGuidanceIntent && !hasVagueCategoryGuidanceIntent)
            return false;

        return !HasReferenceLikeQueryToken(query);
