    internal static async Task<List<RagMatch>> SearchDocumentProfileMatchesAsync(
        NpgsqlDataSource ds,
        Guid tenantId,
        string query,
        string? category,
        string? docId,
        string? docPath,
        int topK,
        CancellationToken ct,
        string? categoryPath = null,
        Action<string, string?>? degradedRetrieverRef = null,
        int commandTimeoutSeconds = RagOptions.DefaultSearchSparseCommandTimeoutSeconds)
    {
        if (string.IsNullOrWhiteSpace(query) || topK <= 0)
            return [];

        var lexicalTerms = BuildDocumentProfileLexicalTerms(query);
        if (lexicalTerms.Count == 0)
            return [];

        var normalizedDocPath = string.IsNullOrWhiteSpace(docPath)
            ? null
            : docPath.Trim().Replace('\\', '/').TrimStart('/');
        var normalizedCategoryPath = NormalizeRagCategoryPathForSql(categoryPath);
        Guid? normalizedDocId = Guid.TryParse(docId, out var parsedDocId) ? parsedDocId : null;
        var resultLimit = ComputeDocumentProfileSearchResultLimit(topK);
        var commandTimeout = RagOptions.ResolveSearchSparseCommandTimeoutSeconds(commandTimeoutSeconds);

        await using var conn = await ds.OpenConnectionAsync(ct);
        const string sql = """
WITH sparse_query AS (
    SELECT websearch_to_tsquery('simple', @query_text) AS q
),
lexical_terms AS (
    SELECT DISTINCT LOWER(term) AS term
    FROM unnest(@lexical_terms::text[]) AS term
    WHERE term IS NOT NULL AND term <> ''
),
scoped_entries AS (
    SELECT
        d.doc_id,
        d.doc_path,
        d.doc_name,
        d.category,
        d.indexed_version,
        d.content_hash,
        d.updated_at,
        e.document_profile_id,
        e.summary_text,
        e.search_text,
        e.search_tsv,
        e.metadata_json,
        e.language,
        e.profile_version,
        e.keywords,
        e.entities,
        e.topics,
        e.hypothetical_questions,
        e.limits
    FROM documents d
    JOIN document_revisions r
      ON r.tenant_id = d.tenant_id
     AND r.doc_id = d.doc_id
     AND r.indexed_version = d.indexed_version
    JOIN document_profile_search_entries e
      ON e.tenant_id = r.tenant_id
     AND e.revision_id = r.revision_id
    WHERE d.tenant_id = @tenant_id
      AND d.status = 'indexed'
      AND d.indexed_version > 0
      AND (@category IS NULL OR LOWER(d.category) = @category)
      AND (@category_path IS NULL OR d.doc_path = @category_path OR d.doc_path LIKE (@category_path || '/%'))
      AND (@doc_id IS NULL OR d.doc_id = @doc_id)
      AND (@doc_path IS NULL OR d.doc_path = @doc_path)
)
SELECT
    se.doc_id AS "DocId",
    se.doc_path AS "DocPath",
    se.doc_name AS "DocName",
    se.category AS "Category",
    se.document_profile_id AS "ProfileId",
    se.indexed_version AS "IngestionVersion",
    LOWER(ENCODE(se.content_hash, 'hex')) AS "HashDoc",
    COALESCE(NULLIF(se.summary_text, ''), se.doc_name, se.doc_path) AS "Text",
    se.search_text AS "SearchText",
    se.metadata_json::text AS "MetadataJson",
    se.language AS "Language",
    se.profile_version AS "ProfileVersion",
    se.keywords AS "Keywords",
    se.entities AS "Entities",
    se.topics AS "Topics",
    se.hypothetical_questions AS "HypotheticalQuestions",
    se.limits AS "Limits",
    ts_rank_cd(
        se.search_tsv,
        sparse_query.q,
        32
    ) + (lm.match_weight::real * 0.04) AS "SparseRank",
    lm.match_count AS "MatchCount"
FROM sparse_query
JOIN scoped_entries se ON TRUE
CROSS JOIN LATERAL (
    SELECT
        COUNT(*) AS match_count,
        COALESCE(SUM(
            CASE
                WHEN lexical_terms.term LIKE '% %' AND length(lexical_terms.term) >= 18 THEN 7.0
                WHEN lexical_terms.term LIKE '% %' THEN 5.0
                WHEN length(lexical_terms.term) >= 10 THEN 2.5
                WHEN length(lexical_terms.term) >= 7 THEN 1.6
                ELSE 1.0
            END), 0.0) AS match_weight
    FROM lexical_terms
    WHERE CASE
        WHEN lexical_terms.term LIKE '% %'
            THEN LOWER(se.search_text) LIKE '%' || REPLACE(lexical_terms.term, ' ', '%') || '%'
        ELSE LOWER(se.search_text) LIKE '%' || lexical_terms.term || '%'
    END
) lm
WHERE (
       se.search_tsv @@ sparse_query.q
       OR lm.match_count > 0
      )
ORDER BY
    (ts_rank_cd(se.search_tsv, sparse_query.q, 32)
        + (lm.match_weight::real * 0.04)) DESC,
    se.updated_at DESC
LIMIT @result_limit;
""";

        try
        {
            var rows = (await conn.QueryAsync<DocumentProfileMatchRow>(new CommandDefinition(sql, new
            {
                tenant_id = tenantId,
                query_text = query.Trim(),
                lexical_terms = lexicalTerms.ToArray(),
                category,
                category_path = normalizedCategoryPath,
                doc_id = normalizedDocId,
                doc_path = normalizedDocPath,
                result_limit = resultLimit
            }, commandTimeout: commandTimeout, cancellationToken: ct))).ToList();

            return RankDocumentProfileRows(query, rows)
                .Take(topK)
                .Select(scored =>
            {
                var row = scored.Row;
                var pageRange = ResolveDocumentProfileMatchPageRange(row.MetadataJson, query);
                var matchedContentCards = BuildMatchedContentCards(row.MetadataJson, query);
                var profileSectionTitle = BuildDocumentProfileSectionTitle(row.Language);
                return new RagMatch(
                    Score: scored.Score,
                    DocId: row.DocId.ToString(),
                    DocPath: row.DocPath,
                    DocName: row.DocName,
                    Category: row.Category,
                    PageStart: pageRange.PageStart,
                    PageEnd: pageRange.PageEnd,
                    ChunkId: row.ProfileId.ToString(),
                    ChunkIndex: -1,
                    Text: BuildDocumentProfileMatchText(row.Text, row.MetadataJson, query, row.Language),
                    IngestionVersion: row.IngestionVersion,
                    HashDoc: row.HashDoc,
                    EmbedText: row.SearchText,
                    EmbeddingBasis: "document_profile_v1",
                    SectionOrdinal: null,
                    UnitOrdinal: null,
                    SectionTitle: profileSectionTitle,
                    HeadingPath: profileSectionTitle,
                    ChunkType: "document_profile",
                    PrevChunkId: null,
                    NextChunkId: null,
                    SameSectionChunkId: null,
                    MatchedContentCards: matchedContentCards.Count == 0 ? null : matchedContentCards,
                    ProfileSignals: BuildDocumentProfileSignals(row, query));
            }).ToList();
        }
        catch (Exception ex) when (ex is PostgresException or InvalidOperationException || IsRetrieverDatabaseTimeout(ex))
        {
            RetrievalTelemetry.RecordRetrieverDegraded("document_profile_v1", ex);
            degradedRetrieverRef?.Invoke("document_profile_v1", FormatRetrieverError(ex));
            return [];
        }
    }

    internal static int ComputeDocumentProfileSearchResultLimit(int topK)
    {
        if (topK <= 0)
            return 0;

        return Math.Clamp(Math.Max(topK + 8, topK * 4), topK, 80);
    }

    private static IReadOnlyList<ScoredDocumentProfileMatchRow> RankDocumentProfileRows(
        string query,
        IReadOnlyList<DocumentProfileMatchRow> rows)
    {
        if (rows.Count == 0)
            return [];

        var peerTexts = rows
            .Select(static row => BuildDocumentProfileCandidateLookupText(row))
            .ToArray();

        return rows
            .Select((row, index) =>
            {
                var baseScore = NormalizeDocumentProfileScore(row.SparseRank, (int)Math.Min(row.MatchCount, int.MaxValue));
                var specificityBoost = ComputeDocumentProfileSpecificityBoost(query, peerTexts[index], peerTexts);
                var score = Math.Clamp(baseScore + specificityBoost, 0.0, 0.92);
                return new ScoredDocumentProfileMatchRow(row, score, specificityBoost, baseScore);
            })
            .OrderByDescending(static item => item.Score)
            .ThenByDescending(static item => item.SpecificityBoost)
            .ThenByDescending(static item => item.BaseScore)
            .ThenBy(static item => item.Row.DocName, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private static string BuildDocumentProfileCandidateLookupText(DocumentProfileMatchRow row)
        => CollapseWhitespace(string.Join(' ', new[]
        {
            row.DocPath,
            row.DocName,
            row.Text,
            row.SearchText,
            row.MetadataJson
        }));

    private static RagProfileSignals? BuildDocumentProfileSignals(DocumentProfileMatchRow row, string query)
    {
        var queryTokens = ExtractLexicalQueryTokens(query);
        var lexicalTerms = BuildDocumentProfileLexicalTerms(query);
        var matchedTerms = SelectMatchedProfileTerms(lexicalTerms, row.SearchText, maxItems: 12);
        var keywords = SelectProfileSignalValues(ProfileSignalValues(row.Keywords), queryTokens, lexicalTerms, maxItems: 8);
        var entities = SelectProfileSignalValues(ProfileSignalValues(row.Entities), queryTokens, lexicalTerms, maxItems: 8);
        var topics = SelectProfileSignalValues(ProfileSignalValues(row.Topics), queryTokens, lexicalTerms, maxItems: 8, fallbackItems: 3);
        var questions = SelectProfileSignalValues(ProfileSignalValues(row.HypotheticalQuestions), queryTokens, lexicalTerms, maxItems: 4);
        var limits = SelectProfileSignalValues(ProfileSignalValues(row.Limits), queryTokens, lexicalTerms, maxItems: 4, fallbackItems: 2);

        if (string.IsNullOrWhiteSpace(row.ProfileVersion)
            && string.IsNullOrWhiteSpace(row.Language)
            && matchedTerms.Count == 0
            && keywords.Count == 0
            && entities.Count == 0
            && topics.Count == 0
            && questions.Count == 0
            && limits.Count == 0
            && row.MatchCount <= 0)
        {
            return null;
        }

        return new RagProfileSignals(
            ProfileVersion: row.ProfileVersion,
            Language: row.Language,
            Keywords: keywords,
            Entities: entities,
            Topics: topics,
            HypotheticalQuestions: questions,
            Limits: limits,
            MatchedTerms: matchedTerms,
            MatchCount: row.MatchCount > int.MaxValue ? int.MaxValue : (int)Math.Max(0, row.MatchCount));
    }

    private static IReadOnlyList<string> SelectMatchedProfileTerms(
        IEnumerable<string>? terms,
        string? candidateText,
        int maxItems)
    {
        var normalizedCandidate = NormalizeForLexicalSignal(candidateText);
        if (string.IsNullOrWhiteSpace(normalizedCandidate) || terms is null)
            return Array.Empty<string>();

        return terms
            .Where(static term => !string.IsNullOrWhiteSpace(term))
            .Select(static term => term.Trim())
            .Where(term => normalizedCandidate.Contains(NormalizeForLexicalSignal(term), StringComparison.Ordinal))
            .Select(CompactProfileSignalValue)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(Math.Clamp(maxItems, 1, 24))
            .ToArray();
    }

    private static IReadOnlyList<string>? ProfileSignalValues(Array? values)
    {
        if (values is null || values.Length == 0)
            return null;

        return values
            .Cast<object?>()
            .Select(static value => value?.ToString())
            .Where(static value => !string.IsNullOrWhiteSpace(value))
            .Select(static value => value!.Trim())
            .ToArray();
    }

    private static IReadOnlyList<string> SelectProfileSignalValues(
        IEnumerable<string>? values,
        IReadOnlyList<string> queryTokens,
        IReadOnlyList<string> lexicalTerms,
        int maxItems,
        int fallbackItems = 0)
    {
        if (values is null)
            return Array.Empty<string>();

        var candidates = values
            .Where(static value => !string.IsNullOrWhiteSpace(value))
            .Select(static value => value.Trim())
            .Select(CompactProfileSignalValue)
            .Where(static value => value.Length >= 2)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();
        if (candidates.Length == 0)
            return Array.Empty<string>();

        var matched = candidates
            .Where(value => ProfileSignalOverlapsQuery(value, queryTokens, lexicalTerms))
            .Take(Math.Clamp(maxItems, 1, 24))
            .ToArray();
        if (matched.Length > 0 || fallbackItems <= 0)
            return matched;

        return candidates
            .Take(Math.Min(Math.Clamp(fallbackItems, 0, maxItems), candidates.Length))
            .ToArray();
    }

    private static string CompactProfileSignalValue(string value)
    {
        var trimmed = value.Trim();
        return trimmed.Length <= 160 ? trimmed : trimmed[..160].TrimEnd();
    }

    private static bool ProfileSignalOverlapsQuery(
        string value,
        IReadOnlyList<string> queryTokens,
        IReadOnlyList<string> lexicalTerms)
    {
        if (string.IsNullOrWhiteSpace(value))
            return false;

        var normalizedValue = NormalizeForLexicalSignal(value);
        if (string.IsNullOrWhiteSpace(normalizedValue))
            return false;

        if (lexicalTerms.Any(term => normalizedValue.Contains(NormalizeForLexicalSignal(term), StringComparison.Ordinal)))
            return true;

        return ComputeLexicalCoverage(queryTokens, value) >= 0.35;
    }

    private static string FormatPostgresRetrieverError(PostgresException ex)
        => string.IsNullOrWhiteSpace(ex.MessageText)
            ? ex.SqlState
            : $"{ex.SqlState}: {ex.MessageText}";

    private static string FormatRetrieverError(Exception ex)
        => ex is PostgresException pg
            ? FormatPostgresRetrieverError(pg)
            : $"{ex.GetType().Name}: {ex.Message}".Trim();

    private static bool IsRetrieverDatabaseTimeout(Exception ex)
    {
        if (ex is TimeoutException)
            return true;
        if (ex is OperationCanceledException)
            return true;
        if (ex is NpgsqlException { InnerException: TimeoutException })
            return true;
        if (ex is NpgsqlException { InnerException: OperationCanceledException })
            return true;
        return ex.InnerException is not null && IsRetrieverDatabaseTimeout(ex.InnerException);
    }

    private static List<SparseMatchRow> MergeSparseRows(
        IReadOnlyList<SparseMatchRow> preferred,
        IReadOnlyList<SparseMatchRow> secondary,
        int topK)
    {
        var merged = new List<SparseMatchRow>(Math.Max(0, topK));
        var seen = new HashSet<Guid>();

        foreach (var row in preferred.Concat(secondary))
        {
            if (!seen.Add(row.ChunkId))
                continue;

            merged.Add(row);
            if (merged.Count >= topK)
                break;
        }

        return merged;
    }

    private static string BuildDocumentProfileMatchText(string summaryText, string? metadataJson, string query, string? language)
    {
        var summary = string.IsNullOrWhiteSpace(summaryText)
            ? string.Empty
            : summaryText.Trim();
        var contentCards = SelectDocumentProfileContentCards(metadataJson, query);
        if (contentCards.Count == 0)
            return summary;

        var rankedCards = contentCards
            .Select(FormatDocumentProfileContentCard)
            .Where(static line => !string.IsNullOrWhiteSpace(line))
            .ToArray();

        if (rankedCards.Length == 0)
            return summary;

        var cardsText = $"{BuildContentCuesLabel(language)}: {string.Join("; ", rankedCards)}.";
        return string.IsNullOrWhiteSpace(summary)
            ? cardsText
            : $"{summary} {cardsText}";
    }

    internal static IReadOnlyList<RagMatchedContentCard> BuildMatchedContentCards(
        string? metadataJson,
        string query,
        int limit = 12,
        int? pageStart = null,
        int? pageEnd = null)
        => BuildMatchedContentCardsFromParsed(
            DocumentProfileProjector.ParseContentCards(metadataJson),
            query,
            limit,
            pageStart,
            pageEnd);

    private static IReadOnlyList<RagMatchedContentCard> BuildMatchedContentCardsFromParsed(
        IReadOnlyList<DocumentProfileContentCard> contentCards,
        string query,
        int limit = 12,
        int? pageStart = null,
        int? pageEnd = null)
        => SelectDocumentProfileContentCards(contentCards, query, limit, pageStart, pageEnd)
            .Select(static card => new RagMatchedContentCard(
                Title: card.Title,
                ContentCardId: card.ContentCardId,
                PageStart: card.PageStart,
                PageEnd: card.PageEnd,
                Kind: card.Kind,
                Signals: card.Signals,
                Evidence: BuildContentCardEvidenceJson(card.Evidence)))
            .ToArray();

    private static IReadOnlyList<RagMatchedContentCard>? BuildSparseMatchedContentCards(SparseMatchRow row, string query)
    {
        var cards = BuildMatchedContentCards(row.MatchedContentCardsJson, query, pageStart: row.PageStart, pageEnd: row.PageEnd);
        return cards.Count == 0 ? null : cards;
    }

    private static JsonElement? BuildContentCardEvidenceJson(DocumentProfileCardEvidence? evidence)
        => evidence is null ? null : JsonSerializer.SerializeToElement(evidence);

    private static IReadOnlyList<DocumentProfileContentCard> SelectDocumentProfileContentCards(
        string? metadataJson,
        string query,
        int limit = 12,
        int? pageStart = null,
        int? pageEnd = null)
    {
        var contentCards = DocumentProfileProjector.ParseContentCards(metadataJson);
        return SelectDocumentProfileContentCards(contentCards, query, limit, pageStart, pageEnd);
    }

    private static IReadOnlyList<DocumentProfileContentCard> SelectDocumentProfileContentCards(
        IReadOnlyList<DocumentProfileContentCard> contentCards,
        string query,
        int limit = 12,
        int? pageStart = null,
        int? pageEnd = null)
    {
        if (contentCards.Count == 0 || limit <= 0)
            return [];

        var queryTokens = ExtractLexicalQueryTokens(query);
        if (queryTokens.Count == 0)
            return [];

        var preferConcreteContentItems = ShouldPreferConcreteContentCardsForComparativeQuery(query);
        var ranked = contentCards
            .Where(card => ContentCardOverlapsMatchPageRange(card, pageStart, pageEnd))
            .Select(card => new
            {
                Card = card,
                Score = ComputeDocumentProfileContentCardQueryScore(query, queryTokens, card),
                Coverage = ComputeLexicalCoverage(queryTokens, BuildDocumentProfileContentCardQueryLookupText(card)),
                TitleCoverage = ComputeLexicalCoverage(queryTokens, card.Title),
                ConcretePriority = ComputeConcreteComparativeContentCardPriority(card),
                IsFacetOnly = LooksLikeFacetOnlyComparativeContentCard(queryTokens, card)
            })
            .Where(item => item.Score > 0.0 || (preferConcreteContentItems && item.ConcretePriority > 0 && !item.IsFacetOnly))
            .ToArray();

        if (preferConcreteContentItems)
        {
            var targetCount = ResolveComparativeContentCardTargetCount(query, limit);
            var concreteCards = ranked
                .Where(static item => item.ConcretePriority > 0 && !item.IsFacetOnly)
                .OrderByDescending(static item => item.ConcretePriority)
                .ThenByDescending(static item => item.Score > 0.0)
                .ThenByDescending(static item => item.Score)
                .ThenByDescending(static item => item.TitleCoverage)
                .ThenByDescending(static item => item.Coverage)
                .ThenBy(static item => item.Card.PageStart ?? int.MaxValue)
                .ThenBy(static item => item.Card.Title, StringComparer.OrdinalIgnoreCase)
                .Take(targetCount)
                .Select(static item => item.Card)
                .ToArray();

            if (concreteCards.Length > 0)
            {
                var selectedIds = new HashSet<string>(concreteCards.Select(GetDocumentProfileContentCardSelectionKey), StringComparer.OrdinalIgnoreCase);
                var supportingCards = ranked
                    .Where(item => !selectedIds.Contains(GetDocumentProfileContentCardSelectionKey(item.Card)))
                    .Where(static item => item.Score > 0.0)
                    .OrderBy(static item => item.IsFacetOnly ? 1 : 0)
                    .ThenByDescending(static item => item.Score)
                    .ThenByDescending(static item => item.TitleCoverage)
                    .ThenByDescending(static item => item.Coverage)
                    .ThenBy(static item => item.Card.PageStart ?? int.MaxValue)
                    .ThenBy(static item => item.Card.Title, StringComparer.OrdinalIgnoreCase)
                    .Select(static item => item.Card);

                return concreteCards
                    .Concat(supportingCards)
                    .Take(limit)
                    .ToArray();
            }
        }

        return ranked
            .Where(static item => item.Score > 0.0)
            .OrderByDescending(static item => item.Score)
            .ThenByDescending(static item => item.TitleCoverage)
            .ThenByDescending(static item => item.Coverage)
            .ThenBy(static item => item.Card.PageStart ?? int.MaxValue)
            .ThenBy(static item => item.Card.Title, StringComparer.OrdinalIgnoreCase)
            .Take(limit)
            .Select(static item => item.Card)
            .ToArray();
    }

    private static string GetDocumentProfileContentCardSelectionKey(DocumentProfileContentCard card)
        => string.IsNullOrWhiteSpace(card.ContentCardId)
            ? $"{card.Title}|{card.PageStart}|{card.PageEnd}|{card.Kind}"
            : card.ContentCardId;

    private static bool ShouldPreferConcreteContentCardsForComparativeQuery(string query)
        => ShouldPreferComparativeDocumentDiversity(query)
           && ResolveComparativeContentCardTargetCount(query, limit: 4) >= 2;

    private static int ResolveComparativeContentCardTargetCount(string query, int limit)
    {
        if (limit <= 0)
            return 0;

        var normalized = " " + FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query)) + " ";
        var requested = 0;
        if (ContainsAny(normalized, " deux ", " two ", " dos ", " duas ", " due ", " zwei "))
            requested = 2;
        else if (ContainsAny(normalized, " trois ", " three ", " tres ", " tre ", " drei "))
            requested = 3;
        else if (ContainsAny(normalized, " quatre ", " four ", " cuatro ", " quattro ", " vier "))
            requested = 4;
        else if (ContainsAny(normalized, " cinq ", " five ", " cinco ", " cinque ", " funf ", " fuenf "))
            requested = 5;

        if (requested <= 0)
            requested = Math.Min(3, limit);

        return Math.Clamp(requested, 1, Math.Min(limit, 6));
    }

    private static int ComputeConcreteComparativeContentCardPriority(DocumentProfileContentCard card)
    {
        if (string.IsNullOrWhiteSpace(card.Title))
            return 0;

        var titleTokens = ExtractLexicalQueryTokens(card.Title);
        if (titleTokens.Count == 0)
            return 0;

        var priority = 0;
        if (card.PageStart is > 0)
            priority += 3;
        if (CardKindUsuallyNamesConcreteContentItem(card.Kind))
            priority += 2;
        if (HasStrongDocumentProfileContentCardEvidence(card))
            priority += 4;
        else
            priority -= 3;
        if (titleTokens.Count is >= 2 and <= 8)
            priority += 2;
        else if (titleTokens.Count == 1 && IsReferenceLikeLookupTerm(titleTokens[0]))
            priority += 1;

        if (LooksLikeProceduralFragmentContentCardTitle(card.Title))
            priority -= 5;
        if (LooksLikeGenericContentSectionCardTitle(card.Title))
            priority -= 6;
        if (LooksLikeTruncatedContentCardTitle(card.Title))
            priority -= 4;
        if (LooksLikeQuantityOrOcrFragmentContentCardTitle(card.Title))
            priority -= 7;

        priority -= ComputeWeakDocumentProfileContentCardEvidencePenalty(card.Evidence);

        return Math.Max(0, priority);
    }

    private static bool CardKindUsuallyNamesConcreteContentItem(string? kind)
        => string.Equals(kind, "llm_content_card", StringComparison.OrdinalIgnoreCase)
           || string.Equals(kind, "content_item", StringComparison.OrdinalIgnoreCase)
           || string.Equals(kind, "unit_lead", StringComparison.OrdinalIgnoreCase)
           || string.Equals(kind, "exact_lead", StringComparison.OrdinalIgnoreCase)
           || string.Equals(kind, "page_embedded_title", StringComparison.OrdinalIgnoreCase)
           || string.Equals(kind, "standard_ref", StringComparison.OrdinalIgnoreCase);

    private static bool HasStrongDocumentProfileContentCardEvidence(DocumentProfileContentCard card)
        => card.Evidence is { QuantityFacts.Count: > 0 }
           || card.Evidence?.Facts is { Count: > 0 }
           || (card.Signals ?? [])
               .Any(static signal =>
                   string.Equals(signal, "structured_facts", StringComparison.OrdinalIgnoreCase)
                   || string.Equals(signal, "quantity_list", StringComparison.OrdinalIgnoreCase)
                   || string.Equals(signal, "scale_basis", StringComparison.OrdinalIgnoreCase)
                   || string.Equals(signal, "scalable_quantities", StringComparison.OrdinalIgnoreCase));

    private static bool LooksLikeFacetOnlyComparativeContentCard(
        IReadOnlyList<string> queryTokens,
        DocumentProfileContentCard card)
    {
        var titleTokens = ExtractLexicalQueryTokens(card.Title);
        if (titleTokens.Count == 0)
            return true;

        var nonFacetTitleTokens = titleTokens
            .Where(static token => !IsComparativeContentCardFacetToken(token))
            .ToArray();
        if (nonFacetTitleTokens.Length == 0)
            return true;

        if (HasStrongDocumentProfileContentCardEvidence(card))
            return false;

        var titleFacetHits = titleTokens.Count(IsComparativeContentCardFacetToken);
        if (titleFacetHits > 0 && titleTokens.Count <= 5)
        {
            var titleCoverage = ComputeLexicalCoverage(queryTokens, card.Title);
            return titleCoverage > 0.0;
        }

        return false;
    }

    private static bool IsComparativeContentCardFacetToken(string token)
    {
        var normalized = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(token));
        return normalized is
            "time" or "temps" or "duration" or "duree" or "minute" or "minutes" or "horaire" or "schedule"
            or "material" or "materials" or "materiel" or "materiaux" or "equipment" or "equipement" or "equipements" or "tool" or "tools" or "outil" or "outils" or "item" or "items" or "part" or "parts" or "supply" or "supplies"
            or "risk" or "risks" or "risque" or "risques" or "failure" or "failures" or "ratage" or "ratages" or "danger" or "dangers" or "erreur" or "erreurs"
            or "difficulty" or "difficulties" or "difficulte" or "difficultes" or "degree" or "degre" or "level" or "niveau"
            or "component" or "components" or "composant" or "composants"
            or "procedure" or "procedures" or "method" or "methods" or "methode" or "methodes" or "step" or "steps" or "etape" or "etapes"
            or "overview" or "summary" or "resume" or "presentation" or "introduction" or "guide" or "guides" or "pictogramme" or "pictogrammes" or "pictogram" or "pictograms"
            or "quantity" or "quantities" or "quantite" or "quantites" or "possibilite" or "possibilites" or "evolution";
    }

    private static bool LooksLikeProceduralFragmentContentCardTitle(string title)
    {
        var normalized = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(title));
        if (string.IsNullOrWhiteSpace(normalized))
            return true;

        var tokens = normalized.Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        if (tokens.Length == 0)
            return true;

        var first = tokens[0];
        if (tokens.Length >= 4
            && ContainsAny(
                $" {normalized} ",
                " avant de ",
                " before ",
                " afin de ",
                " afin d ",
                " apres avoir ",
                " after ",
                " dans le ",
                " dans la ",
                " avec le ",
                " avec la ",
                " without ",
                " sans qu ",
                " pendant ",
                " jusqu ",
                " until "))
        {
            return true;
        }

        if (tokens.Length >= 5 && first is
                "add" or "ajouter" or "ajoutez" or "apply" or "appliquer" or "assemble" or "assembler"
                or "bake" or "battre" or "boil" or "check" or "controlez" or "couper" or "coupez"
                or "cuire" or "faire" or "laisser" or "laver" or "melanger" or "mix" or "mixer"
                or "ouvrir" or "peler" or "place" or "placer" or "prepare" or "preparer"
                or "remove" or "retirer" or "validate" or "valider" or "verser")
        {
            return true;
        }

        return false;
    }

    private static bool LooksLikeGenericContentSectionCardTitle(string title)
    {
        var normalized = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(title));
        if (string.IsNullOrWhiteSpace(normalized))
            return true;

        var tokens = normalized.Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        if (tokens.Length is 0 or > 4)
        {
            return normalized.StartsWith("quantite ", StringComparison.Ordinal)
                   || normalized.StartsWith("quantites ", StringComparison.Ordinal)
                   || normalized.StartsWith("quantity ", StringComparison.Ordinal)
                   || normalized.StartsWith("quantities ", StringComparison.Ordinal);
        }

        return tokens.All(static token => StructuredContentLexicon.IsItemizedCueToken(token)
            || token is "quantity" or "quantities" or "quantite" or "quantites"
            or "item" or "items" or "element" or "elements"
            or "requirement" or "requirements" or "supply" or "supplies"
            or "material" or "materials" or "materiel" or "equipment" or "equipement"
            or "technique" or "techniques" or "method" or "methods" or "methode" or "methodes"
            or "preparation" or "preparacion" or "preparo" or "zubereitung"
            or "procedure" or "procedures" or "step" or "steps" or "etape" or "etapes"
            or "realisation" or "realization" or "instructions" or "instruction"
            or "overview" or "summary" or "resume" or "presentation" or "introduction");
    }

    private static bool LooksLikeTruncatedContentCardTitle(string title)
    {
        var normalized = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(title));
        if (string.IsNullOrWhiteSpace(normalized))
            return true;

        var tokens = normalized.Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        if (tokens.Length == 0)
            return true;

        var last = tokens[^1];
        return last is
            "a" or "au" or "aux" or "avec" or "de" or "du" or "des" or "d" or "l" or "la" or "le" or "les"
            or "and" or "or" or "of" or "to" or "with" or "for" or "from" or "the"
            or "y" or "e" or "con" or "para" or "por" or "do" or "da" or "dos" or "das"
            or "und" or "oder" or "mit" or "zu" or "zur" or "zum";
    }

    private static bool LooksLikeQuantityOrOcrFragmentContentCardTitle(string title)
    {
        if (string.IsNullOrWhiteSpace(title))
            return true;

        var trimmed = title.Trim();
        var first = trimmed[0];
        if (!char.IsLetter(first))
            return true;

        var normalized = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(trimmed));
        if (string.IsNullOrWhiteSpace(normalized))
            return true;

        if (Regex.IsMatch(normalized, @"^\d+\b", RegexOptions.CultureInvariant))
            return true;

        var tokens = normalized.Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        if (tokens.Length == 0)
            return true;

        return tokens[0] is
            "quantite" or "quantites" or "quantity" or "quantities"
            or "nombre" or "number" or "nombres"
            or "page" or "pages";
    }

    private static int ComputeWeakDocumentProfileContentCardEvidencePenalty(DocumentProfileCardEvidence? evidence)
    {
        if (evidence is null)
            return 0;

        var facts = evidence.QuantityFacts ?? [];
        if (facts.Count == 0)
            return 0;

        var weakFacts = facts.Count(IsWeakDocumentProfileQuantityFact);
        if (weakFacts == 0)
            return 0;

        var penalty = 0;
        if (weakFacts == facts.Count)
            penalty += 7;
        else if (weakFacts * 2 >= facts.Count)
            penalty += 4;
        else
            penalty += 1;

        return penalty;
    }

    private static bool IsWeakDocumentProfileQuantityFact(DocumentProfileQuantityFact fact)
    {
        if (fact.Value >= 1000)
            return true;

        var text = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(
            $"{fact.Label} {fact.Unit} {fact.SourceText}"));
        if (string.IsNullOrWhiteSpace(text))
            return true;

        if (text.Length >= 90 && fact.Value >= 100)
            return true;

        return ContainsAny(
            $" {text} ",
            " page ",
            " pages ",
            " fiche ",
            " fiches ",
            " livret ",
            " copyright ",
            " imprime ",
            " edition ",
            " tel ",
            " www ",
            " http ",
            " ven ");
    }

    private static bool ContentCardOverlapsMatchPageRange(DocumentProfileContentCard card, int? pageStart, int? pageEnd)
    {
        if (pageStart is null or <= 0)
            return true;

        var matchStart = pageStart.Value;
        var matchEnd = pageEnd is > 0 ? Math.Max(pageEnd.Value, matchStart) : matchStart;

        if (card.PageStart is null or <= 0)
            return false;

        var cardStart = card.PageStart.Value;
        var cardEnd = card.PageEnd is > 0 ? Math.Max(card.PageEnd.Value, cardStart) : cardStart;
        return cardStart <= matchEnd && cardEnd >= matchStart;
    }

    private static double ComputeDocumentProfileContentCardQueryScore(
        string query,
        IReadOnlyList<string> queryTokens,
        DocumentProfileContentCard card)
    {
        if (queryTokens.Count == 0 || string.IsNullOrWhiteSpace(card.Title))
            return 0.0;

        var title = card.Title.Trim();
        var signals = string.Join(' ', card.Signals ?? Array.Empty<string>());
        var evidenceText = BuildDocumentProfileContentCardEvidenceLookupText(card.Evidence);
        var candidateText = BuildDocumentProfileContentCardQueryLookupText(card);
        var coverage = ComputeLexicalCoverage(queryTokens, candidateText);
        var titleCoverage = ComputeLexicalCoverage(queryTokens, title);
        var signalCoverage = ComputeLexicalCoverage(queryTokens, signals);
        var nonEvidenceSignalCoverage = ComputeLexicalCoverage(
            queryTokens,
            string.Join(' ', (card.Signals ?? Array.Empty<string>()).Where(static signal => !IsStructuredEvidenceDerivedContentCardSignal(signal))));
        var evidenceCoverage = ComputeLexicalCoverage(queryTokens, evidenceText);
        if (coverage <= 0.0 && titleCoverage <= 0.0 && signalCoverage <= 0.0 && evidenceCoverage <= 0.0)
            return 0.0;
        if (titleCoverage <= 0.0
            && nonEvidenceSignalCoverage <= 0.0
            && (signalCoverage > 0.0 || evidenceCoverage > 0.0)
            && !HasStrongEvidenceOnlyContentCardSupport(queryTokens, card.Evidence))
        {
            return 0.0;
        }

        var score = (coverage * 100.0) + (titleCoverage * 70.0) + (signalCoverage * 18.0) + (evidenceCoverage * 42.0);
        var normalizedQuery = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query));
        var normalizedTitle = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(title));
        if (normalizedTitle.Length >= 4 && normalizedQuery.Length >= 4)
        {
            if (normalizedQuery.Contains(normalizedTitle, StringComparison.Ordinal))
                score += 90.0 + Math.Min(35.0, normalizedTitle.Length / 2.0);
            else if (normalizedTitle.Contains(normalizedQuery, StringComparison.Ordinal) && normalizedQuery.Length >= 8)
                score += 45.0;
        }

        var phraseTerms = BuildLexicalContentFallbackTerms(query)
            .Where(static term => term.Contains(' '))
            .Take(24)
            .ToArray();
        if (phraseTerms.Any(term => ContainsOrderedPhraseWindow(title, term, maxGapChars: 30)))
            score += 35.0;
        else if (phraseTerms.Any(term => ContainsOrderedPhraseWindow(candidateText, term, maxGapChars: 45)))
            score += 18.0;
        else if (!string.IsNullOrWhiteSpace(evidenceText)
                 && phraseTerms.Any(term => ContainsOrderedPhraseWindow(evidenceText, term, maxGapChars: 45)))
        {
            score += 24.0;
        }

        var titleAnchorCount = CountSpecificLexicalAnchors(queryTokens, title);
        if (titleAnchorCount > 0)
            score += Math.Min(36.0, titleAnchorCount * 9.0);

        if (titleCoverage <= 0.0 && signalCoverage > 0.0)
            score *= 0.80;
        if (titleCoverage <= 0.0 && signalCoverage <= 0.0 && evidenceCoverage > 0.0)
            score *= 0.95;

        return score;
    }

    private static bool HasStrongEvidenceOnlyContentCardSupport(
        IReadOnlyList<string> queryTokens,
        DocumentProfileCardEvidence? evidence)
    {
        if (evidence is null || queryTokens.Count == 0)
            return false;

        var parts = new List<string>();
        AddMultiTokenEvidenceLabel(parts, evidence.ScaleBasis?.Label);

        foreach (var fact in evidence.QuantityFacts ?? [])
        {
            AddMultiTokenEvidenceLabel(parts, fact.Label);
            if (!string.IsNullOrWhiteSpace(fact.SourceText))
                parts.Add(fact.SourceText);
        }

        foreach (var reason in evidence.NonScalableReasons ?? [])
            AddMultiTokenEvidenceLabel(parts, reason);

        foreach (var fact in evidence.Facts ?? [])
        {
            AddMultiTokenEvidenceLabel(parts, fact.Label);
            if (!string.IsNullOrWhiteSpace(fact.SourceText))
                parts.Add(fact.SourceText);
        }

        var strongEvidenceText = CollapseWhitespace(string.Join(' ', parts));
        if (string.IsNullOrWhiteSpace(strongEvidenceText))
            return false;

        var coverage = ComputeLexicalCoverage(queryTokens, strongEvidenceText);
        return queryTokens.Count <= 2
            ? coverage >= 1.0
            : coverage >= 0.50;
    }

    private static void AddMultiTokenEvidenceLabel(List<string> parts, string? label)
    {
        if (string.IsNullOrWhiteSpace(label))
            return;

        if (ExtractLexicalQueryTokens(label).Count >= 2)
            parts.Add(label);
    }

    private static bool IsStructuredEvidenceDerivedContentCardSignal(string signal)
    {
        if (string.IsNullOrWhiteSpace(signal))
            return false;

        return signal.StartsWith("scale_basis", StringComparison.OrdinalIgnoreCase)
            || signal.StartsWith("scale_basis_count:", StringComparison.OrdinalIgnoreCase)
            || signal.StartsWith("scale_basis_label:", StringComparison.OrdinalIgnoreCase)
            || string.Equals(signal, "quantity_list", StringComparison.OrdinalIgnoreCase)
            || string.Equals(signal, "structured_facts", StringComparison.OrdinalIgnoreCase)
            || string.Equals(signal, "non_scalable_quantities", StringComparison.OrdinalIgnoreCase)
            || string.Equals(signal, "scalable_quantities", StringComparison.OrdinalIgnoreCase);
    }

    private static string BuildDocumentProfileContentCardQueryLookupText(DocumentProfileContentCard card)
        => CollapseWhitespace(string.Join(' ', new[]
        {
            card.Title,
            string.Join(' ', card.Signals ?? Array.Empty<string>()),
            BuildDocumentProfileContentCardEvidenceLookupText(card.Evidence)
        }));

    private static string BuildDocumentProfileContentCardEvidenceLookupText(DocumentProfileCardEvidence? evidence)
    {
        if (evidence is null)
            return string.Empty;

        var parts = new List<string>();
        if (!string.IsNullOrWhiteSpace(evidence.SchemaVersion))
            parts.Add(evidence.SchemaVersion);
        if (evidence.ScaleBasis is not null)
        {
            if (!string.IsNullOrWhiteSpace(evidence.ScaleBasis.Label))
                parts.Add(evidence.ScaleBasis.Label!);
            if (evidence.ScaleBasis.Count > 0)
                parts.Add(evidence.ScaleBasis.Count.ToString(CultureInfo.InvariantCulture));
        }

        foreach (var fact in evidence.QuantityFacts ?? [])
        {
            if (!string.IsNullOrWhiteSpace(fact.Label))
                parts.Add(fact.Label);
            if (!string.IsNullOrWhiteSpace(fact.Unit))
                parts.Add(fact.Unit);
            if (!string.IsNullOrWhiteSpace(fact.SourceText))
                parts.Add(fact.SourceText);
            if (fact.Value > 0)
                parts.Add(fact.Value.ToString("0.###", CultureInfo.InvariantCulture));
        }

        foreach (var reason in evidence.NonScalableReasons ?? [])
        {
            if (!string.IsNullOrWhiteSpace(reason))
                parts.Add(reason);
        }

        if (!string.IsNullOrWhiteSpace(evidence.Language))
            parts.Add($"language:{evidence.Language}");
        if ((evidence.Facts ?? []).Count > 0)
            parts.Add("structured_facts");
        foreach (var fact in evidence.Facts ?? [])
        {
            if (!string.IsNullOrWhiteSpace(fact.Kind))
                parts.Add(fact.Kind);
            if (!string.IsNullOrWhiteSpace(fact.Label))
                parts.Add(fact.Label);
            if (!string.IsNullOrWhiteSpace(fact.Value))
                parts.Add(fact.Value);
            if (!string.IsNullOrWhiteSpace(fact.Unit))
                parts.Add(fact.Unit);
            if (!string.IsNullOrWhiteSpace(fact.SourceText))
                parts.Add(fact.SourceText);
        }

        return CollapseWhitespace(string.Join(' ', parts));
    }

    private static string CollapseWhitespace(string? value)
        => string.IsNullOrWhiteSpace(value)
            ? string.Empty
            : Regex.Replace(value.Trim(), @"\s+", " ", RegexOptions.CultureInvariant);

    private static (int? PageStart, int? PageEnd) ResolveDocumentProfileMatchPageRange(string? metadataJson, string query)
    {
        if (ExtractLexicalQueryTokens(query).Count == 0)
            return (null, null);

        var contentCards = SelectDocumentProfileContentCards(metadataJson, query);
        if (contentCards.Count == 0)
            return (null, null);

        var selected = contentCards
            .Where(static card => card.PageStart is > 0)
            .FirstOrDefault();

        return selected is null
            ? (null, null)
            : (selected.PageStart, selected.PageEnd ?? selected.PageStart);
    }

    private static string BuildContentCuesLabel(string? language)
        => DocumentLanguageResolver.PrimarySubtag(language) switch
        {
            "en" => "Content cues",
            "fr" => "Repères de contenu",
            "es" => "Pistas de contenido",
            "pt" => "Pistas de conteúdo",
            "de" => "Inhaltshinweise",
            "it" => "Indizi di contenuto",
            _ => "Content cues"
        };

    private static string BuildDocumentProfileSectionTitle(string? language)
        => DocumentLanguageResolver.PrimarySubtag(language) switch
        {
            "fr" => "Profil documentaire",
            "es" => "Perfil documental",
            "pt" => "Perfil documental",
            "de" => "Dokumentprofil",
            "it" => "Profilo documentale",
            _ => "Profile summary"
        };

    private static string FormatDocumentProfileContentCard(DocumentProfileContentCard card)
    {
        var title = card.Title.Trim();
        if (string.IsNullOrWhiteSpace(title))
            return string.Empty;

        return card.PageStart is > 0
            ? $"{title} (p.{card.PageStart})"
            : title;
    }

    private static IReadOnlyList<RagItemContentCardDto>? BuildMatchedContentCardDtos(RagMatch match)
    {
        var cards = match.MatchedContentCards;
        if (cards is null || cards.Count == 0)
            return null;

        return cards
            .Where(static card => !string.IsNullOrWhiteSpace(card.Title))
            .Select(static card => new RagItemContentCardDto(
                Title: card.Title.Trim(),
                ContentCardId: card.ContentCardId,
                PageStart: card.PageStart,
                PageEnd: card.PageEnd,
                Kind: card.Kind,
                Signals: card.Signals,
                Evidence: card.Evidence))
            .ToArray();
    }

    private static RagItemProfileSignalsDto? BuildProfileSignalsDto(RagProfileSignals? signals)
    {
        if (signals is null)
            return null;

        return new RagItemProfileSignalsDto(
            ProfileVersion: NormalizeOptionalDtoText(signals.ProfileVersion),
            Language: NormalizeOptionalDtoText(signals.Language),
            Keywords: NormalizeDtoList(signals.Keywords),
            Entities: NormalizeDtoList(signals.Entities),
            Topics: NormalizeDtoList(signals.Topics),
            HypotheticalQuestions: NormalizeDtoList(signals.HypotheticalQuestions),
            Limits: NormalizeDtoList(signals.Limits),
            MatchedTerms: NormalizeDtoList(signals.MatchedTerms),
            MatchCount: signals.MatchCount);
    }

    private static string? NormalizeOptionalDtoText(string? value)
    {
        if (string.IsNullOrWhiteSpace(value))
            return null;

        var trimmed = value.Trim();
        return string.Equals(trimmed, "und", StringComparison.OrdinalIgnoreCase)
            ? null
            : trimmed;
    }

    private static IReadOnlyList<string>? NormalizeDtoList(IEnumerable<string>? values, int maxItems = 12)
    {
        if (values is null)
            return null;

        var normalized = values
            .Where(static value => !string.IsNullOrWhiteSpace(value))
            .Select(static value => value.Trim())
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(Math.Clamp(maxItems, 1, 24))
            .ToArray();

        return normalized.Length == 0 ? null : normalized;
    }

    internal static RagItemSelectionHintsDto BuildSelectionHints(
        RagMatch match,
        RagItemExtractionQualityDto? quality = null)
    {
        var retriever = ResolveRetriever(match);
        var actionabilityScore = 0;
        var supportScore = 0;
        var fragmentScore = 0;
        var navigationScore = 0;
        var qualityPenalty = ComputeSelectionQualityPenalty(quality);

        if (LooksLikeStructuredAnswerUnit(match))
            actionabilityScore += 12;
        else if (LooksLikeStructuredAnswerChunk(match))
            actionabilityScore += 8;

        if (match.MatchedContentCards is { Count: > 0 })
        {
            actionabilityScore += match.MatchedContentCards.Any(static card =>
                string.Equals(card.Kind, "unit_lead", StringComparison.OrdinalIgnoreCase)
                || string.Equals(card.Kind, "exact_lead", StringComparison.OrdinalIgnoreCase))
                ? 5
                : 3;
            supportScore += 2;
        }

        if (string.Equals(retriever, "exact_match", StringComparison.Ordinal))
            actionabilityScore += 5;
        if (string.Equals(retriever, "sparse_bm25", StringComparison.Ordinal))
            actionabilityScore += 2;
        if (string.Equals(retriever, "standard_reference_document_name", StringComparison.Ordinal))
            actionabilityScore += 3;
        if (string.Equals(retriever, "document_profile", StringComparison.Ordinal))
            supportScore += 6;
        if (string.Equals(retriever, "linked_context", StringComparison.Ordinal))
            fragmentScore += 6;
        if (string.Equals(retriever, "dense_qdrant", StringComparison.Ordinal))
            supportScore += 2;

        if (LooksLikeNavigationalChunk(match))
            navigationScore += ComputeNavigationHintScore(match);
        if (LooksLikeGlossaryChunk(match))
            navigationScore += 6;
        if (LooksLikeSourceListChunk(match))
            navigationScore += 8;
        if (LooksLikeDocumentOverviewChunk(match))
            supportScore += 4;

        var textLength = (match.Text ?? string.Empty).Trim().Length;
        if (textLength is > 0 and < 140 && !LooksLikeStructuredAnswerChunk(match))
            fragmentScore += 3;

        ApplySelectionQualityPenalty(
            qualityPenalty,
            ref actionabilityScore,
            ref supportScore,
            ref fragmentScore);

        var evidenceRole =
            qualityPenalty >= 10 ? "low_confidence" :
            navigationScore >= Math.Max(7, actionabilityScore + 2) ? "navigation" :
            fragmentScore >= Math.Max(8, actionabilityScore + 3) ? "fragment" :
            actionabilityScore >= Math.Max(8, supportScore + 1) ? "actionable_item" :
            supportScore >= 5 ? "supporting_context" :
            "advisory";

        return new RagItemSelectionHintsDto(
            EvidenceRole: evidenceRole,
            ActionabilityScore: actionabilityScore,
            SupportScore: supportScore,
            FragmentScore: fragmentScore,
            NavigationScore: navigationScore,
            QualityPenalty: qualityPenalty);
    }

    private static void ApplySelectionQualityPenalty(
        int qualityPenalty,
        ref int actionabilityScore,
        ref int supportScore,
        ref int fragmentScore)
    {
        if (qualityPenalty <= 0)
            return;

        actionabilityScore = Math.Max(0, actionabilityScore - qualityPenalty);
        supportScore = Math.Max(0, supportScore - Math.Max(1, qualityPenalty / 2));
        if (qualityPenalty >= 10)
            fragmentScore += Math.Min(8, qualityPenalty / 2);
    }

    private static int ComputeSelectionQualityPenalty(RagItemExtractionQualityDto? quality)
    {
        if (quality is null)
            return 0;

        var penalty = 0;
        if (quality.DocumentManualReviewRecommended == true)
            penalty += 4;
        if (quality.PageManualReviewRecommended == true)
            penalty += 6;
        if (quality.OcrRecommended == true && quality.OcrApplied != true)
            penalty += 5;

        var confidence = quality.PageExtractionConfidence ?? quality.DocumentExtractionConfidence;
        if (confidence is <= 0.35)
            penalty += 8;
        else if (confidence is <= 0.50)
            penalty += 5;
        else if (confidence is <= 0.70)
            penalty += 2;

        var status = string.Join(' ', quality.PageQualityStatus, quality.DocumentQualityStatus, quality.TextStatus)
            .ToLowerInvariant();
        if (status.Contains("ocr_failed", StringComparison.Ordinal)
            || status.Contains("low_confidence", StringComparison.Ordinal))
        {
            penalty += 6;
        }
        if (status.Contains("manual_review", StringComparison.Ordinal)
            || status.Contains("low_text", StringComparison.Ordinal)
            || status.Contains("empty_text", StringComparison.Ordinal))
        {
            penalty += 4;
        }

        return Math.Clamp(penalty, 0, 24);
    }

    private static int ComputeNavigationHintScore(RagMatch match)
    {
        if (match.NavigationScore is double score)
        {
            if (score >= 0.90)
                return 12;
            if (score >= 0.80)
                return 10;
            if (score >= 0.72)
                return 8;
            if (score >= 0.55)
                return 4;
        }

        if (string.Equals(match.ContentRole, RetrievalContentClassifier.NavigationRole, StringComparison.OrdinalIgnoreCase))
            return 10;
        if (string.Equals(match.ContentRole, RetrievalContentClassifier.MixedNavigationContentRole, StringComparison.OrdinalIgnoreCase))
            return 4;

        return 10;
    }

    internal static bool ShouldSupplementSparseWithLexicalFallback(string? category, string query)
        => ShouldSupplementSparseWithLexicalFallback(!string.IsNullOrWhiteSpace(category), query);

    internal static bool ShouldSupplementSparseWithLexicalFallback(bool scoped, string query)
    {
        var tokens = ExtractLexicalQueryTokens(query);
        if (tokens.Count == 0)
            return false;

        if (ContainsQuantityComputationIntent(query)
            && ExtractQuotedLookupPhrases(query).Count == 0)
        {
            return false;
        }

        if (ContainsBroadOnlySparseQueryIntent(query))
        {
            var normalized = " " + FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query)).ToLowerInvariant() + " ";
            return scoped
                && ShouldPreferComparativeDocumentDiversity(query)
                && ContainsAny(
                    normalized,
                    " compare ",
                    " comparer ",
                    " comparez ",
                    " comparaison ",
                    " comparative ",
                    " comparatif ",
                    " comparison ",
                    " comparar ",
                    " compara ",
                    " confronta ",
                    " choisir entre ",
                    " choisis entre ",
                    " choisissez entre ",
                    " choose between ",
                    " select between ",
                    " vergleiche ",
                    " vergleichen ")
                && ContainsAny(
                    normalized,
                    " choisir ",
                    " choix ",
                    " choose ",
                    " select ",
                    " selection ",
                    " recommande ",
                    " recommend ",
                    " prefer ",
                    " favor ",
                    " favour ");
        }

        var hasStrongToken = tokens.Any(static token =>
            token.Length >= 7
            || token.Any(char.IsDigit)
            || IsReferenceLikeLookupTerm(token));

        if (scoped)
            return hasStrongToken || tokens.Count <= 4;

        return hasStrongToken && tokens.Count <= 4;
    }

    internal static bool ContainsBroadOnlySparseQueryIntent(string query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return false;

        var normalized = " " + FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query)).ToLowerInvariant() + " ";
        var hasBroadIntent = ContainsBroadScopedSynthesisIntent(normalized)
            || ContainsSituationalBroadSelectionIntent(normalized)
            || ShouldPreferDocumentDiversity(query)
            || ContainsDocumentOverviewIntent(query);
        if (ExtractQuotedLookupPhrases(query).Count > 0)
        {
            return false;
        }

        if (ExtractFocusedLookupPhrases(query).Count > 0
            && !ContainsExplicitBroadScopedSynthesisIntent(normalized)
            && !ContainsSituationalBroadSelectionIntent(normalized)
            && !ShouldPreferComparativeDocumentDiversity(query))
        {
            return false;
        }

        return hasBroadIntent;
    }

    internal static bool ContainsQuantityComputationIntent(string query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return false;

        var normalized = " " + FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query)).ToLowerInvariant() + " ";
        return ContainsAny(normalized,
            " combien ",
            " quantite ",
            " quantites ",
            " how many ",
            " quantity ",
            " quantities ",
            " calculate ",
            " calcula ",
            " calcular ",
            " calcular ",
            " quante ",
            " quanti ",
            " wie viele ",
            " menge ",
            " mengen ");
    }

    internal static bool ShouldSkipDocumentProfileSearchForQuantityLookup(string query)
    {
        if (!ContainsQuantityComputationIntent(query))
            return false;

        var normalized = " " + FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query)).ToLowerInvariant() + " ";
        return !HasReferenceLikeQueryToken(query)
            && !ContainsDocumentOverviewIntent(query)
            && !ContainsDocumentCorpusCountIntent(normalized)
            && !ContainsBroadScopedSynthesisIntent(normalized)
            && !ContainsSituationalBroadSelectionIntent(normalized);
    }

