    private static bool ShouldPrioritizeOperationalSettings(string normalized)
    {
        if (!ContainsOperationalSettingLookupIntent(normalized))
            return false;

        if (!ContainsFastDurationPreferenceNormalized(normalized))
            return true;

        return ContainsAny(
            normalized,
            " robot ",
            " machine ",
            " appareil ",
            " appliance ",
            " device ",
            " parametre ",
