    }

    private static bool ContainsFastDurationPreference(string query)
        => ContainsFastDurationPreferenceNormalized($" {NormalizeForLexicalSignal(query)} ");

    private static bool ContainsFastDurationPreferenceNormalized(string normalized)
        => ContainsAny(
            normalized,
            " rapide ",
            " rapidement ",
            " vite ",
            " express ",
            " quick ",
            " quickly ",
            " fast ",
            " speedy ",
            " rapido ");

    private static bool HasFocusedTitlePhraseEvidenceForPreference(string query, RagMatch match)
    {
        var phraseCandidates = ExtractFocusedLookupPhrases(query)
            .Concat(ExtractTitleLookupPhrases(query))
            .Append(BuildFocusedLexicalBackfillQuery(query))
            .Select(NormalizeForLexicalSignal)
            .SelectMany(static phrase => new[] { phrase, StripFastPreferenceFacetFromTitlePhrase(phrase) })
            .Where(static phrase => phrase.Length >= 5)
            .Distinct(StringComparer.Ordinal)
            .ToArray();
        if (phraseCandidates.Length == 0)
            return false;

        var signalText = NormalizeForLexicalSignal(string.Join(' ', new[]
        {
            GetTitleSignalText(match),
            match.Text
        }.Where(static value => !string.IsNullOrWhiteSpace(value))));
        if (signalText.Length == 0)
            return false;

        return phraseCandidates.Any(phrase =>
            ContainsOrderedPhraseWindowInNormalizedText(signalText, phrase, maxGapChars: 16));
    }

    private static string StripFastPreferenceFacetFromTitlePhrase(string normalizedPhrase)
    {
        var withoutMode = SafeRegexReplace(
            normalizedPhrase,
            @"\b(?:en\s+)?mode\s+(?:rapide|express|quick|fast|rapido)\b.*$",
            string.Empty,
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant,
            TimeSpan.FromMilliseconds(100));
        return SafeRegexReplace(
                withoutMode,
                @"\b(?:rapide|rapidement|vite|express|quick|quickly|fast|speedy|rapido)\b.*$",
                string.Empty,
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant,
                TimeSpan.FromMilliseconds(100))
            .Trim();
    }

    private static int ComputeFastDurationPreferencePriority(RagMatch match)
    {
        var minutes = ExtractBestDurationMinutes(GetDirectChunkSignalText(match));
        if (minutes is null)
            return 0;

        return minutes.Value switch
        {
            <= 10 => 5,
            <= 20 => 4,
            <= 35 => 3,
            <= 60 => 2,
            <= 90 => 1,
            _ => 0
        };
    }

    private static int? ExtractBestDurationMinutes(string? text)
    {
        var normalized = NormalizeForLexicalSignal(text);
        if (normalized.Length == 0)
            return null;

        var totalDurations = ExtractDurationMinutes(
            normalized,
            @"\b(?:temps\s+total|total\s+time|duree\s+totale)\s*:?\s*(?:(?<h>\d{1,2})\s*h(?:eures?)?\s*)?(?<m>\d{1,3})?\s*(?:min|minute|minutes)?\b");
        if (totalDurations.Count > 0)
            return totalDurations.Min();

        var durations = ExtractDurationMinutes(
            normalized,
            @"\b(?:(?<h>\d{1,2})\s*h(?:eures?)?(?:\s*(?<m>\d{1,3})\s*(?:min|minute|minutes))?|(?<m>\d{1,3})\s*(?:min|minute|minutes))\b");
        return durations.Count == 0 ? null : durations.Min();
    }

    private static List<int> ExtractDurationMinutes(string normalized, string pattern)
    {
        var values = new List<int>();
        foreach (var match in SafeRegexMatches(
            normalized,
            pattern,
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant,
            TimeSpan.FromMilliseconds(100)))
        {
            var hours = 0;
            var minutes = 0;
            if (match.Groups["h"].Success
                && int.TryParse(match.Groups["h"].Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsedHours))
            {
                hours = parsedHours;
            }
            if (match.Groups["m"].Success
                && int.TryParse(match.Groups["m"].Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out var parsedMinutes))
            {
                minutes = parsedMinutes;
            }

            var total = (hours * 60) + minutes;
            if (total > 0)
                values.Add(total);
        }

        return values;
    }

    private static int ComputeOperationalSettingCandidateSignal(string normalizedQuery, RagMatch match)
    {
        var normalizedText = $" {FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(string.Join(' ', new[]
        {
            match.Text,
            match.EmbedText,
            match.SectionTitle,
            match.HeadingPath,
            match.DocName,
            match.DocPath
        }.Where(static value => !string.IsNullOrWhiteSpace(value))))).ToLowerInvariant()} ";

        if (string.IsNullOrWhiteSpace(normalizedText))
            return 0;

        var signal = 0;
        if (ContainsAny(normalizedQuery, " robot ", " machine ", " appareil ", " appliance ", " device ")
            && ContainsAny(normalizedText, " robot ", " machine ", " appareil ", " appliance ", " device "))
        {
            signal += 5;
        }

        if (ContainsAny(normalizedText, " vitesse ", " vitesses ", " speed ", " speeds "))
            signal += 4;
        if (ContainsAny(normalizedText, " temperature ", " temperatures ", " degre ", " degres ")
            || ContainsCelsiusLikeSetting(normalizedText))
        {
            signal += 3;
        }
        if (ContainsAny(normalizedText, " programme ", " programmes ", " program ", " programs ", " mode ", " modes "))
            signal += 3;
        if (ContainsAny(normalizedText, " accessoire ", " accessoires ", " accessory ", " accessories ", " attachment ", " attachments "))
            signal += 2;
        if (ContainsAny(normalizedText, " temps total ", " total time ", " duree totale "))
            signal += 2;

        return signal + Math.Min(GetStructuredAnswerPriority(match), 2);
    }

    private static bool ContainsCelsiusLikeSetting(string normalizedText)
    {
        if (string.IsNullOrWhiteSpace(normalizedText))
            return false;

        for (var i = 0; i < normalizedText.Length; i++)
        {
            if (!char.IsDigit(normalizedText[i]))
                continue;

            var start = i;
            var value = 0;
            var digitCount = 0;
            while (i < normalizedText.Length && char.IsDigit(normalizedText[i]) && digitCount < 4)
            {
                value = (value * 10) + (normalizedText[i] - '0');
                digitCount++;
                i++;
            }

            if (digitCount is < 2 or > 3 || value < 10 || value > 999)
                continue;

            while (i < normalizedText.Length && normalizedText[i] == ' ')
                i++;

            if (i >= normalizedText.Length || normalizedText[i] != 'c')
                continue;

            var before = start == 0 ? ' ' : normalizedText[start - 1];
            var after = i + 1 >= normalizedText.Length ? ' ' : normalizedText[i + 1];
            if (!char.IsLetterOrDigit(before) && !char.IsLetterOrDigit(after))
                return true;
        }

        return false;
    }

    internal static void PrioritizeExactTitleSelections(string query, List<RagMatch> selected)
    {
        if (selected.Count <= 1)
            return;

        var lexicalTokens = ExtractLexicalQueryTokens(query)
            .Where(static token => !PrimaryAnchorStopwords.Contains(token))
            .Distinct(StringComparer.Ordinal)
            .Take(8)
            .ToArray();
        var useSpecificCoverageTitlePriority = ShouldApplySpecificCoverageTitlePriority(
            query,
            lexicalTokens,
            ExtractComparativeSubjectAnchorTokens(query));
        var ranked = selected
            .Select(match =>
            {
                var exactTitleScore = ComputeExactTitleCandidateScore(query, match);
                var weakDirectTitleTokenRoute = IsDirectTitleTokenRouteMatch(match)
                    && !DirectTitleTokenRouteHasStrongLeadEvidence(match);
                return new
                {
                    Match = match,
                    ExactTitleScore = exactTitleScore,
                    DirectChunkTitleSignal = weakDirectTitleTokenRoute
                        ? 0
                        : ComputeDirectChunkTitleSignal(query, match),
                    MatchedCardTitleSignal = ComputeMatchedContentCardTitleSignal(
                        match,
                        lexicalTokens,
                        NormalizeForLexicalSignal(query)),
                    TrustedExactTitleSignal = exactTitleScore > 0.0 && !IsWeakResolvedRouteTarget(match),
                    SpecificAnchorCount = lexicalTokens.Length > 0
                        ? CountSpecificLexicalAnchors(lexicalTokens, GetTitleSignalText(match))
                        : 0,
                    StructuredAnswerPriority = GetStructuredAnswerPriority(match),
                    ContentEvidencePriority = ComputeContentEvidencePriority(match)
                };
            })
            .ToList();

        var hasExactTitleSignal = ranked.Any(static item => item.ExactTitleScore > 0.0 || item.MatchedCardTitleSignal > 0);
        var hasFullSpecificCoverage = useSpecificCoverageTitlePriority
            && ranked.Any(static item => item.SpecificAnchorCount >= 2);
        if (!hasExactTitleSignal && !hasFullSpecificCoverage)
            return;

        selected.Clear();
        selected.AddRange(ranked
            .OrderByDescending(static item => item.DirectChunkTitleSignal)
            .ThenByDescending(static item => item.TrustedExactTitleSignal ? 1 : 0)
            .ThenByDescending(static item => item.MatchedCardTitleSignal)
            .ThenByDescending(static item => item.ExactTitleScore > 0.0 ? 1 : 0)
            .ThenByDescending(item => useSpecificCoverageTitlePriority && item.SpecificAnchorCount >= 2 ? 1 : 0)
            .ThenByDescending(item => useSpecificCoverageTitlePriority ? item.StructuredAnswerPriority : 0)
            .ThenByDescending(item => useSpecificCoverageTitlePriority ? item.SpecificAnchorCount : 0)
            .ThenByDescending(static item => item.ExactTitleScore)
            .ThenByDescending(static item => item.ContentEvidencePriority)
            .ThenByDescending(static item => item.Match.Score)
            .ThenBy(static item => item.Match.DocPath, StringComparer.OrdinalIgnoreCase)
            .ThenBy(static item => item.Match.ChunkIndex)
            .Select(static item => item.Match));
    }

    internal static void PruneWeakTitleExpansionSelections(string query, List<RagMatch> selected)
    {
        if (selected.Count <= 1)
            return;

        var lexicalTokens = ExtractTitlePruneTokens(query);
        if (lexicalTokens.Length < 2)
            return;

        var useTitlePriority = ExtractQuotedLookupPhrases(query).Count > 0
            && !ShouldTreatQuotedLookupAsTopic(query)
            || ShouldApplySpecificCoverageTitlePriority(
                query,
                lexicalTokens,
                ExtractComparativeSubjectAnchorTokens(query));
        if (!useTitlePriority)
            return;

        var ranked = selected
            .Select(match => new TitleSelectionSignal(
                match,
                ComputeExactTitleCandidateScore(query, match),
                CountSpecificLexicalAnchors(lexicalTokens, GetTitleSignalText(match)),
                HasFullTitleAnchorCoverage(lexicalTokens, match),
                GetStructuredAnswerPriority(match)))
            .ToList();

        var requiredAnchorCount = Math.Min(2, lexicalTokens.Length);
        var strongAnchors = ranked
            .Where(item => item.SpecificAnchorCount >= requiredAnchorCount
                && item.FullTitleCoverage
                && item.StructuredAnswerPriority >= 2)
            .ToArray();
        if (strongAnchors.Length == 0)
        {
            var first = ranked.FirstOrDefault();
            if (first is null
                || first.StructuredAnswerPriority < 2
                || first.SpecificAnchorCount <= 0
                || first.Match.Score < 0.90)
            {
                return;
            }

            strongAnchors = [first];
        }

        var pruned = ranked
            .Where(item => !ShouldPruneWeakTitleExpansion(item, strongAnchors, lexicalTokens))
            .Select(static item => item.Match)
            .ToList();

        if (pruned.Count == selected.Count || pruned.Count == 0)
            return;

        selected.Clear();
        selected.AddRange(pruned);
    }

    private static bool ShouldPruneWeakTitleExpansion(
        TitleSelectionSignal item,
        IReadOnlyList<TitleSelectionSignal> strongAnchors,
        IReadOnlyList<string> lexicalTokens)
    {
        if (item.FullTitleCoverage)
        {
            if (string.Equals(ResolveRetriever(item.Match), "linked_context", StringComparison.Ordinal))
            {
                return !strongAnchors.Any(anchor =>
                    IsUsefulLinkedContextCompanion(lexicalTokens, anchor.Match, item.Match));
            }

            return false;
        }

        var retriever = ResolveRetriever(item.Match);
        if (string.Equals(retriever, "linked_context", StringComparison.Ordinal))
        {
            return !strongAnchors.Any(anchor =>
                IsUsefulLinkedContextCompanion(lexicalTokens, anchor.Match, item.Match));
        }

        foreach (var anchor in strongAnchors)
        {
            if (!string.Equals(anchor.Match.DocPath, item.Match.DocPath, StringComparison.OrdinalIgnoreCase))
                continue;
            if (SharesSpecificSection(anchor.Match, item.Match))
                return false;
            if (IsNearbyPage(anchor.Match, item.Match, maxDistance: 2))
                return true;
        }

        return false;
    }

    private static bool HasFullTitleAnchorCoverage(IReadOnlyList<string> lexicalTokens, RagMatch match)
    {
        if (lexicalTokens.Count < 2)
            return false;

        var titleSignalText = GetTitleSignalText(match);
        if (string.IsNullOrWhiteSpace(titleSignalText))
            return false;

        return ContainsOrderedTitleTokenSubstrings(titleSignalText, lexicalTokens, maxGapChars: 100)
            || ContainsTitleLikeLexicalSequence(
                FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(titleSignalText)),
                lexicalTokens);
    }

    private static bool IsNearbyPage(RagMatch anchor, RagMatch candidate, int maxDistance)
    {
        if (!anchor.PageStart.HasValue || !candidate.PageStart.HasValue)
            return false;

        return Math.Abs(anchor.PageStart.Value - candidate.PageStart.Value) <= maxDistance;
    }

    private static bool IsUsefulLinkedContextCompanion(
        IReadOnlyList<string> lexicalTokens,
        RagMatch anchor,
        RagMatch candidate)
    {
        if (!string.Equals(ResolveRetriever(candidate), "linked_context", StringComparison.Ordinal))
            return false;
        if (!string.Equals(anchor.DocPath, candidate.DocPath, StringComparison.OrdinalIgnoreCase))
            return false;
        if (!IsNearbyPage(anchor, candidate, maxDistance: 2))
            return false;
        if (LooksLikeNavigationalChunk(candidate) || LooksLikeGlossaryChunk(candidate))
            return false;
        if (IsNearDuplicatePageOverlap(anchor, candidate))
            return false;

        if (SharesSpecificSection(anchor, candidate))
            return true;
        if (lexicalTokens.Count == 0)
            return false;

        var directSignalText = GetDirectChunkSignalText(candidate);
        if (string.IsNullOrWhiteSpace(directSignalText))
            return false;

        if (ComputeLexicalCoverage(lexicalTokens, directSignalText) >= 0.50)
            return true;

        var specificAnchors = CountSpecificLexicalAnchors(lexicalTokens, directSignalText);
        if (specificAnchors >= Math.Min(2, lexicalTokens.Count))
            return true;

        var titleTokens = lexicalTokens
            .Where(static token => !SpecificAnchorStopwords.Contains(token))
            .Take(6)
            .ToArray();
        return titleTokens.Length >= 2
            && ContainsOrderedTitleTokenSubstrings(directSignalText, titleTokens, maxGapChars: 80);
    }

    private static bool SharesSpecificSection(RagMatch left, RagMatch right)
    {
        if (!string.IsNullOrWhiteSpace(left.SectionTitle)
            && !string.IsNullOrWhiteSpace(right.SectionTitle)
            && !IsGenericSectionTitle(left.SectionTitle)
            && string.Equals(left.SectionTitle.Trim(), right.SectionTitle.Trim(), StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }

        if (!string.IsNullOrWhiteSpace(left.HeadingPath)
            && !string.IsNullOrWhiteSpace(right.HeadingPath)
            && !IsGenericSectionTitle(left.HeadingPath)
            && string.Equals(left.HeadingPath.Trim(), right.HeadingPath.Trim(), StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }

        return false;
    }

    private static bool IsGenericSectionTitle(string? value)
    {
        var normalized = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(value ?? string.Empty));
        return string.IsNullOrWhiteSpace(normalized)
            || normalized is "document" or "documents" or "root" or "page" or "pages" or "untitled" or "sans titre";
    }

    internal static void PruneWeakAdjacentSiblingSelections(string query, List<RagMatch> selected)
    {
        if (selected.Count <= 1)
            return;

        var lexicalTokens = ExtractTitlePruneTokens(query);
        if (lexicalTokens.Length < 2)
            return;

        var anchor = selected.FirstOrDefault(match =>
            match.Score >= 0.90
            && !string.Equals(ResolveRetriever(match), "linked_context", StringComparison.Ordinal)
            && LooksLikeStructuredAnswerChunk(match)
            && CountSpecificLexicalAnchors(lexicalTokens, GetTitleSignalText(match)) > 0);
        if (anchor is null)
            return;

        selected.RemoveAll(match =>
        {
            if (string.Equals(match.ChunkId, anchor.ChunkId, StringComparison.Ordinal)
                && string.Equals(match.DocPath, anchor.DocPath, StringComparison.OrdinalIgnoreCase))
            {
                return false;
            }

            if (!string.Equals(match.DocPath, anchor.DocPath, StringComparison.OrdinalIgnoreCase))
                return false;
            if (SharesSpecificSection(anchor, match))
                return false;
            if (!IsNearbyPage(anchor, match, maxDistance: 2))
                return false;
            if (string.Equals(ResolveRetriever(match), "linked_context", StringComparison.Ordinal)
                && IsUsefulLinkedContextCompanion(lexicalTokens, anchor, match))
            {
                return false;
            }

            var coverage = ComputeLexicalCoverage(lexicalTokens, GetTitleSignalText(match));
            return coverage < 0.80;
        });
    }

    internal static void PrunePreciseTitleTailSelections(string query, List<RagMatch> selected)
    {
        if (selected.Count <= 1 || !ShouldConstrainPreciseTitleLookup(query))
            return;

        var lexicalTokens = ExtractTitlePruneTokens(query);
        var requiredAnchorCount = Math.Min(2, lexicalTokens.Length);
        var ranked = selected
            .Select(match => new
            {
                Match = match,
                StrictCoverage = HasStrictTitleAnchorCoverage(lexicalTokens, match),
                TitleAnchorCount = CountTitleAnchorTokens(lexicalTokens, GetPreciseTitleSignalText(match)),
                ExactTitleScore = ComputeExactTitleCandidateScore(query, match),
                DirectChunkTitleSignal = ComputeDirectChunkTitleSignal(query, match),
                StructuredAnswerPriority = GetStructuredAnswerPriority(match)
            })
            .ToList();
        var anchor = ranked
            .Where(item => item.Match.Score >= 0.90
                && item.TitleAnchorCount >= requiredAnchorCount
                && (item.StrictCoverage
                    || item.ExactTitleScore > 0.0
                    || item.StructuredAnswerPriority >= 2
                    || HasProfileTitleHint(item.Match)))
            .OrderByDescending(static item => item.StrictCoverage)
            .ThenByDescending(static item => item.DirectChunkTitleSignal)
            .ThenByDescending(static item => item.ExactTitleScore)
            .ThenByDescending(static item => item.StructuredAnswerPriority)
            .ThenByDescending(static item => item.Match.Score)
            .Select(static item => item.Match)
            .FirstOrDefault();
        if (anchor is null)
            return;

        var anchorIsContentChunk = GetStructuredAnswerPriority(anchor) >= 2;
        selected.RemoveAll(match =>
        {
            if (IsSameChunk(match, anchor))
                return false;

            if (string.Equals(ResolveRetriever(match), "linked_context", StringComparison.Ordinal)
                && IsUsefulLinkedContextCompanion(lexicalTokens, anchor, match))
            {
                return false;
            }

            return !HasStrictTitleAnchorCoverage(lexicalTokens, match)
                || (anchorIsContentChunk && string.Equals(match.ChunkType, "document_profile", StringComparison.Ordinal));
        });
    }

    internal static void PrunePreciseTitleLocalNeighborhoodSelections(string query, List<RagMatch> selected)
    {
        if (selected.Count <= 1 || ShouldPreferComparativeDocumentDiversity(query) || ContainsDocumentOverviewIntent(query))
            return;

        var titlePhrases = ExtractTitleLookupPhrases(query);
        if (titlePhrases.Count == 0)
            return;

        var lexicalTokens = ExtractTitlePruneTokens(query);
        if (lexicalTokens.Length < 2)
            return;

        var anchors = selected
            .Select((match, index) => new
            {
                Match = match,
                Index = index,
                DirectChunkTitleSignal = ComputeDirectChunkTitleSignal(query, match),
                ExactTitleScore = ComputeExactTitleCandidateScore(query, match),
                HasPlacementEvidence = HasQuotedTitlePlacementEvidence(titlePhrases, match),
                StrictCoverage = HasStrictTitleAnchorCoverage(lexicalTokens, match),
                ContentEvidencePriority = ComputeContentEvidencePriority(match)
            })
            .Where(item => IsStrongPreciseTitleLocalNeighborhoodAnchor(
                item.Match,
                item.HasPlacementEvidence,
                item.StrictCoverage,
                item.DirectChunkTitleSignal,
                item.ExactTitleScore,
                item.ContentEvidencePriority))
            .OrderBy(static item => item.Index)
            .Select(static item => item.Match)
            .ToArray();
        if (anchors.Length == 0)
            return;

        selected.RemoveAll(match =>
        {
            var anchor = anchors.FirstOrDefault(candidate =>
                !IsSameChunk(candidate, match)
                && SharesSameDocumentPage(candidate, match));
            if (anchor is null)
                return false;

            return !IsUsefulPreciseTitleLocalNeighborhoodCompanion(query, anchor, match);
        });
    }

    internal static void PruneQualifiedQuotedTitleCompetitorDocuments(string query, List<RagMatch> selected)
    {
        if (selected.Count <= 1 || ShouldPreferComparativeDocumentDiversity(query) || ContainsDocumentOverviewIntent(query))
            return;

        var quotedPhrases = ExtractTitleLookupPhrases(query);
        if (quotedPhrases.Count == 0)
            return;

        var normalizedQuery = $" {FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query)).ToLowerInvariant()} ";
        if (!ShouldKeepQuotedTitleSearchOpenForStructuredDetails(query, normalizedQuery)
            && !ShouldConstrainPreciseTitleLookup(query))
        {
            return;
        }

        var documentSignals = selected
            .Select(match => new
            {
                Match = match,
                DocumentKey = BuildSameDocumentPromotionKey(match),
                DirectTextSpecificityPriority = ComputePreciseQuotedLeadTitleSpecificityPriority(quotedPhrases, match.Text),
                HasStructuredEvidence = IsContentSelectionCandidate(match)
                    && !LooksLikeNavigationalChunk(match)
                    && !LooksLikeGlossaryChunk(match)
                    && (ContainsStructuredInventoryLikeCue(match)
                        || ContainsStructuredProcedureCue(match)
                        || ContainsStructuredTimeCue(match)
                        || ComputeContentEvidencePriority(match) >= 0.65)
            })
            .Where(static item => !string.IsNullOrWhiteSpace(item.DocumentKey))
            .GroupBy(static item => item.DocumentKey!, StringComparer.OrdinalIgnoreCase)
            .Select(static group => new
            {
                DocumentKey = group.Key,
                BestDirectTextSpecificityPriority = group.Max(static item => item.DirectTextSpecificityPriority),
                HasStructuredEvidence = group.Any(static item => item.HasStructuredEvidence)
            })
            .ToArray();
        if (documentSignals.Length <= 1)
            return;

        var protectedDocumentKeys = documentSignals
            .Where(static item => item.BestDirectTextSpecificityPriority >= 3 && item.HasStructuredEvidence)
            .Select(static item => item.DocumentKey)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        if (protectedDocumentKeys.Count == 0)
            return;

        var qualifiedCompetitorDocumentKeys = documentSignals
            .Where(item => item.BestDirectTextSpecificityPriority == 1
                && !protectedDocumentKeys.Contains(item.DocumentKey))
            .Select(static item => item.DocumentKey)
            .ToHashSet(StringComparer.OrdinalIgnoreCase);
        if (qualifiedCompetitorDocumentKeys.Count == 0)
            return;

        selected.RemoveAll(match =>
        {
            var documentKey = BuildSameDocumentPromotionKey(match);
            return !string.IsNullOrWhiteSpace(documentKey)
                && qualifiedCompetitorDocumentKeys.Contains(documentKey);
        });
    }

    private static bool IsStrongPreciseTitleLocalNeighborhoodAnchor(
        RagMatch match,
        bool hasPlacementEvidence,
        bool strictCoverage,
        int directChunkTitleSignal,
        double exactTitleScore,
        double contentEvidencePriority)
    {
        if (!string.Equals(ResolveRetriever(match), "local_title_token_route", StringComparison.Ordinal))
            return false;
        if (match.Score < 0.86)
            return false;
        if (!hasPlacementEvidence && !strictCoverage)
            return false;

        return directChunkTitleSignal > 0
            || exactTitleScore > 0.0
            || GetStructuredAnswerPriority(match) >= 2
            || contentEvidencePriority >= 0.65;
    }

    private static bool SharesSameDocumentPage(RagMatch left, RagMatch right)
    {
        if (string.IsNullOrWhiteSpace(left.DocPath) || string.IsNullOrWhiteSpace(right.DocPath))
            return false;
        if (!string.Equals(left.DocPath, right.DocPath, StringComparison.OrdinalIgnoreCase))
            return false;

        return PageRangesOverlap(left.PageStart, left.PageEnd, right.PageStart, right.PageEnd);
    }

    private static bool IsUsefulPreciseTitleLocalNeighborhoodCompanion(string query, RagMatch anchor, RagMatch candidate)
    {
        if (!IsContentSelectionCandidate(candidate))
            return false;
        if (LooksLikeNavigationalChunk(candidate) || LooksLikeGlossaryChunk(candidate))
            return false;
        if (IsNearDuplicatePageOverlap(anchor, candidate))
            return false;

        var normalizedQuery = $" {NormalizeForLexicalSignal(query)} ";
        var asksInventory = ContainsStructuredInventoryRequest(normalizedQuery);
        var asksProcedure = ContainsStructuredProcedureRequest(normalizedQuery);
        var asksTime = ContainsStructuredTimeRequest(normalizedQuery);

        var anchorHasInventory = ContainsStructuredInventoryLikeCue(anchor);
        var anchorHasProcedure = ContainsStructuredProcedureCue(anchor);
        var anchorHasTime = ContainsStructuredTimeCue(anchor);
        var candidateHasInventory = ContainsStructuredInventoryLikeCue(candidate);
        var candidateHasProcedure = ContainsStructuredProcedureCue(candidate);
        var candidateHasTime = ContainsStructuredTimeCue(candidate);

        return (asksInventory && !anchorHasInventory && candidateHasInventory)
            || (asksProcedure && !anchorHasProcedure && candidateHasProcedure)
            || (asksTime && !anchorHasTime && candidateHasTime);
    }

    private static bool ContainsStructuredInventoryLikeCue(RagMatch match)
        => ContainsStructuredInventoryCue(match)
           || LooksLikeStructuredQuantityList(match.Text)
           || ContainsMeasuredQuantityListCue(match);

    private static bool ContainsMeasuredQuantityListCue(RagMatch match)
    {
        var normalized = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(GetDirectChunkSignalText(match)))
            .ToLowerInvariant();
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        var count = Regex.Matches(
            normalized,
            @"\b\d{1,4}(?:[\.,]\d{1,2})?\s*(?:g|gr|kg|mg|ml|cl|l|oz|lb|c\s*a\s*c|c\s*a\s*s|units?|items?|pieces?)\b",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant).Count;
        return count >= 2;
    }

    internal static void PruneUnmatchedPreciseTitleSelections(string query, List<RagMatch> selected)
    {
        if (selected.Count == 0 || !ShouldConstrainPreciseTitleLookup(query))
            return;
        if (ShouldUseCatalogDocumentOverviewFallback(query))
            return;

        var primaryTokens = ExtractTitlePruneTokens(query)
            .Where(IsPrimarySpecificLexicalAnchorToken)
            .Distinct(StringComparer.Ordinal)
            .Take(4)
            .ToArray();
        if (primaryTokens.Length == 0)
            return;

        var requiredPrimaryAnchorCount = Math.Min(2, primaryTokens.Length);
        var primaryAnchors = selected
            .Where(match => CountPrimarySpecificSelectionAnchors(primaryTokens, match) >= requiredPrimaryAnchorCount)
            .ToArray();
        if (primaryAnchors.Length == 0)
        {
            selected.Clear();
            return;
        }

        selected.RemoveAll(match =>
        {
            if (CountPrimarySpecificSelectionAnchors(primaryTokens, match) >= requiredPrimaryAnchorCount)
                return false;

            return !IsUsefulLinkedSelectionNearPrimaryAnchor(primaryTokens, match, primaryAnchors);
        });
    }

    internal static void PruneUnanchoredFocusedLookupSelections(string query, List<RagMatch> selected)
    {
        if (selected.Count == 0)
            return;
        if (ContainsDocumentOverviewIntent(query))
            return;
        if (ShouldUseCatalogDocumentOverviewFallback(query))
            return;
        if (ShouldPreferComparativeDocumentDiversity(query)
            && ShouldAllowDocumentProfileAssistForComparativeLookup(query))
        {
            return;
        }
        var normalized = " " + FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query)).ToLowerInvariant() + " ";
        if (ContainsEvidenceQualityScopedSynthesisIntent(normalized))
            return;
        if (ContainsExplicitBroadScopedSynthesisIntent(normalized)
            || ContainsBroadScopedSynthesisIntent(normalized)
            || ContainsSituationalBroadSelectionIntent(normalized)
            || (ShouldPreferComparativeDocumentDiversity(query)
                && ShouldTreatAsBroadDiversityQuery(query, normalized)))
        {
            return;
        }

        var standardReferencePhrases = ExtractStandardReferenceTitleLookupPhrases(query);
        if (standardReferencePhrases.Count > 0)
        {
            var standardAnchored = selected
                .Where(match => ContainsStandardReferenceSelectionAnchor(standardReferencePhrases, match))
                .ToArray();
            if (standardAnchored.Length > 0)
            {
                selected.RemoveAll(match =>
                    !ContainsStandardReferenceSelectionAnchor(standardReferencePhrases, match)
                    && !IsUsefulLinkedStandardReferenceCompanion(match, standardAnchored));
                return;
            }
        }

        var anchorTokens = ExtractFocusedLookupSelectionAnchorTokens(query);
        if (anchorTokens.Count == 0)
            return;

        var anchored = selected
            .Where(match => ContainsFocusedLookupSelectionAnchor(anchorTokens, match))
            .ToArray();
        if (anchored.Length == 0)
        {
            selected.Clear();
            return;
        }

        selected.RemoveAll(match =>
            !ContainsFocusedLookupSelectionAnchor(anchorTokens, match)
            && !IsUsefulLinkedFocusedLookupCompanion(anchorTokens, match, anchored));
    }

    private static bool ContainsStandardReferenceSelectionAnchor(
        IReadOnlyList<string> standardReferencePhrases,
        RagMatch match)
    {
        if (standardReferencePhrases.Count == 0)
            return true;
        if (IsDocumentProfileMatch(match)
            && !string.Equals(ResolveRetriever(match), "standard_reference_document_name", StringComparison.Ordinal))
            return false;

        var signalText = GetLexicalSignalText(match);
        if (string.IsNullOrWhiteSpace(signalText))
            return false;

        foreach (var phrase in standardReferencePhrases.Take(12))
        {
            var normalizedPhrase = NormalizeForLexicalSignal(phrase);
            if (!string.IsNullOrWhiteSpace(normalizedPhrase)
                && (StandardReferencePhraseMatchesText(normalizedPhrase, match.DocName)
                    || StandardReferencePhraseMatchesText(normalizedPhrase, match.DocPath)
                    || StandardReferencePhraseMatchesText(normalizedPhrase, match.EmbedText)))
            {
                return true;
            }

            var phraseTokens = ExtractTitlePruneTokens(phrase);
            if (phraseTokens.Length < 2)
                continue;

            if (ComputeLexicalCoverage(phraseTokens, signalText) >= 0.80)
                return true;

            var normalizedSignal = NormalizeForLexicalSignal(signalText);
            if (normalizedPhrase.Length >= 4
                && ContainsOrderedPhraseWindowInNormalizedText(normalizedSignal, normalizedPhrase, maxGapChars: 24))
            {
                return true;
            }
        }

        return false;
    }

    private static bool IsUsefulLinkedStandardReferenceCompanion(RagMatch match, IReadOnlyList<RagMatch> anchored)
    {
        if (!string.Equals(ResolveRetriever(match), "linked_context", StringComparison.Ordinal))
            return false;
        if (LooksLikeNavigationalChunk(match) || LooksLikeGlossaryChunk(match))
            return false;

        return anchored.Any(anchor =>
            string.Equals(anchor.DocPath, match.DocPath, StringComparison.OrdinalIgnoreCase)
            && IsNearbyPage(anchor, match, maxDistance: 3));
    }

    internal static IReadOnlyList<string> ExtractFocusedLookupSelectionAnchorTokens(string query)
    {
        var focusedPhrases = ExtractFocusedLookupPhrases(query);
        if (focusedPhrases.Count == 0)
            return Array.Empty<string>();

        return focusedPhrases
            .SelectMany(ExtractTitlePruneTokens)
            .Where(IsFocusedLookupSelectionAnchorToken)
            .Distinct(StringComparer.Ordinal)
            .OrderByDescending(static token => token.Length)
            .ThenBy(static token => token, StringComparer.Ordinal)
            .Take(4)
            .ToArray();
    }

    internal static IReadOnlyList<string> ExtractFocusedLookupPrimaryHeadTokens(string query)
    {
        var phraseCandidates = ExtractFocusedLookupPhrases(query)
            .Append(BuildFocusedLexicalBackfillQuery(query))
            .Where(static phrase => !string.IsNullOrWhiteSpace(phrase))
            .Distinct(StringComparer.OrdinalIgnoreCase);
        var tokens = new List<string>();
        foreach (var phrase in phraseCandidates)
        {
            var titleTokens = ExtractTitlePruneTokens(phrase)
                .Where(static token => !TitleConnectorTokens.Contains(token))
                .Where(static token => !FocusedLookupRequestLeadTokens.Contains(token))
                .Where(static token => !LexicalStopwords.Contains(token))
                .Where(static token => !SpecificAnchorStopwords.Contains(token))
                .Where(static token => !PrimaryAnchorStopwords.Contains(token))
                .Where(static token => !FocusedLookupSecondaryQualifierTokens.Contains(token))
                .ToArray();
            if (titleTokens.Length < 2)
                continue;

            var head = titleTokens[0];
            if (head.Length < 5 && !head.Any(char.IsDigit))
                continue;
            if (!tokens.Contains(head, StringComparer.Ordinal))
                tokens.Add(head);
            if (tokens.Count >= 3)
                break;
        }

        return tokens;
    }

    private static int ComputeFocusedHeadAnchorSignal(IReadOnlyList<string> headTokens, RagMatch match)
    {
        if (headTokens.Count == 0)
            return 0;

        var normalized = NormalizeForLexicalSignal(string.Join(' ', new[]
        {
            GetDirectChunkSignalText(match),
            ExtractMatchedRouteOrProfileTitle(match.EmbedText)
        }.Where(static value => !string.IsNullOrWhiteSpace(value))));
        if (normalized.Length == 0)
            return 0;

        var signal = 0;
        foreach (var token in headTokens)
        {
            if (BuildLexicalTokenVariants(token)
                .DefaultIfEmpty(token)
                .Select(FoldDiacritics)
                .Distinct(StringComparer.Ordinal)
                .Any(variant => variant.Length >= 3 && ContainsExactNormalizedToken(normalized, variant)))
            {
                signal++;
            }
        }

        return signal;
    }

    private static bool IsFocusedLookupSelectionAnchorToken(string token)
        => token.Length >= 3
           && token.Any(char.IsLetterOrDigit)
           && !TitleConnectorTokens.Contains(token)
           && !LexicalStopwords.Contains(token)
           && !SpecificAnchorStopwords.Contains(token)
           && !PrimaryAnchorStopwords.Contains(token)
           && !FocusedLookupSecondaryQualifierTokens.Contains(token);

    private static bool ContainsFocusedLookupSelectionAnchor(IReadOnlyList<string> anchorTokens, RagMatch match)
    {
        if (anchorTokens.Count == 0)
            return true;

        var directSignalText = string.Join("\n", new[]
        {
            GetDirectChunkSignalText(match),
            ExtractMatchedRouteOrProfileTitle(match.EmbedText)
        }.Where(static value => !string.IsNullOrWhiteSpace(value)));
        if (string.IsNullOrWhiteSpace(directSignalText))
            return false;

        return ContainsFocusedLookupSelectionAnchorInNormalizedText(
            anchorTokens,
            NormalizeForLexicalSignal(directSignalText));
    }

    private static bool ContainsFocusedLookupSelectionAnchorInNormalizedText(
        IReadOnlyList<string> anchorTokens,
        string normalizedCandidate)
    {
        if (anchorTokens.Count == 0)
            return true;
        if (string.IsNullOrWhiteSpace(normalizedCandidate))
            return false;

        foreach (var token in anchorTokens)
        {
            if (token.Any(char.IsDigit)
                && ContainsExactNormalizedToken(normalizedCandidate, token))
            {
                return true;
            }

            foreach (var variant in BuildLexicalTokenVariants(token).DefaultIfEmpty(token))
            {
                var foldedVariant = FoldDiacritics(variant);
                if (foldedVariant.Length >= 3 && ContainsExactNormalizedToken(normalizedCandidate, foldedVariant))
                    return true;
                if (foldedVariant.Length >= 6 && normalizedCandidate.Contains(foldedVariant, StringComparison.Ordinal))
                    return true;
                if (foldedVariant.Length >= 6 && ContainsNearNormalizedToken(normalizedCandidate, foldedVariant))
                    return true;
            }
        }

        return false;
    }

    private static bool IsUsefulLinkedFocusedLookupCompanion(
        IReadOnlyList<string> anchorTokens,
        RagMatch match,
        IReadOnlyList<RagMatch> anchored)
    {
        if (!string.Equals(ResolveRetriever(match), "linked_context", StringComparison.Ordinal))
            return false;
        if (LooksLikeNavigationalChunk(match) || LooksLikeGlossaryChunk(match))
            return false;

        return anchored.Any(anchor =>
            string.Equals(anchor.DocPath, match.DocPath, StringComparison.OrdinalIgnoreCase)
            && IsNearbyPage(anchor, match, maxDistance: 2)
            && (SharesSpecificSection(anchor, match)
                || ContainsFocusedLookupSelectionAnchor(anchorTokens, match)));
    }

    internal static bool ShouldRunStructuredContinuationBackfill(string query, IReadOnlyList<RagMatch> selected)
        => selected.Count > 0
           && HasStructuredContinuationBackfillIntent(query)
           && SelectStructuredContinuationAnchors(query, selected, limit: 1).Count > 0;

    internal static IReadOnlyList<RagMatch> SelectStructuredContinuationAnchors(
        string query,
        IReadOnlyList<RagMatch> selected,
        int limit)
    {
        if (limit <= 0 || selected.Count == 0 || !HasStructuredContinuationBackfillIntent(query))
            return Array.Empty<RagMatch>();

        var titleScoringQuery = BuildFocusedLexicalBackfillQuery(query);
        var titleTokens = ExtractTitleScoringTokens(
            string.IsNullOrWhiteSpace(titleScoringQuery) ? query : titleScoringQuery);

        return selected
            .Where(match =>
                Guid.TryParse(match.ChunkId, out _)
                && IsStructuredContinuationAnchor(query, titleTokens, match))
            .OrderByDescending(match => LinkedContextLeadingContinuationNeedsPreviousCompanion(query, match) ? 1 : 0)
            .ThenByDescending(match => ComputeStructuredContinuationAnchorTitleSignal(query, titleTokens, match))
            .ThenByDescending(static match => GetStructuredAnswerPriority(match))
            .ThenByDescending(static match => ComputeContentEvidencePriority(match))
            .ThenByDescending(static match => match.Score)
            .ThenBy(static match => match.DocPath, StringComparer.OrdinalIgnoreCase)
            .ThenBy(static match => match.ChunkIndex)
            .Take(limit)
            .ToArray();
    }

    internal static IReadOnlyList<RagMatch> FilterStructuredContinuationMatches(
        string query,
        IReadOnlyList<RagMatch> anchors,
        IReadOnlyList<RagMatch> candidates,
        int limit)
    {
        if (limit <= 0 || anchors.Count == 0 || candidates.Count == 0 || !HasStructuredContinuationBackfillIntent(query))
            return Array.Empty<RagMatch>();

        var ranked = new List<(RagMatch Match, int AnchorIndex, int RelationPriority, int CuePriority)>();
        for (var anchorIndex = 0; anchorIndex < anchors.Count; anchorIndex++)
        {
            var anchor = anchors[anchorIndex];
            foreach (var candidate in candidates)
            {
                if (IsSameChunk(anchor, candidate))
                    continue;

                var relation = ResolveStructuredContinuationRelation(anchor, candidate);
                if (relation is null)
                    continue;
                if (!IsUsefulStructuredContinuationCandidate(query, anchor, candidate, relation))
                    continue;

                ranked.Add((
                    candidate,
                    anchorIndex,
                    StructuredContinuationRelationPriority(relation),
                    ComputeStructuredContinuationCuePriority(query, candidate)));
            }
        }

        return ranked
            .GroupBy(item => BuildMatchDedupKey(item.Match), StringComparer.OrdinalIgnoreCase)
            .Select(static group => group
                .OrderBy(static item => item.AnchorIndex)
                .ThenByDescending(static item => item.RelationPriority)
                .ThenByDescending(static item => item.CuePriority)
                .ThenByDescending(static item => item.Match.Score)
                .ThenBy(static item => item.Match.DocPath, StringComparer.OrdinalIgnoreCase)
                .ThenBy(static item => item.Match.ChunkIndex)
                .First())
            .OrderBy(static item => item.AnchorIndex)
            .ThenByDescending(static item => item.RelationPriority)
            .ThenByDescending(static item => item.CuePriority)
            .ThenByDescending(static item => item.Match.Score)
            .ThenBy(static item => item.Match.DocPath, StringComparer.OrdinalIgnoreCase)
            .ThenBy(static item => item.Match.ChunkIndex)
            .Select(static item => item.Match)
            .Take(limit)
            .ToArray();
    }

    internal static void MergeStructuredContinuationSelections(
        string query,
        List<RagMatch> selected,
        IReadOnlyList<RagMatch> continuations,
        int topK)
    {
        if (topK <= 0 || selected.Count == 0 || continuations.Count == 0)
            return;

        var anchors = SelectStructuredContinuationAnchors(query, selected, Math.Max(1, Math.Min(topK, selected.Count)));
        if (anchors.Count == 0)
            return;

        var continuationsByAnchorKey = new Dictionary<string, List<RagMatch>>(StringComparer.OrdinalIgnoreCase);
        foreach (var continuation in continuations)
        {
            var anchor = anchors.FirstOrDefault(candidate =>
            {
                var relation = ResolveStructuredContinuationRelation(candidate, continuation);
                return relation is not null
                    && IsUsefulStructuredContinuationCandidate(query, candidate, continuation, relation);
            });
            if (anchor is null)
                continue;

            var anchorKey = BuildMatchDedupKey(anchor);
            if (!continuationsByAnchorKey.TryGetValue(anchorKey, out var bucket))
            {
                bucket = [];
                continuationsByAnchorKey[anchorKey] = bucket;
            }

            bucket.Add(continuation);
        }

        if (continuationsByAnchorKey.Count == 0)
            return;

        var protectedKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var pair in continuationsByAnchorKey)
        {
            protectedKeys.Add(pair.Key);
            foreach (var continuation in pair.Value)
                protectedKeys.Add(BuildMatchDedupKey(continuation));
        }

        var merged = new List<RagMatch>(selected.Count + continuations.Count);
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        void AddIfNew(RagMatch match)
        {
            if (seen.Add(BuildMatchDedupKey(match)))
                merged.Add(match);
        }

        foreach (var match in selected)
        {
            AddIfNew(match);
            var matchKey = BuildMatchDedupKey(match);
            if (!continuationsByAnchorKey.TryGetValue(matchKey, out var companions))
                continue;

            foreach (var continuation in companions
                         .OrderByDescending(candidate =>
                             StructuredContinuationRelationPriority(
                                 ResolveStructuredContinuationRelation(match, candidate) ?? string.Empty))
                         .ThenByDescending(candidate => ComputeStructuredContinuationCuePriority(query, candidate))
                         .ThenByDescending(static candidate => candidate.Score)
                         .ThenBy(static candidate => candidate.ChunkIndex))
            {
                AddIfNew(continuation);
            }
        }

        foreach (var continuation in continuations)
            AddIfNew(continuation);

        while (merged.Count > topK)
        {
            var removeIndex = -1;
            for (var i = merged.Count - 1; i >= 0; i--)
            {
                if (!protectedKeys.Contains(BuildMatchDedupKey(merged[i])))
                {
                    removeIndex = i;
                    break;
                }
            }

            if (removeIndex < 0)
                removeIndex = merged.Count - 1;
            merged.RemoveAt(removeIndex);
        }

        selected.Clear();
        selected.AddRange(merged);
    }

    internal static void ReattachStructuredContinuationCompanions(
        string query,
        List<RagMatch> selected,
        int topK)
    {
        if (selected.Count <= 1 || !HasStructuredContinuationBackfillIntent(query))
            return;

        var continuations = selected
            .Where(static match => string.Equals(ResolveRetriever(match), "linked_context", StringComparison.Ordinal))
            .ToArray();
        if (continuations.Length == 0)
            return;

        MergeStructuredContinuationSelections(query, selected, continuations, topK);
    }

    private static bool HasStructuredContinuationBackfillIntent(string query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return false;

        var normalized = $" {NormalizeForLexicalSignal(query)} ";
        var asksInventory = ContainsStructuredInventoryRequest(normalized);
        var asksProcedure = ContainsStructuredProcedureRequest(normalized);
        var asksTime = ContainsStructuredTimeRequest(normalized);
        var asksSheet = ContainsStructuredSheetRequest(normalized);

        return (asksInventory && asksProcedure)
            || (asksSheet && (asksInventory || asksProcedure || asksTime))
            || (asksProcedure && asksTime)
            || HasPreciseStructuredDetailContinuationIntent(query, normalized);
    }

    internal static bool ShouldRelaxDefaultScoreFloorForFocusedStructuredLookup(string query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return false;

        var hasFocusedTarget = ExtractFocusedLookupPhrases(query).Count > 0
            || ExtractQuotedLookupPhrases(query).Count > 0;
        if (!hasFocusedTarget)
            return false;

        var normalized = $" {NormalizeForLexicalSignal(query)} ";
        return ContainsStructuredSheetRequest(normalized)
            || ContainsStructuredInventoryRequest(normalized)
            || ContainsStructuredProcedureRequest(normalized)
            || ContainsStructuredTimeRequest(normalized)
            || HasSourceAttributionTitleLookupShape(query, normalized);
    }

    private static bool HasPreciseStructuredDetailContinuationIntent(string query, string normalizedQuery)
    {
        var focusedTokens = ExtractTitleScoringTokens(BuildFocusedLexicalBackfillQuery(query));
        if (focusedTokens.Count is < 2 or > 8)
            return false;

        if (ContainsAny(
                normalizedQuery,
                " examples with ",
                " examples that ",
                " exemples avec ",
                " exemples qui ",
                " opciones con ",
                " opcoes com ",
                " esempi con "))
        {
            return false;
        }

        var hasFocusedTarget = ExtractFocusedLookupPhrases(query).Count > 0
            || ExtractQuotedLookupPhrases(query).Count > 0;
        if (!hasFocusedTarget)
            return false;

        return ContainsStructuredSheetRequest(normalizedQuery)
            || ContainsStructuredInventoryRequest(normalizedQuery)
            || ContainsStructuredProcedureRequest(normalizedQuery)
            || ContainsStructuredTimeRequest(normalizedQuery)
            || ContainsAny(
                normalizedQuery,
                " donne moi ",
                " donnez moi ",
                " donne ",
                " donnez ",
                " montre moi ",
                " montre ",
                " show me ",
                " give me ",
                " find me ",
                " get me ",
                " detaille ",
                " details ",
                " explique ",
                " explain ");
    }

    private static bool IsStructuredContinuationAnchor(
        string query,
        IReadOnlyList<string> titleTokens,
        RagMatch match)
    {
        if (string.IsNullOrWhiteSpace(match.DocPath) || string.IsNullOrWhiteSpace(match.ChunkId))
            return false;
        if (IsDocumentProfileMatch(match) || LooksLikeNavigationalChunk(match) || LooksLikeGlossaryChunk(match))
            return false;

        var titleSignal = ComputeStructuredContinuationAnchorTitleSignal(query, titleTokens, match);
        var linkedContinuationNeedsPrevious = LinkedContextLeadingContinuationNeedsPreviousCompanion(query, match);
        if (titleSignal <= 0 && !linkedContinuationNeedsPrevious)
            return false;

        if (!IsContentSelectionCandidate(match)
            && !(IsResolvedTitleOrNavigationRoute(match) && titleSignal > 0)
            && !linkedContinuationNeedsPrevious)
        {
            return false;
        }

        var structuredAnswerPriority = GetStructuredAnswerPriority(match);
        var contentEvidencePriority = ComputeContentEvidencePriority(match);
        var titleOnlyStructuredAnchorNeedsCompanion =
            (IsResolvedTitleOrNavigationRoute(match) || titleSignal >= 4)
            && structuredAnswerPriority < 2
            && !ContainsStructuredInventoryCue(match)
            && !ContainsStructuredProcedureCue(match)
            && (match.Text?.Length ?? 0) <= 700;

        if (structuredAnswerPriority < 2
            && contentEvidencePriority < 0.80
            && !titleOnlyStructuredAnchorNeedsCompanion
            && !linkedContinuationNeedsPrevious)
        {
            return false;
        }

        if (!StructuredContinuationAnchorNeedsCompanion(query, match)
            && !titleOnlyStructuredAnchorNeedsCompanion)
        {
            return false;
        }

        return true;
    }

    private static bool StructuredContinuationAnchorNeedsCompanion(string query, RagMatch match)
    {
        var normalizedQuery = $" {NormalizeForLexicalSignal(query)} ";
        var asksInventory = ContainsStructuredInventoryRequest(normalizedQuery);
        var asksProcedure = ContainsStructuredProcedureRequest(normalizedQuery);
        var asksTime = ContainsStructuredTimeRequest(normalizedQuery);
        var asksSheet = ContainsStructuredSheetRequest(normalizedQuery);

        var hasInventory = ContainsStructuredInventoryCue(match);
        var hasProcedure = ContainsStructuredProcedureCue(match);
        var hasTime = ContainsStructuredTimeCue(match);

        if (DirectTitleRouteBridgeNeedsPreviousCompanion(query, match))
            return true;
        if (TitleRouteLeadingContinuationNeedsPreviousCompanion(query, match))
            return true;
        if (LinkedContextLeadingContinuationNeedsPreviousCompanion(query, match))
            return true;

        return (asksProcedure && !hasProcedure && hasInventory)
            || (asksInventory && !hasInventory && hasProcedure)
            || (asksTime && !hasTime && (hasInventory || hasProcedure))
            || (asksSheet && (hasInventory || hasProcedure) && !(hasInventory && hasProcedure));
    }

    private static bool DirectTitleRouteBridgeNeedsPreviousCompanion(string query, RagMatch match)
    {
        if (!IsDirectTitleTokenRouteMatch(match))
            return false;
        if (string.IsNullOrWhiteSpace(match.PrevChunkId))
            return false;

        var routeTitle = ExtractMatchedRouteOrProfileTitle(match.EmbedText);
        var titleSource = string.Join(
            ' ',
            new[] { routeTitle }
                .Concat(ExtractFocusedLookupPhrases(query))
                .Concat(ExtractQuotedLookupPhrases(query))
                .Append(BuildFocusedLexicalBackfillQuery(query))
                .Where(static value => !string.IsNullOrWhiteSpace(value))
                .Distinct(StringComparer.OrdinalIgnoreCase));
        var titleTokens = NormalizeForLexicalSignal(titleSource)
            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Where(static token => token.Length >= 3 || token.Any(char.IsDigit))
            .Where(static token => !TitleConnectorTokens.Contains(token))
            .Where(static token => !PrimaryAnchorStopwords.Contains(token))
            .Distinct(StringComparer.Ordinal)
            .Take(8)
            .ToArray();
        if (titleTokens.Length < 3)
            return false;

        var directSignal = GetDirectChunkSignalText(match);
        var directTitleHits = CountTitleAnchorTokens(titleTokens, directSignal);
        if (directTitleHits >= titleTokens.Length || directTitleHits < Math.Min(2, titleTokens.Length))
            return false;

        return ContainsStructuredInventoryCue(match)
            || ContainsStructuredProcedureCue(match)
            || ContainsStructuredTimeCue(match);
    }

    private static bool TitleRouteLeadingContinuationNeedsPreviousCompanion(string query, RagMatch match)
    {
        if (!IsResolvedTitleOrNavigationRoute(match))
            return false;
        if (string.IsNullOrWhiteSpace(match.Text))
            return false;
        if (string.IsNullOrWhiteSpace(match.PrevChunkId) && !match.ChunkIndex.HasValue)
            return false;

        var routeTitle = ExtractMatchedRouteOrProfileTitle(match.EmbedText);
        if (string.IsNullOrWhiteSpace(routeTitle))
        {
            routeTitle = ExtractFocusedLookupPhrases(query)
                .Concat(ExtractQuotedLookupPhrases(query))
                .Append(BuildFocusedLexicalBackfillQuery(query))
                .FirstOrDefault(static value => !string.IsNullOrWhiteSpace(value));
        }

        var normalizedTitle = NormalizeForLexicalSignal(routeTitle ?? string.Empty);
        if (normalizedTitle.Length < 5)
            return false;

        var normalizedText = NormalizeForLexicalSignal(match.Text);
        var firstTitle = normalizedText.IndexOf(normalizedTitle, StringComparison.Ordinal);
        if (firstTitle < 0 || firstTitle > 80)
            return false;

        var afterFirstTitle = firstTitle + normalizedTitle.Length;
        var secondTitle = normalizedText.IndexOf(normalizedTitle, afterFirstTitle, StringComparison.Ordinal);
        if (secondTitle <= afterFirstTitle || secondTitle - afterFirstTitle > 420)
            return false;

        var leadingBody = normalizedText[afterFirstTitle..secondTitle];
        if (!Regex.IsMatch(
                leadingBody,
                @"\b(?:lancez|relancez|servez|laissez|repartissez|versez|degustez|couvrez)\b",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant))
        {
            return false;
        }

        var leadingInventoryCueCount = Regex.Matches(
            leadingBody,
            @"\b\d+(?:[,.]\d+)?\s*(?:g|kg|mg|ml|cl|l|oz|lb|units?|items?|pieces?|c)\b",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant).Count;
        if (leadingInventoryCueCount >= 2)
            return false;

        return !StructuredContentLexicon.ContainsItemizedCue(leadingBody);
    }

    private static bool LinkedContextLeadingContinuationNeedsPreviousCompanion(string query, RagMatch match)
    {
        if (!string.Equals(ResolveRetriever(match), "linked_context", StringComparison.Ordinal))
            return false;
        if (string.IsNullOrWhiteSpace(match.PrevChunkId) || string.IsNullOrWhiteSpace(match.Text))
            return false;
        if (!HasStructuredContinuationBackfillIntent(query))
            return false;

        var lead = NormalizeForLexicalSignal(match.Text);
        if (lead.Length > 260)
            lead = lead[..260];

        return Regex.IsMatch(
            lead,
            @"^\s*(?:procedez\s+de\s+la\s+meme\s+facon|de\s+la\s+meme\s+facon|continuer?|continuez|repetez|repeter|[2-9]\d?\s*[\.\)]|recouvrez|cassez\s+delicatement|versez\s+douce\s*ment)\b",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
    }

    private static bool IsLinkedContextLeadingProcedureContinuation(string query, RagMatch match)
    {
        if (!string.Equals(ResolveRetriever(match), "linked_context", StringComparison.Ordinal))
            return false;
        if (string.IsNullOrWhiteSpace(match.Text))
            return false;

        var lead = NormalizeForLexicalSignal(match.Text);
        if (lead.Length == 0)
            return false;

        var seenTitles = new HashSet<string>(StringComparer.Ordinal);
        void AddTitleCandidate(string? value)
        {
            var normalized = NormalizeForLexicalSignal(value);
            if (normalized.Length >= 5)
                seenTitles.Add(normalized);
        }

        AddTitleCandidate(ExtractMatchedRouteOrProfileTitle(match.EmbedText));
        AddTitleCandidate(match.SectionTitle);
        AddTitleCandidate(match.HeadingPath);
        foreach (var phrase in ExtractFocusedLookupPhrases(query))
            AddTitleCandidate(phrase);
        foreach (var phrase in ExtractQuotedLookupPhrases(query))
            AddTitleCandidate(phrase);
        AddTitleCandidate(BuildFocusedLexicalBackfillQuery(query));

        foreach (var normalizedTitle in seenTitles.OrderByDescending(static title => title.Length))
        {
            var titleIndex = lead.IndexOf(normalizedTitle, StringComparison.Ordinal);
            if (titleIndex < 0 || titleIndex > 80)
                continue;

            lead = lead[(titleIndex + normalizedTitle.Length)..].TrimStart();
            break;
        }

        if (lead.Length > 260)
            lead = lead[..260];

        return Regex.IsMatch(
            lead,
            @"^\s*(?:(?:[2-9]\d?\s*(?:[\.\)]|\b))|au\s+bout|a\s+la\s+fin|puis|ensuite|continuer?|continuez|relancez|servez|degustez|cuire\s+encore|et\s+cuire\s+encore|(?:pa|pe)ris\s+et\s+cuire\s+encore)\b",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
    }

    private static int ComputeStructuredContinuationAnchorTitleSignal(
        string query,
        IReadOnlyList<string> titleTokens,
        RagMatch match)
    {
        var signal = 0;
        var quotedPhrases = ExtractTitleLookupPhrases(query);
        if (quotedPhrases.Count > 0 && HasQuotedTitlePlacementEvidence(quotedPhrases, match))
            signal += 4;
        if (ComputeExactTitleCandidateScore(query, match) > 0.0)
            signal += 4;
        if (ComputeQuotedTitleAnchorSignal(query, match) > 0.0)
            signal += 4;
        if (ComputeDirectChunkTitleSignal(query, match) > 0)
            signal += 3;
        if (DirectTitleRouteBridgeNeedsPreviousCompanion(query, match))
            signal += 3;
        if (titleTokens.Count > 0 && HasFullTitleAnchorCoverage(titleTokens, match))
            signal += 3;
        if (IsResolvedTitleOrNavigationRoute(match) && match.Score >= 0.80)
            signal += 2;
        if (HasProfileTitleHint(match))
            signal += 2;
        if (match.MatchedContentCards is { Count: > 0 })
        {
            var lexicalTokens = ExtractLexicalQueryTokens(query)
                .Where(static token => !PrimaryAnchorStopwords.Contains(token))
                .Distinct(StringComparer.Ordinal)
                .Take(8)
                .ToArray();
            signal += Math.Min(2, ComputeMatchedContentCardTitleSignal(
                match,
                lexicalTokens,
                NormalizeForLexicalSignal(query)));
        }

        return signal;
    }

    private static bool IsUsefulStructuredContinuationCandidate(
        string query,
        RagMatch anchor,
        RagMatch candidate,
        string relation)
    {
        if (!string.Equals(anchor.DocPath, candidate.DocPath, StringComparison.OrdinalIgnoreCase))
            return false;
        if (!string.Equals(ResolveRetriever(candidate), "linked_context", StringComparison.Ordinal))
            return false;
        if (LooksLikeNavigationalChunk(candidate) || LooksLikeGlossaryChunk(candidate))
            return false;
        if (!IsContentSelectionCandidate(candidate))
            return false;
        if (!IsNearbyPage(anchor, candidate, maxDistance: 2))
            return false;

        var sharesSection = SharesSpecificSection(anchor, candidate);
        var samePage = anchor.PageStart.HasValue
            && candidate.PageStart.HasValue
            && anchor.PageStart.Value == candidate.PageStart.Value;
        var directTitleBridgeNeedsPrevious = DirectTitleRouteBridgeNeedsPreviousCompanion(query, anchor);
        var titleRouteLeadingContinuationNeedsPrevious = TitleRouteLeadingContinuationNeedsPreviousCompanion(query, anchor);
        var linkedContextLeadingContinuationNeedsPrevious =
            LinkedContextLeadingContinuationNeedsPreviousCompanion(query, anchor);
        var needsPreviousCompanion =
            directTitleBridgeNeedsPrevious
            || titleRouteLeadingContinuationNeedsPrevious
            || linkedContextLeadingContinuationNeedsPrevious;
        if (HasConflictingSpecificSectionTitle(anchor, candidate))
            return false;
        if (string.Equals(relation, "prev", StringComparison.Ordinal))
        {
            if (!sharesSection && !(needsPreviousCompanion && samePage))
                return false;
            if (IsResolvedTitleOrNavigationRoute(anchor) && !needsPreviousCompanion)
                return false;
        }

        var normalizedQuery = $" {NormalizeForLexicalSignal(query)} ";
        var asksInventory = ContainsStructuredInventoryRequest(normalizedQuery);
        var asksProcedure = ContainsStructuredProcedureRequest(normalizedQuery);
        var asksTime = ContainsStructuredTimeRequest(normalizedQuery);
        var asksSheet = ContainsStructuredSheetRequest(normalizedQuery);

        var anchorHasInventory = ContainsStructuredInventoryCue(anchor);
        var anchorHasProcedure = ContainsStructuredProcedureCue(anchor);
        var anchorHasTime = ContainsStructuredTimeCue(anchor);
        var candidateHasInventory = ContainsStructuredInventoryCue(candidate);
        var candidateHasProcedure = ContainsStructuredProcedureCue(candidate);
        var candidateHasTime = ContainsStructuredTimeCue(candidate);

        if (asksProcedure && !anchorHasProcedure && candidateHasProcedure)
            return true;
        if (asksInventory && !anchorHasInventory && candidateHasInventory)
            return true;
        if (asksTime && !anchorHasTime && candidateHasTime)
            return true;
        var isPreviousSamePageBridgeCandidate = string.Equals(relation, "same_page", StringComparison.Ordinal)
            && anchor.ChunkIndex.HasValue
            && candidate.ChunkIndex.HasValue
            && candidate.ChunkIndex.Value < anchor.ChunkIndex.Value;
        if (needsPreviousCompanion
            && asksSheet
            && (string.Equals(relation, "prev", StringComparison.Ordinal) || isPreviousSamePageBridgeCandidate)
            && (candidateHasInventory
                || candidateHasProcedure
                || candidateHasTime
                || ComputeContentEvidencePriority(candidate) >= 0.65))
        {
            return true;
        }
        var anchorIsHighConfidenceTitleOnly =
            IsHighConfidenceTitleOnlyStructuredContinuationAnchor(query, anchor);
        if (asksSheet
            && (IsResolvedTitleOrNavigationRoute(anchor) || anchorIsHighConfidenceTitleOnly)
            && sharesSection
            && (string.Equals(relation, "same_section", StringComparison.Ordinal)
                || string.Equals(relation, "next", StringComparison.Ordinal)
                || string.Equals(relation, "same_page_forward", StringComparison.Ordinal))
            && ComputeContentEvidencePriority(candidate) >= 0.65)
        {
            return true;
        }

        return asksSheet
            && sharesSection
            && ((anchorHasInventory && candidateHasProcedure)
                || (anchorHasProcedure && candidateHasInventory)
                || (!anchorHasTime && candidateHasTime));
    }

    private static bool IsHighConfidenceTitleOnlyStructuredContinuationAnchor(string query, RagMatch anchor)
    {
        if (GetStructuredAnswerPriority(anchor) >= 2)
            return false;
        if (ContainsStructuredInventoryCue(anchor) || ContainsStructuredProcedureCue(anchor))
            return false;
        if ((anchor.Text?.Length ?? 0) > 700)
            return false;

        var titleScoringQuery = BuildFocusedLexicalBackfillQuery(query);
        var titleTokens = ExtractTitleScoringTokens(
            string.IsNullOrWhiteSpace(titleScoringQuery) ? query : titleScoringQuery);
        return ComputeStructuredContinuationAnchorTitleSignal(query, titleTokens, anchor) >= 4;
    }

    private static string? ResolveStructuredContinuationRelation(RagMatch anchor, RagMatch candidate)
    {
        if (SameChunkId(candidate.ChunkId, anchor.NextChunkId)
            || SameChunkId(candidate.PrevChunkId, anchor.ChunkId))
        {
            return "next";
        }

        if (SameChunkId(candidate.ChunkId, anchor.PrevChunkId)
            || SameChunkId(candidate.NextChunkId, anchor.ChunkId))
        {
            return "prev";
        }

        if (SameChunkId(candidate.ChunkId, anchor.SameSectionChunkId)
            || SameChunkId(candidate.SameSectionChunkId, anchor.ChunkId))
        {
            return "same_section";
        }

        if (string.Equals(anchor.DocPath, candidate.DocPath, StringComparison.OrdinalIgnoreCase)
            && anchor.PageStart.HasValue
            && candidate.PageStart.HasValue
            && anchor.PageStart.Value == candidate.PageStart.Value
            && anchor.ChunkIndex.HasValue
            && candidate.ChunkIndex.HasValue
            && candidate.ChunkIndex.Value != anchor.ChunkIndex.Value
            && Math.Abs(candidate.ChunkIndex.Value - anchor.ChunkIndex.Value) <= 4)
        {
            return candidate.ChunkIndex.Value > anchor.ChunkIndex.Value
                ? "same_page_forward"
                : "same_page";
        }

        return null;
    }

    private static int StructuredContinuationRelationPriority(string relation)
        => relation switch
        {
            "same_section" => 4,
            "next" => 3,
            "prev" => 2,
            "same_page_forward" => 2,
            "same_page" => 1,
            _ => 0
        };

    private static int ComputeStructuredContinuationCuePriority(string query, RagMatch candidate)
    {
        var normalizedQuery = $" {NormalizeForLexicalSignal(query)} ";
        var priority = 0;
        if (ContainsStructuredProcedureRequest(normalizedQuery) && ContainsStructuredProcedureCue(candidate))
            priority += 4;
        if (ContainsStructuredInventoryRequest(normalizedQuery) && ContainsStructuredInventoryCue(candidate))
            priority += 3;
        if (ContainsStructuredTimeRequest(normalizedQuery) && ContainsStructuredTimeCue(candidate))
            priority += 2;
        if (ComputeContentEvidencePriority(candidate) >= 0.80)
            priority += 1;
        return priority;
    }

    private static bool ContainsStructuredInventoryRequest(string normalizedQuery)
        => StructuredContentLexicon.ContainsItemizedCue(normalizedQuery)
           || ContainsAny(
            normalizedQuery,
            " material ",
            " materials ",
            " materiel ",
            " materiaux ",
            " equipment ",
            " equipement ",
            " equipements ",
            " tool ",
            " tools ",
            " item ",
            " items ",
            " element ",
            " elements ",
            " requirement ",
            " requirements ",
            " supply ",
            " supplies ",
            " part ",
            " parts ",
            " componentes ",
            " componenti ",
            " components ",
            " composants ");

    private static bool ContainsStructuredProcedureRequest(string normalizedQuery)
        => ContainsAny(
            normalizedQuery,
            " etape ",
            " etapes ",
            " preparation ",
            " preparacion ",
            " preparo ",
            " preparazione ",
            " zubereitung ",
            " procedure ",
            " procedures ",
            " procedimiento ",
            " procedimentos ",
            " steps ",
            " step ",
            " instructions ",
            " instruction ",
            " mode operatoire ");

    private static bool ContainsStructuredTimeRequest(string normalizedQuery)
        => ContainsAny(
            normalizedQuery,
            " temps ",
            " duree ",
            " duration ",
            " time ",
            " dauer ",
            " duracion ",
            " duracao ");

    private static bool ContainsStructuredSheetRequest(string normalizedQuery)
        => StructuredContentLexicon.ContainsStructuredItemTypeCue(normalizedQuery)
           || ContainsAny(
            normalizedQuery,
            " fiche ",
            " ficha ",
            " scheda ",
            " sheet ",
            " card ",
            " section ",
            " topic ",
            " overview ",
            " summary ",
            " procedure ",
            " process ",
            " clear sheet ",
            " fiche claire ");

    private static bool ContainsStructuredInventoryCue(RagMatch match)
    {
        var normalized = NormalizeForLexicalSignal(GetDirectChunkSignalText(match));
        return StructuredContentLexicon.ContainsItemizedCue(normalized)
            || LooksLikeStructuredQuantityList(normalized);
    }

    private static bool ContainsStructuredProcedureCue(RagMatch match)
    {
        var normalized = NormalizeForLexicalSignal(GetDirectChunkSignalText(match));
        return normalized.Contains("preparation", StringComparison.Ordinal)
            || normalized.Contains("preparacion", StringComparison.Ordinal)
            || normalized.Contains("preparazione", StringComparison.Ordinal)
            || normalized.Contains("zubereitung", StringComparison.Ordinal)
            || normalized.Contains("procedure", StringComparison.Ordinal)
            || normalized.Contains("procedimiento", StringComparison.Ordinal)
            || normalized.Contains("procedimento", StringComparison.Ordinal)
            || normalized.Contains("instruction", StringComparison.Ordinal)
            || normalized.Contains("etape", StringComparison.Ordinal)
            || normalized.Contains("step", StringComparison.Ordinal)
            || normalized.Contains("technique", StringComparison.Ordinal)
            || Regex.IsMatch(
                normalized,
                @"(?:^|\s)1\s+(?:\w+\s+){0,18}?(?:ajouter|ajoutez|couper|coupez|cuire|faites|fendre|grattez|incorporer|incorporez|laisser|mettez|melanger|mixer|nettoyer|placer|prechauffer|recouvrez|remuer|remuez|retirer|retournez|versez|verser)\b",
                RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
    }

    private static bool ContainsStructuredTimeCue(RagMatch match)
    {
        var normalized = NormalizeForLexicalSignal(GetDirectChunkSignalText(match));
        return Regex.IsMatch(
            normalized,
            @"\b\d{1,3}\s*(?:min|minute|minutes|h|heure|heures|hour|hours|stunden?)",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
    }

    private static bool HasConflictingSpecificSectionTitle(RagMatch left, RagMatch right)
    {
        var leftTitle = GetSpecificSectionTitle(left);
        var rightTitle = GetSpecificSectionTitle(right);
        if (string.IsNullOrWhiteSpace(leftTitle) || string.IsNullOrWhiteSpace(rightTitle))
            return false;

        return !string.Equals(
            NormalizeForLexicalSignal(leftTitle),
            NormalizeForLexicalSignal(rightTitle),
            StringComparison.Ordinal);
    }

    private static string? GetSpecificSectionTitle(RagMatch match)
    {
        foreach (var value in new[] { match.SectionTitle, match.HeadingPath })
        {
            if (!string.IsNullOrWhiteSpace(value) && !IsGenericSectionTitle(value))
                return value.Trim();
        }

        return null;
    }

    private static bool SameChunkId(string? left, string? right)
        => !string.IsNullOrWhiteSpace(left)
           && !string.IsNullOrWhiteSpace(right)
           && string.Equals(left.Trim(), right.Trim(), StringComparison.OrdinalIgnoreCase);

    private static int CountPrimarySpecificSelectionAnchors(IReadOnlyList<string> primaryTokens, RagMatch match)
    {
        if (primaryTokens.Count == 0)
            return 0;

        var titleSignalText = GetPreciseTitleSignalText(match);
        if (string.IsNullOrWhiteSpace(titleSignalText))
            return 0;

        return CountSpecificLexicalAnchors(primaryTokens, titleSignalText);
    }

    private static bool ContainsPrimarySpecificSelectionAnchor(IReadOnlyList<string> primaryTokens, RagMatch match)
    {
        if (primaryTokens.Count == 0)
            return true;

        return ContainsPrimarySpecificLexicalAnchor(primaryTokens, GetPreciseTitleSignalText(match));
    }

    internal static void PruneUnpagedProfileSelectionsForPreciseLookup(string query, List<RagMatch> selected)
    {
        if (selected.Count <= 1)
            return;
        if (ShouldPreferComparativeDocumentDiversity(query)
            && ShouldAllowDocumentProfileAssistForComparativeLookup(query))
        {
            return;
        }

        var lexicalTokens = ExtractTitlePruneTokens(query);
        if (lexicalTokens.Length is < 2 or > 6)
            return;

        var hasPagedTitleEvidence = selected.Any(match =>
            match.PageStart.HasValue
            && (ComputeExactTitleCandidateScore(query, match) > 0.0
                || ContainsOrderedTitleTokenSubstrings(GetTitleSignalText(match), lexicalTokens, maxGapChars: 60)));
        if (!hasPagedTitleEvidence)
            return;

        selected.RemoveAll(static match =>
            !match.PageStart.HasValue
            && string.Equals(match.ChunkType, "document_profile", StringComparison.Ordinal));
    }

    private static bool IsUsefulLinkedSelectionNearPrimaryAnchor(
        IReadOnlyList<string> primaryTokens,
        RagMatch match,
        IReadOnlyList<RagMatch> primaryAnchors)
    {
        if (!string.Equals(ResolveRetriever(match), "linked_context", StringComparison.Ordinal))
            return false;
        if (LooksLikeNavigationalChunk(match) || LooksLikeGlossaryChunk(match))
            return false;

        return primaryAnchors.Any(anchor =>
            IsUsefulLinkedContextCompanion(primaryTokens, anchor, match));
    }

    private static bool IsSameChunk(RagMatch left, RagMatch right)
        => string.Equals(left.ChunkId, right.ChunkId, StringComparison.Ordinal)
           && string.Equals(left.DocPath, right.DocPath, StringComparison.OrdinalIgnoreCase);

    private static int CountTitleAnchorTokens(IReadOnlyList<string> lexicalTokens, string? candidateText)
    {
        if (lexicalTokens.Count == 0 || string.IsNullOrWhiteSpace(candidateText))
            return 0;

        var normalized = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(candidateText));
        var matched = 0;
        var seen = new HashSet<string>(StringComparer.Ordinal);
        foreach (var token in lexicalTokens)
        {
            foreach (var variant in BuildLexicalTokenVariants(token))
            {
                var foldedVariant = FoldDiacritics(variant);
                if (foldedVariant.Length >= 4
                    && normalized.Contains(foldedVariant, StringComparison.Ordinal))
                {
                    if (seen.Add(token))
                        matched++;
                    break;
                }
            }
        }

        return matched;
    }

    private static bool HasStrictTitleAnchorCoverage(IReadOnlyList<string> lexicalTokens, RagMatch match)
    {
        if (lexicalTokens.Count < 2)
            return false;

        var titleSignalText = GetPreciseTitleSignalText(match);
        if (string.IsNullOrWhiteSpace(titleSignalText))
            return false;

        var normalized = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(titleSignalText));
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        return ContainsTitleLikeLexicalSequence(normalized, lexicalTokens);
    }

    private static string GetPreciseTitleSignalText(RagMatch match)
    {
        return string.Join("\n", new[]
        {
            ExtractMatchedRouteOrProfileTitle(match.EmbedText),
            match.MatchedContentCards is { Count: > 0 }
                ? string.Join("\n", match.MatchedContentCards.Take(MaxCalibrationCardCount).Select(static card => card.Title))
                : null,
            match.Text,
            match.SectionTitle,
            match.HeadingPath
        }.Where(static value => !string.IsNullOrWhiteSpace(value)));
    }

    private static string? ExtractMatchedRouteOrProfileTitle(string? embedText)
    {
        if (string.IsNullOrWhiteSpace(embedText))
            return null;

        string[] prefixes =
        [
            "Matched profile title:",
            "Matched quoted title:",
            "Matched title_anchor_route:",
            "Matched linked_anchor_title:",
            "Matched navigation_route:",
            "Matched direct_title_token_route:",
            "Matched fuzzy_title_lead:"
        ];
        var prefix = prefixes.FirstOrDefault(prefix => embedText.StartsWith(prefix, StringComparison.Ordinal));
        if (prefix is null)
            return null;

        var start = prefix.Length;
        var lineEnd = embedText.IndexOf('\n', start);
        if (lineEnd < 0)
        {
            var documentMarker = FindFirstMarker(embedText, start, [" Document:", " document_name:"]);
            lineEnd = documentMarker >= 0 ? documentMarker : embedText.Length;
        }

        return embedText[start..lineEnd].Trim();
    }

    private static int FindFirstMarker(string value, int startIndex, IReadOnlyList<string> markers)
    {
        var first = -1;
        foreach (var marker in markers)
        {
            var index = value.IndexOf(marker, startIndex, StringComparison.Ordinal);
            if (index >= 0 && (first < 0 || index < first))
                first = index;
        }

        return first;
    }

    private static string[] ExtractTitlePruneTokens(string query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return [];

        var normalized = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query));
        if (string.IsNullOrWhiteSpace(normalized))
            return [];

        return normalized
            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Where(static token => (token.Length >= 4 && token.Any(char.IsLetter)) || token.Any(char.IsDigit))
            .Where(static token => !TitleConnectorTokens.Contains(token))
            .Where(static token => !LexicalStopwords.Contains(token))
            .Where(static token => !PrimaryAnchorStopwords.Contains(token))
            .Distinct(StringComparer.Ordinal)
            .Take(8)
            .ToArray();
    }

    private static IReadOnlyList<string> ExtractTitleScoringTokens(string query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return Array.Empty<string>();

        var normalized = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query));
        if (string.IsNullOrWhiteSpace(normalized))
            return Array.Empty<string>();

        var rawTokens = normalized
            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToArray();
        if (rawTokens.Length == 0)
            return Array.Empty<string>();

        var selected = new List<string>(capacity: Math.Min(rawTokens.Length, 9));
        for (var i = 0; i < rawTokens.Length; i++)
        {
            var token = rawTokens[i];
            if (IsLongTitleSignalToken(token))
            {
                selected.Add(token);
                continue;
            }

            if ((IsShortTitleSignalToken(token)
                    && selected.Count > 0
                    && rawTokens.Take(i).Any(static previous => TitleConnectorTokens.Contains(previous)))
                || IsTerminalShortTitleDisambiguator(rawTokens, i, selected.Count))
            {
                selected.Add(token);
            }
        }

        if (selected.Count < 2 && HasShortConnectorTitleShape(rawTokens))
        {
            selected.AddRange(rawTokens.Where(IsFocusedLookupSignalToken));
        }

        return selected
            .Distinct(StringComparer.Ordinal)
            .Take(9)
            .ToArray();
    }

    private static bool HasShortConnectorTitleShape(IReadOnlyList<string> rawTokens)
        => rawTokens.Count is >= 3 and <= 6
           && rawTokens.Any(static token => TitleConnectorTokens.Contains(token))
           && rawTokens.Count(IsFocusedLookupSignalToken) >= 2;

    private static bool IsLongTitleSignalToken(string token)
        => ((token.Length >= 4 && token.Any(char.IsLetter)) || token.Any(char.IsDigit))
           && !TitleConnectorTokens.Contains(token)
           && !LexicalStopwords.Contains(token)
           && !PrimaryAnchorStopwords.Contains(token);

    private static bool IsShortTitleSignalToken(string token)
        => token.Length is >= 1 and <= 3
           && token.Any(char.IsLetterOrDigit)
           && !TitleConnectorTokens.Contains(token)
           && !LexicalStopwords.Contains(token)
           && !SpecificAnchorStopwords.Contains(token)
           && !PrimaryAnchorStopwords.Contains(token);

    private static bool IsTerminalShortTitleDisambiguator(IReadOnlyList<string> rawTokens, int index, int selectedCount)
    {
        if (index != rawTokens.Count - 1 || selectedCount < 2)
            return false;

        var token = rawTokens[index];
        return token.Length is >= 1 and <= 3
               && token.Any(char.IsLetterOrDigit)
               && !LexicalStopwords.Contains(token)
               && !SpecificAnchorStopwords.Contains(token)
               && !PrimaryAnchorStopwords.Contains(token);
    }

    private static bool IsTitleScoringTokenVariant(string variant)
        => variant.Length >= 4 || IsShortTitleSignalToken(variant) || IsTerminalTitleVariant(variant);

    private static bool IsTerminalTitleVariant(string variant)
        => variant.Length is >= 1 and <= 3
           && variant.Any(char.IsLetterOrDigit)
           && !LexicalStopwords.Contains(variant)
           && !SpecificAnchorStopwords.Contains(variant)
           && !PrimaryAnchorStopwords.Contains(variant);

    private static bool ShouldAllowNavigationalResults(string query)
    {
        var normalized = $" {NormalizeQuery(FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query))).ToLowerInvariant()} ";
        return ContainsAny(normalized,
            " index ",
            " sommaire ",
            " table des matieres ",
            " table of contents ",
            " inhaltsverzeichnis ",
            " indice general ",
            " indice de contenido ",
            " indice de contenidos ",
            " indice de materias ",
            " indice analitico ",
            " sumario ",
            " sommario ",
            " toc ",
            " inventaire ",
            " corpus ",
            " vue d ensemble ",
            " overview ",
            " quels livres ",
            " quelles sources ",
            " quels documents ",
            " que documentos ",
            " quais documentos ",
            " quali documenti ",
            " welche dokumente ",
            " que fuentes ",
            " quais fontes ",
            " quali fonti ",
            " welche quellen ")
            || LooksLikeGenericNavigationalRequest(normalized);
    }

    private static bool ShouldExplicitlyRequestNavigationArtifacts(string query)
    {
        var normalized = $" {NormalizeQuery(FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query))).ToLowerInvariant()} ";
        return ContainsAny(normalized,
            " index ",
            " sommaire ",
            " table des matieres ",
            " table of contents ",
            " inhaltsverzeichnis ",
            " indice general ",
            " indice de contenido ",
            " indice de contenidos ",
            " indice de materias ",
            " indice analitico ",
            " sumario ",
            " sommario ",
            " toc ");
    }

    private static bool LooksLikeGenericNavigationalRequest(string normalizedPaddedQuery)
    {
        if (string.IsNullOrWhiteSpace(normalizedPaddedQuery))
            return false;

        if (ContainsAny(
            normalizedPaddedQuery,
            " inhaltsverzeichnis ",
            " indice general ",
            " indice de contenido ",
            " indice de contenidos ",
            " indice de materias ",
            " indice analitico ",
            " sumario ",
            " sommario ",
            " toc "))
        {
            return true;
        }

        return System.Text.RegularExpressions.Regex.IsMatch(
            normalizedPaddedQuery,
            @"\b(?:liste|list|catalogue|catalog|inventaire|inventory|index)\s+(?:des?|de|du|d['’]?|of|for)?\s*[\p{L}\p{N}][\p{L}\p{N}\s\-_]{2,80}\b|\b[\p{L}\p{N}][\p{L}\p{N}\s\-_]{2,80}\s+(?:liste|list|catalogue|catalog|inventory|index)\b",
            System.Text.RegularExpressions.RegexOptions.CultureInvariant | System.Text.RegularExpressions.RegexOptions.IgnoreCase);
    }

    private static string NormalizeForLexicalSignal(string? value)
        => string.IsNullOrWhiteSpace(value)
            ? string.Empty
            : FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(value));

    internal static bool ContainsOrderedPhraseWindow(string? candidateText, string phrase, int maxGapChars)
    {
        if (string.IsNullOrWhiteSpace(candidateText) || string.IsNullOrWhiteSpace(phrase))
            return false;

        var normalizedPhrase = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(phrase));
        return ContainsOrderedPhraseWindowInNormalizedText(
            NormalizeForLexicalSignal(candidateText),
            normalizedPhrase,
            maxGapChars);
    }

    private static bool ContainsOrderedPhraseWindowInNormalizedText(string normalizedCandidate, string normalizedPhrase, int maxGapChars)
    {
        if (string.IsNullOrWhiteSpace(normalizedCandidate) || string.IsNullOrWhiteSpace(normalizedPhrase))
            return false;

        var tokens = normalizedPhrase
            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Where(static token => token.Length >= 2)
            .ToArray();
        if (tokens.Length < 2)
            return false;

        var searchFrom = 0;
        var previousEnd = -1;
        foreach (var token in tokens)
        {
            var index = normalizedCandidate.IndexOf(token, searchFrom, StringComparison.Ordinal);
            if (index < 0)
                return false;

            if (previousEnd >= 0 && index - previousEnd > maxGapChars)
                return false;

            previousEnd = index + token.Length;
            searchFrom = previousEnd;
        }

        return true;
    }

    private const int MaxCalibrationProfileSignalChars = 24000;
    private const int MaxCalibrationCardSignalChars = 8000;
    private const int MaxCalibrationCardCount = 32;

    private static string GetLexicalSignalText(RagMatch match)
    {
        if (IsDocumentProfileMatch(match))
            return BuildDocumentProfileCalibrationSignal(match, includeEmbedFallback: true);

        return string.IsNullOrWhiteSpace(match.EmbedText)
            ? match.Text ?? string.Empty
            : match.EmbedText!;
    }

    private static string GetDirectChunkSignalText(RagMatch match)
        => string.Join("\n", new[]
        {
            match.Text,
            match.SectionTitle,
            match.HeadingPath
        }.Where(static value => !string.IsNullOrWhiteSpace(value)));

    private static string GetTitleSignalText(RagMatch match)
    {
        if (IsDocumentProfileMatch(match))
            return BuildDocumentProfileCalibrationSignal(match, includeEmbedFallback: true);

        var includeEmbedText = string.Equals(match.ChunkType, "document_profile", StringComparison.Ordinal)
            || HasProfileTitleHint(match);
        return string.Join("\n", new[]
        {
            includeEmbedText ? match.EmbedText : null,
            match.Text,
            match.SectionTitle,
            match.HeadingPath
        }.Where(static value => !string.IsNullOrWhiteSpace(value)));
    }

    private static int ComputeShortTechnicalDirectEvidencePriority(
        string query,
        RagMatch match,
        string normalizedTextForSignals,
        string normalizedTitleSignalText)
    {
        var (queryTerms, hasProperty, hasElectrical, hasThermal) = ClassifyShortTechnicalPropertyLookup(query);
        if (queryTerms.Count == 0)
            return 0;

        if (!hasProperty || (!hasElectrical && !hasThermal))
            return 0;

        _ = normalizedTextForSignals;
        _ = normalizedTitleSignalText;

        var directTitleEvidence = NormalizeForLexicalSignal($"{match.SectionTitle} {match.HeadingPath}");
        var directChunkEvidence = NormalizeForLexicalSignal($"{match.Text} {match.SectionTitle} {match.HeadingPath}");

        if (hasElectrical)
        {
            if (ContainsElectricalPropertyPhrase(directTitleEvidence))
                return 5;
            if (ContainsElectricalPropertyPhrase(directChunkEvidence))
                return 4;
        }

        if (hasThermal)
        {
            if (ContainsThermalPropertyPhrase(directTitleEvidence))
                return 5;
            if (ContainsThermalPropertyPhrase(directChunkEvidence))
                return 4;
        }

        return 0;
    }

    private static bool ShouldRunShortTechnicalDirectEvidenceLinkedBackfill(string query, IReadOnlyList<RagMatch> selected)
    {
        if (selected.Count == 0 || !IsShortTechnicalPropertyLookup(query))
            return false;

        var firstDirectEvidenceRank = selected
            .Take(8)
            .Select((match, index) => new
            {
                Match = match,
                Index = index,
                Priority = ComputeShortTechnicalDirectEvidencePriority(query, match, string.Empty, string.Empty)
            })
            .FirstOrDefault(static item => item.Priority > 0)?.Index;
        if (firstDirectEvidenceRank == 0)
            return false;

        return selected.Take(8).Any(static match =>
            !string.IsNullOrWhiteSpace(match.PrevChunkId)
            || !string.IsNullOrWhiteSpace(match.NextChunkId)
            || !string.IsNullOrWhiteSpace(match.SameSectionChunkId));
    }

    private static bool ShouldRunShortTechnicalDirectPhraseBackfill(string query, IReadOnlyList<RagMatch> selected)
    {
        if (!IsShortTechnicalPropertyLookup(query))
            return false;

        var limit = Math.Min(selected.Count, 8);
        for (var i = 0; i < limit; i++)
        {
            if (ComputeShortTechnicalDirectEvidencePriority(query, selected[i], string.Empty, string.Empty) > 0)
                return i > 0;
        }

        return true;
    }

    private static void PrioritizeShortTechnicalDirectEvidenceSelections(string query, List<RagMatch> selected)
    {
        if (selected.Count < 2 || !IsShortTechnicalPropertyLookup(query))
            return;

        var ranked = selected
            .Select((match, index) => new
            {
                Match = match,
                Index = index,
                Priority = ComputeShortTechnicalDirectEvidencePriority(query, match, string.Empty, string.Empty)
            })
            .OrderByDescending(static item => item.Priority > 0)
            .ThenByDescending(static item => item.Priority)
            .ThenBy(static item => item.Index)
            .Select(static item => item.Match)
            .ToList();

        selected.Clear();
        selected.AddRange(ranked);
    }

    private static bool IsShortTechnicalPropertyLookup(string query)
    {
        var (_, hasProperty, hasElectrical, hasThermal) = ClassifyShortTechnicalPropertyLookup(query);
        return hasProperty && (hasElectrical || hasThermal);
    }

    private static (HashSet<string> Terms, bool HasProperty, bool HasElectrical, bool HasThermal) ClassifyShortTechnicalPropertyLookup(string query)
    {
        var terms = BuildShortTechnicalLookupTerms(query);
        var normalized = $" {NormalizeForLexicalSignal(RepairLikelyMojibakeText(query))} ";
        var hasProperty = terms.Overlaps(new[] { "propriete", "proprietes", "property", "properties", "characteristic", "characteristics" })
            || ContainsAny(
                normalized,
                " propriete ",
                " proprietes ",
                " property ",
                " properties ",
                " characteristic ",
                " characteristics ");
        var hasElectrical = terms.Overlaps(new[] { "electrique", "electriques", "electric", "electrical", "electricity", "dielectric" })
            || ContainsAny(
                normalized,
                " electrique ",
                " electriques ",
                " electric ",
                " electrical ",
                " dielectric ");
        var hasThermal = terms.Overlaps(new[] { "thermique", "thermiques", "thermal", "temperature", "temperatures", "melt point", "melting point" })
            || ContainsAny(
                normalized,
                " thermique ",
                " thermiques ",
                " thermal ",
                " temperature ",
                " temperatures ",
                " melt point ",
                " melting point ");

        if (!hasProperty
            && (ContainsAny(normalized, " thermal properties ", " temperature properties ", " electrical properties ", " dielectric properties ")
                || ContainsAny(normalized, " proprietes thermiques ", " proprietes electriques ")))
        {
            hasProperty = true;
        }

        return (terms, hasProperty, hasElectrical, hasThermal);
    }

    private static HashSet<string> BuildShortTechnicalLookupTerms(string query)
    {
        var normalized = NormalizeForLexicalSignal(RepairLikelyMojibakeText(query));
        var terms = ExtractLexicalQueryTokens(normalized)
            .SelectMany(static token => BuildLexicalTokenVariants(token).DefaultIfEmpty(token))
            .Where(static term => !string.IsNullOrWhiteSpace(term))
            .ToHashSet(StringComparer.Ordinal);
        foreach (var phrase in BuildQueryExpansionTerms(normalized).Where(static term => term.Contains(' ')))
            terms.Add(phrase);
        return terms;
    }

    internal static IReadOnlyList<string> BuildShortTechnicalDirectPhraseTerms(string query)
    {
        var (queryTerms, hasProperty, hasElectrical, hasThermal) = ClassifyShortTechnicalPropertyLookup(query);
        if (queryTerms.Count == 0)
            return [];

        if (!hasProperty || (!hasElectrical && !hasThermal))
            return [];

        var phrases = new List<string>();
        if (hasElectrical)
        {
            phrases.AddRange([
                "electrical properties",
                "electric properties",
                "dielectric properties",
                "electrical characteristics",
                "dielectric strength",
                "dielectric constant",
                "volume resistivity",
                "surface resistivity",
                "propriete electrique",
                "proprietes electriques",
                "caracteristique electrique",
                "caracteristiques electriques"
            ]);
        }

        if (hasThermal)
        {
            phrases.AddRange([
                "thermal properties",
                "temperature properties",
                "thermal characteristics",
                "melt point",
                "melting point",
                "service temperature",
                "service temperature range",
                "propriete thermique",
                "proprietes thermiques",
                "caracteristique thermique",
                "caracteristiques thermiques"
            ]);
        }

        return phrases
            .Select(static phrase => NormalizeForLexicalSignal(phrase))
            .Where(static phrase => phrase.Contains(' '))
            .Distinct(StringComparer.Ordinal)
            .OrderByDescending(static phrase => phrase.Length)
            .ThenBy(static phrase => phrase, StringComparer.Ordinal)
            .ToArray();
    }

    private static bool ContainsElectricalPropertyPhrase(string normalizedEvidence)
        => Regex.IsMatch(
            normalizedEvidence,
            @"\b(?:electrical\s+properties|electric\s+properties|dielectric\s+properties|properties\s+(?:electrical|electric|dielectric)|electrical\s+characteristics|dielectric\s+strength|proprietes?\s+electriques?|caracteristiques?\s+electriques?)\b",
            RegexOptions.CultureInvariant);

    private static bool ContainsThermalPropertyPhrase(string normalizedEvidence)
        => Regex.IsMatch(
            normalizedEvidence,
            @"\b(?:thermal\s+properties|temperature\s+properties|properties\s+thermal|thermal\s+characteristics|melt\s+point|melting\s+point|service\s+temperature|proprietes?\s+thermiques?|caracteristiques?\s+thermiques?)\b",
            RegexOptions.CultureInvariant);

    private static string BuildMatchedContentCardCalibrationSignal(RagMatch match)
    {
        if (match.MatchedContentCards is not { Count: > 0 })
            return string.Empty;

        var sb = new StringBuilder();
        foreach (var card in match.MatchedContentCards.Take(MaxCalibrationCardCount))
        {
            AppendCalibrationSignalPart(sb, card.Title, maxChars: 500);
            AppendCalibrationSignalPart(sb, card.Kind, maxChars: 120);
            if (card.Signals is { Count: > 0 })
            {
                foreach (var signal in card.Signals.Take(12))
                    AppendCalibrationSignalPart(sb, signal, maxChars: 240);
            }

            if (card.Evidence is { } evidence)
                AppendCalibrationSignalPart(sb, evidence.GetRawText(), maxChars: 1000);

            if (sb.Length >= MaxCalibrationCardSignalChars)
                break;
        }

        return sb.ToString();
    }

    private static string BuildDocumentProfileCalibrationSignal(RagMatch match, bool includeEmbedFallback)
    {
        var sb = new StringBuilder();
        AppendCalibrationSignalPart(sb, match.Text, maxChars: 5000);
        AppendCalibrationSignalPart(sb, match.SectionTitle, maxChars: 500);
        AppendCalibrationSignalPart(sb, match.HeadingPath, maxChars: 500);

        if (match.MatchedContentCards is { Count: > 0 })
        {
            var cardsSb = new StringBuilder();
            foreach (var card in match.MatchedContentCards.Take(MaxCalibrationCardCount))
            {
                AppendCalibrationSignalPart(cardsSb, card.Title, maxChars: 500);
                AppendCalibrationSignalPart(cardsSb, card.Kind, maxChars: 120);
                if (card.Signals is { Count: > 0 })
                {
                    foreach (var signal in card.Signals.Take(12))
                        AppendCalibrationSignalPart(cardsSb, signal, maxChars: 240);
                }

                if (cardsSb.Length >= MaxCalibrationCardSignalChars)
                    break;
            }

            AppendCalibrationSignalPart(sb, cardsSb.ToString(), MaxCalibrationCardSignalChars);
        }

        if (includeEmbedFallback)
            AppendCalibrationSignalPart(sb, match.EmbedText, MaxCalibrationProfileSignalChars);

        return sb.ToString();
    }

    private static void AppendCalibrationSignalPart(StringBuilder sb, string? value, int maxChars)
    {
        if (string.IsNullOrWhiteSpace(value) || maxChars <= 0)
            return;

        if (sb.Length > 0)
            sb.Append('\n');

        var trimmed = value.Trim();
        if (trimmed.Length <= maxChars)
        {
            sb.Append(trimmed);
            return;
        }

        var headChars = Math.Max(1, maxChars / 2);
        var tailChars = Math.Max(1, maxChars - headChars);
        sb.Append(trimmed, 0, headChars);
        sb.Append('\n');
        sb.Append(trimmed, trimmed.Length - tailChars, tailChars);
    }

    internal static bool HasProfileTitleHint(RagMatch match)
    {
        if (string.IsNullOrWhiteSpace(match.EmbedText))
            return false;

        if (match.EmbedText!.StartsWith("Matched navigation_route:", StringComparison.Ordinal))
            return NavigationRouteHasTargetTitleEvidence(match);
        if (match.EmbedText.StartsWith("Matched direct_title_token_route:", StringComparison.Ordinal))
            return DirectTitleTokenRouteHasTargetTitleEvidence(match);
        if (match.EmbedText.StartsWith("Matched quoted title:", StringComparison.Ordinal))
            return MatchedQuotedTitleHasTargetTitleEvidence(match);

        return match.EmbedText.StartsWith("Matched profile title:", StringComparison.Ordinal)
            || match.EmbedText.StartsWith("Matched title_anchor_route:", StringComparison.Ordinal)
            || match.EmbedText.StartsWith("Matched linked_anchor_title:", StringComparison.Ordinal)
            || match.EmbedText.StartsWith("Matched fuzzy_title_lead:", StringComparison.Ordinal);
    }

    internal static bool MatchedQuotedTitleHasTargetTitleEvidence(RagMatch match)
    {
        var matchedTitle = ExtractMatchedRouteOrProfileTitle(match.EmbedText);
        if (string.IsNullOrWhiteSpace(matchedTitle))
            return false;

        var phrases = matchedTitle
            .Split(';', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Select(static phrase => ExactMatchEntryExtractor.NormalizeForLookup(phrase))
            .Where(static phrase => phrase.Length >= 4)
            .Distinct(StringComparer.Ordinal)
            .Take(8)
            .ToArray();
        if (phrases.Length == 0)
            return false;

        if (HasLocalTitleTokenLeadEvidence(match.Text, match.SectionTitle, match.HeadingPath, phrases))
            return true;

        if (match.MatchedContentCards is not { Count: > 0 })
            return false;

        foreach (var card in match.MatchedContentCards.Take(MaxCalibrationCardCount))
        {
            var title = card.Title;
            if (string.IsNullOrWhiteSpace(title))
                continue;

            if (ComputeQuotedLookupCandidateScore(phrases, title) > 0.0)
                return true;
        }

        return false;
    }

    internal static bool NavigationRouteHasTargetTitleEvidence(RagMatch match)
    {
        if (!IsNavigationRouteMatch(match))
            return true;

        return RouteHasTargetTitleEvidence(match);
    }

    internal static bool DirectTitleTokenRouteHasTargetTitleEvidence(RagMatch match)
    {
        if (!IsDirectTitleTokenRouteMatch(match))
            return true;

        return RouteHasTargetTitleEvidence(match);
    }

    internal static bool DirectTitleTokenRouteHasStrongLeadEvidence(RagMatch match)
    {
        if (!IsDirectTitleTokenRouteMatch(match))
            return true;

        var routeTitle = ExtractMatchedRouteOrProfileTitle(match.EmbedText);
        if (string.IsNullOrWhiteSpace(routeTitle))
            return false;

        var normalizedRouteTitle = NormalizeNavigationRouteEvidenceTitle(routeTitle);
        if (string.IsNullOrWhiteSpace(normalizedRouteTitle))
            return false;

        var normalizedSection = NormalizeForLexicalSignal(string.Join(' ', new[]
        {
            match.SectionTitle,
            match.HeadingPath
        }.Where(static value => !string.IsNullOrWhiteSpace(value))));
        if (!string.IsNullOrWhiteSpace(normalizedSection)
            && normalizedSection.Contains(normalizedRouteTitle, StringComparison.Ordinal))
        {
            return true;
        }

        var titleTokens = normalizedRouteTitle
            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Where(static token => token.Length >= 3 || token.Any(char.IsDigit))
            .Where(static token => !TitleConnectorTokens.Contains(token))
            .Where(static token => !LexicalStopwords.Contains(token))
            .Where(static token => !SpecificAnchorStopwords.Contains(token))
            .Where(static token => !PrimaryAnchorStopwords.Contains(token))
            .Distinct(StringComparer.Ordinal)
            .Take(8)
            .ToArray();

        if (match.MatchedContentCards is { Count: > 0 } && titleTokens.Length >= 2)
        {
            foreach (var card in match.MatchedContentCards.Take(MaxCalibrationCardCount))
            {
                var normalizedCardTitle = NormalizeForLexicalSignal(card.Title);
                if (string.IsNullOrWhiteSpace(normalizedCardTitle))
                    continue;

                if (normalizedCardTitle.Contains(normalizedRouteTitle, StringComparison.Ordinal)
                    || ContainsOrderedTitleTokenSubstringsInNormalizedText(normalizedCardTitle, titleTokens, maxGapChars: 24)
                    || ContainsTitleLikeLexicalSequence(normalizedCardTitle, titleTokens))
                {
                    return true;
                }
            }
        }

        var normalizedText = NormalizeForLexicalSignal(match.Text ?? string.Empty);
        if (string.IsNullOrWhiteSpace(normalizedText))
            return false;

        var exactPosition = normalizedText.IndexOf(normalizedRouteTitle, StringComparison.Ordinal);
        if (LooksLikeStandaloneLeadTitlePlacement(match.Text, normalizedText, normalizedRouteTitle, exactPosition))
            return true;
        if (HasLocalTitleTokenFooterTitleEvidence(normalizedText, exactPosition, normalizedRouteTitle.Length))
            return true;

        if (titleTokens.Length < 2)
            return false;

        var leadingText = normalizedText.Length <= 48 ? normalizedText : normalizedText[..48];
        var firstTitleTokenPosition = leadingText.IndexOf(titleTokens[0], StringComparison.Ordinal);
        if (firstTitleTokenPosition < 0 || firstTitleTokenPosition > 8)
        {
            var leadWindow = normalizedText.Length <= 140 ? normalizedText : normalizedText[..140];
            var leadWindowTitleTokenPosition = leadWindow.IndexOf(titleTokens[0], StringComparison.Ordinal);
            return leadWindowTitleTokenPosition >= 0
                && HasLeadTitleCue(leadWindow, normalizedRouteTitle, leadWindowTitleTokenPosition)
                && ContainsTitleLikeLexicalSequence(leadWindow, titleTokens)
                && LooksLikeStructuredAnswerChunk(match);
        }

        return ContainsOrderedTitleTokenSubstringsInNormalizedText(leadingText, titleTokens, maxGapChars: 16)
            || ContainsTitleLikeLexicalSequence(leadingText, titleTokens);
    }

    private static bool LooksLikeStandaloneLeadTitlePlacement(
        string? rawText,
        string normalizedText,
        string normalizedTitle,
        int exactPosition)
    {
        if (exactPosition < 0 || string.IsNullOrWhiteSpace(normalizedText) || string.IsNullOrWhiteSpace(normalizedTitle))
            return false;
        if (exactPosition > 140)
            return false;

        var before = normalizedText[..exactPosition].TrimEnd();
        if (before.Length == 0)
            return !LeadTitlePrefixEndsWithBlockedToken(before);
        if (exactPosition <= 8)
        {
            if (LeadTitlePrefixEndsWithBlockedToken(before))
                return false;
            if (LooksLikeShortDurationTitlePrefix(before))
                return true;

            return HasRawStandaloneTitleBoundary(rawText, normalizedTitle);
        }

        if (!HasRawStandaloneTitleBoundary(rawText, normalizedTitle))
            return false;

        return !LeadTitlePrefixEndsWithBlockedToken(before);
    }

    private static bool LooksLikeShortDurationTitlePrefix(string normalizedPrefix)
        => Regex.IsMatch(
            normalizedPrefix,
            @"^\d{1,3}\s*(?:min|minute|minutes|h|heure|heures|hour|hours)$",
            RegexOptions.CultureInvariant);

    private static bool LeadTitlePrefixEndsWithBlockedToken(string before)
    {
        var beforeTokens = before.Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        if (beforeTokens.Length == 0)
            return false;

        var lastToken = beforeTokens[^1];
        return lastToken.Any(char.IsDigit)
            || string.Equals(lastToken, "de", StringComparison.Ordinal)
            || string.Equals(lastToken, "du", StringComparison.Ordinal)
            || string.Equals(lastToken, "des", StringComparison.Ordinal)
            || string.Equals(lastToken, "d", StringComparison.Ordinal)
            || string.Equals(lastToken, "of", StringComparison.Ordinal)
            || string.Equals(lastToken, "with", StringComparison.Ordinal);
    }

    private static bool HasRawStandaloneTitleBoundary(string? rawText, string normalizedTitle)
    {
        if (string.IsNullOrWhiteSpace(rawText) || string.IsNullOrWhiteSpace(normalizedTitle))
            return false;

        var tokens = normalizedTitle
            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Select(System.Text.RegularExpressions.Regex.Escape)
            .ToArray();
        if (tokens.Length == 0)
            return false;

        var foldedRawText = FoldDiacritics(rawText).ToLowerInvariant();
        var pattern = @"(?<![\p{L}\p{Nd}])"
            + string.Join(@"[\s\p{P}\p{S}]+", tokens)
            + @"(?![\p{L}\p{Nd}])";
        foreach (System.Text.RegularExpressions.Match match in System.Text.RegularExpressions.Regex.Matches(
                     foldedRawText,
                     pattern,
                     System.Text.RegularExpressions.RegexOptions.CultureInvariant))
        {
            if (match.Index > 180)
                break;
            if (match.Index <= 8)
            {
                var rawPrefix = foldedRawText[..match.Index].Trim();
                if (rawPrefix.Length == 0
                    || !rawPrefix.Any(char.IsLetterOrDigit)
                    || LooksLikeShortDurationTitlePrefix(NormalizeForLexicalSignal(rawPrefix)))
                {
                    return true;
                }
            }

            var beforeIndex = match.Index - 1;
            var crossedLineBreak = false;
            while (beforeIndex >= 0 && char.IsWhiteSpace(foldedRawText[beforeIndex]))
            {
                crossedLineBreak |= foldedRawText[beforeIndex] is '\n' or '\r';
                beforeIndex--;
            }
            if (beforeIndex < 0)
                return true;
            if (crossedLineBreak)
                return true;

            if (IsStandaloneTitleBoundaryCharacter(foldedRawText[beforeIndex]))
                return true;
        }

        return false;
    }

    private static bool HasRawExactQuotedTitleEndBoundary(string? rawText, string normalizedTitle)
    {
        if (string.IsNullOrWhiteSpace(rawText) || string.IsNullOrWhiteSpace(normalizedTitle))
            return false;

        var tokens = normalizedTitle
            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Select(System.Text.RegularExpressions.Regex.Escape)
            .ToArray();
        if (tokens.Length == 0)
            return false;

        var foldedRawText = FoldDiacritics(rawText).ToLowerInvariant();
        var pattern = @"(?<![\p{L}\p{Nd}])"
            + string.Join(@"[\s\p{P}\p{S}]+", tokens)
            + @"(?![\p{L}\p{Nd}])";
        foreach (System.Text.RegularExpressions.Match match in System.Text.RegularExpressions.Regex.Matches(
                     foldedRawText,
                     pattern,
                     System.Text.RegularExpressions.RegexOptions.CultureInvariant))
        {
            var suffixIndex = match.Index + match.Length;
            var crossedLineBreak = false;
            while (suffixIndex < foldedRawText.Length && char.IsWhiteSpace(foldedRawText[suffixIndex]))
            {
                crossedLineBreak |= foldedRawText[suffixIndex] is '\n' or '\r';
                suffixIndex++;
            }

            if (suffixIndex >= foldedRawText.Length || crossedLineBreak)
                return true;

            var suffixChar = foldedRawText[suffixIndex];
            if (char.IsDigit(suffixChar))
                return true;
            if (suffixChar is '.' or ':' or ';' or '!' or '?' or ')' or ']' or '}')
                return true;
        }

        return false;
    }

    private static bool IsStandaloneTitleBoundaryCharacter(char ch)
        => ch is '.' or ':' or ';' or '!' or '?' or '\n' or '\r';

    private static bool RouteHasTargetTitleEvidence(RagMatch match)
    {
        var routeTitle = ExtractMatchedRouteOrProfileTitle(match.EmbedText);
        if (string.IsNullOrWhiteSpace(routeTitle))
            return false;

        var directSignal = GetDirectChunkSignalText(match);
        if (string.IsNullOrWhiteSpace(directSignal))
            return false;

        var normalizedRouteTitle = NormalizeNavigationRouteEvidenceTitle(routeTitle);
        if (string.IsNullOrWhiteSpace(normalizedRouteTitle))
            return false;

        var normalizedDirect = NormalizeForLexicalSignal(directSignal);
        if (string.IsNullOrWhiteSpace(normalizedDirect))
            return false;

        if (normalizedRouteTitle.Length >= 4
            && normalizedDirect.Contains(normalizedRouteTitle, StringComparison.Ordinal))
        {
            return true;
        }

        var titleTokens = normalizedRouteTitle
            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Where(static token => token.Length >= 3 || token.Any(char.IsDigit))
            .Where(static token => !TitleConnectorTokens.Contains(token))
            .Where(static token => !LexicalStopwords.Contains(token))
            .Where(static token => !SpecificAnchorStopwords.Contains(token))
            .Where(static token => !PrimaryAnchorStopwords.Contains(token))
            .Distinct(StringComparer.Ordinal)
            .Take(8)
            .ToArray();

        if (titleTokens.Length == 1)
            return ContainsExactNormalizedToken(normalizedDirect, titleTokens[0]);

        if (titleTokens.Length >= 2
            && ContainsOrderedTitleTokenSubstringsInNormalizedText(normalizedDirect, titleTokens, maxGapChars: 12))
        {
            return true;
        }

        return titleTokens.Length >= 2
            && ContainsTitleLikeLexicalSequence(normalizedDirect, titleTokens);
    }

    private static bool IsNavigationRouteMatch(RagMatch match)
        => string.Equals(ResolveRetriever(match), "navigation_route", StringComparison.Ordinal)
           || string.Equals(match.EmbeddingBasis, "navigation_route_v1", StringComparison.Ordinal);

    private static bool IsDirectTitleTokenRouteMatch(RagMatch match)
        => string.Equals(ResolveRetriever(match), "direct_title_token_route", StringComparison.Ordinal)
           || string.Equals(match.EmbeddingBasis, "direct_title_token_route_v1", StringComparison.Ordinal);

    private static bool IsExplicitDocumentTitleRouteMatch(RagMatch match)
        => string.Equals(ResolveRetriever(match), "explicit_document_title_route", StringComparison.Ordinal)
           || string.Equals(match.EmbeddingBasis, "explicit_document_title_route_v1", StringComparison.Ordinal);

    internal static int ResolveDirectTitleTokenRouteMinimumOverlap(int queryTokenCount)
    {
        if (queryTokenCount <= 0)
            return 1;

        return queryTokenCount switch
        {
            <= 2 => queryTokenCount,
            <= 4 => 3,
            _ => Math.Max(3, (int)Math.Ceiling(queryTokenCount * 0.60))
        };
    }

    private static string NormalizeNavigationRouteEvidenceTitle(string title)
    {
        var tokens = NormalizeForLexicalSignal(title)
            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .ToList();

        while (tokens.Count > 1
               && (tokens[0].Length == 1
                   || tokens[0].All(char.IsDigit)
                   || IsFocusedLookupLeadingEdgeToken(tokens[0])))
        {
            tokens.RemoveAt(0);
        }

        return string.Join(' ', tokens);
    }

    internal static bool ContainsSpecificLexicalAnchor(IReadOnlyList<string> lexicalTokens, string? candidateText)
        => CountSpecificLexicalAnchors(lexicalTokens, candidateText) > 0;

    internal static bool RequiresPrimarySpecificLexicalAnchor(IReadOnlyList<string> lexicalTokens)
        => lexicalTokens.Any(IsPrimarySpecificLexicalAnchorToken);

    internal static bool ContainsPrimarySpecificLexicalAnchor(IReadOnlyList<string> lexicalTokens, string? candidateText)
    {
        if (lexicalTokens.Count == 0 || string.IsNullOrWhiteSpace(candidateText))
            return false;

        return ContainsPrimarySpecificLexicalAnchorInNormalizedText(
            lexicalTokens,
            NormalizeForLexicalSignal(candidateText));
    }

    private static bool ContainsPrimarySpecificLexicalAnchorInNormalizedText(IReadOnlyList<string> lexicalTokens, string normalizedCandidate)
    {
        if (lexicalTokens.Count == 0 || string.IsNullOrWhiteSpace(normalizedCandidate))
            return false;

        var primaryTokens = lexicalTokens
            .Where(IsPrimarySpecificLexicalAnchorToken)
            .OrderByDescending(static token => token.Length)
            .ThenBy(static token => token, StringComparer.Ordinal)
            .Take(2)
            .ToArray();
        if (primaryTokens.Length == 0)
            return true;

        foreach (var token in primaryTokens)
        {
            if (token.Any(char.IsDigit)
                && ContainsExactNormalizedToken(normalizedCandidate, token))
            {
                return true;
            }

            foreach (var variant in BuildLexicalTokenVariants(token))
            {
                var foldedVariant = FoldDiacritics(variant);
                if (foldedVariant.Length >= 5 && ContainsExactNormalizedToken(normalizedCandidate, foldedVariant))
                    return true;
                if (foldedVariant.Length >= 6 && normalizedCandidate.Contains(foldedVariant, StringComparison.Ordinal))
                    return true;
                if (foldedVariant.Length >= 6 && ContainsNearNormalizedToken(normalizedCandidate, foldedVariant))
                    return true;
            }
        }

        return false;
    }

    internal static IReadOnlyList<string> ExtractComparativeSubjectAnchorTokens(string query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return Array.Empty<string>();

        var normalized = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query));
        if (string.IsNullOrWhiteSpace(normalized))
            return Array.Empty<string>();

        var tokens = normalized
            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        if (tokens.Length < 3)
            return Array.Empty<string>();

        var markerIndex = Array.FindIndex(tokens, IsComparativeCriterionMarker);
        if (markerIndex <= 0)
            return Array.Empty<string>();

        var start = Math.Max(0, markerIndex - 5);
        return tokens
            .Skip(start)
            .Take(markerIndex - start)
            .Where(IsComparativeSubjectAnchorToken)
            .TakeLast(2)
            .Distinct(StringComparer.Ordinal)
            .ToArray();
    }

    internal static bool ContainsComparativeSubjectAnchor(IReadOnlyList<string> subjectTokens, string? candidateText)
    {
        if (subjectTokens.Count == 0)
            return true;
        if (string.IsNullOrWhiteSpace(candidateText))
            return false;

        return ContainsComparativeSubjectAnchorInNormalizedText(subjectTokens, NormalizeForLexicalSignal(candidateText));
    }

    private static bool ContainsComparativeSubjectAnchorInNormalizedText(IReadOnlyList<string> subjectTokens, string normalizedCandidate)
    {
        if (subjectTokens.Count == 0)
            return true;
        if (string.IsNullOrWhiteSpace(normalizedCandidate))
            return false;

        foreach (var token in subjectTokens)
        {
            var variants = BuildLexicalTokenVariants(token)
                .DefaultIfEmpty(token)
                .Distinct(StringComparer.Ordinal);
            if (variants.Any(variant => normalizedCandidate.Contains(FoldDiacritics(variant), StringComparison.Ordinal)))
                return true;
        }

        return false;
    }

    private static bool IsComparativeCriterionMarker(string token)
        => token is "plus" or "most" or "mas" or "mais" or "mehr";

    private static bool IsComparativeSubjectAnchorToken(string token)
        => token.Length >= 3
           && token.Any(char.IsLetter)
           && !LexicalStopwords.Contains(token)
           && !ComparativeSubjectStopwords.Contains(token);

    private static bool IsPrimarySpecificLexicalAnchorToken(string token)
        => !SpecificAnchorStopwords.Contains(token)
            && !PrimaryAnchorStopwords.Contains(token)
            && (token.Length >= 6 || token.Any(char.IsDigit) || IsReferenceLikeLookupTerm(token));

    internal static double ComputeExactTitleCandidateScore(string query, RagMatch match)
    {
        if (string.IsNullOrWhiteSpace(query))
            return 0.0;
        var quotedPhrases = ExtractQuotedLookupPhrases(query);
        if (quotedPhrases.Count == 0 && ContainsExactTitleActionMarker(query))
            return 0.0;
        if (quotedPhrases.Count > 0
            && string.Equals(ResolveRetriever(match), "exact_match", StringComparison.Ordinal)
            && !HasQuotedTitlePlacementEvidence(quotedPhrases, match))
        {
            return 0.0;
        }

        var titleTokens = ExtractTitleScoringTokens(query);
        if (titleTokens.Count < 2 || titleTokens.Count > 8)
            return 0.0;

        var candidateText = GetTitleSignalText(match);
        if (string.IsNullOrWhiteSpace(candidateText))
            return 0.0;

        var phraseTerms = BuildLexicalContentFallbackTerms(query)
            .Where(static term => term.Contains(' '))
            .Take(16)
            .ToArray();
        return ComputeExactTitleCandidateScoreCore(
            match,
            NormalizeForLexicalSignal(candidateText),
            NormalizeForLexicalSignal(match.Text),
            titleTokens,
            phraseTerms,
            NormalizeForLexicalSignal(query));
    }

    internal static double ComputeQuotedTitleAnchorSignal(string query, RagMatch match)
    {
        var quotedPhrases = ExtractTitleLookupPhrases(query);
        if (quotedPhrases.Count == 0)
            return 0.0;

        var titleAnchorText = BuildTitleAnchorSignalText(match);
        return string.IsNullOrWhiteSpace(titleAnchorText)
            ? 0.0
            : ComputeQuotedLookupCandidateScore(quotedPhrases, titleAnchorText);
    }

    private static string BuildTitleAnchorSignalText(RagMatch match)
    {
        var parts = new List<string?>(capacity: 6)
        {
            match.SectionTitle,
            match.HeadingPath
        };

        if (match.MatchedContentCards is { Count: > 0 })
        {
            parts.AddRange(match.MatchedContentCards
                .Take(MaxCalibrationCardCount)
                .Select(static card => card.Title));
        }

        if (IsResolvedTitleOrNavigationRoute(match) || IsDocumentProfileMatch(match) || HasProfileTitleHint(match))
            parts.Add(match.EmbedText);

        return string.Join("\n", parts.Where(static value => !string.IsNullOrWhiteSpace(value)));
    }

    private static double ComputeExactTitleCandidateScoreCore(
        RagMatch match,
        string normalizedCandidate,
        string normalizedChunkText,
        IReadOnlyList<string> titleTokens,
        IReadOnlyList<string> phraseTerms,
        string normalizedQuery)
    {
        if (titleTokens.Count < 2 || titleTokens.Count > 8)
            return 0.0;
        if (string.IsNullOrWhiteSpace(normalizedCandidate))
            return 0.0;

        var score = ContainsOrderedTitleTokenSubstringsInNormalizedText(normalizedCandidate, titleTokens, maxGapChars: 80)
            ? 16.0 + Math.Min(4.0, titleTokens.Count)
            : 0.0;
        if (normalizedQuery.Length >= 8
            && normalizedQuery.Count(static ch => ch == ' ') >= 1
            && normalizedCandidate.Contains(normalizedQuery, StringComparison.Ordinal))
        {
            score += 18.0;
        }

        if (normalizedQuery.Length >= 8
            && normalizedQuery.Count(static ch => ch == ' ') >= 1
            && normalizedChunkText.Contains(normalizedQuery, StringComparison.Ordinal))
        {
            score += 14.0;
        }

        var orderedPhraseMatch = phraseTerms.Any(term => ContainsOrderedPhraseWindowInNormalizedText(normalizedCandidate, term, maxGapChars: 40));
        if (orderedPhraseMatch)
            score += 10.0;

        if (ContainsOrderedTitleTokenSubstringsInNormalizedText(normalizedCandidate, titleTokens, maxGapChars: 60))
            score += 14.0;

        if (ContainsTitleLikeLexicalSequence(normalizedCandidate, titleTokens))
            score += 12.0;

        if (ContainsTitleLikeLexicalSequence(normalizedChunkText, titleTokens))
            score += 10.0;

        if (score <= 0.0)
            return 0.0;

        if (normalizedCandidate.StartsWith(normalizedQuery, StringComparison.Ordinal)
            || normalizedCandidate.StartsWith("matched profile title " + normalizedQuery, StringComparison.Ordinal))
        {
            score += 4.0;
        }

        if (string.Equals(match.ChunkType, "footer_titled_item_window_v1", StringComparison.Ordinal))
            score += 10.0;
        else if (string.Equals(match.ChunkType, "unit_exact_v1", StringComparison.Ordinal))
            score += 8.0;
        else if (string.Equals(match.ChunkType, "section_window_v1", StringComparison.Ordinal))
            score += 1.0;
        else if (string.Equals(match.ChunkType, "document_profile", StringComparison.Ordinal))
            score += 1.0;

        return score;
    }

    private static int ComputeDirectChunkTitleSignal(string query, RagMatch match)
    {
        if (string.IsNullOrWhiteSpace(query) || string.IsNullOrWhiteSpace(match.Text))
            return 0;

        var quotedPhrases = ExtractTitleLookupPhrases(query);
        if (quotedPhrases.Count > 0)
            return HasQuotedTitlePlacementEvidence(quotedPhrases, match) ? 4 : 0;

        var titleTokens = ExtractTitleScoringTokens(query);
        if (titleTokens.Count < 2 || titleTokens.Count > 8)
            return 0;

        return ComputeDirectChunkTitleSignalCore(
            NormalizeForLexicalSignal(match.Text),
            titleTokens,
            NormalizeForLexicalSignal(query));
    }

    private static int ComputeDirectChunkTitleSignalCore(
        string normalizedChunkText,
        IReadOnlyList<string> titleTokens,
        string normalizedQuery)
    {
        if (titleTokens.Count < 2 || titleTokens.Count > 8 || string.IsNullOrWhiteSpace(normalizedChunkText))
            return 0;

        if (normalizedQuery.Length >= 8
            && normalizedQuery.Count(static ch => ch == ' ') >= 1
            && normalizedChunkText.Contains(normalizedQuery, StringComparison.Ordinal))
        {
            return 3;
        }

        if (ContainsOrderedTitleTokenSubstringsInNormalizedText(normalizedChunkText, titleTokens, maxGapChars: 60))
            return 2;

        return ContainsTitleLikeLexicalSequence(normalizedChunkText, titleTokens) ? 1 : 0;
    }

    private static int ComputeMatchedContentCardTitleSignal(
        RagMatch match,
        IReadOnlyList<string> titleTokens,
        string normalizedQuery)
    {
        if (titleTokens.Count < 2 || titleTokens.Count > 8)
            return 0;
        if (match.MatchedContentCards is not { Count: > 0 })
            return 0;

        var best = 0;
        foreach (var card in match.MatchedContentCards.Take(MaxCalibrationCardCount))
        {
            if (string.IsNullOrWhiteSpace(card.Title) || !LooksLikeConcreteMatchedContentCardTitle(card.Title))
                continue;

            var normalizedCard = NormalizeForLexicalSignal(card.Title);
            if (string.IsNullOrWhiteSpace(normalizedCard))
                continue;

            if (normalizedQuery.Length >= 8
                && normalizedQuery.Count(static ch => ch == ' ') >= 1
                && normalizedCard.Contains(normalizedQuery, StringComparison.Ordinal))
                best = Math.Max(best, 4);
            else if (ContainsOrderedTitleTokenSubstringsInNormalizedText(normalizedCard, titleTokens, maxGapChars: 40))
                best = Math.Max(best, 3);
            else if (ContainsTitleLikeLexicalSequence(normalizedCard, titleTokens))
                best = Math.Max(best, 2);
            else if (ComputeLexicalCoverageInNormalizedText(titleTokens, normalizedCard) >= 0.80)
                best = Math.Max(best, 1);

            if (best >= 4)
                break;
        }

        return best;
    }

    private static bool ContainsTitleLikeLexicalSequence(string normalizedCandidate, IReadOnlyList<string> titleTokens)
    {
        if (string.IsNullOrWhiteSpace(normalizedCandidate) || titleTokens.Count < 2)
            return false;

        var candidateTokens = normalizedCandidate
            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Where(static token => token.Length > 0)
            .Take(1500)
            .ToArray();
        if (candidateTokens.Length < titleTokens.Count)
            return false;

        var tokenVariants = titleTokens
            .Select(token => BuildLexicalTokenVariants(token)
                .Select(FoldDiacritics)
                .Where(IsTitleScoringTokenVariant)
                .DefaultIfEmpty(FoldDiacritics(token))
                .ToHashSet(StringComparer.Ordinal))
            .ToArray();

        for (var start = 0; start < candidateTokens.Length; start++)
        {
            if (!TokenMatchesTitleVariant(candidateTokens[start], tokenVariants[0]))
                continue;

            var current = start;
            var matchedAll = true;
            for (var expected = 1; expected < tokenVariants.Length; expected++)
            {
                var next = FindNextTitleToken(candidateTokens, current + 1, tokenVariants[expected]);
                if (next < 0)
                {
                    matchedAll = false;
                    break;
                }

                for (var i = current + 1; i < next; i++)
                {
                    if (!TitleConnectorTokens.Contains(candidateTokens[i]))
                    {
                        matchedAll = false;
                        break;
                    }
                }

                if (!matchedAll)
                    break;

                current = next;
            }

            if (matchedAll)
                return true;
        }

        return false;
    }

    private static int FindNextTitleToken(IReadOnlyList<string> candidateTokens, int startIndex, IReadOnlySet<string> expectedVariants)
    {
        var maxExclusive = Math.Min(candidateTokens.Count, startIndex + 6);
        for (var i = startIndex; i < maxExclusive; i++)
        {
            if (TokenMatchesTitleVariant(candidateTokens[i], expectedVariants))
                return i;
            if (!TitleConnectorTokens.Contains(candidateTokens[i]))
                break;
        }

        return -1;
    }

    private static bool TokenMatchesTitleVariant(string candidateToken, IReadOnlySet<string> expectedVariants)
    {
        if (expectedVariants.Contains(candidateToken))
            return true;

        foreach (var variant in expectedVariants)
        {
            if (variant.Length < 4
                || candidateToken.Length <= variant.Length
                || !candidateToken.StartsWith(variant, StringComparison.Ordinal))
            {
                continue;
            }

            var suffix = candidateToken[variant.Length..];
            if (TitleConnectorTokens.Contains(suffix)
                || suffix.All(char.IsDigit)
                || (suffix.Length <= 2 && suffix.All(char.IsLetter)))
            {
                return true;
            }
        }

        return false;
    }

    private static bool ContainsOrderedTitleTokenSubstrings(string candidateText, IReadOnlyList<string> titleTokens, int maxGapChars)
    {
        if (string.IsNullOrWhiteSpace(candidateText) || titleTokens.Count < 2)
            return false;

        return ContainsOrderedTitleTokenSubstringsInNormalizedText(
            FoldDiacritics(candidateText).ToLowerInvariant(),
            titleTokens,
            maxGapChars);
    }

    private static bool ContainsOrderedTitleTokenSubstringsInNormalizedText(
        string normalizedCandidate,
        IReadOnlyList<string> titleTokens,
        int maxGapChars)
    {
        if (string.IsNullOrWhiteSpace(normalizedCandidate) || titleTokens.Count < 2)
            return false;

        var variantGroups = titleTokens
            .Select(token => BuildLexicalTokenVariants(token)
                .Select(FoldDiacritics)
                .Append(FoldDiacritics(token))
                .Where(static variant => variant.Length >= 4)
                .Distinct(StringComparer.Ordinal)
                .ToArray())
            .ToArray();
        if (variantGroups.Any(static group => group.Length == 0))
            return false;

        return TryFindOrderedTitleTokenSubstrings(
            normalizedCandidate,
            variantGroups,
            tokenIndex: 0,
            searchFrom: 0,
            previousEnd: -1,
            maxGapChars);
    }

    private static bool TryFindOrderedTitleTokenSubstrings(
        string normalizedCandidate,
        IReadOnlyList<string[]> variantGroups,
        int tokenIndex,
        int searchFrom,
        int previousEnd,
        int maxGapChars)
    {
        if (tokenIndex >= variantGroups.Count)
            return true;

        var attempts = 0;
        foreach (var occurrence in EnumerateTitleTokenOccurrences(normalizedCandidate, variantGroups[tokenIndex], searchFrom))
        {
            if (previousEnd >= 0 && occurrence.Index - previousEnd > maxGapChars)
                break;

            if (TryFindOrderedTitleTokenSubstrings(
                normalizedCandidate,
                variantGroups,
                tokenIndex + 1,
                occurrence.Index + occurrence.Length,
                occurrence.Index + occurrence.Length,
                maxGapChars))
            {
                return true;
            }

            attempts++;
            if (attempts >= 48)
                break;
        }

        return false;
    }

    private static IEnumerable<(int Index, int Length)> EnumerateTitleTokenOccurrences(
        string normalizedCandidate,
        IReadOnlyList<string> variants,
        int searchFrom)
    {
        var seen = new HashSet<int>();
        while (searchFrom < normalizedCandidate.Length)
        {
            var bestIndex = -1;
            var bestLength = 0;
            foreach (var variant in variants)
            {
                var index = normalizedCandidate.IndexOf(variant, searchFrom, StringComparison.Ordinal);
                if (index < 0)
                    continue;
                if (bestIndex < 0 || index < bestIndex || (index == bestIndex && variant.Length > bestLength))
                {
                    bestIndex = index;
                    bestLength = variant.Length;
                }
            }

            if (bestIndex < 0)
                yield break;

            if (seen.Add(bestIndex))
                yield return (bestIndex, bestLength);

            searchFrom = bestIndex + 1;
        }
    }

    private static double ComputeRawOrderedTitleScore(string query, string candidateText)
    {
        if (string.IsNullOrWhiteSpace(query) || string.IsNullOrWhiteSpace(candidateText))
            return 0.0;

        var queryTokens = System.Text.RegularExpressions.Regex
            .Split(FoldDiacritics(query).ToLowerInvariant(), @"[^\p{L}\p{Nd}]+")
            .Select(static token => ExactMatchEntryExtractor.NormalizeForLookup(token))
            .Where(static token => token.Length >= 4)
            .Where(static token => token.Any(char.IsLetter))
            .Where(static token => !LexicalStopwords.Contains(token))
            .Where(static token => !PrimaryAnchorStopwords.Contains(token))
            .Distinct(StringComparer.Ordinal)
            .Take(8)
            .ToArray();
        if (queryTokens.Length < 2)
            return 0.0;

        return ContainsOrderedTitleTokenSubstrings(candidateText, queryTokens, maxGapChars: 80)
            ? 16.0 + Math.Min(4.0, queryTokens.Length)
            : 0.0;
    }

    private static bool ContainsExactTitleActionMarker(string query)
    {
        var normalized = $" {FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query))} ";
        return ContainsAny(
            normalized,
            " explique ",
            " expliquer ",
            " expliquez ",
            " explain ",
            " explains ",
            " summarize ",
            " summary ",
            " resume ",
            " resumer ",
            " resumee ",
            " decris ",
            " decrire ",
            " describe ",
            " detaille ",
            " detailler ",
            " pourquoi ",
            " why ",
            " comment ",
            " how ");
    }

    private static bool ContainsSummarizationIntent(string query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return false;

        var normalized = $" {FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query))} ";
        return ContainsAny(
            normalized,
            " resume ",
            " resumer ",
            " resumes ",
            " summary ",
            " summarize ",
            " summarizes ",
            " summarise ",
            " summarises ",
            " synthese ",
            " synthesis ");
    }

    private static bool ShouldApplySpecificCoverageTitlePriority(
        string query,
        IReadOnlyList<string> lexicalTokens,
        IReadOnlyList<string> comparativeSubjectTokens)
    {
        if (lexicalTokens.Count is < 2 or > 6)
            return false;
        if (comparativeSubjectTokens.Count > 0)
            return false;
        if (ExtractQuotedLookupPhrases(query).Count == 0 && ContainsExactTitleActionMarker(query))
            return false;

        var normalized = $" {FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query))} ";
        if (IsRecommendationSelectionQuery(normalized))
            return false;

        return !ContainsAny(
            normalized,
            " compare ",
            " comparer ",
            " comparison ",
            " comparaison ",
            " difference ",
            " differences ",
            " differents ",
            " differentes ");
    }

    private static bool ShouldPrioritizeFocusedSpecificContentCoverage(
        string query,
        IReadOnlyList<string> lexicalTokens)
    {
        if (lexicalTokens.Count is < 3 or > 8)
            return false;

        var normalized = $" {FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query)).ToLowerInvariant()} ";
        if (IsRecommendationSelectionQuery(normalized)
            || ContainsAny(
                normalized,
                " lequel ",
                " laquelle ",
                " lesquels ",
                " lesquelles ",
                " which one ",
                " what one ",
                " compare ",
                " comparer ",
                " comparison ",
                " comparaison ",
                " difference ",
                " differences "))
        {
            return false;
        }

        return ExtractFocusedLookupPhrases(query).Count > 0
            || ContainsExactTitleActionMarker(query)
            || ShouldTreatFocusedLookupAsPreciseTitle(query);
    }

    private static int ResolveRequiredFocusedSpecificContentCoverage(IReadOnlyList<string> lexicalTokens)
    {
        if (lexicalTokens.Count == 0)
            return 1;

        var meaningfulSpecificTokenCount = lexicalTokens
            .Where(static token => !SpecificAnchorStopwords.Contains(token))
            .Where(static token => !PrimaryAnchorStopwords.Contains(token))
            .Where(static token => token.Length >= 5 || token.Any(char.IsDigit))
            .Distinct(StringComparer.Ordinal)
            .Count();

        return meaningfulSpecificTokenCount == 0
            ? 1
            : Math.Min(2, meaningfulSpecificTokenCount);
    }

    private static bool IsRecommendationSelectionQuery(string normalizedPaddedQuery)
        => ContainsAny(
                normalizedPaddedQuery,
                " quel ",
                " quelle ",
                " quelles ",
                " quels ",
                " which ",
                " what ",
                " cual ",
                " qual ",
                " quale ",
                " welche ")
            && ContainsAny(
                normalizedPaddedQuery,
                " choisir ",
                " choose ",
                " recommander ",
                " recommande ",
                " recommandes ",
                " recommendation ",
                " recommendations ",
                " adaptee ",
                " adaptees ",
                " adapte ",
                " adaptes ",
                " suitable ",
                " best ",
                " meilleur ",
                " meilleure ",
                " meilleurs ",
                " meilleures ");

    internal static int CountSpecificLexicalAnchors(IReadOnlyList<string> lexicalTokens, string? candidateText)
    {
        if (lexicalTokens.Count == 0 || string.IsNullOrWhiteSpace(candidateText))
            return 0;

        return CountSpecificLexicalAnchorsInNormalizedText(lexicalTokens, NormalizeForLexicalSignal(candidateText));
    }

    private static int CountSpecificLexicalAnchorsInNormalizedText(IReadOnlyList<string> lexicalTokens, string normalized)
    {
        if (lexicalTokens.Count == 0 || string.IsNullOrWhiteSpace(normalized))
            return 0;

        var matched = 0;
        var seen = new HashSet<string>(StringComparer.Ordinal);
        foreach (var token in lexicalTokens)
        {
            if (SpecificAnchorStopwords.Contains(token))
                continue;
            if (token.Any(char.IsDigit)
                && ContainsExactNormalizedToken(normalized, token))
            {
                if (seen.Add(token))
                    matched++;
                continue;
            }

            if (token.Length < 5 && !token.Any(char.IsDigit))
                continue;

            foreach (var variant in BuildLexicalTokenVariants(token))
            {
                var foldedVariant = FoldDiacritics(variant);
                if ((foldedVariant.Length >= 5 && ContainsExactNormalizedToken(normalized, foldedVariant))
                    || (foldedVariant.Length >= 6
                    && (normalized.Contains(foldedVariant, StringComparison.Ordinal)
                        || ContainsNearNormalizedToken(normalized, foldedVariant)))
                   )
                {
                    if (seen.Add(token))
                        matched++;
                    break;
                }
            }
        }

        return matched;
    }

    private static bool ContainsNearNormalizedToken(string normalizedCandidate, string token)
    {
        if (string.IsNullOrWhiteSpace(normalizedCandidate) || string.IsNullOrWhiteSpace(token) || token.Length < 6)
            return false;

        foreach (var candidate in normalizedCandidate.Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            if (candidate.Length < 6 || Math.Abs(candidate.Length - token.Length) > 1)
                continue;
            if (ComputeBoundedEditDistance(candidate, token, maxDistance: 1) <= 1)
                return true;
        }

        return false;
    }

    private static int ComputeBoundedEditDistance(string left, string right, int maxDistance)
    {
        if (Math.Abs(left.Length - right.Length) > maxDistance)
            return maxDistance + 1;

        var previous = new int[right.Length + 1];
        var current = new int[right.Length + 1];
        for (var j = 0; j <= right.Length; j++)
            previous[j] = j;

        for (var i = 1; i <= left.Length; i++)
        {
            current[0] = i;
            var rowMin = current[0];
            for (var j = 1; j <= right.Length; j++)
            {
                var cost = left[i - 1] == right[j - 1] ? 0 : 1;
                current[j] = Math.Min(
                    Math.Min(current[j - 1] + 1, previous[j] + 1),
                    previous[j - 1] + cost);
                rowMin = Math.Min(rowMin, current[j]);
            }

            if (rowMin > maxDistance)
                return maxDistance + 1;

            (previous, current) = (current, previous);
        }

        return previous[right.Length];
    }

    private static bool ContainsExactNormalizedToken(string normalizedCandidate, string token)
    {
        if (string.IsNullOrWhiteSpace(normalizedCandidate) || string.IsNullOrWhiteSpace(token))
            return false;

        return normalizedCandidate
            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Contains(token, StringComparer.Ordinal);
    }

    internal static bool LooksLikeStructuredAnswerUnit(RagMatch match)
    {
        if (!string.Equals(match.ChunkType, "unit_exact_v1", StringComparison.Ordinal)
            && !string.Equals(match.ChunkType, "footer_titled_item_window_v1", StringComparison.Ordinal))
            return false;

        return LooksLikeStructuredAnswerText(match.Text);
    }

    internal static bool LooksLikeStructuredAnswerChunk(RagMatch match)
    {
        if (!string.Equals(match.ChunkType, "unit_exact_v1", StringComparison.Ordinal)
            && !string.Equals(match.ChunkType, "footer_titled_item_window_v1", StringComparison.Ordinal)
            && !string.Equals(match.ChunkType, "section_window_v1", StringComparison.Ordinal))
            return false;

        return LooksLikeStructuredAnswerText(match.Text);
    }

    private static int GetStructuredAnswerPriority(RagMatch match)
    {
        if (LooksLikeStructuredAnswerUnit(match))
            return 3;
        if (LooksLikeStructuredAnswerChunk(match))
            return 2;
        if (string.Equals(match.ChunkType, "document_profile", StringComparison.Ordinal))
            return 1;
        return 0;
    }

    internal static double ComputeContentEvidencePriority(RagMatch match)
    {
        var priority = GetStructuredAnswerPriority(match) * 0.35;

        if (match.ContentDensityScore is double density)
            priority += Math.Clamp(density, 0.0, 1.0);

        if (string.Equals(match.ContentRole, RetrievalContentClassifier.ContentRole, StringComparison.OrdinalIgnoreCase))
            priority += 0.25;
        else if (string.Equals(match.ContentRole, RetrievalContentClassifier.MixedNavigationContentRole, StringComparison.OrdinalIgnoreCase))
            priority += 0.10;
        else if (string.Equals(match.ContentRole, RetrievalContentClassifier.NavigationRole, StringComparison.OrdinalIgnoreCase))
            priority -= 0.25;

        var looksNavigational = LooksLikeNavigationalChunk(match);
        var shouldConserveCardBoost = looksNavigational
            || string.Equals(match.ContentRole, RetrievalContentClassifier.MixedNavigationContentRole, StringComparison.OrdinalIgnoreCase)
            || match.NavigationScore is >= 0.55;
        if (match.MatchedContentCards is { Count: > 0 })
        {
            var hasStrongCardSupport = match.MatchedContentCards.Any(HasStrongMatchedContentCardSupport);
            priority += shouldConserveCardBoost
                ? hasStrongCardSupport ? 0.06 : 0.0
                : hasStrongCardSupport ? 0.12 : 0.04;
        }

        if (looksNavigational)
            priority -= 0.45;
        if (LooksLikeSourceListChunk(match) || LooksLikeGlossaryChunk(match))
            priority -= 0.25;

        return Math.Clamp(priority, -1.0, 3.0);
    }

    private static bool HasStrongMatchedContentCardSupport(RagMatchedContentCard card)
    {
        if (card.Signals is null || card.Signals.Count == 0)
            return false;

        return card.Signals.Any(static signal =>
            string.Equals(signal, "structured_facts", StringComparison.OrdinalIgnoreCase)
            || string.Equals(signal, "quantity_list", StringComparison.OrdinalIgnoreCase)
            || string.Equals(signal, "scale_basis", StringComparison.OrdinalIgnoreCase)
            || string.Equals(signal, "scalable_quantities", StringComparison.OrdinalIgnoreCase));
    }

    private static int ComputeWeakMatchedContentCardTitlePenalty(
        RagMatch match,
        bool fullTitleCoverage,
        double exactTitleScore,
        int directChunkTitleSignal,
        double quotedTitleAnchorSignal,
        bool allowIndependentTitleSignalWaiver)
    {
        if (allowIndependentTitleSignalWaiver
            && (fullTitleCoverage
            || exactTitleScore > 0.0
            || directChunkTitleSignal > 0
            || quotedTitleAnchorSignal > 0.0))
        {
            return 0;
        }

        if (match.MatchedContentCards is not { Count: > 0 })
            return 0;

        var inspected = 0;
        foreach (var card in match.MatchedContentCards.Take(MaxCalibrationCardCount))
        {
            if (string.IsNullOrWhiteSpace(card.Title))
                continue;

            inspected++;
            if (LooksLikeConcreteMatchedContentCardTitle(card.Title))
                return 0;
        }

        return inspected > 0 ? 1 : 0;
    }

    private static bool LooksLikeConcreteMatchedContentCardTitle(string title)
    {
        if (LooksLikeProceduralFragmentContentCardTitle(title)
            || LooksLikeGenericContentSectionCardTitle(title)
            || LooksLikeTruncatedContentCardTitle(title)
            || LooksLikeQuantityOrOcrFragmentContentCardTitle(title))
        {
            return false;
        }

        var titleTokens = ExtractLexicalQueryTokens(title);
        return titleTokens.Count >= 2
               || (titleTokens.Count == 1 && IsReferenceLikeLookupTerm(titleTokens[0]));
    }

    private static int ComputeUnrequestedQualifiedTitlePenalty(
        IReadOnlyList<string> subjectTokens,
        IReadOnlyList<string> queryTokens,
        RagMatch match)
    {
        if (subjectTokens.Count is 0 or > 3)
            return 0;

        var titleCandidates = EnumerateCandidateTitleTexts(match, includeSyntheticRouteTitle: false)
            .Where(static title => !string.IsNullOrWhiteSpace(title))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .Take(MaxCalibrationCardCount + 3)
            .ToArray();
        if (titleCandidates.Length == 0)
            return 1;

        var bestPenalty = int.MaxValue;
        foreach (var title in titleCandidates)
        {
            var normalizedTitle = NormalizeForLexicalSignal(title);
            if (string.IsNullOrWhiteSpace(normalizedTitle)
                || !ContainsAllTitleSubjectTokens(subjectTokens, normalizedTitle))
            {
                continue;
            }

            var titleTokens = ExtractLexicalQueryTokens(title)
                .Where(static token => !TitleConnectorTokens.Contains(token))
                .Where(static token => !PrimaryAnchorStopwords.Contains(token))
                .Distinct(StringComparer.Ordinal)
                .ToArray();
            if (titleTokens.Length == 0)
                continue;

            var extraTokenCount = titleTokens.Count(token =>
                !TokenMatchesAnyQueryToken(token, queryTokens)
                && !TokenMatchesAnyQueryToken(token, subjectTokens));
            if (extraTokenCount == 0)
                return 0;

            bestPenalty = Math.Min(bestPenalty, Math.Min(3, extraTokenCount));
        }

        return bestPenalty == int.MaxValue ? 1 : bestPenalty;
    }

    private static IReadOnlyList<string> BuildUnrequestedQualifiedTitleSubjectTokens(
        string query,
        IReadOnlyList<string> fallbackTitleTokens)
    {
        foreach (var phrase in ExtractComparativeLookupPhrases(query))
        {
            var phraseTokens = ExtractTitleScoringTokens(phrase);
            if (phraseTokens.Count is >= 1 and <= 3)
                return phraseTokens;
        }

        return fallbackTitleTokens.Count is >= 1 and <= 3
            ? fallbackTitleTokens
            : Array.Empty<string>();
    }

    private static IEnumerable<string> EnumerateCandidateTitleTexts(
        RagMatch match,
        bool includeSyntheticRouteTitle = true)
    {
        if (includeSyntheticRouteTitle)
        {
            var routeTitle = ExtractMatchedRouteOrProfileTitle(match.EmbedText);
            if (!string.IsNullOrWhiteSpace(routeTitle))
                yield return routeTitle;
        }

        if (match.MatchedContentCards is { Count: > 0 })
        {
            foreach (var card in match.MatchedContentCards.Take(MaxCalibrationCardCount))
            {
                if (!string.IsNullOrWhiteSpace(card.Title))
                    yield return card.Title;
            }
        }

        if (!string.IsNullOrWhiteSpace(match.SectionTitle))
            yield return match.SectionTitle;
        if (!string.IsNullOrWhiteSpace(match.HeadingPath))
            yield return match.HeadingPath;
    }

    private static bool ContainsAllTitleSubjectTokens(
        IReadOnlyList<string> subjectTokens,
        string normalizedTitle)
    {
        foreach (var token in subjectTokens)
        {
            if (!TokenMatchesNormalizedText(token, normalizedTitle))
                return false;
        }

        return true;
    }

    private static bool TokenMatchesAnyQueryToken(string token, IReadOnlyList<string> queryTokens)
        => queryTokens.Any(queryToken =>
            string.Equals(queryToken, token, StringComparison.Ordinal)
            || BuildLexicalTokenVariants(queryToken)
                .DefaultIfEmpty(queryToken)
                .Any(variant => string.Equals(FoldDiacritics(variant), token, StringComparison.Ordinal))
            || BuildLexicalTokenVariants(token)
                .DefaultIfEmpty(token)
                .Any(variant => string.Equals(FoldDiacritics(variant), queryToken, StringComparison.Ordinal)));

    private static bool TokenMatchesNormalizedText(string token, string normalizedText)
        => BuildLexicalTokenVariants(token)
            .DefaultIfEmpty(token)
            .Select(FoldDiacritics)
            .Distinct(StringComparer.Ordinal)
            .Any(variant => variant.Length >= 3 && ContainsExactNormalizedToken(normalizedText, variant));

    private static bool LooksLikeStructuredAnswerText(string? value)
    {
        return StructuredContentLexicon.ContainsStructuredAnswerCue(value)
            || LooksLikeStructuredQuantityList(value);
    }

    internal static bool LooksLikeStructuredQuantityList(string? value)
        => StructuredContentLexicon.LooksLikeStructuredQuantityList(value);

    internal static bool LooksLikeSourceListChunk(RagMatch match)
    {
        var text = match.Text ?? string.Empty;
        if (string.IsNullOrWhiteSpace(text))
            return false;

        var lower = text.ToLowerInvariant();
        var urlCount = CountOccurrences(lower, "http://")
            + CountOccurrences(lower, "https://")
            + CountOccurrences(lower, "www.");
        if (urlCount >= 3)
            return true;

        var domainMarkers = CountOccurrences(lower, ".com")
            + CountOccurrences(lower, ".org")
            + CountOccurrences(lower, ".net")
            + CountOccurrences(lower, ".fr")
            + CountOccurrences(lower, ".ca")
            + CountOccurrences(lower, ".ch");

        return domainMarkers >= 5 && CountInlinePageNumberBoundaries(text) <= 2;
    }

    internal static bool LooksLikeDocumentOverviewChunk(RagMatch match)
    {
        var text = FoldDiacritics(match.Text ?? string.Empty).ToLowerInvariant();
        if (string.IsNullOrWhiteSpace(text))
            return false;

        var hasOverviewLanguage =
            text.Contains("ce livre", StringComparison.Ordinal)
            || text.Contains("ce guide", StringComparison.Ordinal)
            || text.Contains("ce document", StringComparison.Ordinal)
            || text.Contains("cet ouvrage", StringComparison.Ordinal)
            || text.Contains("this book", StringComparison.Ordinal)
            || text.Contains("this guide", StringComparison.Ordinal)
            || text.Contains("this document", StringComparison.Ordinal)
            || text.Contains("contains examples", StringComparison.Ordinal)
            || text.Contains("contient quelques exemples", StringComparison.Ordinal)
            || text.Contains("vous permettra", StringComparison.Ordinal)
            || text.Contains("permettra de", StringComparison.Ordinal)
            || text.Contains("introduction", StringComparison.Ordinal);

        if (!hasOverviewLanguage)
            return false;

        return !ContainsActionableDocumentProfileLanguage(text);
    }

    private static bool ContainsActionableDocumentProfileLanguage(string normalizedText)
        => ContainsAny(
            normalizedText,
            "procedure",
            "procedures",
            "materials",
            "material",
            "materiel",
            "materiaux",
            "materiales",
            "materiali",
            "materialien",
            "components",
            "component",
            "composants",
            "componentes",
            "componenti",
            "komponenten",
            "instructions",
            "instruction",
            "consignes",
            "instrucciones",
            "instrucoes",
            "istruzioni",
            "anweisungen",
            "steps",
            "step",
            "etapes",
            "pasos",
            "passos",
            "schritte",
            "tools",
            "outils",
            "herramientas",
            "ferramentas",
            "strumenti",
            "werkzeug",
            "equipment",
            "equipement",
            "equipamentos",
            "attrezzatura",
            "ausrustung");

    internal static bool LooksLikeNavigationalChunk(RagMatch match)
    {
        if (IsDocumentProfileMatch(match))
            return false;

        if (string.Equals(match.ContentRole, RetrievalContentClassifier.NavigationRole, StringComparison.OrdinalIgnoreCase))
            return true;

        var text = match.Text ?? string.Empty;
        var hasMeasuredSequentialContent = RetrievalContentClassifier.LooksLikeMeasuredSequentialContent(text);

        if (match.NavigationScore is >= 0.72
            && (match.ContentDensityScore is null or < 0.50)
            && !hasMeasuredSequentialContent)
            return true;

        if (RetrievalContentClassifier.IsNavigationChunkType(match.ChunkType))
            return true;

        var context = $"{match.SectionTitle} {match.HeadingPath} {text}";
        var folded = FoldDiacritics(context).ToLowerInvariant();
        var foldedText = FoldDiacritics(text).ToLowerInvariant();
        var padded = $" {NormalizeQuery(folded)} ";
        var hasStrongIndexMarker = HasStrongNavigationalMarker(folded, padded);
        var hasExplicitTocMarker = ContainsExplicitTableOfContentsMarker(folded, padded);
        var hasShortTocMarker = ContainsShortTableOfContentsMarker(padded)
            && (CountInlinePageNumberBoundaries(text) >= 3 || CountBulletMarkers(text) >= 8 || LooksLikeTitleListChunk(text));
        var hasStructuredProcedureBody = (foldedText.Contains("materials", StringComparison.Ordinal)
                || foldedText.Contains("materiaux", StringComparison.Ordinal)
                || foldedText.Contains("components", StringComparison.Ordinal)
                || foldedText.Contains("composants", StringComparison.Ordinal))
            && (foldedText.Contains("method", StringComparison.Ordinal)
                || foldedText.Contains("procedure", StringComparison.Ordinal)
                || foldedText.Contains("instructions", StringComparison.Ordinal)
                || foldedText.Contains("steps", StringComparison.Ordinal));
        if (hasStructuredProcedureBody && !hasStrongIndexMarker && !hasExplicitTocMarker && !hasShortTocMarker)
            return false;

        if (hasExplicitTocMarker
            || hasShortTocMarker
            || hasStrongIndexMarker
            || folded.Contains("fiche-index", StringComparison.Ordinal)
            || folded.Contains("fiche index", StringComparison.Ordinal)
            || padded.Contains(" index ", StringComparison.Ordinal))
        {
            if (!hasStrongIndexMarker
                && padded.Contains(" index ", StringComparison.Ordinal)
                && CountBulletMarkers(text) < 8
                && CountInlinePageNumberBoundaries(text) < 5
                && !LooksLikeTitleListChunk(text))
                return false;

            return true;
        }

        if (CountInlinePageNumberBoundaries(text) >= 5 && !hasMeasuredSequentialContent)
            return true;

        return LooksLikeTitleListChunk(text);
    }

    internal static bool LooksLikeGlossaryChunk(RagMatch match)
    {
        if (IsDocumentProfileMatch(match))
            return false;

        var text = match.Text ?? string.Empty;
        if (string.IsNullOrWhiteSpace(text))
            return false;

        var folded = FoldDiacritics(text).ToLowerInvariant();
        var definitionHeadings = System.Text.RegularExpressions.Regex.Matches(
            text,
            @"(?:^|[\r\n\s])[\p{Lu}][\p{Lu}\p{Mn}\p{Pd}\s]{2,42}\s*:",
            System.Text.RegularExpressions.RegexOptions.CultureInvariant).Count;
        if (definitionHeadings >= 4)
            return true;

        var glossaryLanguage = ContainsAny(
            $" {NormalizeQuery(folded)} ",
            " glossaire ",
            " glossary ",
            " vocabulaire ",
            " vocabulary ",
            " definition ",
            " definitions ");
        if (!glossaryLanguage)
            return false;

        var shortDefinitionSignals = CountOccurrences(folded, " signifie ")
            + CountOccurrences(folded, " designe ")
            + CountOccurrences(folded, " means ")
            + CountOccurrences(folded, " refers to ")
            + CountOccurrences(folded, " consiste a ");
        return shortDefinitionSignals >= 2 || definitionHeadings >= 2;
    }

    internal static bool ShouldAllowGlossaryResults(string query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return false;

        var normalized = $" {NormalizeQuery(FoldDiacritics(query).ToLowerInvariant())} ";
        return ContainsAny(
            normalized,
            " definition ",
            " definir ",
            " definis ",
            " que veut dire ",
            " signifie ",
            " meaning ",
            " define ",
            " glossaire ",
            " glossary ",
            " vocabulaire ",
            " vocabulary ",
            " terme ",
            " term ");
    }

    internal static bool LooksLikeStrongNavigationalChunk(RagMatch match)
    {
        if (match.NavigationScore is >= 0.85
            && (match.ContentDensityScore is null or < 0.45))
            return true;

        if (RetrievalContentClassifier.IsNavigationChunkType(match.ChunkType))
            return true;

        var text = match.Text ?? string.Empty;
        var context = $"{match.SectionTitle} {match.HeadingPath} {text}";
        var folded = FoldDiacritics(context).ToLowerInvariant();
        var padded = $" {NormalizeQuery(folded)} ";

        return HasStrongNavigationalMarker(folded, padded)
            || folded.Contains("table des matieres", StringComparison.Ordinal)
            || folded.Contains("table of contents", StringComparison.Ordinal)
            || folded.Contains("inhaltsverzeichnis", StringComparison.Ordinal)
            || padded.Contains(" sommaire ", StringComparison.Ordinal)
            || padded.Contains(" contents ", StringComparison.Ordinal)
            || padded.Contains(" sumario ", StringComparison.Ordinal)
            || padded.Contains(" sommario ", StringComparison.Ordinal)
            || padded.Contains(" toc ", StringComparison.Ordinal)
            || (padded.Contains(" indice ", StringComparison.Ordinal) && CountInlinePageNumberBoundaries(text) >= 3)
            || CountInlinePageNumberBoundaries(text) >= 8;
    }

    private static bool ContainsExplicitTableOfContentsMarker(string foldedText, string paddedNormalizedText)
        => foldedText.Contains("sommaire", StringComparison.Ordinal)
            || foldedText.Contains("table des matieres", StringComparison.Ordinal)
            || foldedText.Contains("table of contents", StringComparison.Ordinal)
            || foldedText.Contains("inhaltsverzeichnis", StringComparison.Ordinal)
            || paddedNormalizedText.Contains(" contents ", StringComparison.Ordinal)
            || paddedNormalizedText.Contains(" indice general ", StringComparison.Ordinal)
            || paddedNormalizedText.Contains(" indice de contenido ", StringComparison.Ordinal)
            || paddedNormalizedText.Contains(" indice de contenidos ", StringComparison.Ordinal)
            || paddedNormalizedText.Contains(" indice de materias ", StringComparison.Ordinal)
            || paddedNormalizedText.Contains(" indice analitico ", StringComparison.Ordinal);

    private static bool ContainsShortTableOfContentsMarker(string paddedNormalizedText)
        => paddedNormalizedText.Contains(" sumario ", StringComparison.Ordinal)
            || paddedNormalizedText.Contains(" sommario ", StringComparison.Ordinal)
            || paddedNormalizedText.Contains(" indice ", StringComparison.Ordinal)
            || paddedNormalizedText.Contains(" toc ", StringComparison.Ordinal);

    private static bool HasStrongNavigationalMarker(string foldedText, string paddedNormalizedText)
    {
        if (string.IsNullOrWhiteSpace(foldedText) || string.IsNullOrWhiteSpace(paddedNormalizedText))
            return false;

        if (foldedText.Contains("fiche-index", StringComparison.Ordinal)
            || foldedText.Contains("fiche index", StringComparison.Ordinal))
            return true;

        return System.Text.RegularExpressions.Regex.IsMatch(
            paddedNormalizedText,
            @"\b(?:index|liste|list|catalogue|catalog|inventaire|inventory)\s+(?:des?|de|du|d['’]?|of|for)?\s*[\p{L}\p{N}][\p{L}\p{N}\s\-_]{2,80}\b|\b[\p{L}\p{N}][\p{L}\p{N}\s\-_]{2,80}\s+(?:index|liste|list|catalogue|catalog|inventory)\b",
            System.Text.RegularExpressions.RegexOptions.CultureInvariant | System.Text.RegularExpressions.RegexOptions.IgnoreCase);
    }

    private static int CountBulletMarkers(string text)
        => string.IsNullOrWhiteSpace(text)
            ? 0
            : text.Count(static ch => ch is '\u2022' or '-' or '*');

    private static int CountInlinePageNumberBoundaries(string text)
    {
        if (string.IsNullOrWhiteSpace(text))
            return 0;

        var count = 0;
        var digitRun = 0;
        foreach (var ch in text)
        {
            if (char.IsDigit(ch))
            {
                digitRun++;
                continue;
            }

            if (digitRun is > 0 and <= 4 && char.IsLetter(ch) && char.IsUpper(ch))
                count++;

            digitRun = 0;
        }

        return count;
    }

    private static bool LooksLikeTitleListChunk(string text)
    {
        if (string.IsNullOrWhiteSpace(text) || text.Length < 180)
            return false;

        var words = 0;
        var capitalizedStarts = 0;
        var sentenceMarkers = 0;
        var inWord = false;

        foreach (var ch in text)
        {
            if (ch is '.' or '!' or '?' or ';' or ':' or '\u2022')
                sentenceMarkers++;

            if (char.IsLetter(ch))
            {
                if (!inWord)
                {
                    words++;
                    if (char.IsUpper(ch))
                        capitalizedStarts++;
                }

                inWord = true;
            }
            else
            {
                inWord = false;
            }
        }

        return (words >= 24
                && capitalizedStarts >= Math.Max(12, words / 3)
                && sentenceMarkers <= 2)
            || (words >= 40
                && capitalizedStarts >= 20
                && sentenceMarkers <= 2)
            || (CountLowerToUpperTransitions(text) >= 8 && sentenceMarkers <= 3);
    }

    private static int CountLowerToUpperTransitions(string text)
    {
        var count = 0;
        var previousWasLower = false;
        foreach (var ch in text)
        {
            if (char.IsUpper(ch) && previousWasLower)
                count++;

            previousWasLower = char.IsLower(ch);
        }

        return count;
    }

    private static int CountOccurrences(string text, string needle)
    {
        if (string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(needle))
            return 0;

        var count = 0;
        var index = 0;
        while (index < text.Length)
        {
            var found = text.IndexOf(needle, index, StringComparison.Ordinal);
            if (found < 0)
                break;

            count++;
            index = found + needle.Length;
        }

        return count;
    }

    internal static List<RagMatch> RerankDenseMatches(IReadOnlyList<RagMatch> matches)
        => matches
            .Select(match => new
            {
                Match = match,
                Score = match.Score + ComputeDenseBoost(match)
            })
            .OrderByDescending(item => item.Score)
            .ThenBy(item => item.Match.DocPath, StringComparer.OrdinalIgnoreCase)
            .ToList()
            .Select(item => item.Match with { Score = item.Score })
            .ToList();

    internal static List<RagMatch> ApplyRerankScores(
        IReadOnlyList<RagMatch> originalCandidates,
        IReadOnlyList<TeiClient.RerankItem> rerankedItems,
        int rerankedPrefixCount)
    {
        if (originalCandidates.Count == 0 || rerankedItems.Count == 0 || rerankedPrefixCount <= 0)
            return originalCandidates.ToList();

        var limitedPrefixCount = Math.Min(rerankedPrefixCount, originalCandidates.Count);
        var prefix = originalCandidates.Take(limitedPrefixCount).ToArray();
        var suffix = originalCandidates.Skip(limitedPrefixCount).ToArray();
        var byIndex = rerankedItems
            .Where(item => item.Index >= 0 && item.Index < prefix.Length)
            .GroupBy(item => item.Index)
            .ToDictionary(group => group.Key, group => group.OrderByDescending(x => x.Score).First().Score);

        if (byIndex.Count == 0)
            return originalCandidates.ToList();

        var orderedScores = rerankedItems
            .Where(item => item.Index >= 0 && item.Index < prefix.Length)
            .Select(item => item.Score)
            .OrderBy(score => score)
            .ToArray();
        var minScore = orderedScores.Length == 0 ? 0.0 : orderedScores.First();
        var maxScore = orderedScores.Length == 0 ? 0.0 : orderedScores.Last();

        var rerankedPrefix = byIndex
            .Select(pair =>
            {
                var match = prefix[pair.Key];
                var normalizedRerank = NormalizeRerankScore(pair.Value, minScore, maxScore);
                var blended = Math.Min(1.02, (match.Score * 0.35) + (normalizedRerank * 0.65));
                return match with
                {
                    Score = blended,
                    RerankScore = pair.Value
                };
            })
            .OrderByDescending(item => item.Score)
            .ThenByDescending(item => item.RerankScore)
            .ToList();

        var untouchedPrefix = Enumerable.Range(0, prefix.Length)
            .Where(index => !byIndex.ContainsKey(index))
            .Select(index => prefix[index])
            .ToList();

        var finalList = new List<RagMatch>(originalCandidates.Count);
        finalList.AddRange(rerankedPrefix);
        finalList.AddRange(untouchedPrefix);
        finalList.AddRange(suffix);
        return finalList;
    }

    private static double ComputeDenseBoost(RagMatch match)
    {
        double boost = 0.0;
        if (string.Equals(match.ChunkType, "unit_exact_v1", StringComparison.Ordinal))
            boost += 0.02;
        else if (string.Equals(match.ChunkType, "section_window_v1", StringComparison.Ordinal))
            boost += 0.01;

        if (!string.IsNullOrWhiteSpace(match.HeadingPath))
            boost += 0.005;
        if (string.Equals(match.EmbeddingBasis, "contextual_text_v1", StringComparison.Ordinal))
            boost += 0.005;

        return boost;
    }

    internal static double NormalizeRerankScore(double rawScore, double minScore, double maxScore)
    {
        if (double.IsNaN(rawScore) || double.IsInfinity(rawScore))
            return 0.0;
        if (maxScore <= minScore)
            return 1.0;

        var normalized = (rawScore - minScore) / (maxScore - minScore);
        return Math.Clamp(normalized, 0.0, 1.0);
    }

    internal static double NormalizeSparseScore(double rawScore)
    {
        if (rawScore <= 0.0 || double.IsNaN(rawScore) || double.IsInfinity(rawScore))
            return 0.0;

        var normalized = 0.45 + Math.Min(0.42, Math.Log10(1 + (rawScore * 1000.0)) * 0.24);
        return Math.Min(0.92, normalized);
    }

    internal static double NormalizeDocumentProfileScore(double sparseRank, int matchCount)
    {
        if (matchCount <= 0)
            return 0.32;

        var lexicalScore = NormalizeSparseScore(sparseRank);
        var matchScore = Math.Min(0.28, matchCount * 0.045);
        var combined = Math.Max(lexicalScore, 0.48 + matchScore);
        return Math.Clamp(combined, 0.0, 0.86);
    }

    internal static double ComputeDocumentProfileSpecificityBoost(
        string query,
        string? candidateText,
        IReadOnlyList<string> peerCandidateTexts)
    {
        if (string.IsNullOrWhiteSpace(candidateText) || peerCandidateTexts.Count == 0)
            return 0.0;

        var tokens = BuildDocumentProfileSpecificityTokens(query);
        if (tokens.Count == 0)
            return 0.0;

        var normalizedCandidate = NormalizeForLexicalSignal(candidateText);
        if (string.IsNullOrWhiteSpace(normalizedCandidate))
            return 0.0;

        var normalizedPeers = peerCandidateTexts
            .Select(NormalizeForLexicalSignal)
            .Where(static text => !string.IsNullOrWhiteSpace(text))
            .ToArray();
        if (normalizedPeers.Length == 0)
            return 0.0;

        var rawBoost = 0.0;
        foreach (var token in tokens)
        {
            var variants = BuildLexicalTokenVariants(token);
            if (variants.Count == 0)
                continue;

            if (!variants.Any(variant => normalizedCandidate.Contains(variant, StringComparison.Ordinal)))
                continue;

            var documentFrequency = normalizedPeers.Count(peer =>
                variants.Any(variant => peer.Contains(variant, StringComparison.Ordinal)));
            if (documentFrequency <= 0)
                continue;

            var inverseFrequency = Math.Log((normalizedPeers.Length + 1.0) / (documentFrequency + 0.5)) + 1.0;
            var tokenWeight =
                IsReferenceLikeLookupTerm(token) ? 1.45 :
                token.Length >= 10 ? 1.25 :
                token.Length >= 7 ? 1.10 :
                1.0;
            rawBoost += inverseFrequency * tokenWeight;
        }

        return Math.Clamp(rawBoost * 0.025, 0.0, 0.24);
    }

    internal static double ComputeDocumentProfileConstraintCoverageScore(
        IReadOnlyList<string> tokens,
        string normalizedCandidate)
    {
        if (tokens.Count == 0 || string.IsNullOrWhiteSpace(normalizedCandidate))
            return 0.0;

        var matchedWeight = 0.0;
        var totalWeight = 0.0;
        foreach (var token in tokens)
        {
            var variants = BuildLexicalTokenVariants(token);
            if (variants.Count == 0)
                continue;

            var weight = GetDocumentProfileConstraintTokenWeight(token);
            totalWeight += weight;
            if (variants.Any(variant => ContainsExactNormalizedToken(normalizedCandidate, variant)))
            {
                matchedWeight += weight;
                if (IsAudienceConstraintToken(token))
                {
                    totalWeight += 2.0;
                    if (ContainsAudienceConstraintPhrase(normalizedCandidate, token))
                        matchedWeight += 2.0;
                }
            }
        }

        return totalWeight <= 0.0
            ? 0.0
            : Math.Clamp(matchedWeight / totalWeight, 0.0, 1.0);
    }

    internal static double ComputeDocumentProfileSelectionConstraintCoverage(
        IReadOnlyList<string> tokens,
        RagMatch match)
    {
        if (tokens.Count == 0 || !IsDocumentProfileMatch(match))
            return 0.0;

        var coverage = ComputeDocumentProfileConstraintCoverageScore(
            tokens,
            NormalizeForLexicalSignal(GetTitleSignalText(match)));
        if (tokens.Any(IsAudienceConstraintToken)
            && !ContainsAnyDocumentProfileConstraintToken(tokens.Where(IsAudienceConstraintToken), NormalizeForLexicalSignal(GetTitleSignalText(match))))
        {
            return 0.0;
        }

        if (coverage >= 0.34)
            return coverage;

        return match.MatchedContentCards is { Count: > 0 } && coverage >= 0.20
            ? Math.Max(coverage, 0.34)
            : 0.0;
    }

    private static bool ContainsAnyDocumentProfileConstraintToken(
        IEnumerable<string> tokens,
        string normalizedCandidate)
    {
        if (string.IsNullOrWhiteSpace(normalizedCandidate))
            return false;

        foreach (var token in tokens)
        {
            var variants = BuildLexicalTokenVariants(token);
            if (variants.Any(variant => ContainsExactNormalizedToken(normalizedCandidate, variant)))
                return true;
        }

        return false;
    }

    private static double GetDocumentProfileConstraintTokenWeight(string token)
        => token switch
        {
            "enfant" or "enfants" or "children" or "child" or "kids" or "apprenti" or "apprentis"
                or "apprentice" or "apprentices" or "debutant" or "debutants" or "beginner" or "beginners" => 2.0,
            "materiel" or "material" or "materials" or "risque" or "risques" or "risk" or "risks"
                or "failure" or "ratage" or "temps" or "time" or "duration" or "duree" => 1.5,
            _ => 1.0
        };

    private static bool IsAudienceConstraintToken(string token)
        => token is "enfant" or "enfants" or "children" or "child" or "kids" or "apprenti" or "apprentis"
            or "apprentice" or "apprentices" or "debutant" or "debutants" or "beginner" or "beginners";

    private static bool ContainsAudienceConstraintPhrase(string normalizedCandidate, string token)
    {
        if (token is "enfant" or "enfants" or "children" or "child" or "kids")
        {
            return ContainsAny(
                normalizedCandidate,
                " pour enfants ",
                " pour les enfants ",
                " aux enfants ",
                " avec les enfants ",
                " destine aux enfants ",
                " destine pour enfants ",
                " adaptes aux enfants ",
                " adapte aux enfants ",
                " for children ",
                " for kids ",
                " with children ",
                " intended for children ",
                " designed for children ",
                " adapted for children ",
                " suitable for children ");
        }

        if (token is "apprenti" or "apprentis" or "apprentice" or "apprentices" or "debutant" or "debutants" or "beginner" or "beginners")
        {
            return ContainsAny(
                normalizedCandidate,
                " pour apprentis ",
                " pour les apprentis ",
                " pour debutants ",
                " pour les debutants ",
                " aux apprentis ",
                " aux debutants ",
                " destine aux apprentis ",
                " destine aux debutants ",
                " for apprentices ",
                " for beginners ",
                " intended for apprentices ",
                " intended for beginners ",
                " designed for apprentices ",
                " designed for beginners ",
                " suitable for apprentices ",
                " suitable for beginners ");
        }

        return false;
    }

    internal static IReadOnlyList<string> BuildDocumentProfileSpecificityTokens(string query)
        => ExtractLexicalQueryTokens(query)
            .Where(static token => token.Length >= 5 || IsReferenceLikeLookupTerm(token))
            .Where(static token => !PrimaryAnchorStopwords.Contains(token))
            .Where(static token => !IsGenericDocumentProfileSpecificityToken(token))
            .Distinct(StringComparer.Ordinal)
            .ToArray();

    private static bool IsGenericDocumentProfileSpecificityToken(string token)
        => StructuredContentLexicon.IsStructuredItemTypeToken(token)
            || token is "procedure" or "procedures" or "document" or "documents"
            or "fichier" or "fichiers" or "source" or "sources"
            or "guide" or "guides" or "fiche" or "fiches"
            or "scan" or "scans" or "scanne" or "scannee" or "scannes" or "scannees" or "ocr"
            or "confiance" or "confidence" or "comment" or "demande" or "issue" or "indiquer"
            or "answer" or "reponse" or "repondre"
            or "sale" or "sales" or "salee" or "salees";

    internal static IReadOnlyList<string> ExtractLexicalQueryTokens(string query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return Array.Empty<string>();

        var normalized = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query));
        if (string.IsNullOrWhiteSpace(normalized))
            return Array.Empty<string>();

        return normalized
            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Where(static token => token.Length >= 4)
            .Where(static token => token.Any(char.IsLetter))
            .Where(static token => !LexicalStopwords.Contains(token))
            .Distinct(StringComparer.Ordinal)
            .ToArray();
    }

    internal static IReadOnlyList<string> BuildLexicalContentFallbackTerms(string query)
    {
        var tokens = ExtractLexicalQueryTokens(query);
        if (tokens.Count == 0)
            return Array.Empty<string>();

        var terms = new HashSet<string>(StringComparer.Ordinal);
        var canonicalTokens = new List<string>();
        foreach (var token in tokens)
        {
            var variants = BuildLexicalTokenVariants(token);
            foreach (var variant in variants)
                terms.Add(variant);

            var canonical = variants
                .OrderBy(static variant => ContainsNonAscii(variant) ? 1 : 0)
                .ThenBy(static variant => variant.Length)
                .ThenBy(static variant => variant, StringComparer.Ordinal)
                .FirstOrDefault();
            if (!string.IsNullOrWhiteSpace(canonical))
                canonicalTokens.Add(canonical);
        }

        AddAdjacentPhraseTerms(terms, canonicalTokens);

        var surfaceTokens = ExtractLexicalQuerySurfaceTokens(query);
        if (surfaceTokens.Count > 0)
        {
            foreach (var token in surfaceTokens)
                terms.Add(token);

            AddAdjacentPhraseTerms(terms, surfaceTokens);
        }

        AddAdjacentAlphaNumericPhraseTerms(terms, query);
        AddCrossLanguageTechnicalPhraseVariants(terms, canonicalTokens);

        foreach (var quotedPhrase in ExtractQuotedLookupPhrases(query))
        {
            terms.Add(quotedPhrase);
            var foldedPhrase = FoldDiacritics(quotedPhrase);
            if (!string.Equals(foldedPhrase, quotedPhrase, StringComparison.Ordinal))
                terms.Add(foldedPhrase);
        }

        foreach (var focusedPhrase in ExtractFocusedLookupPhrases(query))
        {
            terms.Add(focusedPhrase);
            var foldedPhrase = FoldDiacritics(focusedPhrase);
            if (!string.Equals(foldedPhrase, focusedPhrase, StringComparison.Ordinal))
                terms.Add(foldedPhrase);
        }

        var filteredTerms = terms
            .Where(static term => term.Length >= 4)
            .Where(static term => !LexicalStopwords.Contains(term))
            .Where(static term => !SpecificAnchorStopwords.Contains(term))
            .ToArray();

        var phraseTerms = filteredTerms
            .Where(static term => term.Contains(' '))
            .OrderBy(static term => term, StringComparer.Ordinal)
            .Take(40);
        var singleTerms = filteredTerms
            .Where(static term => !term.Contains(' '))
            .OrderBy(static term => term, StringComparer.Ordinal)
            .Take(40);

        return phraseTerms
            .Concat(singleTerms)
            .Distinct(StringComparer.Ordinal)
            .ToArray();
    }

    private static void AddCrossLanguageTechnicalPhraseVariants(HashSet<string> terms, IReadOnlyList<string> canonicalTokens)
    {
        if (canonicalTokens.Count < 2)
            return;

        var normalized = $" {string.Join(' ', canonicalTokens)} ";
        if (ContainsAny(normalized, " salle propre ", " salles propres ", " clean room ", " clean rooms ", " cleanroom ", " cleanrooms "))
        {
            terms.Add("salle propre");
            terms.Add("salles propres");
            terms.Add("clean room");
            terms.Add("clean rooms");
            terms.Add("cleanroom");
            terms.Add("cleanrooms");
        }
        if (ContainsAny(
                normalized,
                " safety data sheet ",
                " safety data sheets ",
                " material safety data sheet ",
                " material safety data sheets ",
                " fiche de donnees de securite ",
                " fiches de donnees de securite ",
                " fiche donnees securite ",
                " fiches donnees securite ",
                " fiche de securite ",
                " fiches de securite ")
            || ContainsAny(normalized, " msds ", " sds ", " fds ")
            || (ContainsAny(normalized, " safety ", " securite ")
                && ContainsAny(normalized, " data sheet ", " data sheets ", " fiche ", " fiches ", " donnees ")))
        {
            terms.Add("msds");
            terms.Add("sds");
            terms.Add("fds");
            terms.Add("safety data sheet");
            terms.Add("safety data sheets");
            terms.Add("material safety data sheet");
            terms.Add("material safety data sheets");
            terms.Add("fiche de donnees de securite");
            terms.Add("fiches de donnees de securite");
            terms.Add("fiche de securite");
            terms.Add("fiches de securite");
        }
        if (ContainsAny(normalized, " old ", " older ", " previous ", " prior ", " archived ", " archive ", " archives ", " historical ", " legacy ", " obsolete ", " ancien ", " ancienne ", " anciens ", " anciennes ", " precedente ", " precedent ", " anterieure ", " anterieur ")
            && ContainsAny(normalized, " version ", " versions ", " edition ", " editions ", " document ", " documents "))
        {
            terms.Add("old version");
            terms.Add("old versions");
            terms.Add("previous version");
            terms.Add("previous versions");
            terms.Add("prior version");
            terms.Add("archived version");
            terms.Add("archived document");
            terms.Add("historical version");
            terms.Add("ancienne version");
            terms.Add("anciennes versions");
            terms.Add("version precedente");
            terms.Add("version anterieure");
        }
        if (ContainsAny(normalized, " current ", " latest ", " newest ", " recent ", " newer ", " actuelle ", " actuel ", " courante ", " courant ", " derniere ", " nouvelle ", " nouveau ")
            && ContainsAny(normalized, " version ", " versions ", " edition ", " editions ", " document ", " documents "))
        {
            terms.Add("current version");
            terms.Add("current versions");
            terms.Add("latest version");
            terms.Add("latest versions");
            terms.Add("newest version");
            terms.Add("version actuelle");
            terms.Add("version courante");
            terms.Add("derniere version");
            terms.Add("nouvelle version");
        }
    }

    private static string? SelectCrossLanguageTechnicalPhraseVariant(string phrase)
    {
        if (string.IsNullOrWhiteSpace(phrase))
            return null;

        var normalized = $" {FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(phrase)).ToLowerInvariant()} ";
        if (ContainsAny(normalized, " salle propre ", " salles propres "))
            return "cleanroom";
        if (ContainsAny(normalized, " clean room ", " clean rooms ", " cleanroom ", " cleanrooms "))
            return "salle propre";
        if (ContainsAny(normalized, " fiche de donnees de securite ", " fiche donnees securite ", " fiche de securite ", " fds "))
            return "safety data sheet";
        if (ContainsAny(normalized, " material safety data sheet ", " safety data sheet ", " msds ", " sds "))
            return "fiche de donnees de securite";
        if (ContainsAny(normalized, " ancienne version ", " anciennes versions ", " version precedente ", " version anterieure "))
            return "old version";
        if (ContainsAny(normalized, " old version ", " old versions ", " previous version ", " prior version ", " archived version ", " historical version "))
            return "ancienne version";
        if (ContainsAny(normalized, " version actuelle ", " version courante ", " derniere version ", " nouvelle version "))
            return "current version";
        if (ContainsAny(normalized, " current version ", " latest version ", " newest version "))
            return "version courante";

        return null;
    }

    internal static IReadOnlyList<string> BuildSupplementalSparseLexicalFallbackTerms(string query)
    {
        var defaultTerms = BuildLexicalContentFallbackTerms(query);
        if (defaultTerms.Count == 0)
            return defaultTerms;

        var surfaceNormalized = ExactMatchEntryExtractor.NormalizeForLookup(query);
        var normalized = FoldDiacritics(surfaceNormalized);
        if (string.IsNullOrWhiteSpace(normalized)
            || !ShouldPreferComparativeDocumentDiversity(query))
        {
            return defaultTerms;
        }

        var betweenMatch = Regex.Match(
            normalized,
            @"\b(?:entre|between)\s+(?<target>[\p{L}\p{Nd}\s\-:;,]{8,180}?)(?=\s+(?:comment|how|pourquoi|why|explique|explain)\b|[\?\r\n]|$)",
            RegexOptions.CultureInvariant | RegexOptions.IgnoreCase);
        if (betweenMatch.Success)
        {
            var betweenSubject = betweenMatch.Groups["target"].Value.Trim();
            var betweenTermSet = new HashSet<string>(BuildLexicalContentFallbackTerms(betweenSubject), StringComparer.Ordinal);
            AddReversedAdjacentSupplementalSubjectPhrases(betweenTermSet, ExtractLexicalQueryTokens(betweenSubject));
            var betweenTerms = betweenTermSet
                .Where(static term => !string.IsNullOrWhiteSpace(term))
                .Where(static term => !LexicalStopwords.Contains(term))
                .Where(static term => !SpecificAnchorStopwords.Contains(term))
                .Where(static term => !PrimaryAnchorStopwords.Contains(term))
                .Distinct(StringComparer.Ordinal)
                .ToArray();
            if (betweenTerms.Length > 0)
                return betweenTerms;
        }

        const string choicePattern =
            @"\b(?:choisir|choix|choose|select|selection|recommande|recommend|prefer|favor|favour|privilegie|priorise)\b";
        var choiceMatch = Regex.Match(
            normalized,
            choicePattern,
            RegexOptions.CultureInvariant | RegexOptions.IgnoreCase);
        if (!choiceMatch.Success || choiceMatch.Index <= 0)
            return defaultTerms;

        var subjectText = normalized[..choiceMatch.Index].Trim();
        var surfaceChoiceMatch = Regex.Match(
            surfaceNormalized,
            choicePattern,
            RegexOptions.CultureInvariant | RegexOptions.IgnoreCase);
        var subjectSurfaceText = surfaceChoiceMatch.Success && surfaceChoiceMatch.Index > 0
            ? surfaceNormalized[..surfaceChoiceMatch.Index].Trim()
            : SliceSurfaceNormalizedByFoldedLength(surfaceNormalized, choiceMatch.Index).Trim();
        var subjectTermSet = new HashSet<string>(BuildLexicalContentFallbackTerms(subjectSurfaceText), StringComparer.Ordinal);
        foreach (var term in BuildLexicalContentFallbackTerms(subjectText))
            subjectTermSet.Add(term);
        AddReversedAdjacentSupplementalSubjectPhrases(subjectTermSet, ExtractLexicalQuerySurfaceTokens(subjectSurfaceText));
        AddReversedAdjacentSupplementalSubjectPhrases(subjectTermSet, ExtractLexicalQueryTokens(subjectText));

        var subjectTerms = subjectTermSet
            .Where(static term => !string.IsNullOrWhiteSpace(term))
            .Where(static term => !LexicalStopwords.Contains(term))
            .Where(static term => !SpecificAnchorStopwords.Contains(term))
            .Where(static term => !PrimaryAnchorStopwords.Contains(term))
            .Distinct(StringComparer.Ordinal)
            .ToArray();

        return subjectTerms.Length == 0 ? defaultTerms : subjectTerms;
    }

    private static void AddReversedAdjacentSupplementalSubjectPhrases(
        HashSet<string> terms,
        IReadOnlyList<string> subjectTokens)
    {
        if (subjectTokens.Count < 2)
            return;

        var cleanTokens = subjectTokens
            .Where(static token => token.Length >= 4)
            .Where(static token => !LexicalStopwords.Contains(FoldDiacritics(token)))
            .Where(static token => !SpecificAnchorStopwords.Contains(FoldDiacritics(token)))
            .Where(static token => !PrimaryAnchorStopwords.Contains(FoldDiacritics(token)))
            .Where(static token => !BroadDiversityAbstractAssistTokens.Contains(FoldDiacritics(token)))
            .Take(8)
            .ToArray();
        if (cleanTokens.Length < 2)
            return;

        for (var i = 0; i < cleanTokens.Length - 1; i++)
        {
            var leftVariants = BuildSupplementalSubjectPhraseTokenVariants(cleanTokens[i]);
            var rightVariants = BuildSupplementalSubjectPhraseTokenVariants(cleanTokens[i + 1]);

            foreach (var right in rightVariants)
            {
                foreach (var left in leftVariants)
                {
                    if (!string.Equals(right, left, StringComparison.Ordinal))
                        terms.Add($"{right} {left}");
                }
            }
        }
    }

    private static IReadOnlyList<string> BuildSupplementalSubjectPhraseTokenVariants(string token)
    {
        var folded = FoldDiacritics(token);
        if (string.IsNullOrWhiteSpace(folded))
            return Array.Empty<string>();

        var variants = new HashSet<string>(BuildLexicalTokenVariants(folded), StringComparer.Ordinal);
        variants.Add(folded);
        if (folded.Length >= 5
            && (folded.EndsWith("s", StringComparison.Ordinal) || folded.EndsWith("x", StringComparison.Ordinal)))
        {
            variants.Add(folded[..^1]);
        }
        foreach (var variant in variants.ToArray())
        {
            if (variant.Length >= 6 && variant.EndsWith("e", StringComparison.Ordinal))
                variants.Add(variant + "r");
        }

        return variants
            .Where(static variant => variant.Length >= 4)
            .Where(static variant => !LexicalStopwords.Contains(variant))
            .Take(5)
            .ToArray();
    }

    private static string SliceSurfaceNormalizedByFoldedLength(string surfaceNormalized, int foldedLength)
    {
        if (string.IsNullOrWhiteSpace(surfaceNormalized) || foldedLength <= 0)
            return string.Empty;

        var consumedFoldedLength = 0;
        var surfaceLength = 0;
        foreach (var ch in surfaceNormalized)
        {
            var foldedCharLength = FoldDiacritics(ch.ToString()).Length;
            if (consumedFoldedLength + foldedCharLength > foldedLength)
                break;

            consumedFoldedLength += foldedCharLength;
            surfaceLength++;
            if (consumedFoldedLength == foldedLength)
                break;
        }

        return surfaceNormalized[..Math.Min(surfaceLength, surfaceNormalized.Length)];
    }

    internal static IReadOnlyList<string> BuildDocumentProfileLexicalTerms(string query)
    {
        var terms = new HashSet<string>(
            BuildLexicalContentFallbackTerms(query).Where(static term => !IsGenericDocumentProfileLexicalTerm(term)),
            StringComparer.Ordinal);
        foreach (var token in ExtractLexicalQuerySurfaceTokens(query))
        {
            if (!IsGenericDocumentProfileLexicalTerm(token))
                terms.Add(token);
        }
        var specificityTerms = new HashSet<string>(StringComparer.Ordinal);
        foreach (var token in BuildDocumentProfileSpecificityTokens(query))
        {
            foreach (var variant in BuildLexicalTokenVariants(token))
            {
                terms.Add(variant);
                specificityTerms.Add(variant);
            }
        }

        var filteredTerms = terms
            .Where(static term => term.Length >= 4 || IsShortTitleSignalToken(term))
            .ToArray();
        var phraseTerms = filteredTerms
            .Where(static term => term.Contains(' '))
            .OrderByDescending(term => specificityTerms.Contains(term))
            .ThenBy(static term => term, StringComparer.Ordinal)
            .Take(64);
        var singleTerms = filteredTerms
            .Where(static term => !term.Contains(' '))
            .OrderByDescending(term => specificityTerms.Contains(term))
            .ThenBy(static term => term, StringComparer.Ordinal)
            .Take(64);

        return phraseTerms
            .Concat(singleTerms)
            .Take(128)
            .ToArray();
    }

    private static bool IsGenericDocumentProfileLexicalTerm(string term)
    {
        if (string.IsNullOrWhiteSpace(term))
            return true;

        return term
            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Any(IsGenericDocumentProfileSpecificityToken);
    }

    internal static IReadOnlyList<string> ExtractTitleLookupPhrases(string query)
    {
        var quotedPhrases = ExtractQuotedLookupPhrases(query);
        if (quotedPhrases.Count > 0)
            return quotedPhrases;

        var dateAnchoredPhrases = ExtractDateAnchoredTitleLookupPhrases(query)
            .SelectMany(phrase => BuildSurfaceTitleLookupPhraseVariants(query, phrase))
            .Distinct(StringComparer.Ordinal)
            .Take(8)
            .ToArray();
        if (dateAnchoredPhrases.Length > 0)
            return dateAnchoredPhrases;

        var explicitFilePhrases = ExtractExplicitFileLookupPhraseGroups(query)
            .SelectMany(static group => group)
            .Where(static phrase => !string.IsNullOrWhiteSpace(phrase))
            .SelectMany(phrase => BuildSurfaceTitleLookupPhraseVariants(query, phrase))
            .Distinct(StringComparer.Ordinal)
            .Take(8)
            .ToArray();
        var compactCodePhrases = ExtractCompactDocumentCodeLookupPhrases(query)
            .SelectMany(phrase => BuildSurfaceTitleLookupPhraseVariants(query, phrase))
            .Distinct(StringComparer.Ordinal)
            .Take(4)
            .ToArray();
        if (explicitFilePhrases.Length > 0)
        {
            if (compactCodePhrases.Length > 0
                && !ContainsExplicitFilenameSurface(query)
                && !ShouldSkipUnanchoredTitleAnchorRouteForBroadDiversity(query))
            {
                return compactCodePhrases;
            }

            return explicitFilePhrases;
        }

        var standardReferencePhrases = ExtractStandardReferenceTitleLookupPhrases(query)
            .SelectMany(phrase => BuildSurfaceTitleLookupPhraseVariants(query, phrase))
            .Distinct(StringComparer.Ordinal)
            .Take(6)
            .ToArray();
        if (standardReferencePhrases.Length > 0)
            return standardReferencePhrases;

        if (compactCodePhrases.Length > 0
            && !ShouldSkipUnanchoredTitleAnchorRouteForBroadDiversity(query))
        {
            return compactCodePhrases;
        }

        if (!ShouldTreatFocusedLookupAsPreciseTitle(query))
            return Array.Empty<string>();

        return ExtractFocusedLookupPhrases(query)
            .Where(static phrase => ExtractTitlePruneTokens(phrase).Length is >= 2 and <= 8)
            .SelectMany(phrase => BuildSurfaceTitleLookupPhraseVariants(query, phrase))
            .Distinct(StringComparer.Ordinal)
            .Take(4)
            .ToArray();
    }

    internal static IReadOnlyList<string> ExtractCompactDocumentCodeLookupPhrases(string query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return Array.Empty<string>();

        return Regex.Matches(
                query,
                @"\b[\p{L}\p{Nd}]{2,8}\b",
                RegexOptions.CultureInvariant)
            .Select(static match => match.Value)
            .Where(static token => token.Any(char.IsDigit)
                                   || token.Where(char.IsLetter).All(char.IsUpper))
            .Select(static token => NormalizeForLexicalSignal(token))
            .Where(IsLikelyCompactDocumentCodeOperand)
            .Distinct(StringComparer.Ordinal)
            .Take(6)
            .ToArray();
    }

    internal static IReadOnlyList<string> ExtractCompactDocumentCodeProfileRecoveryPhrases(string query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return Array.Empty<string>();

        return ExtractCompactDocumentCodeLookupPhrases(query)
            .Concat(ExtractBareVsComparativeOperands(query).Where(IsLikelyCompactDocumentCodeOperand))
            .Distinct(StringComparer.Ordinal)
            .Take(6)
            .ToArray();
    }

    internal static bool SelectionsCoverCompactDocumentCodePhrase(string phrase, IReadOnlyList<RagMatch> selected)
    {
        var normalizedPhrase = NormalizeForLexicalSignal(phrase);
        if (string.IsNullOrWhiteSpace(normalizedPhrase) || selected.Count == 0)
            return false;

        var compactPhrase = normalizedPhrase.Replace(" ", string.Empty, StringComparison.Ordinal);
        return selected.Any(match =>
        {
            var titleSignal = NormalizeForLexicalSignal(string.Join(' ', new[] { match.DocName, match.DocPath }
                .Where(static value => !string.IsNullOrWhiteSpace(value))));
            if (string.IsNullOrWhiteSpace(titleSignal))
                return false;

            return titleSignal.Contains(" " + normalizedPhrase + " ", StringComparison.Ordinal)
                || (!string.IsNullOrWhiteSpace(compactPhrase)
                    && titleSignal.Replace(" ", string.Empty, StringComparison.Ordinal).Contains(compactPhrase, StringComparison.Ordinal));
        });
    }

    internal static bool ShouldAllowCompactDocumentCodeEmptyRecovery(string query, bool hasExplicitFileDocumentHint)
        => !hasExplicitFileDocumentHint
           || !ContainsExplicitFilenameSurface(query);

    internal static bool ShouldAllowLexicalProfileEmptyRecovery(string query, bool hasExplicitFileDocumentHint)
        => !hasExplicitFileDocumentHint
           || !ContainsExplicitFilenameSurface(query);

    private static bool ContainsExplicitFilenameSurface(string query)
        => !string.IsNullOrWhiteSpace(query)
           && (query.Contains('`', StringComparison.Ordinal)
               || query.Contains('_', StringComparison.Ordinal)
               || SafeRegexIsMatch(
                   query,
                   @"\.[a-z0-9]{2,5}\b",
                   RegexOptions.CultureInvariant | RegexOptions.IgnoreCase,
                   TimeSpan.FromMilliseconds(100)));

    internal static IReadOnlyList<string> ExtractDateAnchoredTitleLookupPhrases(string query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return Array.Empty<string>();

        var normalized = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query)).ToLowerInvariant();
        var tokens = normalized
            .Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        if (tokens.Length < 3)
            return Array.Empty<string>();

        var phrases = new List<string>();
        for (var index = 0; index < tokens.Length; index++)
        {
            if (TryReadDayMonthYear(tokens, index, out var dayMonthYear))
            {
                AddDateAnchoredTitleLookupPhrases(tokens, dayMonthYear, phrases);
                continue;
            }

            if (TryReadMonthDayYear(tokens, index, out var monthDayYear))
                AddDateAnchoredTitleLookupPhrases(tokens, monthDayYear, phrases);
        }

        return phrases
            .Where(static phrase => !string.IsNullOrWhiteSpace(phrase))
            .Distinct(StringComparer.Ordinal)
            .Take(12)
            .ToArray();
    }

    internal static bool SelectionsCoverDateAnchoredDocument(string query, IReadOnlyList<RagMatch> selected)
    {
        if (selected.Count == 0)
            return false;

        var phrases = ExtractDateAnchoredTitleLookupPhrases(query);
        if (phrases.Count == 0)
            return true;

        var normalizedPhrases = phrases
            .Select(NormalizeForLexicalSignal)
            .Where(static phrase => !string.IsNullOrWhiteSpace(phrase))
            .ToArray();
        if (normalizedPhrases.Length == 0)
            return true;

        return selected.Any(match =>
        {
            var title = NormalizeForLexicalSignal(string.Join(' ', new[]
            {
                match.DocName,
                match.DocPath,
                match.SectionTitle,
                match.HeadingPath
            }.Where(static value => !string.IsNullOrWhiteSpace(value))));
            if (string.IsNullOrWhiteSpace(title))
                return false;

            return normalizedPhrases.Any(phrase =>
            {
                if (ContainsOrderedPhraseWindowInNormalizedText(title, phrase, maxGapChars: 18))
                    return true;

                var tokens = phrase.Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
                return tokens.Length > 0 && tokens.All(token => ContainsExactNormalizedToken(title, token));
            });
        });
    }

    private static bool TryReadDayMonthYear(
        IReadOnlyList<string> tokens,
        int index,
        [NotNullWhen(true)] out DateTitleLookup? result)
    {
        result = null;
        if (!TryParseDayToken(tokens[index], out var day))
            return false;

        if (index + 2 < tokens.Count
            && TryParseMonthToken(tokens[index + 1], out var month)
            && TryParseYearToken(tokens[index + 2], out var year))
        {
            result = new DateTitleLookup(index, index + 2, year, month, day);
            return true;
        }

        if (index + 3 < tokens.Count
            && TryParseDayToken(tokens[index + 1], out var rangeEndDay)
            && TryParseMonthToken(tokens[index + 2], out month)
            && TryParseYearToken(tokens[index + 3], out year))
        {
            result = new DateTitleLookup(index, index + 3, year, month, rangeEndDay);
            return true;
        }

        return false;
    }

    private static bool TryReadMonthDayYear(
        IReadOnlyList<string> tokens,
        int index,
        [NotNullWhen(true)] out DateTitleLookup? result)
    {
        result = null;
        if (!TryParseMonthToken(tokens[index], out var month))
            return false;

        if (index + 2 < tokens.Count
            && TryParseDayToken(tokens[index + 1], out var day)
            && TryParseYearToken(tokens[index + 2], out var year))
        {
            result = new DateTitleLookup(index, index + 2, year, month, day);
            return true;
        }

        if (index + 3 < tokens.Count
            && TryParseDayToken(tokens[index + 1], out _)
            && TryParseDayToken(tokens[index + 2], out var rangeEndDay)
            && TryParseYearToken(tokens[index + 3], out year))
        {
            result = new DateTitleLookup(index, index + 3, year, month, rangeEndDay);
            return true;
        }

        return false;
    }

    private static void AddDateAnchoredTitleLookupPhrases(
        IReadOnlyList<string> tokens,
        DateTitleLookup date,
        List<string> phrases)
    {
        var month = date.Month.ToString("00", CultureInfo.InvariantCulture);
        var day = date.Day.ToString("00", CultureInfo.InvariantCulture);
        var year = date.Year.ToString(CultureInfo.InvariantCulture);
        var canonicalDate = $"{year} {month} {day}";
        var compactDate = $"{year}{month}{day}";
        var anchors = ExtractDateTitleAnchorTokens(tokens, date.StartIndex, date.EndIndex);
        var specificAnchors = anchors
            .Where(static token => !DateTitleGenericAnchorTokens.Contains(token))
            .Where(static token => !DateTitleInstructionAnchorTokens.Contains(token))
            .TakeLast(3)
            .Reverse()
            .ToArray();
        var genericAnchors = anchors
            .Where(static token => DateTitleGenericAnchorTokens.Contains(token))
            .TakeLast(2)
            .Reverse()
            .ToArray();

        phrases.Add(canonicalDate);
        phrases.Add(compactDate);

        foreach (var specific in specificAnchors)
        {
            phrases.Add($"{specific} {canonicalDate}");
            phrases.Add($"{specific} {compactDate}");
            foreach (var generic in genericAnchors)
            {
                phrases.Add($"{specific} {generic} {canonicalDate}");
                phrases.Add($"{generic} {specific} {canonicalDate}");
            }
        }

        if (specificAnchors.Length == 0)
        {
            foreach (var generic in genericAnchors)
                phrases.Add($"{generic} {canonicalDate}");
        }
    }

    private static IReadOnlyList<string> ExtractDateTitleAnchorTokens(
        IReadOnlyList<string> tokens,
        int dateStartIndex,
        int dateEndIndex)
    {
        var anchors = new List<string>();
        var start = Math.Max(0, dateStartIndex - 8);
        for (var index = start; index < dateStartIndex; index++)
        {
            if (IsDateTitleAnchorToken(tokens[index]))
                anchors.Add(tokens[index]);
        }

        return anchors
            .Distinct(StringComparer.Ordinal)
            .TakeLast(6)
            .ToArray();
    }

    private static bool IsDateTitleAnchorToken(string token)
        => token.Length >= 3
           && token.Any(char.IsLetter)
           && !LexicalStopwords.Contains(token)
           && !PrimaryAnchorStopwords.Contains(token)
           && !SpecificAnchorStopwords.Contains(token)
           && !TitleConnectorTokens.Contains(token)
           && !TryParseMonthToken(token, out _);

    private static bool TryParseDayToken(string token, out int day)
    {
        day = 0;
        return int.TryParse(token, NumberStyles.None, CultureInfo.InvariantCulture, out day)
            && day is >= 1 and <= 31;
    }

    private static bool TryParseYearToken(string token, out int year)
    {
        year = 0;
        return int.TryParse(token, NumberStyles.None, CultureInfo.InvariantCulture, out year)
            && year is >= 1900 and <= 2099;
    }

    private static bool TryParseMonthToken(string token, out int month)
        => DateTitleMonthNumbers.TryGetValue(token.TrimEnd('.'), out month);

    private sealed record DateTitleLookup(int StartIndex, int EndIndex, int Year, int Month, int Day);

