    {
        "ancien",
        "ancienne",
        "anciens",
        "anciennes",
        "old",
        "older",
        "nouveau",
        "nouvelle",
        "nouveaux",
        "nouvelles",
        "new",
        "newer",
        "source",
        "sources",
        "changement",
        "changements",
        "change",
        "changes",
        "impact",
        "impacts",
        "colonne",
        "colonnes",
        "column",
        "columns",
        "tableau",
        "table",
        "version",
        "versions",
        "date",
        "dates",
        "page",
