                variants.Add("applications");
                break;

            case "enfant":
            case "enfants":
            case "child":
            case "children":
            case "kid":
            case "kids":
                variants.Add("enfant");
                variants.Add("enfants");
                variants.Add("child");
                variants.Add("children");
                variants.Add("kid");
                variants.Add("kids");
                break;

            case "apprenti":
            case "apprentis":
            case "apprentice":
            case "apprentices":
            case "debutant":
            case "debutants":
            case "beginner":
            case "beginners":
                variants.Add("apprenti");
                variants.Add("apprentis");
                variants.Add("apprentice");
                variants.Add("apprentices");
                variants.Add("debutant");
                variants.Add("debutants");
                variants.Add("beginner");
                variants.Add("beginners");
                break;
        }
    }

    private static void AddSimpleGenderNumberVariants(HashSet<string> variants, string token)
    {
        if (token.Length < 6)
            return;

        if (token.EndsWith("aises", StringComparison.Ordinal)
            || token.EndsWith("antes", StringComparison.Ordinal)
            || token.EndsWith("entes", StringComparison.Ordinal)
            || token.EndsWith("ales", StringComparison.Ordinal))
        {
            variants.Add(token[..^2]);
        }
        else if (token.EndsWith("aise", StringComparison.Ordinal)
                 || token.EndsWith("ante", StringComparison.Ordinal)
                 || token.EndsWith("ente", StringComparison.Ordinal)
                 || token.EndsWith("ale", StringComparison.Ordinal))
        {
            variants.Add(token[..^1]);
        }

        if (token.EndsWith("euses", StringComparison.Ordinal))
            variants.Add(token[..^5] + "eux");
        else if (token.EndsWith("euse", StringComparison.Ordinal))
            variants.Add(token[..^4] + "eux");

        if (token.EndsWith("ives", StringComparison.Ordinal))
            variants.Add(token[..^4] + "if");
        else if (token.EndsWith("ive", StringComparison.Ordinal))
            variants.Add(token[..^3] + "if");

        if (token.EndsWith("elles", StringComparison.Ordinal))
            variants.Add(token[..^5] + "el");
        else if (token.EndsWith("elle", StringComparison.Ordinal))
            variants.Add(token[..^4] + "el");
    }

    private static void AddAdjacentPhraseTerms(HashSet<string> terms, IReadOnlyList<string> canonicalTokens)
    {
        if (canonicalTokens.Count < 2)
            return;

        var clean = canonicalTokens
            .Where(static token => token.Length >= 4)
            .Where(static token => !LexicalStopwords.Contains(token))
            .Where(static token => !SpecificAnchorStopwords.Contains(token))
            .Take(8)
            .ToArray();

        for (var n = 2; n <= 3; n++)
        {
            if (clean.Length < n)
                continue;

            for (var i = 0; i <= clean.Length - n; i++)
            {
                AddPhraseWithSurfaceVariants(terms, clean.Skip(i).Take(n).ToArray());
            }
        }
    }

    private static void AddPhraseWithSurfaceVariants(HashSet<string> terms, IReadOnlyList<string> tokens)
    {
        if (tokens.Count == 0)
            return;

        var tokenVariants = tokens
            .Select(BuildPhraseSurfaceVariants)
            .Where(static variants => variants.Count > 0)
            .ToArray();
        if (tokenVariants.Length != tokens.Count)
            return;

        var phrases = new List<string> { string.Empty };
        foreach (var variants in tokenVariants)
        {
            var next = new List<string>();
            foreach (var prefix in phrases)
            {
                foreach (var variant in variants)
                {
                    var phrase = string.IsNullOrWhiteSpace(prefix)
                        ? variant
                        : $"{prefix} {variant}";
                    next.Add(phrase);
                    if (next.Count >= 32)
                        break;
                }

                if (next.Count >= 32)
                    break;
            }

            phrases = next;
        }

        foreach (var phrase in phrases)
        {
            if (phrase.Length is >= 9 and <= 80)
                terms.Add(phrase);
        }
    }

    private static IReadOnlyList<string> BuildPhraseSurfaceVariants(string token)
        => BuildLexicalTokenVariants(token)
            .Where(static variant => variant.Length >= 4)
            .Where(static variant => !LexicalStopwords.Contains(variant))
            .OrderBy(variant => string.Equals(variant, token, StringComparison.Ordinal) ? 0 : ContainsNonAscii(variant) ? 1 : 2)
            .ThenBy(static variant => variant.Length)
            .ThenBy(static variant => variant, StringComparer.Ordinal)
            .Take(5)
            .ToArray();

    private static bool ContainsNonAscii(string value)
        => value.Any(static ch => ch > 127);

    internal static string ExpandRetrievalQuery(string query, string? category)
    {
        if (string.IsNullOrWhiteSpace(query))
            return query;

        _ = category;

        var repairedQuery = RepairReplacementAccentMarkers(query);
        var lookup = ExactMatchEntryExtractor.NormalizeForLookup(repairedQuery);
        var normalized = FoldDiacritics(lookup);
        if (string.IsNullOrWhiteSpace(normalized))
            return repairedQuery.Trim();

        var trimmed = repairedQuery.Trim();
        var expandedTerms = BuildQueryExpansionTerms(normalized);
        var additions = new List<string>();
        if (!string.Equals(normalized, lookup, StringComparison.Ordinal))
            additions.Add(normalized);
        foreach (var term in expandedTerms)
        {
            if (!lookup.Contains(term, StringComparison.OrdinalIgnoreCase)
                && !normalized.Contains(term, StringComparison.OrdinalIgnoreCase))
                additions.Add(term);
        }

        return additions.Count == 0
            ? trimmed
            : $"{trimmed} {string.Join(' ', additions.Distinct(StringComparer.OrdinalIgnoreCase))}";
    }

    internal static string ResolvePrimaryRetrievalQuery(string query, string? category)
    {
        if (TryExtractDelimitedUserDemandTopic(query, out var delimitedTopic))
            return ExpandRetrievalQuery(delimitedTopic, category);

        if (ShouldTreatQuotedLookupAsTopic(query))
        {
            var quotedTopicPhrase = ExtractFocusedLookupPhrases(query).FirstOrDefault();
            if (!string.IsNullOrWhiteSpace(quotedTopicPhrase))
                return ExpandRetrievalQuery(quotedTopicPhrase, category);
        }

        if (ContainsDocumentOverviewIntent(query))
            return ExpandRetrievalQuery(query, category);
        if (LooksLikeShortAudienceConstrainedGenericFragment(query))
            return query.Trim();

        var focusedLookupPhrase = ExtractFocusedLookupPhrases(query).FirstOrDefault();
        return ExpandRetrievalQuery(
            string.IsNullOrWhiteSpace(focusedLookupPhrase) ? query : focusedLookupPhrase,
            category);
    }

    internal static string ResolveLexicalRetrievalSurface(string query, string retrievalQuery)
        => TryExtractDelimitedUserDemandTopic(query, out _)
            && !string.IsNullOrWhiteSpace(retrievalQuery)
            || ShouldUseExpandedLexicalRetrievalSurface(query, retrievalQuery)
            ? retrievalQuery
            : query;

    private static bool ShouldUseExpandedLexicalRetrievalSurface(string query, string retrievalQuery)
    {
        if (string.IsNullOrWhiteSpace(query)
            || string.IsNullOrWhiteSpace(retrievalQuery)
            || string.Equals(query.Trim(), retrievalQuery.Trim(), StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        if (ContainsDocumentOverviewIntent(query)
            || HasExplicitFileLookupIntent(query)
            || ExtractQuotedLookupPhrases(query).Count > 0)
        {
            return false;
        }

        var normalized = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(RepairReplacementAccentMarkers(query)));
        if (string.IsNullOrWhiteSpace(normalized))
            return false;

        var tokenCount = ExtractLexicalQueryTokens(normalized)
            .Where(static token => token.Length >= 4)
            .Where(static token => !LexicalStopwords.Contains(token))
            .Distinct(StringComparer.Ordinal)
            .Count();
        if (tokenCount is < 1 or > 4)
            return false;

        return BuildQueryExpansionTerms(normalized).Count > 0;
    }

    internal static IReadOnlyList<string> BuildQueryExpansionTerms(string normalizedQuery)
    {
        if (string.IsNullOrWhiteSpace(normalizedQuery))
            return Array.Empty<string>();

        var tokens = ExtractLexicalQueryTokens(normalizedQuery)
            .Where(static token => token.Length >= 4)
            .Where(static token => !LexicalStopwords.Contains(token))
            .Distinct(StringComparer.Ordinal)
            .ToArray();
        if (tokens.Length == 0)
            return Array.Empty<string>();

        var variants = tokens
            .SelectMany(static token => BuildLexicalTokenVariants(token).DefaultIfEmpty(token))
            .Where(static variant => !string.IsNullOrWhiteSpace(variant))
            .Where(IsCorpusAgnosticQueryExpansionVariant)
            .Where(variant => !normalizedQuery.Contains(variant, StringComparison.OrdinalIgnoreCase))
            .Distinct(StringComparer.Ordinal)
            .Take(10)
            .ToList();

        var expanded = tokens
            .SelectMany(static token => BuildLexicalTokenVariants(token).DefaultIfEmpty(token))
            .ToHashSet(StringComparer.Ordinal);
        if (expanded.Any(static token => token is "accidental" or "accident")
            && expanded.Any(static token => token is "damage" or "damages"))
        {
            variants.Insert(0, "accidental damage");
        }
        if (expanded.Any(static token => token is "legal")
            && expanded.Any(static token => token is "advice" or "conseil"))
        {
            variants.Insert(0, "legal advice");
        }
        if (expanded.Any(static token => token is "cover" or "coverage" or "covered")
            && ContainsAny($" {normalizedQuery} ", " pas ", " non ", " not "))
        {
            variants.Insert(0, "not covered");
        }
        if (expanded.Any(static token => token is "insured" or "insurance" or "covered")
            && expanded.Any(static token => token is "property" or "properties" or "belonging" or "belongings" or "asset" or "assets" or "item" or "items"))
        {
            variants.Insert(0, "personal belongings");
            variants.Insert(0, "covered property");
            variants.Insert(0, "insured property");
        }
        if (expanded.Any(static token => token is "proof" or "proofs" or "evidence")
            && expanded.Any(static token => token is "provide" or "provided" or "providing" or "submit" or "submitted" or "required"))
        {
            variants.Insert(0, "documents required");
            variants.Insert(0, "supporting documents");
            variants.Insert(0, "supporting evidence");
            variants.Insert(0, "provide evidence");
        }
        if (expanded.Any(static token => token is "property" or "properties" or "propriete" or "proprietes" or "characteristic" or "characteristics")
            && expanded.Any(static token => token is "electric" or "electrical" or "electricity" or "dielectric"))
        {
            variants.Insert(0, "dielectric properties");
            variants.Insert(0, "electrical properties");
        }
        if (expanded.Any(static token => token is "property" or "properties" or "propriete" or "proprietes" or "characteristic" or "characteristics")
            && expanded.Any(static token => token is "thermal" or "temperature" or "temperatures" or "melt point" or "melting point"))
        {
            variants.Insert(0, "temperature properties");
            variants.Insert(0, "thermal properties");
        }

        return variants
            .Distinct(StringComparer.Ordinal)
            .Take(10)
            .ToArray();
    }

    internal static string BuildLexicalProfileEmptyRecoveryQuery(string query, string? category)
    {
        if (string.IsNullOrWhiteSpace(query))
            return string.Empty;

        var expanded = ExpandRetrievalQuery(query, category);
        if (string.IsNullOrWhiteSpace(expanded)
            || string.Equals(expanded.Trim(), query.Trim(), StringComparison.OrdinalIgnoreCase))
        {
            return string.Empty;
        }

        var normalized = FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(expanded));
        var tokens = ExtractLexicalQueryTokens(normalized)
            .Where(static token => token.Length >= 4)
            .Where(static token => !LexicalStopwords.Contains(token))
            .Distinct(StringComparer.Ordinal)
            .Take(24)
            .ToArray();
        return tokens.Length == 0
            ? string.Empty
            : string.Join(' ', tokens);
    }

    private static bool IsCorpusAgnosticQueryExpansionVariant(string variant)
        => variant switch
        {
            "damage" or "damages" or "damaged" or "accidental" or "accident" or "accidents" => true,
            "cover" or "covers" or "covered" or "coverage" => true,
            "warranty" or "warranties" => true,
            "claim" or "claims" or "notification" or "incident" or "incidents" => true,
            "excluded" or "exclude" or "excludes" or "not covered" => true,
            "legal" or "law" or "advice" or "advisory" => true,
            "insured" or "insurance" or "belonging" or "belongings" => true,
            "proof" or "proofs" or "evidence" or "provide" or "provided" or "providing" or "submit" or "submitted" or "required" => true,
            "objective" or "objectives" or "goal" or "goals" => true,
            "country" or "countries" or "achieve" or "achieved" or "reached" => true,
            "powder" or "powders" or "powdered" or "powdering" or "coating" or "coatings" or "coated" => true,
            "powder coating" or "powder coatings" or "powder-coated" or "coating powder" => true,
            "surface treatment" or "finish" or "finishing" => true,
            "propriete" or "proprietes" or "property" or "properties" or "characteristic" or "characteristics" => true,
            "electric" or "electrical" or "electricity" or "dielectric" => true,
            "thermal" or "temperature" or "temperatures" or "melt point" or "melting point" => true,
            _ => false
        };

    internal static string FoldDiacritics(string value)
    {
        if (string.IsNullOrWhiteSpace(value))
            return string.Empty;

        var normalized = value.Normalize(NormalizationForm.FormD);
        var sb = new StringBuilder(normalized.Length);
        foreach (var ch in normalized)
        {
            if (CharUnicodeInfo.GetUnicodeCategory(ch) != UnicodeCategory.NonSpacingMark)
            {
                _ = ch switch
                {
                    'œ' => sb.Append("oe"),
                    'Œ' => sb.Append("OE"),
                    'æ' => sb.Append("ae"),
                    'Æ' => sb.Append("AE"),
                    'ß' => sb.Append("ss"),
                    'ø' => sb.Append('o'),
                    'Ø' => sb.Append('O'),
                    'ł' => sb.Append('l'),
                    'Ł' => sb.Append('L'),
                    'đ' => sb.Append('d'),
                    'Đ' => sb.Append('D'),
                    _ => sb.Append(ch)
                };
            }
        }

        return sb.ToString().Normalize(NormalizationForm.FormC);
    }

    internal static double ComputeLexicalCoverage(IReadOnlyList<string> queryTokens, string? candidateText)
    {
        if (queryTokens.Count == 0 || string.IsNullOrWhiteSpace(candidateText))
            return 0.0;

        return ComputeLexicalCoverageInNormalizedText(queryTokens, NormalizeForLexicalSignal(candidateText));
    }

    private static double ComputeLexicalCoverageInNormalizedText(IReadOnlyList<string> queryTokens, string normalizedCandidate)
    {
        if (queryTokens.Count == 0 || string.IsNullOrWhiteSpace(normalizedCandidate))
            return 0.0;

        var matched = 0;
        foreach (var token in queryTokens)
        {
            var variants = BuildLexicalTokenVariants(token);
            if (variants.Any(variant => normalizedCandidate.Contains(variant, StringComparison.Ordinal)))
                matched++;
        }

        return matched == 0 ? 0.0 : (double)matched / queryTokens.Count;
    }

    internal static bool ComputeHypQuestionsMatched(string query, IReadOnlyList<string>? hypotheticalQuestions)
    {
        if (hypotheticalQuestions is null || hypotheticalQuestions.Count == 0)
            return false;

        var queryTokens = ExtractLexicalQueryTokens(query);
        if (queryTokens.Count == 0)
            return false;

        return hypotheticalQuestions.Any(question => ComputeLexicalCoverage(queryTokens, question) >= 0.5);
    }

    internal static bool? ResolveHypQuestionsMatched(string? docPath, IReadOnlyDictionary<string, bool?>? byDocPath)
    {
        if (string.IsNullOrWhiteSpace(docPath) || byDocPath is null)
            return null;

        var normalizedDocPath = NormalizeRagDocPath(docPath);
        if (!string.IsNullOrWhiteSpace(normalizedDocPath)
            && byDocPath.TryGetValue(normalizedDocPath, out var normalizedMatched))
            return normalizedMatched;

        return byDocPath.TryGetValue(docPath, out var matched) ? matched : null;
    }

    internal static double ComputeLinkedMatchScore(double anchorScore, string linkType, string? anchorRetriever = null)
    {
        var penalty = linkType switch
        {
            "same_section" => 0.02,
            "next" => 0.035,
            "prev" => 0.04,
            "same_page_route" => 0.045,
            "same_page_exact" => 0.045,
            _ => 0.05
        };

        if (string.Equals(anchorRetriever, "linked_context", StringComparison.Ordinal))
            penalty += 0.015;
        else if (string.Equals(anchorRetriever, "exact_match", StringComparison.Ordinal))
            penalty += 0.01;
        else if (string.Equals(anchorRetriever, "sparse_bm25", StringComparison.Ordinal))
            penalty += 0.005;

        return Math.Max(0.0, anchorScore - penalty);
    }

    private sealed record LinkedAnchorCandidate(
        Guid SourceId,
        string SourceRetriever,
        double AnchorScore,
        string? AnchorTitle);

    private sealed record TitleSelectionSignal(
        RagMatch Match,
        double ExactTitleScore,
        int SpecificAnchorCount,
        bool FullTitleCoverage,
        int StructuredAnswerPriority);

    internal static double ComputeExactMatchScore(string? matchKind, string? matchedTerm, string? text)
    {
        var score = matchKind switch
        {
            "standard_ref" => 1.0,
            "code_ref" => 0.985,
            _ => 0.96
        };

        var normalizedMatchedTerm = ExactMatchEntryExtractor.NormalizeForLookup(matchedTerm ?? string.Empty);
        var normalizedText = ExactMatchEntryExtractor.NormalizeForLookup(text ?? string.Empty);
        if (!string.IsNullOrWhiteSpace(normalizedMatchedTerm))
        {
            score += Math.Min(0.01, normalizedMatchedTerm.Length / 500.0);
            if (string.Equals(normalizedMatchedTerm, normalizedText, StringComparison.Ordinal))
            {
                score += 0.005;
            }
            else if (normalizedMatchedTerm.Length >= 12
                && normalizedMatchedTerm.Contains(' ')
                && normalizedText.StartsWith(normalizedMatchedTerm, StringComparison.Ordinal))
            {
                score -= 0.006;
            }
        }

        return Math.Min(1.02, score);
    }

    internal static bool ShouldShortCircuitAfterExact(IReadOnlyList<RagMatch> exactMatches)
        => ShouldShortCircuitAfterExact(string.Empty, exactMatches);

    internal static bool ShouldShortCircuitAfterExact(string query, IReadOnlyList<RagMatch> exactMatches)
    {
        if (exactMatches.Count == 0)
            return false;
        if (ContainsDocumentCompanionRelationIntent(query))
            return false;

        var top = exactMatches[0];
        if (!string.Equals(top.EmbeddingBasis, "exact_match_v1", StringComparison.Ordinal))
            return false;

        var isStrongReferenceHit =
            string.Equals(top.ChunkType, "exact_match_entry", StringComparison.Ordinal)
            || string.Equals(top.ChunkType, "document_metadata_ref", StringComparison.Ordinal);

        if (!isStrongReferenceHit || top.Score < 0.97)
            return false;
        if (LooksLikeNavigationalChunk(top))
            return false;

        if (exactMatches.Count == 1)
            return true;

        var second = exactMatches[1];
        return top.Score - second.Score >= 0.04;
    }

    internal static bool ContainsDocumentCompanionRelationIntent(string query)
    {
        if (string.IsNullOrWhiteSpace(query))
            return false;

        var normalized = $" {FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query)).ToLowerInvariant()} ";
        return ContainsAny(
            normalized,
            " norme principale ",
            " norme complete ",
            " norme complète ",
            " standard principal ",
            " main standard ",
            " full standard ",
            " complete standard ",
            " document principal ",
            " fichier principal ",
            " main document ",
            " main file ",
            " par rapport au document ",
            " par rapport a document ",
            " par rapport au fichier ",
            " par rapport a fichier ",
            " role du fichier ",
            " role de fichier ",
            " role du document ",
            " role de document ",
            " corrigendum ",
            " corrigenda ",
            " amendement ",
            " amendment ",
            " addendum ",
            " supplement ",
            " supplemental document ",
            " supplemental file ",
            " document supplementaire ",
            " fichier supplementaire ",
            " annexe ",
            " annex ",
            " appendix ",
            " correction document ",
            " correction file ",
            " notice de correction ",
            " document connexe ",
            " fichier connexe ",
            " related document ",
            " related file ",
            " companion document ",
            " companion file ");
    }

    internal static bool ShouldProbeUnquotedTitleAnchorRoute(
        string query,
        bool skipChunkRetrieversForDocumentOverview,
        bool useScopedProfileFallback)
    {
        if (skipChunkRetrieversForDocumentOverview || useScopedProfileFallback)
            return false;
        if (ExtractQuotedLookupPhrases(query).Count > 0)
            return false;
        if (LooksLikeShortAudienceConstrainedGenericFragment(query))
            return false;

        var normalized = $" {FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query))} ";
        var focusedPhrases = ExtractFocusedLookupPhrases(query)
            .Distinct(StringComparer.Ordinal)
            .ToArray();
        var focusedBackfillQuery = BuildFocusedLexicalBackfillQuery(query);
        var focusedBackfillTokens = ExtractLexicalQueryTokens(focusedBackfillQuery);
        var hasPreciseLookupVerbTarget = ContainsPreciseLookupVerb(normalized)
            && focusedBackfillTokens.Count is >= 2 and <= 6;
        var hasSourceAttributionTitleShape = HasSourceAttributionTitleLookupShape(query, normalized);

        if (ShouldPreferComparativeDocumentDiversity(query)
            || ContainsDocumentOverviewIntent(query)
            || ContainsExplicitBroadScopedSynthesisIntent(normalized)
            || (ContainsSituationalBroadSelectionIntent(normalized) && focusedPhrases.Length == 0)
            || ContainsGuidanceOrAdviceSelectionIntent(normalized)
            || IsRecommendationSelectionQuery(normalized))
        {
            return false;
        }
        if (ContainsBroadScopedSynthesisIntent(normalized) && !hasPreciseLookupVerbTarget)
            return false;

        if (focusedPhrases.Length == 1
            || hasSourceAttributionTitleShape
            || ShouldConstrainPreciseTitleLookup(query))
        {
            return true;
        }

        return hasPreciseLookupVerbTarget;
    }

    internal static bool ShouldSkipLocalTitleTokenRouteForIndexedTitleAnchors(
        string query,
        bool hasCategoryScope,
        bool hasDocScope,
        bool skipChunkRetrieversForDocumentOverview,
        bool useScopedProfileFallback)
    {
        if (!hasCategoryScope || hasDocScope || skipChunkRetrieversForDocumentOverview || useScopedProfileFallback)
            return false;
        if (ExtractTitleLookupPhrases(query).Count == 0)
            return false;
        if (ExtractQuotedLookupPhrases(query).Count > 0)
            return true;

        return ShouldProbeUnquotedTitleAnchorRoute(
            query,
            skipChunkRetrieversForDocumentOverview,
            useScopedProfileFallback);
    }

    private static bool ContainsPreciseLookupVerb(string normalized)
        => ContainsAny(
            normalized,
            " cherche ",
            " recherche ",
            " chercher ",
            " rechercher ",
            " donne ",
            " donne moi ",
            " donnez ",
            " montre ",
            " montre moi ",
            " explique ",
            " expliques ",
            " expliquer ",
            " detaille ",
            " trouve ",
            " trouver ",
            " find ",
            " give ",
            " show ",
            " explain ",
            " details ",
            " get ",
            " search ",
            " looking ",
            " busca ",
            " buscar ",
            " busco ",
            " procura ",
            " procurar ",
            " procuro ",
            " cerca ",
            " cercare ",
            " cerco ",
            " suche ",
            " such ",
            " finde ",
            " finden ");

    internal static bool ShouldShortCircuitAfterTitleAnchorRoute(string query, IReadOnlyList<RagMatch> titleAnchorRouteMatches)
    {
        if (titleAnchorRouteMatches.Count == 0)
            return false;
        if (!ShouldProbeUnquotedTitleAnchorRoute(
                query,
                skipChunkRetrieversForDocumentOverview: false,
                useScopedProfileFallback: false))
        {
            return false;
        }
        var normalized = $" {FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query))} ";
        if (HasSourceAttributionTitleLookupShape(query, normalized))
            return false;

        var candidates = RankTitleAnchorRouteShortCircuitMatches(titleAnchorRouteMatches);
        if (candidates.Count == 0)
            return false;

        var top = candidates[0];
        var minimumScore = string.Equals(ResolveRetriever(top), "direct_title_token_route", StringComparison.Ordinal)
            ? 0.78
            : 0.90;
        if (top.Score < minimumScore)
            return false;

        if (QueryRequestsSafetyDataSheetDocumentType(query)
            && !TitleSignalMatchesSafetyDataSheetDocumentType(GetDocumentTypeTitleSignalText(top)))
        {
            return false;
        }

        var second = candidates.FirstOrDefault(match => !IsSameDocument(top, match));
        if (second is null)
            return true;

        return top.Score - second.Score >= 0.04;
    }

    internal static IReadOnlyList<RagMatch> RankTitleAnchorRouteShortCircuitMatches(IReadOnlyList<RagMatch> titleAnchorRouteMatches)
        => titleAnchorRouteMatches
            .Where(IsTitleAnchorRouteShortCircuitCandidate)
            .OrderByDescending(static match => match.Score)
            .ThenBy(static match => match.DocPath, StringComparer.OrdinalIgnoreCase)
            .ThenBy(static match => match.ChunkIndex)
            .ToArray();

    private static bool IsTitleAnchorRouteShortCircuitCandidate(RagMatch match)
        => IsResolvedTitleOrNavigationRoute(match)
            && (!IsDirectTitleTokenRouteMatch(match) || DirectTitleTokenRouteHasStrongLeadEvidence(match))
            && !LooksLikeNavigationalChunk(match)
            && !HasBorderlineNavigationShortcutRisk(match)
            && HasUsefulResolvedTitleBody(match);

    private static bool HasBorderlineNavigationShortcutRisk(RagMatch match)
        => match.NavigationScore is >= 0.72
            && match.ContentDensityScore is null or <= 0.55;

    private static bool HasUsefulResolvedTitleBody(RagMatch match)
    {
        if (GetStructuredAnswerPriority(match) >= 2)
            return true;
        if (match.MatchedContentCards is { Count: > 0 })
            return true;

        return (match.Text?.Trim().Length ?? 0) >= 160;
    }

    internal static bool ShouldShortCircuitAfterQuotedTitle(string query, IReadOnlyList<RagMatch> quotedTitleMatches)
    {
        if (quotedTitleMatches.Count == 0)
            return false;
        var quotedPhrases = ExtractQuotedLookupPhrases(query);
        if (quotedPhrases.Count != 1)
            return false;

        var normalized = $" {FoldDiacritics(ExactMatchEntryExtractor.NormalizeForLookup(query))} ";
        if (ShouldPreferComparativeDocumentDiversity(query)
            || ContainsDocumentOverviewIntent(query)
            || ContainsEnumerativeLookupIntent(normalized)
            || ContainsGuidanceOrAdviceSelectionIntent(normalized)
            || ShouldKeepQuotedTitleSearchOpenForStructuredDetails(query, normalized))
        {
            return false;
        }

        var top = quotedTitleMatches[0];
        if (top.Score < 0.90 || LooksLikeNavigationalChunk(top))
            return false;
        if (!HasQuotedTitlePlacementEvidence(quotedPhrases, top))
            return false;

        if (quotedTitleMatches.Count == 1)
            return true;

        var second = quotedTitleMatches[1];
        if (IsSameDocument(top, second))
            return true;

        return top.Score - second.Score >= 0.04;
    }

    private static bool ShouldKeepQuotedTitleSearchOpenForStructuredDetails(string query, string normalized)
        => ContainsParameterDetailLookupIntent(normalized)
           || HasSourceAttributionTitleLookupShape(query, normalized)
           || ContainsAny(
               normalized,
               " fiche ",
               " card ",
               " scheda ",
               " components ",
               " component ",
               " materials ",
               " material ",
               " etape ",
               " etapes ",
               " step ",
               " steps ",
               " source ",
               " sources ",
               " citation ",
               " citations ");

    internal static bool ShouldSkipQuotedTitleFullScan(string query, bool hasDocScope)
        => !hasDocScope
           && ExtractQuotedLookupPhrases(query).Count == 0
           && ExtractTitleLookupPhrases(query).Count > 0;

    private static bool IsSameDocument(RagMatch left, RagMatch right)
    {
        if (!string.IsNullOrWhiteSpace(left.DocId)
            && !string.IsNullOrWhiteSpace(right.DocId)
            && string.Equals(left.DocId, right.DocId, StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }

        return !string.IsNullOrWhiteSpace(left.DocPath)
            && !string.IsNullOrWhiteSpace(right.DocPath)
            && string.Equals(left.DocPath, right.DocPath, StringComparison.OrdinalIgnoreCase);
    }

    internal static string ResolveRetriever(RagMatch match)
        => match.EmbeddingBasis switch
        {
            "exact_match_v1" => "exact_match",
            "sparse_bm25_v1" => "sparse_bm25",
            "short_technical_phrase_v1" => "sparse_bm25",
            "document_profile_v1" => "document_profile",
            "linked_context_v1" => "linked_context",
            "explicit_document_title_route_v1" => "explicit_document_title_route",
            "title_anchor_route_v1" => "title_anchor_route",
            "navigation_route_v1" => "navigation_route",
            "direct_title_token_route_v1" => "direct_title_token_route",
            "local_title_token_route_v1" => "local_title_token_route",
            "fuzzy_title_lead_v1" => "fuzzy_title_lead",
            "standard_reference_document_name_v1" => "standard_reference_document_name",
            "reference_version_operand_document_name_v1" => "reference_version_operand_document_name",
            "date_document_name_v1" => "date_document_name",
            "document_status_operand_v1" => "document_status_operand",
            _ => "dense_qdrant"
        };

    private static void AccumulateRrf(
        Dictionary<string, RrfAccumulator> accumulators,
        IReadOnlyList<RagMatch> matches,
        int rrfK)
    {
        for (var i = 0; i < matches.Count; i++)
        {
            var match = matches[i];
            var key = BuildMatchDedupKey(match);
            var contribution = 1.0 / (rrfK + i + 1);
            if (accumulators.TryGetValue(key, out var existing))
            {
                accumulators[key] = existing with
                {
                    Score = existing.Score + contribution,
                    Representative = SelectRepresentative(existing.Representative, match)
                };
            }
            else
            {
                accumulators[key] = new RrfAccumulator(contribution, match);
            }
        }
    }

    private static RagMatch SelectRepresentative(RagMatch left, RagMatch right)
    {
        var leftPriority = GetRetrieverPriority(left);
        var rightPriority = GetRetrieverPriority(right);
        if (rightPriority != leftPriority)
            return rightPriority > leftPriority ? right : left;

        return right.Score > left.Score ? right : left;
    }

    private static int GetRetrieverPriority(RagMatch match)
        => ResolveRetriever(match) switch
        {
            "exact_match" => 5,
            "explicit_document_title_route" => 5,
            "title_anchor_route" => 4,
            "navigation_route" => 4,
            "direct_title_token_route" => 4,
            "local_title_token_route" => 4,
            "fuzzy_title_lead" => 4,
            "standard_reference_document_name" => 4,
            "reference_version_operand_document_name" => 4,
            "date_document_name" => 4,
            "sparse_bm25" => 3,
            "dense_qdrant" => 2,
            _ => 1
        };

