    private static bool ContainsNormalizedWholeTerm(string normalizedText, string term)
        => Regex.IsMatch(
            normalizedText,
            $@"(?:^|[^\p{{L}}\p{{N}}]){Regex.Escape(term)}(?:$|[^\p{{L}}\p{{N}}])",
            RegexOptions.CultureInvariant);

